@import "tailwindcss" source(none);
@source "../src";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme {
  --font-sans: "Space Grotesk", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Space Grotesk", ui-sans-serif, system-ui, sans-serif;
  --font-serif: "Space Grotesk", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

/*
 * Design system definition.
 *
 * The @theme inline block maps CSS custom properties to Tailwind utility
 * classes (e.g. --color-primary -> bg-primary, text-primary).
 *
 * The :root and .dark blocks define the actual color values using oklch.
 * All colors MUST use oklch format.
 *
 * To add a new semantic color:
 * 1. Add the variable to :root (light value) and .dark (dark value)
 * 2. Register it in @theme inline as --color-<name>: var(--<name>)
 */

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-primary-deep: var(--primary-deep);
  --color-primary-soft: var(--primary-soft);
  --color-ink: var(--ink);
  --color-surface: var(--surface);
  --color-dark: var(--dark);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-offset-background: var(--background);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.205 0.005 285);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.205 0.005 285);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.205 0.005 285);
  --primary: oklch(0.548 0.117 158.2);
  --primary-foreground: oklch(1 0 0);
  --primary-deep: oklch(0.42 0.098 158.2);
  --primary-soft: oklch(0.958 0.028 158.2);
  --secondary: oklch(0.977 0.002 247);
  --secondary-foreground: oklch(0.205 0.005 285);
  --muted: oklch(0.977 0.002 247);
  --muted-foreground: oklch(0.575 0.012 264);
  --accent: oklch(0.958 0.028 158.2);
  --accent-foreground: oklch(0.42 0.098 158.2);
  --ink: oklch(0.205 0.005 285);
  --surface: oklch(0.978 0.002 247);
  --dark: oklch(0.19 0.012 160);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.984 0.003 247.858);
  --border: oklch(0.928 0.004 247);
  --input: oklch(0.928 0.004 247);
  --ring: oklch(0.548 0.117 158.2);
  --gradient-hero: linear-gradient(
    100deg,
    color-mix(in oklab, var(--dark) 88%, transparent),
    color-mix(in oklab, var(--primary-deep) 55%, transparent)
  );
  --shadow-card: 0 1px 2px oklch(0.2 0.01 160 / 0.04), 0 12px 32px -18px oklch(0.2 0.01 160 / 0.35);
  --shadow-lift: 0 20px 45px -22px oklch(0.42 0.098 158.2 / 0.45);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.984 0.003 247.858);
  --sidebar-foreground: oklch(0.129 0.042 264.695);
  --sidebar-primary: oklch(0.208 0.042 265.755);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.968 0.007 247.896);
  --sidebar-accent-foreground: oklch(0.208 0.042 265.755);
  --sidebar-border: oklch(0.929 0.013 255.508);
  --sidebar-ring: oklch(0.704 0.04 256.788);
}

.dark {
  --background: oklch(0.129 0.042 264.695);
  --foreground: oklch(0.984 0.003 247.858);
  --card: oklch(0.208 0.042 265.755);
  --card-foreground: oklch(0.984 0.003 247.858);
  --popover: oklch(0.208 0.042 265.755);
  --popover-foreground: oklch(0.984 0.003 247.858);
  --primary: oklch(0.929 0.013 255.508);
  --primary-foreground: oklch(0.208 0.042 265.755);
  --secondary: oklch(0.279 0.041 260.031);
  --secondary-foreground: oklch(0.984 0.003 247.858);
  --muted: oklch(0.279 0.041 260.031);
  --muted-foreground: oklch(0.704 0.04 256.788);
  --accent: oklch(0.279 0.041 260.031);
  --accent-foreground: oklch(0.984 0.003 247.858);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.984 0.003 247.858);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.551 0.027 264.364);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.208 0.042 265.755);
  --sidebar-foreground: oklch(0.984 0.003 247.858);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.279 0.041 260.031);
  --sidebar-accent-foreground: oklch(0.984 0.003 247.858);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.551 0.027 264.364);
}

@layer base {
  html {
    scroll-behavior: smooth;
    font-family: var(--font-sans);
  }

  * {
    border-color: var(--color-border);
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
  }
}

@utility container-page {
  width: 100%;
  margin-inline: auto;
  max-width: min(100%, 94rem);
  padding-inline: clamp(0.875rem, 1.5vw, 1.75rem);
}

@utility container-nav {
  width: 100%;
  max-width: none;
  margin-inline: auto;
  padding-inline: clamp(0.875rem, 1.5vw, 1.75rem);
}

@utility section-curve {
  margin-inline: clamp(0.25rem, 0.65vw, 0.5rem);
  border-radius: clamp(1rem, 2vw, 1.5rem);
  overflow: hidden;
}

/* First rounded section sits below the fixed nav with the same inset as left/right. */
main > .section-curve:first-child {
  margin-top: clamp(0.25rem, 0.65vw, 0.5rem);
}

@utility section-curve-sticky {
  margin-inline: clamp(0.25rem, 0.65vw, 0.5rem);
  border-radius: clamp(1rem, 2vw, 1.5rem);
}

@utility section-curve-hero {
  overflow: hidden;
  border-bottom-left-radius: clamp(1rem, 2vw, 1.5rem);
  border-bottom-right-radius: clamp(1rem, 2vw, 1.5rem);
}

/* Shared section kicker — readable at a glance for section orientation */
@utility section-eyebrow {
  font-family: var(--font-mono);
  font-size: clamp(0.875rem, 0.8rem + 0.35vw, 1.0625rem);
  font-weight: 700;
  letter-spacing: 0.14em;
  line-height: 1.35;
  text-transform: none;
}

.sticky-scroll-panel {
  scroll-snap-align: start;
  scroll-snap-stop: always;
}

.globe-stage {
  isolation: isolate;
}

.globe-stage canvas {
  position: absolute;
  inset: 0;
}

.globe-top-fringe {
  position: absolute;
  inset: 0 0 auto;
  z-index: 2;
  height: 28%;
  background: repeating-linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 22%, transparent) 0,
    transparent 14px,
    transparent 28px
  );
  mask-image: linear-gradient(to bottom, black 0%, transparent 100%);
  pointer-events: none;
}

.globe-slide-card {
  border: 1px solid color-mix(in oklab, var(--background) 22%, transparent);
  border-radius: clamp(1rem, 2vw, 1.35rem);
  background: transparent;
  min-height: min(32rem, 72vh);
  box-shadow: 0 32px 80px -40px color-mix(in oklab, var(--dark) 45%, transparent);
  text-align: center;
}

.globe-slide-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--dark) 55%, transparent) 0%,
    color-mix(in oklab, var(--dark) 78%, transparent) 45%,
    color-mix(in oklab, var(--dark) 92%, transparent) 100%
  );
}

.globe-slide-card-content {
  padding: clamp(1.75rem, 4vw, 2.75rem);
  padding-top: clamp(2.5rem, 8vw, 4rem);
  backdrop-filter: blur(2px);
}

@media (max-width: 639px) {
  .globe-scroll-section {
    --globe-last-pad: 8rem;
    --globe-card-gutter: 1.25rem;
  }

  .globe-scroll-article {
    padding-inline: var(--globe-card-gutter);
  }

  .globe-slide-card {
    min-height: 0;
  }

  .globe-slide-card-content {
    padding: 1.35rem 1.15rem 1.5rem;
  }

  .globe-pin-caption {
    inset-inline: 0.85rem;
    bottom: 2.35rem;
  }

  .globe-rail-label {
    font-size: 0.625rem;
    letter-spacing: 0.14em;
  }
}

.globe-slide-stat {
  border: 1px solid color-mix(in oklab, var(--background) 28%, transparent);
  background: color-mix(in oklab, var(--background) 12%, transparent);
  backdrop-filter: blur(8px);
}

.globe-rail-label {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: none;
  color: color-mix(in oklab, var(--foreground) 45%, transparent);
}

.globe-rail-value {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1;
  color: var(--foreground);
}

.globe-rail-meta {
  margin-top: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.35;
  color: color-mix(in oklab, var(--foreground) 62%, transparent);
}

/* Globe scroll — reserved heading band (flex-shrink: 0, below the 4.5rem
   nav). Cards use matching padding so they never enter this slot.
   Short viewports shrink type + inset; ≥1080px keeps the first-slide gap. */
.globe-scroll-section {
  --globe-nav-clear: 4.5rem;
  --globe-heading-band: 8.5rem;
  --globe-card-inset: 8rem;
  --globe-card-inset-first: 9rem;
  --globe-last-pad: 6.75rem;
  --globe-card-gutter: 1.25rem;
}

.globe-scroll-heading {
  position: relative;
  z-index: 2;
  flex-shrink: 0;
  box-sizing: border-box;
  min-height: var(--globe-heading-band);
  padding-top: var(--globe-nav-clear);
  padding-bottom: 0.35rem;
}

.globe-scroll-heading-kicker {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: none;
  color: color-mix(in oklab, var(--foreground) 50%, transparent);
}

.globe-scroll-heading-title {
  margin-top: 0.25rem;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.2;
  color: var(--foreground);
}

.globe-scroll-heading .section-eyebrow {
  margin-top: 0.75rem;
}

.globe-scroll-article {
  padding-top: var(--globe-card-inset);
}

.globe-scroll-article:first-of-type {
  padding-top: var(--globe-card-inset-first);
}

.globe-scroll-article:last-of-type {
  z-index: 12;
  padding-bottom: var(--globe-last-pad);
}

.globe-scroll-article:last-of-type .globe-slide-card {
  position: relative;
  z-index: 13;
}

.globe-pin-caption {
  z-index: 3;
}

.globe-slide-card-foot {
  position: relative;
  z-index: 2;
}

@media (min-width: 640px) {
  .globe-scroll-section {
    --globe-heading-band: 10.25rem;
    --globe-card-inset: 11.25rem;
    --globe-card-inset-first: 12.5rem;
    --globe-last-pad: 7.5rem;
  }
}

@media (min-width: 1024px) {
  .globe-scroll-section {
    --globe-heading-band: 10.5rem;
    --globe-card-inset: 12.5rem;
    --globe-card-inset-first: 13.75rem;
  }
}

@media (max-height: 1079px) {
  .globe-scroll-section {
    --globe-heading-band: 8.75rem;
    --globe-card-inset: 9.25rem;
    --globe-card-inset-first: 9.75rem;
  }

  .globe-scroll-heading-title {
    font-size: 0.8125rem;
  }

  .globe-scroll-heading .section-eyebrow {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    letter-spacing: 0.12em;
  }
}

@media (max-height: 900px) {
  .globe-scroll-section {
    --globe-heading-band: 8.5rem;
    --globe-card-inset: 8.75rem;
    --globe-card-inset-first: 9.25rem;
  }
}

@media (max-height: 768px) {
  .globe-scroll-section {
    --globe-heading-band: 8.25rem;
    --globe-card-inset: 8.5rem;
    --globe-card-inset-first: 8.75rem;
  }

  .globe-scroll-heading-title {
    font-size: 0.75rem;
  }
}

@media (min-width: 1024px) and (min-height: 1080px) {
  .globe-scroll-section {
    --globe-heading-band: 10.5rem;
    --globe-card-inset: 12.5rem;
    --globe-card-inset-first: 13.75rem;
  }
}

.globe-apex-glow {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    42% 38% at 50% 14%,
    color-mix(in oklab, var(--primary) 50%, transparent),
    transparent 72%
  );
  opacity: 0.9;
  pointer-events: none;
}

.globe-text-rail {
  border-block: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, transparent);
  backdrop-filter: blur(10px);
  padding-block: clamp(2.5rem, 6vh, 4rem);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--background) 40%, transparent) inset,
    0 24px 60px -40px color-mix(in oklab, var(--foreground) 12%, transparent);
}

.globe-emblem-wrap {
  position: absolute;
  top: clamp(3.5rem, 12vh, 6rem);
  left: 50%;
  z-index: 3;
  transform: translateX(-50%);
}

.globe-axis-markers {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}

.globe-axis-line {
  position: absolute;
  left: 50%;
  width: 1px;
  background: color-mix(in oklab, var(--foreground) 35%, transparent);
  transform: translateX(-50%);
}

.globe-axis-line-top {
  top: clamp(6.5rem, 18vh, 9rem);
  height: clamp(2rem, 5vh, 3.5rem);
}

.globe-axis-line-bottom {
  bottom: clamp(4rem, 12vh, 6rem);
  height: clamp(2.5rem, 6vh, 4rem);
}

.globe-axis-plus {
  position: absolute;
  top: calc(clamp(6.5rem, 18vh, 9rem) + clamp(2rem, 5vh, 3.5rem) + 0.35rem);
  left: calc(50% + 0.65rem);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: color-mix(in oklab, var(--foreground) 70%, transparent);
}

.globe-crosshair-left,
.globe-crosshair-right {
  position: absolute;
  top: 50%;
  z-index: 2;
  width: clamp(2rem, 8vw, 5rem);
  height: 1px;
  background: color-mix(in oklab, var(--foreground) 30%, transparent);
  transform: translateY(-50%);
}

.globe-crosshair-left {
  left: clamp(0.75rem, 4vw, 2.5rem);
}

.globe-crosshair-right {
  right: clamp(0.75rem, 4vw, 2.5rem);
}

.globe-crosshair-left::after,
.globe-crosshair-right::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 1px;
  height: 10px;
  background: color-mix(in oklab, var(--foreground) 35%, transparent);
  transform: translateY(-50%);
}

.globe-crosshair-left::after {
  right: 0;
}

.globe-crosshair-right::after {
  left: 0;
}

.globe-side-index {
  position: absolute;
  top: 50%;
  z-index: 3;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  color: color-mix(in oklab, var(--foreground) 45%, transparent);
  transform: translateY(-50%);
}

.globe-side-index-left {
  left: clamp(1.25rem, 6vw, 3.5rem);
}

.globe-side-index-right {
  right: clamp(1.25rem, 6vw, 3.5rem);
}

.globe-frame-left,
.globe-frame-right {
  position: absolute;
  top: 12%;
  bottom: 12%;
  width: 1px;
  background: color-mix(in oklab, var(--foreground) 18%, transparent);
}

.globe-frame-left {
  left: clamp(1.5rem, 8vw, 5rem);
}

.globe-frame-right {
  right: clamp(1.5rem, 8vw, 5rem);
}

.globe-frame-left::before,
.globe-frame-right::before {
  content: "";
  position: absolute;
  top: 0;
  width: 10px;
  height: 1px;
  background: var(--foreground);
  opacity: 0.35;
}

.globe-frame-left::before {
  left: 0;
}

.globe-frame-right::before {
  right: 0;
}

.globe-frame-left::after,
.globe-frame-right::after {
  content: "";
  position: absolute;
  bottom: 0;
  width: 10px;
  height: 1px;
  background: var(--foreground);
  opacity: 0.35;
}

.globe-frame-left::after {
  left: 0;
}

.globe-frame-right::after {
  right: 0;
}

@media (min-width: 1024px) {
  .sticky-scroll-panel {
    scroll-margin-top: 6rem;
  }
}

@utility reveal {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  &[data-visible="true"] {
    opacity: 1;
    transform: none;
  }
}

@utility lift {
  transition:
    transform 0.3s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.3s ease,
    border-color 0.3s ease;
  &:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lift);
    border-color: color-mix(in oklab, var(--primary) 35%, transparent);
  }
}

@utility caret {
  &::after {
    content: "";
    display: inline-block;
    width: 0.06em;
    min-width: 2px;
    height: 1em;
    margin-left: 0.12em;
    vertical-align: -0.12em;
    background: currentColor;
    animation: blink 1s steps(2, start) infinite;
  }
}

@keyframes blink {
  to {
    visibility: hidden;
  }
}

@keyframes hero-ken-burns {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.08);
  }
}

@keyframes hero-copy-in {
  from {
    opacity: 0;
    transform: translateY(1.25rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes hero-slide-progress {
  from {
    width: 0%;
  }
  to {
    width: 100%;
  }
}

@utility hero-ken-burns {
  animation: hero-ken-burns 14s ease-out forwards;
}

.hero-copy-item {
  opacity: 0;
  animation: hero-copy-in 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.hero-copy-delay-0 {
  animation-delay: 0ms;
}
.hero-copy-delay-1 {
  animation-delay: 90ms;
}
.hero-copy-delay-2 {
  animation-delay: 180ms;
}
.hero-copy-delay-3 {
  animation-delay: 270ms;
}
.hero-copy-delay-4 {
  animation-delay: 360ms;
}
.hero-copy-delay-5 {
  animation-delay: 450ms;
}
.hero-copy-delay-6 {
  animation-delay: 540ms;
}

.hero-slide-progress {
  animation: hero-slide-progress linear forwards;
}

/* Hero copy — stable height from tallest slide (no clipping) */

.hero-copy {
  display: grid;
  align-items: start;
}

.hero-copy-layer {
  grid-area: 1 / 1;
  width: 100%;
}

.hero-copy-layer-measure {
  visibility: hidden;
  pointer-events: none;
  user-select: none;
}

.hero-copy-layer-active {
  z-index: 1;
}

.hero-copy-typewriter {
  display: block;
  min-height: 1.12em;
}

/* Hero abstract mesh (no stock imagery) --------------------------- */

.hero-mesh-bg {
  background:
    radial-gradient(ellipse 80% 60% at 15% 20%, color-mix(in oklab, var(--primary) 22%, transparent), transparent 58%),
    radial-gradient(ellipse 70% 55% at 85% 75%, color-mix(in oklab, var(--primary) 14%, transparent), transparent 55%),
    radial-gradient(circle at 50% 100%, oklch(0.12 0.03 160), oklch(0.08 0.02 165));
}

.hero-mesh-bg::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(oklch(1 0 0 / 0.04) 1px, transparent 1px),
    linear-gradient(90deg, oklch(1 0 0 / 0.04) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(180deg, black, transparent 95%);
}

.hero-mesh-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 40%, oklch(1 0 0 / 0.03), transparent 35%);
  animation: hero-mesh-drift 18s ease-in-out infinite alternate;
}

@keyframes hero-mesh-drift {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(2%, -1.5%, 0) scale(1.04);
  }
}

/* Hero ecosystem visualization ---------------------------------- */

.hero-eco-scene {
  perspective: 1600px;
  perspective-origin: 50% 42%;
  position: relative;
  width: 100%;
  max-width: 44rem;
  margin-inline: auto;
  padding: 1rem 0.25rem 1.5rem;
}

.hero-eco-ambient {
  pointer-events: none;
  position: absolute;
  inset: 6% 2% 10%;
  z-index: 0;
  border-radius: 1.5rem;
  background: radial-gradient(
    ellipse 75% 60% at 50% 45%,
    color-mix(in oklab, var(--primary) 24%, transparent),
    transparent 72%
  );
  filter: blur(30px);
  opacity: 0.9;
  animation: hero-eco-ambient 7s ease-in-out infinite;
}

@keyframes hero-eco-ambient {
  0%,
  100% {
    opacity: 0.65;
    transform: scale(0.96);
  }
  50% {
    opacity: 1;
    transform: scale(1.03);
  }
}

.hero-eco-card {
  --tilt-x: 8deg;
  --tilt-y: -16deg;
  --tilt-glare-x: 32%;
  --tilt-glare-y: 22%;
  --ht-bg: oklch(0.995 0.004 155);
  --ht-panel: oklch(0.985 0.007 155);
  --ht-elevated: oklch(0.972 0.012 155);
  --ht-border: oklch(0.88 0.018 155);
  --ht-text: oklch(0.24 0.03 160);
  --ht-muted: oklch(0.5 0.025 160);
  --ht-faint: oklch(0.68 0.02 160);
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  min-height: 28rem;
  transform-style: preserve-3d;
  transform: rotateX(var(--tilt-x)) rotateY(var(--tilt-y)) rotateZ(-1.5deg);
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
  border-radius: 1.15rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-bg);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.85) inset,
    0 28px 64px -32px oklch(0.28 0.06 160 / 0.4),
    0 0 0 1px oklch(1 0 0 / 0.55) inset,
    0 0 52px -8px color-mix(in oklab, var(--primary) 30%, transparent);
  overflow: hidden;
}

.hero-eco-alive {
  animation: hero-eco-float 6s ease-in-out infinite;
}

@keyframes hero-eco-float {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -7px;
  }
}

.hero-eco-scene:hover .hero-eco-card {
  animation-play-state: paused;
  transition-duration: 0.12s;
}

.hero-eco-grid-bg {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.5;
  background-image:
    linear-gradient(var(--ht-border) 1px, transparent 1px),
    linear-gradient(90deg, var(--ht-border) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: linear-gradient(180deg, black, transparent 94%);
}

.hero-eco-glare {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 5;
  border-radius: inherit;
  background: radial-gradient(
    circle at var(--tilt-glare-x) var(--tilt-glare-y),
    oklch(1 0 0 / 0.72),
    transparent 48%
  );
  mix-blend-mode: soft-light;
}

.hero-eco-scan {
  pointer-events: none;
  position: absolute;
  inset-inline: 0;
  top: 0;
  z-index: 4;
  height: 32%;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 12%, transparent),
    transparent
  );
  animation: hero-tilt-scan 4.8s ease-in-out infinite;
}

.hero-eco-chrome {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  padding: 0.75rem 0.95rem;
  border-bottom: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.76);
  backdrop-filter: blur(10px);
}

.hero-eco-dots {
  display: inline-flex;
  gap: 0.35rem;
}

.hero-eco-dots i {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 999px;
  background: #ff5f57;
}

.hero-eco-dots i:nth-child(2) {
  background: #febc2e;
}

.hero-eco-dots i:nth-child(3) {
  background: #28c840;
}

.hero-eco-path {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  border-radius: 999px;
  border: 1px solid var(--ht-border);
  background: var(--ht-elevated);
  padding: 0.28rem 0.7rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-eco-brand-tab {
  flex: 1;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-eco-ticker {
  position: relative;
  z-index: 2;
  overflow: hidden;
  border-bottom: 1px solid var(--ht-border);
  background: color-mix(in oklab, var(--primary) 6%, oklch(1 0 0));
  padding: 0.3rem 0;
}

.hero-eco-ticker-track {
  display: flex;
  width: max-content;
  gap: 1.5rem;
  padding-inline: 0.95rem;
  animation: hero-eco-ticker 16s linear infinite;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--ht-muted);
  white-space: nowrap;
}

.hero-eco-ticker-track span::before {
  content: "●";
  margin-right: 0.45rem;
  color: var(--primary);
  font-size: 6px;
}

@keyframes hero-eco-ticker {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

.hero-eco-live {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.hero-eco-live-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
  animation: partner-blink 1.8s ease-in-out infinite;
}

.hero-eco-body {
  position: relative;
  z-index: 2;
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.85rem 0.95rem 1rem;
}

.hero-eco-kicker {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: none;
  color: var(--primary);
}

.hero-eco-title {
  max-width: 22rem;
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--ht-text);
}

.hero-eco-orbit-wrap {
  position: relative;
  flex-shrink: 0;
  min-height: 12.5rem;
  margin-top: 0.15rem;
}

.hero-eco-orbit-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.hero-eco-orbit-ring {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 22%, var(--ht-border));
  stroke-width: 1;
}

.hero-eco-orbit-ring-outer {
  stroke-dasharray: 4 7;
  animation: constellation-spin 28s linear infinite;
}

.hero-eco-orbit-ring-inner {
  stroke-dasharray: 2 6;
  animation: constellation-spin 20s linear infinite reverse;
}

.hero-eco-spoke {
  stroke: color-mix(in oklab, var(--primary) 18%, var(--ht-border));
  stroke-width: 1;
  stroke-dasharray: 3 5;
}

.hero-eco-spoke[data-active="true"] {
  stroke: color-mix(in oklab, var(--primary) 55%, var(--ht-border));
  stroke-width: 1.5;
  stroke-dasharray: none;
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 35%, transparent));
}

.hero-eco-spoke-node {
  fill: var(--ht-faint);
  opacity: 0.7;
}

.hero-eco-spoke-node[data-active="true"] {
  fill: var(--primary);
  opacity: 1;
}

.hero-eco-data-pulse {
  fill: var(--primary);
  opacity: 0;
}

.hero-eco-data-pulse[data-active="true"] {
  opacity: 0.95;
}

.hero-eco-pipeline-track {
  fill: none;
  stroke: var(--ht-border);
  stroke-width: 1.5;
}

.hero-eco-pipeline-flow {
  fill: none;
  stroke: url(#hero-eco-flow);
  stroke-width: 2;
  stroke-dasharray: 8 14;
  animation: hero-eco-dash 2.4s linear infinite;
}

@keyframes hero-eco-dash {
  to {
    stroke-dashoffset: -44;
  }
}

.hero-eco-core {
  position: absolute;
  left: 50%;
  top: 44%;
  z-index: 3;
  translate: -50% -50%;
}

.hero-eco-core-ring {
  position: absolute;
  inset: -1.35rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, var(--ht-border));
  animation: hero-eco-pulse-ring 3s ease-out infinite;
}

.hero-eco-core-ring-2 {
  inset: -2rem;
  animation-delay: 1.1s;
}

@keyframes hero-eco-pulse-ring {
  0% {
    transform: scale(0.92);
    opacity: 0.55;
  }
  70% {
    transform: scale(1.08);
    opacity: 0;
  }
  100% {
    transform: scale(1.08);
    opacity: 0;
  }
}

.hero-eco-core-inner {
  position: relative;
  z-index: 1;
  display: flex;
  width: 7.25rem;
  height: 7.25rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 42%, var(--ht-border));
  background:
    radial-gradient(
      circle at 35% 30%,
      color-mix(in oklab, var(--primary) 16%, oklch(1 0 0)),
      oklch(1 0 0 / 0.94)
    );
  box-shadow:
    0 0 32px color-mix(in oklab, var(--primary) 24%, transparent),
    inset 0 0 0 1px oklch(1 0 0 / 0.75);
  text-align: center;
}

.hero-eco-core-mark {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1;
  color: var(--ht-text);
}

.hero-eco-core-label {
  margin-top: 0.2rem;
  font-size: 0.62rem;
  font-weight: 700;
  line-height: 1.1;
  color: var(--ht-text);
}

.hero-eco-core-sub {
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.hero-eco-cap {
  position: absolute;
  left: 50%;
  top: 44%;
  z-index: 4;
  display: flex;
  width: 5.5rem;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  text-align: center;
  transform: translate(-50%, -50%) rotate(var(--eco-angle)) translateY(-8.5rem)
    rotate(calc(-1 * var(--eco-angle)));
  animation:
    hero-eco-cap-in 0.6s cubic-bezier(0.22, 1, 0.36, 1) both,
    hero-eco-cap-float 4.5s ease-in-out infinite;
  animation-delay: 0s, var(--eco-float-delay, 0s);
  transition:
    scale 0.35s ease,
    filter 0.35s ease;
}

.hero-eco-cap-active .hero-eco-cap-icon {
  border-color: color-mix(in oklab, var(--primary) 50%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 10%, oklch(1 0 0));
  box-shadow:
    0 0 0 3px color-mix(in oklab, var(--primary) 14%, transparent),
    0 0 22px color-mix(in oklab, var(--primary) 28%, transparent);
  scale: 1.08;
}

.hero-eco-cap-active .hero-eco-cap-label {
  color: var(--primary);
}

@keyframes hero-eco-cap-float {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -3px;
  }
}

.hero-eco-console {
  flex-shrink: 0;
  border: 1px solid var(--ht-border);
  border-radius: 0.75rem;
  background: oklch(1 0 0 / 0.72);
  overflow: hidden;
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / 0.55);
}

.hero-eco-tabs {
  display: flex;
  gap: 0.25rem;
  padding: 0.45rem 0.45rem 0;
  border-bottom: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.82);
}

.hero-eco-tab {
  position: relative;
  flex: 1;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 0.45rem 0.45rem 0 0;
  background: transparent;
  padding: 0.38rem 0.35rem 0.48rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--ht-muted);
  cursor: pointer;
  transition:
    color 0.25s ease,
    background 0.25s ease,
    border-color 0.25s ease;
}

.hero-eco-tab[data-active="true"] {
  color: var(--primary);
  border-color: var(--ht-border);
  border-bottom-color: transparent;
  background: oklch(1 0 0 / 0.95);
}

.hero-eco-tab-fill {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  width: 100%;
  transform-origin: left;
  background: var(--primary);
  animation: partner-tab-fill linear forwards;
}

.hero-eco-panel-shell {
  min-height: 6.75rem;
  padding: 0.55rem 0.65rem 0.65rem;
}

.hero-eco-panel-swap {
  animation: hero-eco-panel-in 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes hero-eco-panel-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-eco-panel-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem;
  align-items: stretch;
}

.hero-eco-panel-grid-pricing {
  grid-template-columns: 1fr;
  gap: 0.45rem;
}

.hero-eco-panel-col {
  min-width: 0;
}

.hero-eco-panel-kicker {
  margin-bottom: 0.35rem;
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--ht-faint);
}

.hero-eco-mini-table {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.hero-eco-mini-row {
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 0.3rem;
  border-radius: 0.35rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  padding: 0.28rem 0.35rem;
  font-size: 9px;
  color: var(--ht-text);
  animation: hero-eco-row-in 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.hero-eco-mini-row[data-hot="true"] {
  border-color: color-mix(in oklab, var(--primary) 35%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 7%, oklch(1 0 0));
  box-shadow: inset 2px 0 0 var(--primary);
}

.hero-eco-mini-row strong {
  font-family: var(--font-mono);
  font-size: 9px;
}

.hero-eco-mini-row em {
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 700;
  color: var(--primary);
}

.hero-eco-mini-dot {
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: var(--ht-faint);
}

.hero-eco-mini-row[data-hot="true"] .hero-eco-mini-dot {
  background: var(--primary);
  animation: partner-blink 1.8s ease-in-out infinite;
}

@keyframes hero-eco-row-in {
  from {
    opacity: 0;
    transform: translateX(6px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.hero-eco-mini-bars {
  display: flex;
  height: 4.5rem;
  align-items: flex-end;
  gap: 0.28rem;
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  padding: 0.45rem 0.4rem 0.35rem;
}

.hero-eco-mini-bar {
  flex: 1;
  border-radius: 0.2rem 0.2rem 0 0;
  background: linear-gradient(
    180deg,
    var(--primary),
    color-mix(in oklab, var(--primary-deep) 80%, transparent)
  );
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 25%, transparent);
  transform-origin: bottom;
  animation: hero-eco-bar-grow 0.7s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes hero-eco-bar-grow {
  from {
    transform: scaleY(0.12);
    opacity: 0.35;
  }
  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

.hero-eco-price-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.75rem;
  border-radius: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--primary) 24%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 6%, oklch(1 0 0));
  padding: 0.45rem 0.55rem;
}

.hero-eco-price-value {
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
  line-height: 1;
  color: var(--ht-text);
}

.hero-eco-price-value span {
  margin-left: 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--primary);
}

.hero-eco-price-rails {
  display: flex;
  gap: 0.65rem;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--ht-muted);
  text-align: right;
}

.hero-eco-price-rails strong {
  display: block;
  margin-top: 0.1rem;
  font-size: 10px;
  color: var(--ht-text);
}

.hero-eco-spark-wrap {
  position: relative;
  height: 4.25rem;
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  overflow: hidden;
  padding: 0.35rem;
}

.hero-eco-spark-svg {
  width: 100%;
  height: 100%;
}

.hero-eco-spark-line {
  stroke: var(--primary);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-dasharray: 220;
  animation: hero-price-draw 1.1s ease-out both;
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 45%, transparent));
}

.hero-eco-spark-area {
  fill: color-mix(in oklab, var(--primary) 18%, transparent);
}

.hero-eco-spark-cursor {
  position: absolute;
  top: 22%;
  right: 10%;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
  animation: partner-blink 1.4s ease-in-out infinite;
}

.hero-eco-sync-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.35rem;
}

.hero-eco-sync-stats div {
  border-radius: 0.4rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  padding: 0.35rem 0.4rem;
  text-align: center;
}

.hero-eco-sync-stats strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.95rem;
  color: var(--ht-text);
}

.hero-eco-sync-stats span {
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-eco-sync-list {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.hero-eco-sync-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  border-radius: 0.35rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  padding: 0.28rem 0.4rem;
  font-size: 9px;
  color: var(--ht-text);
  animation: hero-eco-row-in 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.hero-eco-sync-line span:last-child {
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--primary);
}

.hero-eco-sync-line[data-ok="false"] span:last-child {
  color: var(--ht-faint);
}

.hero-eco-heat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.28rem;
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  padding: 0.4rem;
}

.hero-eco-heat-grid span {
  aspect-ratio: 1;
  border-radius: 0.2rem;
  background: var(--primary);
  animation: hero-eco-heat-pulse 2.4s ease-in-out infinite;
}

.hero-eco-heat-grid span[data-hot="true"] {
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 40%, transparent);
}

@keyframes hero-eco-heat-pulse {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.15);
  }
}

.hero-eco-coverage {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.35rem;
}

.hero-eco-coverage div {
  border-radius: 0.4rem;
  border: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.85);
  padding: 0.4rem 0.35rem;
  text-align: center;
}

.hero-eco-coverage span {
  display: block;
  margin-top: 0.1rem;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-eco-stat-num {
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--ht-text);
  animation: hero-eco-stat-pop 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes hero-eco-stat-pop {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-eco-foot-stat {
  font-weight: 700;
  color: var(--primary);
}

.hero-eco-packet-2 {
  width: 0.25rem;
  height: 0.25rem;
  opacity: 0.65;
}

@keyframes hero-eco-cap-in {
  from {
    opacity: 0;
    scale: 0.85;
  }
  to {
    opacity: 1;
    scale: 1;
  }
}

.hero-eco-cap-icon {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--ht-border));
  background: oklch(1 0 0 / 0.88);
  color: var(--primary);
  box-shadow: 0 0 16px color-mix(in oklab, var(--primary) 16%, transparent);
}

.hero-eco-cap-label {
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-eco-pipeline {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0;
  overflow-x: auto;
  padding-bottom: 0.15rem;
  scrollbar-width: none;
}

.hero-eco-pipeline::-webkit-scrollbar {
  display: none;
}

.hero-eco-pipeline-item {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.hero-eco-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  min-width: 4.35rem;
  text-align: center;
}

.hero-eco-node-dot {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 999px;
  background: var(--ht-faint);
  box-shadow: 0 0 0 3px oklch(1 0 0 / 0.8);
}

.hero-eco-node-label {
  font-size: 0.625rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--ht-muted);
}

.hero-eco-node-featured {
  min-width: 5.5rem;
}

.hero-eco-node-featured .hero-eco-node-dot {
  width: 0.75rem;
  height: 0.75rem;
  background: var(--primary);
  box-shadow:
    0 0 0 4px color-mix(in oklab, var(--primary) 18%, transparent),
    0 0 18px color-mix(in oklab, var(--primary) 35%, transparent);
  animation: partner-blink 2s ease-in-out infinite;
}

.hero-eco-node-featured .hero-eco-node-label {
  font-size: 0.6875rem;
  font-weight: 700;
  color: var(--ht-text);
}

.hero-eco-arrow {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: 1.35rem;
  height: 0.75rem;
  margin-inline: 0.1rem;
  flex-shrink: 0;
}

.hero-eco-arrow-line {
  width: 100%;
  height: 1px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 35%, var(--ht-border)),
    color-mix(in oklab, var(--primary) 65%, var(--ht-border))
  );
}

.hero-eco-arrow-head {
  position: absolute;
  right: 0;
  width: 0.35rem;
  height: 0.35rem;
  border-top: 1.5px solid var(--primary);
  border-right: 1.5px solid var(--primary);
  rotate: 45deg;
}

.hero-eco-packet {
  position: absolute;
  left: 0;
  top: 50%;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 55%, transparent);
  animation: hero-eco-packet 2.2s ease-in-out infinite;
}

@keyframes hero-eco-packet {
  0% {
    left: 0;
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  85% {
    opacity: 1;
  }
  100% {
    left: calc(100% - 0.35rem);
    opacity: 0;
  }
}

.hero-eco-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem;
  padding-top: 0.35rem;
  border-top: 1px dashed var(--ht-border);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--ht-muted);
}

@media (max-width: 1023px) {
  .hero-eco-scene {
    max-width: 28rem;
    padding-block: 0.5rem 1rem;
  }

  .hero-eco-card {
    min-height: 30rem;
  }

  .hero-eco-orbit-wrap {
    min-height: 11rem;
  }

  .hero-eco-cap {
    top: 44%;
    transform: translate(-50%, -50%) rotate(var(--eco-angle)) translateY(-7.25rem)
      rotate(calc(-1 * var(--eco-angle)));
    width: 4.75rem;
  }

  .hero-eco-cap-label {
    font-size: 7px;
  }

  .hero-eco-core-inner {
    width: 6.25rem;
    height: 6.25rem;
  }

  .hero-eco-node {
    min-width: 3.75rem;
  }

  .hero-eco-node-label {
    font-size: 0.5625rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-mesh-bg::after,
  .hero-eco-ambient,
  .hero-eco-alive,
  .hero-eco-scan,
  .hero-eco-ticker-track,
  .hero-eco-orbit-ring-outer,
  .hero-eco-orbit-ring-inner,
  .hero-eco-pipeline-flow,
  .hero-eco-core-ring,
  .hero-eco-cap,
  .hero-eco-packet,
  .hero-eco-packet-2,
  .hero-eco-tab-fill,
  .hero-eco-mini-bar,
  .hero-eco-spark-line,
  .hero-eco-spark-cursor,
  .hero-eco-heat-grid span,
  .hero-eco-live-dot,
  .hero-eco-node-featured .hero-eco-node-dot {
    animation: none;
  }

  .hero-eco-card {
    transform: rotateX(6deg) rotateY(-12deg);
  }
}

/* â”€â”€ Hero 3D tilt dashboard â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.hero-tilt-scene {
  perspective: 1600px;
  perspective-origin: 50% 40%;
  position: relative;
  width: 100%;
  max-width: 44rem;
  margin-inline: auto;
  padding: 1.5rem 0.25rem 2rem;
}

.hero-tilt-ambient {
  pointer-events: none;
  position: absolute;
  inset: 8% 4% 12%;
  z-index: 0;
  border-radius: 1.5rem;
  background:
    radial-gradient(
      ellipse 70% 55% at 50% 45%,
      color-mix(in oklab, var(--primary) 22%, transparent),
      transparent 72%
    );
  filter: blur(28px);
  opacity: 0.85;
  animation: hero-tilt-ambient 6s ease-in-out infinite;
}

@keyframes hero-tilt-ambient {
  0%,
  100% {
    opacity: 0.65;
    transform: scale(0.98);
  }
  50% {
    opacity: 0.95;
    transform: scale(1.02);
  }
}

.hero-tilt-card {
  --tilt-x: 10deg;
  --tilt-y: -20deg;
  --tilt-glare-x: 28%;
  --tilt-glare-y: 18%;
  --hero-card-h: 28rem;
  --ht-bg: oklch(0.995 0.004 155);
  --ht-panel: oklch(0.985 0.007 155);
  --ht-elevated: oklch(0.972 0.012 155);
  --ht-border: oklch(0.88 0.018 155);
  --ht-text: oklch(0.24 0.03 160);
  --ht-muted: oklch(0.5 0.025 160);
  --ht-faint: oklch(0.68 0.02 160);
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  height: var(--hero-card-h);
  min-height: var(--hero-card-h);
  max-height: var(--hero-card-h);
  transform-style: preserve-3d;
  transform: rotateX(var(--tilt-x)) rotateY(var(--tilt-y)) rotateZ(-2deg);
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
  border-radius: 1.15rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-bg);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.85) inset,
    0 28px 64px -32px oklch(0.28 0.06 160 / 0.38),
    0 0 0 1px oklch(1 0 0 / 0.55) inset,
    0 0 48px -10px color-mix(in oklab, var(--primary) 28%, transparent);
  overflow: hidden;
  will-change: transform;
}

.hero-tilt-grid-bg {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.55;
  background-image:
    linear-gradient(var(--ht-border) 1px, transparent 1px),
    linear-gradient(90deg, var(--ht-border) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: linear-gradient(180deg, black, transparent 92%);
}

.hero-tilt-alive {
  animation: hero-tilt-float 5.5s ease-in-out infinite;
}

@keyframes hero-tilt-float {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -8px;
  }
}

.hero-tilt-scene:hover .hero-tilt-card {
  transition-duration: 0.12s;
  animation-play-state: paused;
}

.hero-tilt-glare {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 5;
  border-radius: inherit;
  background: radial-gradient(
    circle at var(--tilt-glare-x) var(--tilt-glare-y),
    oklch(1 0 0 / 0.72),
    transparent 48%
  );
  mix-blend-mode: soft-light;
}

.hero-tilt-scan {
  pointer-events: none;
  position: absolute;
  inset-inline: 0;
  top: 0;
  z-index: 4;
  height: 35%;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 14%, transparent),
    transparent
  );
  animation: hero-tilt-scan 4.5s ease-in-out infinite;
}

@keyframes hero-tilt-scan {
  0%,
  100% {
    transform: translateY(-40%);
    opacity: 0.2;
  }
  50% {
    transform: translateY(180%);
    opacity: 0.65;
  }
}

.hero-tilt-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.8rem 1rem;
  border-bottom: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  background: color-mix(in oklab, var(--background) 4%, transparent);
}

.hero-tilt-url {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  max-width: 18rem;
  flex: 1;
  justify-content: center;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 6%, transparent);
  padding: 0.32rem 0.85rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 45%, transparent);
}

.hero-tilt-live-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
  animation: partner-blink 1.8s ease-in-out infinite;
}

.hero-tilt-lock {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  border: 1.5px solid color-mix(in oklab, var(--primary) 70%, transparent);
  box-shadow: inset 0 -3px 0 0 color-mix(in oklab, var(--primary) 40%, transparent);
}

.hero-tilt-body {
  display: grid;
  grid-template-columns: 3.5rem 1fr;
  gap: 0.75rem;
  padding: 0.9rem;
  min-height: 22rem;
}

.hero-tilt-body-modes {
  min-height: 23.5rem;
  padding-bottom: 0.35rem;
}

.hero-tilt-card[data-mode="intel"] {
  border-color: color-mix(in oklab, var(--primary) 32%, var(--ht-border));
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.92), var(--ht-bg) 38%),
    radial-gradient(
      ellipse 90% 60% at 100% 0%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 55%
    ),
    var(--ht-bg);
}

.hero-tilt-card[data-mode="pricing"] {
  border-color: color-mix(in oklab, var(--primary) 38%, var(--ht-border));
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.9), var(--ht-bg) 42%),
    radial-gradient(
      ellipse 80% 55% at 70% -10%,
      color-mix(in oklab, var(--primary) 12%, transparent),
      transparent 58%
    ),
    var(--ht-bg);
}

.hero-tilt-card[data-mode="sync"] {
  border-color: color-mix(in oklab, var(--primary) 36%, var(--ht-border));
  background:
    linear-gradient(180deg, oklch(1 0 0 / 0.9), var(--ht-bg) 40%),
    radial-gradient(
      circle at 42% 42%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 48%
    ),
    var(--ht-bg);
}

/* Full card shells (each mode owns chrome + body) --------------- */

.hero-shell {
  position: relative;
  z-index: 2;
  display: flex;
  height: 100%;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
}

.hero-shell-chrome {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  padding: 0.75rem 0.95rem;
  border-bottom: 1px solid var(--ht-border);
  background: oklch(1 0 0 / 0.72);
  backdrop-filter: blur(10px);
}

.hero-shell-chrome-pricing {
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 10%, oklch(1 0 0)),
    oklch(1 0 0 / 0.78) 58%
  );
  border-bottom-color: color-mix(in oklab, var(--primary) 24%, var(--ht-border));
}

.hero-shell-chrome-sync {
  background: oklch(1 0 0 / 0.76);
  border-bottom-style: dashed;
  border-bottom-color: color-mix(in oklab, var(--primary) 30%, var(--ht-border));
}

.hero-shell-dots {
  display: inline-flex;
  gap: 0.35rem;
}

.hero-shell-dots i {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 999px;
  background: #ff5f57;
}

.hero-shell-dots i:nth-child(2) {
  background: #febc2e;
}

.hero-shell-dots i:nth-child(3) {
  background: #28c840;
}

.hero-shell-path {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  border-radius: 999px;
  background: var(--ht-elevated);
  border: 1px solid var(--ht-border);
  padding: 0.28rem 0.7rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-shell-path-center {
  flex: 1;
  justify-content: center;
  background: transparent;
  border-color: transparent;
  color: var(--ht-faint);
}

.hero-shell-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.hero-shell-body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  gap: 0;
  overflow: hidden;
}

.hero-shell-body-pricing {
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem 0.95rem 0.45rem;
}

.hero-shell-body-sync {
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem 0.95rem 0.45rem;
}

.hero-mode-top {
  display: flex;
  flex-shrink: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.hero-mode-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.hero-mode-title {
  margin-top: 0.2rem;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--ht-text);
}

.hero-mode-pill {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 10%, oklch(1 0 0));
  padding: 0.3rem 0.65rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
  text-transform: none;
  box-shadow: 0 0 18px color-mix(in oklab, var(--primary) 18%, transparent);
}

.hero-mode-mini {
  margin-bottom: 0.35rem;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.14em;
