  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--ht-muted);
}

.hero-mode-pill-pulse {
  animation: partner-blink 1.6s ease-in-out infinite;
}

/* Intel — terminal rail + matrix */
.hero-intel-rail {
  display: flex;
  width: 2.75rem;
  flex-direction: column;
  align-items: center;
  gap: 0.45rem;
  padding: 0.85rem 0.45rem;
  border-right: 1px solid color-mix(in oklab, var(--primary) 22%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 6%, oklch(1 0 0));
}

.hero-intel-rail span {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 0.45rem;
  color: var(--ht-faint);
  border: 1px solid transparent;
}

.hero-intel-rail span[data-active="true"] {
  color: var(--primary);
  border-color: color-mix(in oklab, var(--primary) 35%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 12%, oklch(1 0 0));
  box-shadow: 0 0 16px color-mix(in oklab, var(--primary) 22%, transparent);
}

.hero-intel-rail-meta {
  margin-top: auto !important;
  height: auto !important;
  border: 0 !important;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  color: var(--ht-faint) !important;
}

.hero-intel-main {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.7rem 0.9rem 0.45rem;
  overflow: hidden;
}

.hero-intel-grid {
