/* Nav-height spacer. 4.5rem bar + extra gap so the pill clears the light overlay.
   Desktop (≥1024px) uses a larger clamp below — do not shrink it.
   Laptop 1024–1919 zooms .hero-fit-zoom to 0.85, so that band bumps the
   offset further so the extra pad still reads after zoom. */
.hero-fit-offset {
  height: calc(4.5rem + 1.75rem);
}

/* Homepage hero pill only — smaller than .section-eyebrow, not uppercase. */
.hero-fit .hero-copy .hero-copy-eyebrow {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  line-height: 1.3;
  text-transform: none;
  padding: 0.18rem 0.5rem;
}

/* Homepage hero — mobile (<1024px): one locked frame, console-led.
   Height is 100svh, never dvh: dvh re-measures when the mobile browser
   toolbar collapses, which resized the console slot mid-scroll.
   Every rule below targets a stable hook (.hero-copy-head/-lead/-actions,
   .hero-copy-dense/-brief/-tags) and NOT .hero-copy-delay-*, because the
   delay classes only exist on the active slide layer — sizing only the
   active layer let the hidden measure layers (default desktop type) set
   the grid height, so the reserved copy box changed on every slide swap.
   Copy on phones = pill + headline + typewriter + short body + two CTAs.
   Do not display:none the pill or short body — shrink type if the frame is tight.
   Long lead, dense body/bullets and tags stay desktop-only. */
@media (max-width: 1023px) {
  .hero-fit {
    height: 100vh;
    height: 100svh;
    max-height: 100svh;
    overflow: hidden;
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
  }

  .hero-fit-main {
    align-items: stretch;
    min-height: 0;
    overflow: visible;
  }

  .hero-fit-main > .container-page {
    flex: 1 1 auto;
    min-height: 0;
    padding-block: 0.45rem 0.2rem;
  }

  .hero-fit-grid {
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0.4rem;
  }

  .hero-copy {
    flex: 0 0 auto;
    min-width: 0;
    overflow: visible;
  }

  /* Long lead, dense body + detail list, tag row stay off on phones.
     Pill + shortBody stay visible (user-facing "info" on iPhone). */
  .hero-fit .hero-copy .hero-copy-lead,
  .hero-copy-dense,
  .hero-fit .hero-copy ul.hero-copy-tags {
    display: none;
  }

  .hero-fit .hero-copy .hero-copy-eyebrow {
    display: inline-flex;
    max-width: 100%;
    margin: 0;
    padding: 0.2rem 0.5rem;
    font-size: clamp(0.5625rem, 2.4vw, 0.6875rem);
    letter-spacing: 0.02em;
    line-height: 1.3;
    text-transform: none;
    border-radius: 9999px;
  }

  .hero-fit .hero-copy .hero-copy-head {
    margin-top: 0.45rem;
    padding-top: 0.12em;
    font-size: clamp(1.22rem, 5.2vw, 1.65rem);
    line-height: 1.25;
    overflow: visible;
    text-wrap: wrap;
  }

  .hero-fit .hero-copy-typewriter {
    margin-top: 0.2rem;
    padding-block: 0.08em;
    font-size: clamp(1.32rem, 5.8vw, 1.85rem);
    line-height: 1.22;
    min-height: 1.3em;
    overflow: visible;
  }

  /* Clamp is a guard rail, not a crop: three lines is more than any slide's
     shortBody needs, so the reserved height is identical on every slide. */
  .hero-fit .hero-copy p.hero-copy-brief {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
    margin-top: 0.4rem;
    font-size: clamp(0.75rem, 3.2vw, 0.875rem);
    line-height: 1.4;
  }

  .hero-fit .hero-copy .hero-copy-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    margin-top: 0.65rem;
  }

  .hero-fit .hero-copy .hero-copy-actions > a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 2.75rem;
    padding: 0.5rem 0.6rem;
    font-size: clamp(0.75rem, 3.3vw, 0.875rem);
    text-align: center;
    white-space: nowrap;
  }

  .hero-fit-dots {
    padding-top: 0.15rem;
    padding-bottom: max(0.55rem, env(safe-area-inset-bottom));
  }

  /* Console still owns the leftover row and bleeds the gutters, but is
     scaled ~12% off the previous full-slot 1.0 so it stays dominant
     without covering CTAs or cropping at 320–430px. Do not return to
     0.84/0.78 — those made the HUD a postage stamp. --hero-bleed only
     eats the gutter, so the stage can never be wider than the viewport.
     Scale is visual only; the reserved flex slot does not reflow. */
  .hero-fit-console {
    --hero-console-scale: 0.85;
    --hero-bleed: clamp(0.55rem, 1.5vw, 1.4rem);
    display: flex;
    flex: 1 1 0;
    min-height: 10.25rem;
    width: calc(100% + var(--hero-bleed) * 2);
    max-width: none;
    margin-inline: calc(var(--hero-bleed) * -1);
    justify-content: center;
    align-items: center;
    overflow: hidden;
  }

  .hero-fit-console .hero-tilt-scene {
    flex: 1 1 auto;
    width: 100%;
    max-width: 44rem;
    height: 100%;
    max-height: 34rem;
    margin-inline: auto;
    padding: 0.45rem 0.75rem 0.7rem;
    /* Deep perspective on purpose: a short one (900px) foreshortens so hard that the
       projected card loses ~12% of its height, which fights "console much bigger". */
    perspective: 1500px;
    perspective-origin: 50% 45%;
    transform: scale(var(--hero-console-scale));
    transform-origin: center center;
  }

  /* Tilted like desktop but shallower so the HUD stays readable, and static
     (no float) so nothing drifts or resizes while a slide plays. The angles are
     literal, not var(--tilt-*): a tap emits synthetic mouse events, and the
     pointer handler would otherwise write the desktop angles inline. */
  .hero-fit-console .hero-tilt-card {
    --hero-card-h: 100%;
    transform: rotateX(7.5deg) rotateY(-11deg) rotateZ(-1.4deg);
  }

  .hero-fit-console .hero-tilt-alive {
    animation: none;
  }

  .hero-fit-console .hero-tilt-ambient {
    inset: 6% 6% 10%;
  }
}

/* Short screens (≤700px tall, incl. Safari chrome on many iPhones): keep
   pill + short body, shrink type instead of display:none. iPhone 375/390
   innerHeight often lands under 700px with the URL bar expanded. */
@media (max-width: 1023px) and (max-height: 700px) {
  .hero-fit .hero-copy .hero-copy-eyebrow {
    font-size: 0.5625rem;
    padding: 0.16rem 0.45rem;
    letter-spacing: 0.02em;
    text-transform: none;
  }

  .hero-fit .hero-copy .hero-copy-head {
    margin-top: 0.35rem;
    padding-top: 0.14em;
    font-size: clamp(1.12rem, 4.8vw, 1.45rem);
    line-height: 1.26;
  }

  .hero-fit .hero-copy-typewriter {
    font-size: clamp(1.2rem, 5.4vw, 1.6rem);
    line-height: 1.24;
  }

  .hero-fit .hero-copy p.hero-copy-brief {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    margin-top: 0.3rem;
    font-size: clamp(0.7rem, 3vw, 0.8125rem);
    line-height: 1.35;
  }

  .hero-fit .hero-copy .hero-copy-actions {
    margin-top: 0.5rem;
  }

  .hero-fit-console {
    --hero-console-scale: 0.82;
    min-height: 9.5rem;
  }
}

/* Tablets still use the mobile lock, but they have far more height to give the
   console, so lift the phone caps instead of leaving dead space around the card.
   Type boost is gated on min-height so iPhone landscape (≥640px wide, short)
   keeps the short-screen sizes above. */
@media (min-width: 640px) and (max-width: 1023px) and (min-height: 701px) {
  .hero-fit .hero-copy .hero-copy-eyebrow {
    font-size: 0.6875rem;
    padding: 0.18rem 0.5rem;
  }

  .hero-fit .hero-copy .hero-copy-head {
    font-size: clamp(1.75rem, 3.6vw, 2.35rem);
    line-height: 1.22;
  }

  .hero-fit .hero-copy-typewriter {
    font-size: clamp(1.95rem, 4vw, 2.6rem);
    line-height: 1.2;
  }

  .hero-fit .hero-copy p.hero-copy-brief {
    font-size: 1rem;
  }
}

@media (min-width: 640px) and (max-width: 1023px) {
  .hero-fit .hero-copy .hero-copy-actions {
    grid-template-columns: repeat(2, minmax(0, max-content));
    gap: 0.75rem;
  }

  .hero-fit .hero-copy .hero-copy-actions > a {
    padding-inline: 1.25rem;
    font-size: 0.9375rem;
  }

  .hero-fit-console .hero-tilt-scene {
    max-width: 52rem;
    max-height: 46rem;
  }
}

/* Landscape phones — side by side instead of stacked, so the console keeps a
   usable height and the CTAs stay above the fold. */
@media (max-width: 1023px) and (orientation: landscape) and (max-height: 560px) {
  .hero-fit-grid {
    flex-direction: row;
    align-items: center;
    gap: 0.85rem;
  }

  .hero-copy {
    flex: 0 1 45%;
  }

  /* align-self must stay stretch: the scene/card height is a percentage, and a
     center-aligned flex item would only be as tall as its content. */
  .hero-fit-console {
    flex: 1 1 0;
    align-self: stretch;
    min-height: 0;
    width: auto;
    margin-inline: 0;
  }

  .hero-fit-console .hero-tilt-scene {
    padding: 0.3rem 0.4rem 0.45rem;
  }
}

/* Transparent to the mobile 3-row grid. Desktop: flex column so rows size to content. */
.hero-fit-zoom {
  display: contents;
}

/* Homepage hero — desktop / MacBook: copy + console as one centered unit.
   min-height 100dvh (not a locked height) so short laptops grow instead of cropping.
   Do not use minmax(0,1fr) here — that shrinks the middle row and clips CTAs/dots. */
@media (min-width: 1024px) {
  .hero-fit {
    display: flex;
    flex-direction: column;
    height: auto;
    max-height: none;
    min-height: 100dvh;
  }

  .hero-fit-zoom {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-height: min-content;
  }

  /* nav ~4.5rem + extra breathing room so the pill clears the overlay */
  .hero-fit-offset {
    height: clamp(7.5rem, 6.25rem + 4.5vh, 9.25rem);
  }

  .hero-fit .hero-copy .hero-copy-eyebrow {
    font-size: 0.6875rem;
    padding: 0.18rem 0.5rem;
    letter-spacing: 0.02em;
    text-transform: none;
  }

  .hero-fit-main {
    flex: 1 1 auto;
    align-items: center;
    min-height: auto;
    overflow: visible;
  }

  .hero-fit-main > .container-page {
    justify-content: center;
    padding-block: clamp(1.25rem, 2.2vh, 2rem) clamp(1.5rem, 2.8vh, 2.5rem);
  }

  .hero-fit-grid {
    align-items: start;
    justify-content: center;
    column-gap: clamp(1.5rem, 2.4vw, 2.75rem);
  }

  .hero-fit .hero-copy .hero-copy-delay-6,
  .hero-fit .hero-copy ul.hero-copy-tags {
    margin-top: 1.75rem;
  }

  .hero-fit-dots {
    flex-shrink: 0;
    padding-bottom: clamp(1.75rem, 3vh, 2.75rem);
    padding-top: 0.5rem;
  }

  .hero-fit-console {
    --hero-console-scale: 1;
  }

  .hero-fit-console .hero-tilt-scene {
    transform: scale(var(--hero-console-scale));
    transform-origin: top left;
  }
}

/* Laptop / MacBook CSS px (1024–1919): 85% zoom on the whole inner hero
   (offset + copy + console + CTAs + dots). 1512×982, 1440×900, 1680×1050.
   ≥1920px stays 100% so this does not stack on any large-screen html zoom. */
@media (min-width: 1024px) and (max-width: 1919px) {
  .hero-fit-zoom {
    flex: 0 0 auto;
    zoom: 0.85;
  }

  /* Offset lives inside .hero-fit-zoom. Bump it so extra top pad still reads
     after 0.85 zoom (~2.85rem visual gap below the 4.5rem nav). */
  .hero-fit-offset {
    height: clamp(8.65rem, 7.25rem + 5.5vh, 11rem);
  }

  .hero-fit-console {
    --hero-console-scale: 1;
  }

  .hero-fit-console .hero-tilt-scene {
    margin-bottom: 0;
  }
}

@supports not (zoom: 0.85) {
  @media (min-width: 1024px) and (max-width: 1919px) {
    .hero-fit-zoom {
      transform: scale(0.85);
      transform-origin: top center;
    }
  }
}

/* Wide but short windows (≥1920 CSS px) — console-only scale, no extra hero zoom. */
@media (min-width: 1920px) and (max-height: 980px) {
  .hero-fit-console {
    --hero-console-scale: 0.88;
  }

  .hero-fit-console .hero-tilt-scene {
    margin-bottom: calc((var(--hero-card-h, 28rem) + 3.5rem) * (var(--hero-console-scale) - 1));
  }
}

@media (min-width: 1920px) and (max-height: 900px) {
  .hero-fit-console {
    --hero-console-scale: 0.8;
  }
}

@media (min-width: 1920px) and (max-height: 820px) {
  .hero-fit-console {
    --hero-console-scale: 0.72;
  }
}

@media (min-width: 1024px) {
  .container-nav {
    max-width: min(100%, 94rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-tilt-card,
  .hero-tilt-alive,
  .hero-tilt-ambient {
    transition: none;
    animation: none;
    transform: rotateX(6deg) rotateY(-12deg);
  }
  .hero-tilt-bar,
  .hero-tilt-swap,
  .hero-tilt-list-row,
  .hero-tilt-scan,
  .hero-tilt-live-dot,
  .hero-price-spark-line,
  .hero-price-tape-track,
  .hero-sync-orbit-ring,
  .hero-sync-pulse,
  .hero-spin,
  .hero-mode-tab-fill,
  .hero-mode-pill-pulse {
    animation: none;
  }
}

/* Mobile console keeps its 3D tilt (set in the hero-fit block above) but never
   floats — the drift is what made the locked frame feel unstable. */
@media (max-width: 1023px) {
  .hero-fit-console .hero-tilt-alive {
    animation: none;
  }

  .hero-fit-console .hero-tilt-scene:hover .hero-tilt-card {
    transform: rotateX(7.5deg) rotateY(-11deg) rotateZ(-1.4deg);
  }
}

