  display: grid;
  gap: 0.1rem;
  padding: 0.45rem 0.55rem;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  background: color-mix(in oklab, var(--surface) 70%, var(--background));
}

.how-it-desk-rail-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--foreground);
}

.how-it-desk-rail-hint {
  font-family: var(--font-mono);
  font-size: 0.625rem;
  color: var(--muted-foreground);
}

.how-it-desk-note {
  margin-top: auto;
  font-size: 0.75rem;
  line-height: 1.45;
  color: var(--muted-foreground);
}

/* 375px phones: drop the rail column so the ledger never scrolls sideways. */
@media (max-width: 29.9375rem) {
  .how-it-desk-rail-col {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .how-it-dot {
    transition: none;
  }
}

/* â”€â”€ Pipeline architecture diagram â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.tools-flow {
  --flow-ink: color-mix(in oklab, var(--primary) 50%, transparent);
  --flow-dash: 12px;
  background-image:
    radial-gradient(
      ellipse 120% 70% at 50% 0%,
      color-mix(in oklab, var(--primary) 7%, transparent),
      transparent 60%
    ),
    linear-gradient(color-mix(in oklab, var(--foreground) 3.5%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--foreground) 3.5%, transparent) 1px, transparent 1px);
  background-size:
    100% 100%,
    28px 28px,
    28px 28px;
}

.flow-corner {
  position: absolute;
  width: 0.75rem;
  height: 0.75rem;
  border-color: color-mix(in oklab, var(--primary) 55%, transparent);
  pointer-events: none;
}

.flow-corner-tl {
  top: -1px;
  left: -1px;
  border-top: 2px solid;
  border-left: 2px solid;
  border-top-left-radius: 0.5rem;
}
.flow-corner-tr {
  top: -1px;
  right: -1px;
  border-top: 2px solid;
  border-right: 2px solid;
  border-top-right-radius: 0.5rem;
}
.flow-corner-bl {
  bottom: -1px;
  left: -1px;
  border-bottom: 2px solid;
  border-left: 2px solid;
  border-bottom-left-radius: 0.5rem;
}
.flow-corner-br {
  bottom: -1px;
  right: -1px;
  border-bottom: 2px solid;
  border-right: 2px solid;
  border-bottom-right-radius: 0.5rem;
}

.flow-tier-label {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: none;
  color: color-mix(in oklab, var(--foreground) 45%, transparent);
}

.flow-status-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
}

.tools-flow[data-live="true"] .flow-status-dot {
  animation: flow-blink 1.8s ease-in-out infinite;
}

@keyframes flow-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

/* Dashed rails ------------------------------------------------- */

.flow-line-v {
  width: 2px;
  background-image: linear-gradient(
    180deg,
    var(--flow-ink) 0 6px,
    transparent 6px var(--flow-dash)
  );
  background-size: 2px var(--flow-dash);
  background-repeat: repeat-y;
}

.flow-line-h {
  height: 2px;
  background-image: linear-gradient(90deg, var(--flow-ink) 0 6px, transparent 6px var(--flow-dash));
  background-size: var(--flow-dash) 2px;
  background-repeat: repeat-x;
}

.tools-flow[data-live="true"] .flow-line-v {
  animation: flow-march-v 0.85s linear infinite;
}

.tools-flow[data-live="true"] .flow-line-h {
  animation: flow-march-h 0.85s linear infinite;
}

@keyframes flow-march-v {
  to {
    background-position-y: var(--flow-dash);
  }
}

@keyframes flow-march-h {
  to {
    background-position-x: var(--flow-dash);
  }
}

/* Junctions ---------------------------------------------------- */

.flow-junction {
  position: relative;
  width: 100%;
}

.flow-junction .flow-bus {
  position: absolute;
  top: 50%;
  left: calc(50% / var(--flow-cols, 3));
  right: calc(50% / var(--flow-cols, 3));
  transform: translateY(-50%);
}

.flow-junction .flow-trunk,
.flow-junction .flow-branch {
  position: absolute;
  transform: translateX(-50%);
}

.flow-junction .flow-trunk {
  left: 50%;
}

.flow-junction-in .flow-trunk {
  top: 50%;
  bottom: 0;
}
.flow-junction-in .flow-branch {
  top: 0;
  height: 50%;
}

.flow-junction-out .flow-trunk {
  top: 0;
  height: 50%;
}
.flow-junction-out .flow-branch {
  top: 50%;
  bottom: 0;
}

.flow-node {
  position: absolute;
  top: 50%;
  width: 9px;
  height: 9px;
  margin-top: -4.5px;
  transform: translateX(-50%);
  border-radius: 999px;
  background: var(--background);
  border: 2px solid color-mix(in oklab, var(--primary) 65%, transparent);
}

.flow-node-trunk {
  left: 50%;
  background: var(--primary);
  border-color: color-mix(in oklab, var(--primary) 35%, transparent);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--primary) 12%, transparent);
}

/* Column links ------------------------------------------------- */

.flow-link {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 4.25rem;
}

.flow-link-short {
  min-height: 1.75rem;
}

.flow-link-segment {
  position: relative;
  flex: 1;
  min-height: 0.75rem;
}

.flow-packet {
  margin-block: 0.35rem;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, transparent);
  background: var(--background);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--foreground) 55%, transparent);
  white-space: nowrap;
}

.flow-packet-inline {
  margin-top: 0.4rem;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: none;
  color: color-mix(in oklab, var(--primary-deep) 90%, transparent);
}

/* Travelling packets ------------------------------------------ */

.flow-pulse {
  position: absolute;
  left: 50%;
  top: 0;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 10px 3px color-mix(in oklab, var(--primary) 45%, transparent);
  transform: translate(-50%, -50%);
  opacity: 0;
}

.tools-flow[data-live="true"] .flow-pulse {
  animation: flow-travel 2.1s linear infinite;
}

.flow-junction-in .flow-trunk .flow-pulse {
  animation-delay: 0.5s;
}

@keyframes flow-travel {
  0% {
    top: 0;
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  85% {
    opacity: 1;
  }
  100% {
    top: 100%;
    opacity: 0;
  }
}

/* Blocks ------------------------------------------------------- */

.flow-source-ring {
  position: relative;
  border: 2px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: var(--background);
  box-shadow: 0 0 0 5px color-mix(in oklab, var(--primary) 7%, transparent);
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    transform 0.3s ease;
}

.flow-source:hover .flow-source-ring {
  transform: translateY(-3px);
  border-color: var(--primary);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--primary) 14%, transparent);
}

.flow-bar,
.flow-process {
  position: relative;
  overflow: hidden;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--primary-deep) 88%, var(--primary)),
    var(--primary-deep)
  );
  box-shadow: 0 14px 34px -22px color-mix(in oklab, var(--primary-deep) 65%, transparent);
}

.flow-bar::after,
.flow-process::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 35%,
    color-mix(in oklab, var(--background) 26%, transparent) 50%,
    transparent 65%
  );
  transform: translateX(-100%);
  pointer-events: none;
}

.tools-flow[data-live="true"] .flow-bar::after {
  animation: flow-sheen 3.6s ease-in-out infinite;
}

.tools-flow[data-live="true"] .flow-process::after {
  animation: flow-sheen 4.2s ease-in-out infinite;
}

.flow-bar-terminal::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--background) 22%, transparent);
  pointer-events: none;
}

@keyframes flow-sheen {
  0% {
    transform: translateX(-100%);
  }
  55%,
  100% {
    transform: translateX(100%);
  }
}

.flow-bar-dot {
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 70%, transparent);
}

.flow-card {
  position: relative;
  box-shadow: var(--shadow-card);
  transition:
    transform 0.3s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.flow-col:hover {
  --flow-ink: color-mix(in oklab, var(--primary) 95%, transparent);
}

.flow-col:hover .flow-card {
  transform: translateY(-4px);
  border-color: color-mix(in oklab, var(--primary) 38%, transparent);
  box-shadow: var(--shadow-lift);
}

.flow-col:hover .flow-packet {
  border-color: color-mix(in oklab, var(--primary) 45%, transparent);
  color: var(--primary-deep);
}

/* Collapse a junction to a single trunk when its row is stacked - */

@media (max-width: 1023px) {
  .flow-junction:not(.flow-junction-sm) {
    height: 2.5rem;
  }
  .flow-junction:not(.flow-junction-sm) .flow-bus,
  .flow-junction:not(.flow-junction-sm) .flow-branch,
  .flow-junction:not(.flow-junction-sm) .flow-node {
    display: none;
  }
  .flow-junction:not(.flow-junction-sm) .flow-trunk {
    top: 0;
    bottom: 0;
    height: auto;
  }
  .flow-link {
    min-height: 3.5rem;
  }
}

@media (max-width: 639px) {
  .flow-junction-sm {
    height: 2.5rem;
  }
  .flow-junction-sm .flow-bus,
  .flow-junction-sm .flow-branch,
  .flow-junction-sm .flow-node {
    display: none;
  }
  .flow-junction-sm .flow-trunk {
    top: 0;
    bottom: 0;
    height: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tools-flow[data-live="true"] .flow-line-v,
  .tools-flow[data-live="true"] .flow-line-h,
  .tools-flow[data-live="true"] .flow-pulse,
  .tools-flow[data-live="true"] .flow-bar::after,
  .tools-flow[data-live="true"] .flow-process::after,
  .tools-flow[data-live="true"] .flow-status-dot {
    animation: none;
  }
  .flow-pulse {
    display: none;
  }
}

/* â”€â”€ Platform toolkit showcase â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.toolkit {
  height: auto;
  overflow: hidden;
  background:
    radial-gradient(
      ellipse 70% 55% at 12% -5%,
      color-mix(in oklab, var(--primary) 20%, transparent),
      transparent 62%
    ),
    radial-gradient(
      ellipse 60% 55% at 92% 105%,
      color-mix(in oklab, var(--primary-deep) 42%, transparent),
      transparent 68%
    ),
    var(--dark);
}

.toolkit-bg-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(color-mix(in oklab, var(--background) 5%, transparent) 1px, transparent 1px),
    linear-gradient(
      90deg,
      color-mix(in oklab, var(--background) 5%, transparent) 1px,
      transparent 1px
    );
  background-size: 34px 34px;
  mask-image: radial-gradient(ellipse 80% 70% at 50% 30%, black, transparent 85%);
}

.toolkit-bg-scan {
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: 22rem;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 9%, transparent),
    transparent
  );
  animation: toolkit-scan 9s ease-in-out infinite;
}

@keyframes toolkit-scan {
  0%,
  100% {
    transform: translateY(-30%);
    opacity: 0.25;
  }
  50% {
    transform: translateY(190%);
    opacity: 0.7;
  }
}

.toolkit-live-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 20%, transparent);
  animation: toolkit-blink 1.9s ease-in-out infinite;
}

@keyframes toolkit-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

/* Progressive rail --------------------------------------------- */

.toolkit-step + .toolkit-step {
  border-top: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
}

.toolkit-rail {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 12%, transparent);
}

.toolkit-rail-fill {
  display: block;
  width: 100%;
  height: 100%;
  transform-origin: top;
  transform: scaleY(0);
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    var(--primary),
    color-mix(in oklab, var(--primary) 55%, transparent)
  );
  box-shadow: 0 0 14px color-mix(in oklab, var(--primary) 60%, transparent);
}

.toolkit-step[data-state="done"] .toolkit-rail-fill {
  transform: scaleY(1);
  opacity: 0.5;
}

.toolkit-step[data-state="active"] .toolkit-rail-fill {
  animation-name: toolkitFill;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
  animation-duration: 5200ms;
  transform: scaleY(1);
}

@keyframes toolkitFill {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}

.toolkit-step-button {
  cursor: pointer;
  transition: opacity 0.4s ease;
}

.toolkit-step-button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 4px;
  border-radius: 0.5rem;
}

.toolkit-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.25rem 0.6rem;
  border-radius: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--background) 16%, transparent);
  background: color-mix(in oklab, var(--background) 8%, transparent);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 75%, transparent);
  transition:
    color 0.3s ease,
    border-color 0.3s ease,
    background 0.3s ease;
}

.toolkit-headline {
  color: color-mix(in oklab, var(--background) 62%, transparent);
  transition: color 0.4s ease;
}

.toolkit-step[data-state="active"] .toolkit-headline {
  color: var(--background);
}

.toolkit-step[data-state="active"] .toolkit-chip {
  border-color: color-mix(in oklab, var(--primary) 45%, transparent);
  background: color-mix(in oklab, var(--primary) 16%, transparent);
  color: var(--primary);
}

.toolkit-step-button:hover .toolkit-headline {
  color: color-mix(in oklab, var(--background) 88%, transparent);
}

.toolkit-reveal {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition:
    grid-template-rows 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.4s ease;
}

.toolkit-reveal > * {
  overflow: hidden;
}

.toolkit-step[data-state="active"] .toolkit-reveal {
  grid-template-rows: 1fr;
  opacity: 1;
}

.toolkit-telemetry {
  position: relative;
  padding-left: 0.7rem;
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.toolkit-telemetry::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 4px;
  height: 4px;
  margin-top: -2px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 80%, transparent);
}

/* Layered panel stack ------------------------------------------ */

.toolkit-stage {
  min-height: 0;
}

.toolkit-rail-list {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--primary) 35%, transparent) transparent;
}

.toolkit-rail-lock {
  position: relative;
  display: grid;
  min-height: 0;
}

.toolkit-rail-ghost {
  visibility: hidden;
  pointer-events: none;
}

.toolkit-reveal-ghost-slot {
  display: grid;
}

.toolkit-reveal-ghost-panel {
  grid-area: 1 / 1;
}

.toolkit-reveal-slot {
  border-top: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
}

.toolkit-rail-list:not(.toolkit-rail-ghost) .toolkit-reveal-ghost-panel {
  visibility: hidden;
  pointer-events: none;
}

.toolkit-rail-list:not(.toolkit-rail-ghost) .toolkit-reveal-ghost-panel[data-active="true"] {
  visibility: visible;
  pointer-events: auto;
}

/* Live rail overlays the ghost so reserved copy cannot grow the page. */
@media (max-width: 1023px) {
  .toolkit-rail-lock > .toolkit-rail-list:not(.toolkit-rail-ghost) {
    position: absolute;
    inset: 0;
    z-index: 1;
    overflow: visible;
  }
}

@media (min-width: 1024px) {
  /* Document flow like HowItWorks: no 100svh lock, no inner wheel trap.
     Nav is ~4.5rem solid light — do not pin this section under it. */
  .toolkit {
    height: auto;
    max-height: none;
    overflow: hidden;
  }

  .toolkit > .container-page {
    flex: 1 1 auto;
    min-height: 0;
    display: flex;
    flex-direction: column;
  }

  .toolkit-stage {
    flex: 1 1 auto;
    min-height: 0;
    max-height: none;
    align-items: stretch;
  }

  .toolkit-rail-lock {
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: visible;
  }

  .toolkit-rail-ghost {
    display: none;
  }

  .toolkit-rail-lock > .toolkit-rail-list {
    flex: 1 1 auto;
    min-height: 0;
    overflow: visible;
    overscroll-behavior: auto;
  }

  .toolkit-panel {
    display: flex;
    min-height: 0;
    max-height: none;
    flex-direction: column;
    align-self: stretch;
    overflow: hidden;
  }

  .toolkit-stack {
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
    flex-direction: column;
  }

  .toolkit-main {
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
    flex-direction: column;
  }

  .toolkit-screen {
    flex: 0 0 auto;
    min-height: 0;
    height: auto;
    max-height: none;
  }
}

.toolkit-rail-list::-webkit-scrollbar {
  width: 4px;
}

.toolkit-rail-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 40%, transparent);
}

@media (max-width: 1023px) {
  .toolkit-stack {
    padding-inline-end: 0;
    padding-bottom: 0.25rem;
  }
  .toolkit-ghost {
    display: none;
  }
  .toolkit-float {
    position: relative;
    right: auto;
    bottom: auto;
    margin-top: 0.75rem;
    width: fit-content;
    max-width: 100%;
    transform: none;
  }
  .toolkit-headline {
    overflow-wrap: anywhere;
  }
}

@media (max-width: 639px) {
  .toolkit-step-button {
    min-height: 2.75rem;
  }

  .toolkit-screen {
    aspect-ratio: 16 / 11;
  }
}

.toolkit-stack {
  --tk-px: 0;
  --tk-py: 0;
}

.toolkit-layer {
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.toolkit-ghost {
  position: absolute;
  top: 0;
  left: 2.5rem;
  right: 4.5rem;
  bottom: 3rem;
  border-radius: 1.25rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
  transform: translate3d(calc(var(--tk-px) * -10px), calc(var(--tk-py) * -8px), 0) rotate(-1.2deg);
}

.toolkit-main {
  position: relative;
  overflow: hidden;
  border-radius: 1.1rem;
  border: 1px solid color-mix(in oklab, var(--background) 16%, transparent);
  background: color-mix(in oklab, var(--dark) 82%, var(--background));
  box-shadow:
    0 40px 90px -45px oklch(0 0 0 / 0.75),
    0 0 0 1px color-mix(in oklab, var(--primary) 14%, transparent);
  transform: translate3d(calc(var(--tk-px) * 12px), calc(var(--tk-py) * 10px), 0);
}

.toolkit-hud {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.65rem 0.9rem;
  border-bottom: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
}

.toolkit-hud-path {
  display: grid;
  min-width: 0;
}

.toolkit-hud-path > span {
  grid-area: 1 / 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  visibility: hidden;
}

.toolkit-hud-path > span[data-active="true"] {
  visibility: visible;
}

.toolkit-screen {
  position: relative;
  display: grid;
  aspect-ratio: 4 / 3;
  width: 100%;
  height: auto;
  min-height: 0;
  overflow: hidden;
  container-type: size;
  container-name: tks;
  background: color-mix(in oklab, var(--background) 96%, var(--primary));
}

.toolkit-swap-layer {
  grid-area: 1 / 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  visibility: hidden;
  pointer-events: none;
}

.toolkit-swap-layer[data-active="true"] {
  visibility: visible;
  pointer-events: auto;
  animation: toolkit-swap 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.toolkit-swap-layer > * {
  width: 100%;
  height: 100%;
}

.toolkit-segments {
  display: flex;
  gap: 4px;
  padding: 0.7rem 0.9rem;
  border-top: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
}

.toolkit-segment {
  flex: 1;
  height: 3px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 18%, transparent);
  transition:
    background 0.4s ease,
    box-shadow 0.4s ease;
}

.toolkit-segment[data-state="done"] {
  background: color-mix(in oklab, var(--primary) 45%, transparent);
}

.toolkit-segment[data-state="active"] {
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 65%, transparent);
}

.toolkit-float {
  position: absolute;
  right: 0;
  bottom: 0;
  display: grid;
  min-width: 8.5rem;
  padding: 0.9rem 1.1rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--dark) 88%, var(--background));
  box-shadow: 0 24px 55px -30px oklch(0 0 0 / 0.8);
  transform: translate3d(calc(var(--tk-px) * -22px), calc(var(--tk-py) * -16px), 0);
}

.toolkit-float-panel {
  grid-area: 1 / 1;
  visibility: hidden;
  pointer-events: none;
}

.toolkit-float-panel[data-active="true"] {
  visibility: visible;
  pointer-events: auto;
  animation: toolkit-swap 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.toolkit-meta-tag,
.toolkit-next-label {
  display: grid;
  min-width: 0;
}

.toolkit-meta-tag > span,
.toolkit-next-label > span {
  grid-area: 1 / 1;
  visibility: hidden;
}

.toolkit-meta-tag > span[data-active="true"],
.toolkit-next-label > span[data-active="true"] {
  visibility: visible;
}

.toolkit-swap {
  animation: toolkit-swap 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes toolkit-swap {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.toolkit-bar {
  transform-origin: bottom;
  animation: toolkit-bar-grow 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes toolkit-bar-grow {
  from {
    transform: scaleY(0.15);
    opacity: 0.4;
  }
  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

.toolkit-row {
  animation: toolkit-row-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes toolkit-row-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.toolkit-next {
  cursor: pointer;
  transition: gap 0.3s ease;
}

.toolkit-next:hover {
  gap: 0.75rem;
}

@media (prefers-reduced-motion: reduce) {
  .toolkit-bg-scan,
  .toolkit-live-dot,
  .toolkit-bar,
  .toolkit-row,
  .toolkit-swap,
  .toolkit-swap-layer[data-active="true"],
  .toolkit-float-panel[data-active="true"] {
    animation: none;
  }
  .toolkit-step[data-state="active"] .toolkit-rail-fill {
    animation: none;
    transform: scaleY(1);
  }
  .toolkit-layer {
    transform: none !important;
  }
}

/* â”€â”€ Stats (light variants) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.stats-ledger {
  background: color-mix(in oklab, var(--surface) 88%, var(--primary) 4%);
}

.stats-ledger-bar {
  animation: stats-ledger-grow 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes stats-ledger-grow {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

.stats-glow-card {
  box-shadow:
    0 0 0 1px transparent,
    0 20px 45px -30px color-mix(in oklab, var(--primary) 35%, transparent);
}

.stats-glow-card-halo {
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--primary) 25%, transparent),
    0 30px 60px -25px color-mix(in oklab, var(--primary) 45%, transparent);
}

/* â”€â”€ Section event backdrops (light Unsplash atmosphere) â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.section-backdrop {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.section-backdrop-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: grayscale(18%) saturate(0.75) contrast(1.05);
  transform: scale(1.04);
}

.section-backdrop-wash {
  position: absolute;
  inset: 0;
}

.section-backdrop[data-tone="light"] .section-backdrop-wash {
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 92%, transparent) 0%,
      color-mix(in oklab, var(--background) 88%, transparent) 45%,
      color-mix(in oklab, var(--background) 94%, transparent) 100%
    ),
    radial-gradient(
      ellipse 70% 55% at 80% 20%,
      color-mix(in oklab, var(--primary) 6%, transparent),
      transparent 70%
    );
}

.section-backdrop[data-tone="surface"] .section-backdrop-wash {
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--surface) 92%, transparent) 0%,
      color-mix(in oklab, var(--surface) 87%, transparent) 50%,
      color-mix(in oklab, var(--surface) 94%, transparent) 100%
    ),
    radial-gradient(
      ellipse 65% 50% at 15% 80%,
      color-mix(in oklab, var(--primary) 5%, transparent),
      transparent 72%
    );
}

.section-backdrop[data-tone="dark"] .section-backdrop-wash {
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--dark) 88%, transparent) 0%,
      color-mix(in oklab, var(--dark) 82%, transparent) 50%,
      color-mix(in oklab, var(--dark) 90%, transparent) 100%
    ),
    radial-gradient(
      ellipse 60% 45% at 70% 30%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 70%
    );
}

.section-backdrop-grid {
  position: absolute;
  inset: 0;
  opacity: 0.35;
  background-image:
    linear-gradient(color-mix(in oklab, var(--foreground) 4%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--foreground) 4%, transparent) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse 75% 70% at 50% 40%, black, transparent 88%);
}

.section-backdrop[data-tone="dark"] .section-backdrop-grid {
  background-image:
    linear-gradient(color-mix(in oklab, var(--background) 6%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--background) 6%, transparent) 1px, transparent 1px);
}

/* â”€â”€ Process bento â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* The scene's intrinsic ratio (and its aspect-ratio/min-height on mobile) was
   transferred up as a minimum inline size, so the 1fr track grew past the
   container and the cards were clipped on the right at 320px. */
.process-bento-grid > *,
.process-bento-card,
.process-bento-card .bento-scene {
  min-width: 0;
}

.process-bento-card {
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease,
    transform 0.35s ease;
}

.process-bento-card:hover {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  box-shadow: 0 28px 60px -40px color-mix(in oklab, var(--primary) 35%, transparent);
  transform: translateY(-2px);
}

@keyframes bento-flow-march {
  to {
    stroke-dashoffset: -48;
  }
}

@keyframes bento-node-float {
  0%,
  100% {
    transform: translate(-50%, -50%) translateY(0);
  }
  50% {
    transform: translate(-50%, -50%) translateY(-5px);
  }
}

@keyframes bento-node-float-centered {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
}

@keyframes bento-pulse-scale {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.08);
  }
}

@keyframes bento-audit-scroll {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-50%);
  }
}

@keyframes bento-orbit-rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes bento-orbit-travel {
  from {
    transform: rotate(0deg) translateX(var(--bento-orbit-r, 62px)) rotate(0deg);
  }
  to {
    transform: rotate(360deg) translateX(var(--bento-orbit-r, 62px)) rotate(-360deg);
  }
}

@keyframes bento-chart-march {
  to {
    stroke-dashoffset: -120;
  }
}

@keyframes bento-chart-breathe {
  0%,
  100% {
    opacity: 0.25;
  }
  50% {
    opacity: 0.45;
  }
}

@keyframes bento-price-float {
  0%,
  100% {
    transform: translate(-50%, -100%) translateY(0);
  }
  50% {
    transform: translate(-50%, -100%) translateY(-3px);
  }
}

@keyframes bento-launch-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@keyframes bento-connect-pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.35;
  }
  50% {
    transform: scale(1.45);
    opacity: 0.05;
  }
}

@keyframes bento-ghost-drift {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.45;
  }
  50% {
    transform: translateY(-6px);
    opacity: 0.7;
  }
}

.bento-flow-line {
  stroke-dasharray: 8 6;
  animation: bento-flow-march 1.4s linear infinite;
}

.bento-node-float {
  animation: bento-node-float 2.8s ease-in-out infinite;
}

.bento-pulse-dot {
  animation: bento-pulse-scale 2s ease-in-out infinite;
  transform-origin: center;
  transform-box: fill-box;
}

.bento-pulse-ring {
  animation: bento-pulse-scale 2.4s ease-in-out infinite;
  transform-origin: center;
  transform-box: fill-box;
}

.bento-packet {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 12px color-mix(in oklab, var(--primary) 65%, transparent);
  offset-path: path("M 150 40 Q 150 95 150 150");
  animation: bento-packet-run 2.2s ease-in-out infinite;
}

@keyframes bento-packet-run {
  0% {
    offset-distance: 0%;
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  90% {
    opacity: 1;
  }
  100% {
    offset-distance: 100%;
    opacity: 0;
  }
}

.bento-audit-fade {
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--muted) 50%, var(--background)) 0%,
    transparent 20%,
    transparent 80%,
    color-mix(in oklab, var(--muted) 50%, var(--background)) 100%
  );
}

.bento-audit-track {
  animation: bento-audit-scroll 14s linear infinite;
}

.bento-audit-hot {
  animation: bento-audit-glow 2.5s ease-in-out infinite;
}

@keyframes bento-audit-glow {
  0%,
  100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--primary) 0%, transparent);
  }
  50% {
    box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  }
}

.bento-orbit-spin {
  transform-origin: 150px 90px;
  animation: bento-orbit-rotate 22s linear infinite;
}

.bento-orbit-spin-reverse {
  transform-origin: 150px 90px;
  animation: bento-orbit-rotate 16s linear infinite reverse;
}

.bento-orbit-hub {
  position: absolute;
  left: 50%;
  top: 56%;
  width: 0;
  height: 0;
}

.bento-orbit-node {
  left: -16px;
  top: -16px;
  animation: bento-orbit-travel 12s linear infinite;
}

.bento-chart-line {
  stroke-dasharray: 14 10;
  animation: bento-chart-march 2.5s linear infinite;
}

.bento-chart-area {
  animation: bento-chart-breathe 3s ease-in-out infinite;
}

.bento-chart-grid {
  stroke-dasharray: 4 6;
  animation: bento-flow-march 2s linear infinite;
}

.bento-price-tag {
  white-space: nowrap;
  animation: bento-price-float 2.2s ease-in-out infinite;
}

/* Chart marker (HTML, not svg — see ReportIllustration) */
.bento-chart-marker {
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  translate: -50% -50%;
}

.bento-chart-marker i {
  position: absolute;
  border-radius: 999px;
  background: var(--primary);
}

.bento-chart-marker-dot {
  width: 10px;
  height: 10px;
  animation: bento-pulse-scale 2s ease-in-out infinite;
}

.bento-chart-marker-ring {
  width: 22px;
  height: 22px;
  opacity: 0.15;
  animation: bento-pulse-scale 2.4s ease-in-out infinite;
}

.bento-launch-panel {
  animation: bento-launch-float 3.2s ease-in-out infinite;
}

.bento-launch-panel-delay {
  animation-delay: 0.8s;
}

.bento-launch-flow {
  animation: bento-flow-march 1.2s linear infinite;
}

.bento-connect-ring {
  animation: bento-connect-pulse 2s ease-in-out infinite;
}

.bento-launch-ghost {
  position: absolute;
  border-radius: 0.65rem;
  background: color-mix(in oklab, var(--muted) 55%, transparent);
  animation: bento-ghost-drift 4s ease-in-out infinite;
}

.bento-launch-ghost-a {
  left: 1.25rem;
  top: 1.25rem;
  height: 3.25rem;
  width: 5rem;
}

.bento-launch-ghost-b {
  right: 1.5rem;
  bottom: 0.85rem;
  height: 2.5rem;
  width: 6rem;
  animation-delay: 1.2s;
}

/* Bento layered scene — background image + live visualization */

.bento-scene {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  width: 100%;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.55),
    0 16px 40px -32px color-mix(in oklab, var(--foreground) 18%, transparent);
}

.bento-scene--standard,
.bento-scene--wide {
  height: 11rem;
}

.bento-scene--chart {
  height: 10rem;
}

.bento-scene-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background: color-mix(in oklab, var(--muted) 40%, var(--background));
}

.bento-scene-photo {
  position: absolute;
  inset: -6%;
  width: 112%;
  height: 112%;
  object-fit: cover;
  object-position: var(--bento-bg-pos, center);
  opacity: var(--bento-bg-opacity, 0.9);
  transform: scale(var(--bento-bg-scale, 1.06));
  filter: saturate(1.04) contrast(1.03);
  animation: bento-bg-ken-burns 32s ease-in-out infinite alternate;
  will-change: transform;
}

.bento-scene-atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(
      180deg,
      oklch(0.995 0.002 247 / 0.62) 0%,
      oklch(0.995 0.002 247 / 0.14) 32%,
      oklch(0.995 0.002 247 / 0.1) 68%,
      oklch(0.995 0.002 247 / 0.58) 100%
    ),
    linear-gradient(
      100deg,
      color-mix(in oklab, var(--primary) 6%, transparent),
      transparent 50%
    );
}

.bento-scene-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 48px oklch(0.25 0.02 160 / 0.08);
}

.bento-scene-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 80% 65% at 50% 52%,
    color-mix(in oklab, var(--primary) 8%, transparent),
    transparent 72%
  );
  opacity: 0.85;
  animation: bento-atmosphere-shift 9s ease-in-out infinite alternate;
}

.bento-scene-sweep {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    105deg,
    transparent 40%,
    color-mix(in oklab, var(--primary) 5%, transparent) 50%,
    transparent 60%
  );
  opacity: 0.28;
  animation: bento-light-sweep 14s ease-in-out infinite;
}

.bento-scene-viz {
  position: relative;
  z-index: 2;
  height: 100%;
  width: 100%;
}

.bento-illus-svg {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 1px 0 oklch(1 0 0 / 0.35));
}

.bento-scene-chip,
.bento-scene-panel {
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.bento-scene--marketplace .bento-scene-atmosphere {
  background:
    linear-gradient(
      180deg,
      oklch(0.995 0.002 247 / 0.55) 0%,
      oklch(0.995 0.002 247 / 0.08) 40%,
      oklch(0.995 0.002 247 / 0.45) 100%
    ),
    radial-gradient(
      ellipse 75% 60% at 50% 70%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 72%
    );
}

.bento-scene--audit .bento-scene-atmosphere {
  background:
    linear-gradient(
      180deg,
      oklch(0.995 0.002 247 / 0.5) 0%,
      oklch(0.995 0.002 247 / 0.06) 42%,
      oklch(0.995 0.002 247 / 0.48) 100%
    );
}

.bento-scene--audit .bento-audit-fade {
  background: linear-gradient(
    180deg,
    oklch(0.995 0.002 247 / 0.55) 0%,
    transparent 16%,
    transparent 82%,
    oklch(0.995 0.002 247 / 0.5) 100%
  );
}

.bento-scene--travel .bento-scene-glow {
  background: radial-gradient(
    ellipse 80% 65% at 50% 56%,
    color-mix(in oklab, var(--primary) 10%, transparent),
    transparent 74%
  );
}

.bento-scene--workflow .bento-scene-atmosphere {
  background:
    linear-gradient(
      90deg,
      oklch(0.995 0.002 247 / 0.52) 0%,
      oklch(0.995 0.002 247 / 0.06) 48%,
      oklch(0.995 0.002 247 / 0.5) 100%
    );
}

.bento-scene--platform .bento-scene-atmosphere {
  background:
    linear-gradient(
      180deg,
      oklch(0.995 0.002 247 / 0.48) 0%,
      oklch(0.995 0.002 247 / 0.05) 50%,
      oklch(0.995 0.002 247 / 0.52) 100%
    );
}

.process-bento-card:hover .bento-scene-photo {
  transform: scale(calc(var(--bento-bg-scale, 1.06) * 1.02));
  filter: saturate(1.06) contrast(1.04);
}

@keyframes bento-bg-ken-burns {
  0% {
    transform: scale(var(--bento-bg-scale, 1.06)) translate(0, 0);
  }
  100% {
    transform: scale(calc(var(--bento-bg-scale, 1.06) * 1.03)) translate(-0.8%, -0.5%);
  }
}

@keyframes bento-atmosphere-shift {
  0% {
    opacity: 0.75;
  }
  100% {
    opacity: 1;
  }
}

@keyframes bento-light-sweep {
  0%,
  100% {
    opacity: 0.2;
    transform: translateX(-8%);
  }
  50% {
    opacity: 0.5;
    transform: translateX(8%);
  }
}

/* Process bento — mobile / tablet (<1024px). Cards are one per row here, so the
   scene gets a bigger stage. Height comes from an aspect ratio instead of a fixed
   rem value: `.bento-illus-svg` keeps its 300×160 viewBox while the HTML chips are
   positioned as a % of the frame, so any other ratio letterboxed the svg and pulled
   the chips off the paths. The audit + wide scenes have no viewBox to honour
   (list / preserveAspectRatio="none" chart), so they can run taller. */
@media (max-width: 1023px) {
  .bento-scene--standard,
  .bento-scene--wide {
    height: auto;
    max-width: 32rem;
    margin-inline: auto;
  }

  .bento-scene--standard {
    aspect-ratio: 15 / 8;
    min-height: 8rem;
  }

  .bento-scene--wide {
    aspect-ratio: 3 / 2;
    min-height: 14rem;
  }

  .bento-scene--audit {
    aspect-ratio: 3 / 2;
    min-height: 13rem;
  }

  /* Chart stretches (preserveAspectRatio="none"), so keep the box wider than
     the platform card or the curve reads as distorted. */
  .bento-scene--workflow {
    aspect-ratio: 16 / 9;
    min-height: 11rem;
  }

  /* The chips already carry `translate: -50% -50%` from utilities, so the
     keyframe's own translate() centred them twice and pushed the first chip
     off the left edge. Float only — the utilities do the centring. */
  .bento-node-float {
    animation-name: bento-node-float-centered;
  }

  /* Orbit radius has to follow the stage width, otherwise the chips ride
     outside the dashed ring and clip on the bottom edge. */
  @supports (container-type: inline-size) {
    .bento-scene--travel {
      container-type: inline-size;
    }

    .bento-scene--travel .bento-orbit-node {
      --bento-orbit-r: 16.7cqw;
    }
  }
}

@media (max-width: 639px) {
  .bento-scene-photo {
    opacity: var(--bento-bg-opacity, 0.88);
    filter: saturate(1.02) contrast(1.02);
  }

  .bento-scene-sweep {
    animation: none;
    opacity: 0.25;
  }

  .bento-launch-ghost {
    display: none;
  }

  /* Scale the overlay glyphs up with the stage — at phone widths the old
     sizes were the reason the scenes read as unclear. */
  .bento-node-float,
  .bento-orbit-node {
    width: 2.2rem;
    height: 2.2rem;
    font-size: 9px;
  }

  .bento-orbit-node {
    left: -1.1rem;
    top: -1.1rem;
  }

  .bento-audit {
    padding: 0.85rem;
  }

  .bento-audit .bento-scene-panel {
    padding: 0.55rem 0.7rem;
    font-size: 11.5px;
  }

  .bento-price-tag {
    font-size: 12px;
    padding: 0.4rem 0.7rem;
  }

  .bento-launch {
    gap: 0.85rem;
  }

  .bento-launch-panel {
    max-width: 13.5rem;
    padding: 0.85rem 0.9rem;
  }

  .bento-launch-panel p {
    font-size: 11.5px;
  }
}

/* Smallest phones — trade card padding for illustration width. */
@media (max-width: 359px) {
  .process-bento-card {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bento-scene-photo,
  .bento-scene-glow,
  .bento-scene-sweep {
    animation: none !important;
  }

  .process-bento-card:hover .bento-scene-photo {
    transform: scale(var(--bento-bg-scale, 1.06));
  }

  .bento-flow-line,
  .bento-node-float,
  .bento-pulse-dot,
  .bento-pulse-ring,
  .bento-packet,
  .bento-audit-track,
  .bento-audit-hot,
  .bento-orbit-spin,
  .bento-orbit-spin-reverse,
  .bento-orbit-node,
  .bento-chart-line,
  .bento-chart-area,
  .bento-chart-grid,
  .bento-price-tag,
  .bento-launch-panel,
  .bento-launch-flow,
  .bento-connect-ring,
  .bento-launch-ghost {
    animation: none;
  }
}

/* â”€â”€ Partner product showcase (light) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.partner-showcase {
  background:
    radial-gradient(
      ellipse 55% 45% at 90% 0%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 65%
    ),
    radial-gradient(
      ellipse 40% 35% at 5% 100%,
      color-mix(in oklab, var(--primary) 6%, transparent),
      transparent 70%
    ),
    var(--background);
}

.partner-showcase-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(color-mix(in oklab, var(--foreground) 4%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--foreground) 4%, transparent) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: radial-gradient(ellipse 75% 65% at 50% 35%, black, transparent 88%);
  opacity: 0.45;
}

.partner-live-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
  animation: partner-blink 1.8s ease-in-out infinite;
}

@keyframes partner-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

.partner-tabs {
  scrollbar-width: none;
}

.partner-tabs::-webkit-scrollbar {
  display: none;
}

.partner-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  overflow: hidden;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--card) 80%, transparent);
  padding: 0.55rem 0.95rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
  transition:
    color 0.3s ease,
    border-color 0.3s ease,
    background 0.3s ease;
}

.partner-tab:hover {
  color: var(--foreground);
  border-color: color-mix(in oklab, var(--foreground) 18%, var(--border));
}

.partner-tab[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 45%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.partner-tab:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.partner-tab-progress {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  width: 100%;
  transform-origin: left;
  background: var(--primary);
  animation-name: partner-tab-fill;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

@keyframes partner-tab-fill {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

.partner-copy-slot {
  display: grid;
}

.partner-copy {
  grid-area: 1 / 1;
  align-self: start;
  min-width: 0;
  visibility: hidden;
  pointer-events: none;
  animation: none;
}

.partner-copy[data-active="true"] {
  visibility: visible;
  pointer-events: auto;
  animation: partner-copy-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes partner-copy-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.partner-frame {
  display: flex;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid var(--border);
  background: var(--card);
  box-shadow:
    0 28px 70px -40px oklch(0.2 0.02 160 / 0.35),
    0 0 0 1px color-mix(in oklab, var(--primary) 8%, transparent);
}

.partner-frame-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.7rem 0.95rem;
  border-bottom: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 88%, var(--background));
}

.partner-frame-screen {
  position: relative;
  display: grid;
  width: 100%;
  padding: 0;
  margin: 0;
  border: 0;
  cursor: zoom-in;
  background: var(--muted);
  text-align: left;
}

.partner-frame-screen:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
}

.partner-shot {
  grid-area: 1 / 1;
  display: block;
  width: 100%;
  height: auto;
  max-height: min(62vh, 560px);
  object-fit: contain;
  object-position: top center;
  background: var(--card);
  visibility: hidden;
  animation: none;
}

.partner-shot[data-active="true"] {
  visibility: visible;
  animation: partner-shot-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes partner-shot-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.partner-expand-hint {
  position: absolute;
  right: 0.75rem;
  bottom: 0.75rem;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 92%, transparent);
  padding: 0.4rem 0.7rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--foreground);
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
  box-shadow: 0 10px 24px -16px oklch(0 0 0 / 0.35);
}

.partner-frame-screen:hover .partner-expand-hint,
.partner-frame-screen:focus-visible .partner-expand-hint {
  opacity: 1;
  transform: translateY(0);
}

.partner-segments {
  display: flex;
  gap: 4px;
  padding: 0.7rem 0.95rem;
  border-top: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 80%, var(--background));
}

.partner-segment {
  flex: 1;
  height: 3px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 10%, transparent);
  transition:
    background 0.35s ease,
    box-shadow 0.35s ease;
}

.partner-segment[data-state="done"] {
  background: color-mix(in oklab, var(--primary) 40%, transparent);
}

.partner-segment[data-state="active"] {
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 40%, transparent);
}

/* Lightbox â€” hide default dialog close; we render our own */
.partner-lightbox > button.absolute {
  display: none;
}

.partner-lightbox-body {
  max-height: calc(96vh - 3.5rem);
  overflow: auto;
  background: color-mix(in oklab, var(--muted) 55%, var(--background));
  padding: 0.75rem;
}

.partner-lightbox-img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 0.5rem;
  border: 1px solid var(--border);
  background: var(--card);
}

@media (max-width: 639px) {
  .partner-tab {
    min-height: 2.5rem;
  }

  .partner-shot {
    max-height: min(42vh, 280px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .partner-live-dot,
  .partner-tab-progress,
  .partner-copy,
  .partner-copy[data-active="true"],
  .partner-shot,
  .partner-shot[data-active="true"] {
    animation: none;
  }
  .partner-tab-progress {
    transform: scaleX(1);
  }
}


