/* Feature orbit (light) */

.feature-orbit {
  --fo-mint: oklch(0.548 0.117 158.2);
  --fo-amber: oklch(0.62 0.12 75);
  --fo-teal: oklch(0.5 0.1 190);
  --fo-cyan: oklch(0.55 0.1 210);
  --fo-forest: oklch(0.42 0.098 158.2);
  position: relative;
  overflow: hidden;
  border-radius: 1.5rem;
  background:
    radial-gradient(
      ellipse 70% 55% at 50% 45%,
      color-mix(in oklab, var(--primary) 8%, transparent),
      transparent 70%
    ),
    oklch(0.985 0.008 158);
}

.feature-orbit-bg {
  pointer-events: none;
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    color-mix(in oklab, var(--foreground) 10%, transparent) 1px,
    transparent 1px
  );
  background-size: 22px 22px;
  mask-image: radial-gradient(ellipse 75% 70% at 50% 50%, #000 20%, transparent 75%);
  opacity: 0.55;
}

.feature-orbit-em {
  font-family: inherit;
  font-style: italic;
  font-weight: 500;
  color: var(--primary-deep);
}

.feature-orbit-stage {
  --orbit-r: clamp(12.5rem, 22vw, 15.5rem);
  --spin-s: 28s;
  position: relative;
  height: min(38rem, 72vw);
  margin-inline: auto;
  max-width: 72rem;
}

.feature-orbit-side-type {
  pointer-events: none;
  position: absolute;
  top: 50%;
  z-index: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-family: inherit;
  font-size: clamp(1.6rem, 2.8vw, 2.35rem);
  font-style: italic;
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: color-mix(in oklab, var(--foreground) 14%, transparent);
  user-select: none;
}

.feature-orbit-side-type span {
  font-family: var(--font-display);
  font-size: 0.72em;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--primary) 28%, transparent);
}

.feature-orbit-side-type-left {
  left: 0.25rem;
  translate: 0 -50%;
  text-align: left;
}

.feature-orbit-side-type-right {
  right: 0.25rem;
  translate: 0 -50%;
  text-align: right;
}

.feature-orbit-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--orbit-r) * 2);
  height: calc(var(--orbit-r) * 2);
  translate: -50% -50%;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, transparent);
  animation: feature-orbit-spin var(--spin-s) linear infinite;
}

.feature-orbit-ring-soft {
  width: calc(var(--orbit-r) * 2 + 4.5rem);
  height: calc(var(--orbit-r) * 2 + 4.5rem);
  border-color: color-mix(in oklab, var(--foreground) 6%, transparent);
  border-style: dashed;
  animation-direction: reverse;
  animation-duration: calc(var(--spin-s) * 1.45);
}

.feature-orbit-satellite {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 1;
  width: 8px;
  height: 8px;
  margin: -4px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: feature-orbit-sat var(--spin-s) linear infinite;
}

.feature-orbit-satellite-2 {
  width: 6px;
  height: 6px;
  margin: -3px;
  background: var(--fo-amber, oklch(0.62 0.12 75));
  animation-duration: calc(var(--spin-s) * 1.35);
  animation-direction: reverse;
}

@keyframes feature-orbit-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes feature-orbit-sat {
  from {
    transform: rotate(0deg) translateY(calc(var(--orbit-r) * -1 - 1.1rem));
  }
  to {
    transform: rotate(360deg) translateY(calc(var(--orbit-r) * -1 - 1.1rem));
  }
}

.feature-orbit-core {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 8.5rem;
  height: 8.5rem;
  translate: -50% -50%;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, transparent);
  background:
    radial-gradient(
      circle at 40% 35%,
      color-mix(in oklab, var(--primary) 18%, white),
      white 70%
    );
  box-shadow: 0 18px 40px -28px color-mix(in oklab, var(--primary) 45%, transparent);
}

.feature-orbit-core-glow {
  position: absolute;
  inset: -28%;
  border-radius: 999px;
  background: radial-gradient(
    circle,
    color-mix(in oklab, var(--primary) 22%, transparent),
    transparent 68%
  );
  z-index: -1;
  animation: feature-orbit-pulse 4.5s ease-in-out infinite;
}

@keyframes feature-orbit-pulse {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(0.96);
  }
  50% {
    opacity: 1;
    transform: scale(1.05);
  }
}

.feature-orbit-core-logo {
  width: 72%;
  height: auto;
  object-fit: contain;
}

.feature-orbit-core-badge {
  position: absolute;
  bottom: -0.35rem;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 30%, transparent);
  background: white;
  padding: 0.22rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.feature-orbit-node {
  --angle: 0deg;
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 3;
  /* Place on orbit, then counter-rotate so the card stays upright */
  transform: translate(-50%, -50%) rotate(var(--angle))
    translateY(calc(var(--orbit-r) * -1)) rotate(calc(var(--angle) * -1));
}

.feature-orbit-node[data-active="true"] {
  z-index: 5;
}

.feature-orbit-card {
  position: relative;
  display: flex;
  width: 9.75rem;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.75rem;
  overflow: hidden;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, white 92%, transparent),
      color-mix(in oklab, var(--primary-soft) 55%, white)
    );
  padding: 0.95rem 0.9rem 1rem;
  text-align: left;
  box-shadow: 0 14px 32px -26px color-mix(in oklab, var(--foreground) 35%, transparent);
  transition:
    transform 0.4s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.35s ease,
    box-shadow 0.35s ease;
  cursor: pointer;
}

.feature-orbit-card::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  opacity: 0.35;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.45'/%3E%3C/svg%3E");
  mix-blend-mode: multiply;
}

.feature-orbit-card[data-active="true"] {
  transform: scale(1.04);
  border-color: color-mix(in oklab, var(--fo-accent, var(--primary)) 45%, transparent);
  box-shadow: 0 18px 36px -22px color-mix(in oklab, var(--fo-accent, var(--primary)) 40%, transparent);
}

.feature-orbit-node[data-accent="mint"],
.feature-orbit-card[data-accent="mint"],
.feature-orbit-detail[data-accent="mint"],
.feature-orbit-dot[data-accent="mint"],
.feature-orbit-mobile-card[data-accent="mint"] {
  --fo-accent: var(--fo-mint);
}

.feature-orbit-node[data-accent="amber"],
.feature-orbit-card[data-accent="amber"],
.feature-orbit-detail[data-accent="amber"],
.feature-orbit-dot[data-accent="amber"],
.feature-orbit-mobile-card[data-accent="amber"] {
  --fo-accent: var(--fo-amber);
}

.feature-orbit-node[data-accent="teal"],
.feature-orbit-card[data-accent="teal"],
.feature-orbit-detail[data-accent="teal"],
.feature-orbit-dot[data-accent="teal"],
.feature-orbit-mobile-card[data-accent="teal"] {
  --fo-accent: var(--fo-teal);
}

.feature-orbit-node[data-accent="cyan"],
.feature-orbit-card[data-accent="cyan"],
.feature-orbit-detail[data-accent="cyan"],
.feature-orbit-dot[data-accent="cyan"],
.feature-orbit-mobile-card[data-accent="cyan"] {
  --fo-accent: var(--fo-cyan);
}

.feature-orbit-node[data-accent="forest"],
.feature-orbit-card[data-accent="forest"],
.feature-orbit-detail[data-accent="forest"],
.feature-orbit-dot[data-accent="forest"],
.feature-orbit-mobile-card[data-accent="forest"] {
  --fo-accent: var(--fo-forest);
}

.feature-orbit-icon {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 2.65rem;
  height: 2.65rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--fo-accent, var(--primary)) 28%, transparent);
  color: var(--fo-accent, var(--primary));
  background-color: color-mix(in oklab, var(--fo-accent, var(--primary)) 8%, white);
  background-image:
    linear-gradient(
      color-mix(in oklab, var(--fo-accent, var(--primary)) 12%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      color-mix(in oklab, var(--fo-accent, var(--primary)) 12%, transparent) 1px,
      transparent 1px
    );
  background-size: 7px 7px;
}

.feature-orbit-card-title {
  position: relative;
  z-index: 1;
  font-size: 0.92rem;
  line-height: 1.3;
  color: var(--foreground);
}

.feature-orbit-card-title strong {
  font-family: var(--font-display);
  font-weight: 700;
}

.feature-orbit-card-title em {
  font-family: inherit;
  font-style: italic;
  font-weight: 500;
  color: color-mix(in oklab, var(--fo-accent, var(--primary)) 85%, var(--foreground));
}

.feature-orbit-card-fill {
  position: absolute;
  left: 0;
  bottom: 0;
  z-index: 1;
  height: 2px;
  width: 100%;
  transform-origin: left;
  background: var(--fo-accent, var(--primary));
  animation-name: partner-tab-fill;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

.feature-orbit-detail {
  position: absolute;
  top: 50%;
  z-index: 4;
  width: 14.5rem;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--fo-accent, var(--primary)) 28%, transparent);
  background: color-mix(in oklab, white 94%, var(--fo-accent, var(--primary)));
  padding: 1rem 1.05rem;
  box-shadow: 0 18px 40px -28px color-mix(in oklab, var(--fo-accent, var(--primary)) 45%, transparent);
  animation: feature-orbit-detail-in 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.feature-orbit-node[data-side="left"] .feature-orbit-detail {
  right: calc(100% + 0.85rem);
  transform: translateY(-50%);
}

.feature-orbit-node[data-side="right"] .feature-orbit-detail {
  left: calc(100% + 0.85rem);
  transform: translateY(-50%);
}

@keyframes feature-orbit-detail-in {
  from {
    opacity: 0;
    filter: blur(2px);
  }
  to {
    opacity: 1;
    filter: blur(0);
  }
}

.feature-orbit-detail-cat {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: none;
  color: var(--fo-accent, var(--primary));
}

.feature-orbit-detail-body {
  margin-top: 0.45rem;
  font-size: 0.9rem;
  line-height: 1.45;
  color: color-mix(in oklab, var(--foreground) 78%, transparent);
}

.feature-orbit-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 999px;
  border: 0;
  background: color-mix(in oklab, var(--foreground) 15%, transparent);
  cursor: pointer;
  transition:
    transform 0.3s ease,
    background 0.3s ease;
}

.feature-orbit-dot[data-active="true"] {
  transform: scale(1.35);
  background: var(--fo-accent, var(--primary));
}

.feature-orbit-mobile-card {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  width: 100%;
  border-radius: 1.1rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  padding: 1rem;
  text-align: left;
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.feature-orbit-mobile-card[data-active="true"] {
  border-color: color-mix(in oklab, var(--fo-accent, var(--primary)) 40%, transparent);
  box-shadow: 0 14px 32px -24px color-mix(in oklab, var(--fo-accent, var(--primary)) 40%, transparent);
}

.feature-orbit-detail-reserve {
  display: none;
}

@media (min-width: 1024px) {
  .feature-orbit-detail-reserve {
    display: block;
    height: 7.5rem;
    flex-shrink: 0;
  }
}

.feature-orbit-mobile-list {
  display: grid;
  gap: 0.75rem;
}

.feature-orbit-mobile-detail-slot {
  display: grid;
  margin-top: 0.75rem;
  min-height: 7.25rem;
  border-radius: 1.1rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  padding: 1rem 1.05rem;
}

.feature-orbit-mobile-detail-panel {
  grid-area: 1 / 1;
  visibility: hidden;
}

.feature-orbit-mobile-detail-panel[data-active="true"] {
  visibility: visible;
}

@media (max-width: 1279px) and (min-width: 1024px) {
  .feature-orbit-stage {
    --orbit-r: 12rem;
    height: 34rem;
  }

  .feature-orbit-detail {
    width: 12.5rem;
  }

  .feature-orbit-card {
    width: 8.75rem;
  }

  .feature-orbit-side-type {
    font-size: 1.45rem;
  }
}

/* Live sync feed + connected marketplaces — vertical ticker windows */
.fo-feed-window {
  position: relative;
  overflow: hidden;
  height: 11.75rem;
  margin-top: 1.25rem;
  mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    #000 12%,
    #000 88%,
    transparent 100%
  );
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    #000 12%,
    #000 88%,
    transparent 100%
  );
}

.fo-feed-track {
  display: flex;
  flex-direction: column;
  animation: fo-feed-up 18s linear infinite;
  will-change: transform;
}

.fo-feed-track--down {
  animation-name: fo-feed-down;
  animation-duration: 22s;
}

.fo-feed-window:hover .fo-feed-track {
  animation-play-state: paused;
}

.fo-feed-list {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  gap: 1rem;
  padding-bottom: 1rem;
}

.fo-feed-list--markets {
  gap: 0.875rem;
  padding-bottom: 0.875rem;
}

@keyframes fo-feed-up {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-50%);
  }
}

@keyframes fo-feed-down {
  from {
    transform: translateY(-50%);
  }
  to {
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .feature-orbit-ring,
  .feature-orbit-satellite,
  .feature-orbit-core-glow,
  .feature-orbit-detail,
  .feature-orbit-card-fill,
  .fo-feed-track {
    animation: none;
  }

  .fo-feed-track {
    transform: none;
    will-change: auto;
  }

  .fo-feed-list--clone {
    display: none;
  }

  .fo-feed-window {
    height: auto;
    overflow: visible;
    mask-image: none;
    -webkit-mask-image: none;
  }
}

/* ── TwoTrack — 3D section reveal (in-view settle, not scroll-scrub) ── */

.two-track-cinema {
  position: relative;
  overflow: clip;
}

.two-track-panel {
  z-index: 2;
  display: flex;
  align-items: center;
  padding-block: clamp(3rem, 8vh, 5rem);
}

.two-track-3d-headline,
.two-track-3d-stage,
.two-track-3d-footer {
  opacity: 0;
  transform: translateY(22px);
}

.two-track-cinema[data-settled="true"] .two-track-3d-headline,
.two-track-cinema[data-settled="true"] .two-track-3d-stage,
.two-track-cinema[data-settled="true"] .two-track-3d-footer {
  opacity: 1;
  transform: none;
}

.two-track-cinema[data-settled="true"] .two-track-3d-headline {
  transition-delay: 0.12s;
}

.two-track-cinema[data-settled="true"] .two-track-3d-stage {
  transition-delay: 0.28s;
}

.two-track-cinema[data-settled="true"] .two-track-3d-footer {
  transition-delay: 0.42s;
}

.two-track-stage {
  perspective: 1800px;
  perspective-origin: 50% 46%;
  display: grid;
  gap: clamp(2rem, 5vh, 3.5rem);
  margin-top: clamp(2rem, 5vh, 3rem);
  transform-style: preserve-3d;
  align-items: stretch;
  --tt-screen-h: clamp(32rem, 46vw, 38rem);
  --tt-bezel-h: calc(var(--tt-screen-h) + 1.3rem);
  --tt-panel-pad: 0.65rem 0.72rem;
  --tt-console-gap: 0.5rem;
}

@media (min-width: 1024px) {
  .two-track-stage {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 2rem;
  }

  .two-track-cinema:not([data-settled="true"]) .two-track-3d-card {
    transform: rotateX(18deg) rotateY(var(--tt-tilt-y, 0deg)) rotateZ(var(--tt-tilt-z, 0deg))
      translateY(40px) scale(0.94);
  }

  .two-track-cinema[data-settled="true"] .two-track-3d-card {
    transform: none;
  }
}

.two-track-3d-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  transform-origin: 50% 55%;
  transform-style: preserve-3d;
  will-change: transform;
  transition: transform 1s cubic-bezier(0.42, 0, 0.58, 1);
}

.two-track-3d-bezel {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  width: 100%;
  height: var(--tt-bezel-h);
  min-height: var(--tt-bezel-h);
  max-height: var(--tt-bezel-h);
  padding: 0.65rem;
  border-radius: 1.35rem;
  background: linear-gradient(
    145deg,
    oklch(0.92 0.01 155),
    oklch(0.86 0.015 155)
  );
  box-shadow:
    0 28px 64px -36px oklch(0.28 0.04 160 / 0.35),
    0 0 0 1px oklch(1 0 0 / 0.5) inset;
}

.two-track-3d-screen {
  position: relative;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  overflow: hidden;
  border-radius: 0.95rem;
  border: 1px solid oklch(0.88 0.012 155);
  background: oklch(0.995 0.003 155);
  height: var(--tt-screen-h);
  min-height: var(--tt-screen-h);
  max-height: var(--tt-screen-h);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.9) inset,
    0 20px 48px -32px color-mix(in oklab, var(--foreground) 14%, transparent);
}

.two-track-chrome {
  position: relative;
  z-index: 6;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.75rem;
  border-bottom: 1px solid color-mix(in oklab, var(--foreground) 6%, transparent);
  background: color-mix(in oklab, var(--muted) 32%, white);
  padding: 0.65rem 1rem;
}

.two-track-chrome-dots {
  display: inline-flex;
  gap: 0.28rem;
}

.two-track-chrome-dots i {
  display: block;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 12%, transparent);
}

.two-track-chrome-dots i:first-child {
  background: #ff5f57;
}

.two-track-chrome-dots i:nth-child(2) {
  background: #febc2e;
}

.two-track-chrome-dots i:nth-child(3) {
  background: #28c840;
}

.two-track-chrome-path {
  flex: 1;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--muted-foreground);
}

.two-track-chrome-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, var(--border));
  background: color-mix(in oklab, var(--primary) 7%, transparent);
  padding: 0.18rem 0.6rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--primary);
  flex-shrink: 0;
}

.two-track-chrome-pulse {
  position: relative;
  flex-shrink: 0;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.two-track-chrome-pulse::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  animation: two-track-pulse-ring 2.4s ease-out infinite;
}

.two-track-3d-grid {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.45;
  background-image: radial-gradient(oklch(0.72 0.02 155 / 0.55) 1px, transparent 1px);
  background-size: 16px 16px;
  mask-image: linear-gradient(180deg, black 40%, transparent 100%);
}

.two-track-3d-glare {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  background: radial-gradient(
    circle at 28% 16%,
    oklch(1 0 0 / 0.55),
    transparent 42%
  );
}

.two-track-3d-scan {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 3;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 8%, transparent) 50%,
    transparent
  );
  opacity: 0.35;
  animation: two-track-screen-scan 5.5s ease-in-out infinite;
}

.two-track-3d-inner {
  position: relative;
  z-index: 2;
  display: grid;
  flex: 1 1 auto;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: var(--tt-console-gap);
  min-height: 0;
  overflow: hidden;
  padding: clamp(0.85rem, 2.2vw, 1.25rem);
}

.two-track-3d-headline {
  display: flex;
  flex-shrink: 0;
  flex-direction: column;
  gap: 0.12rem;
  transition: opacity 0.55s ease-out, transform 0.55s ease-out;
}

.two-track-3d-line {
  font-size: clamp(1.15rem, 2.2vw, 1.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.two-track-3d-accent {
  font-size: clamp(1.3rem, 2.6vw, 1.75rem);
  font-style: italic;
  font-weight: 600;
  line-height: 1.05;
  color: var(--primary);
}

.two-track-3d-fade {
  margin-top: 0.12rem;
  font-size: clamp(0.95rem, 1.8vw, 1.15rem);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: color-mix(in oklab, var(--foreground) 22%, transparent);
}

.two-track-3d-stage {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  transition: opacity 0.55s ease-out, transform 0.55s ease-out;
}

.two-track-3d-stage > .two-track-console {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
}

.two-track-3d-footer {
  flex-shrink: 0;
  padding-top: 0.55rem;
  padding-right: 2.65rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 6%, transparent);
  transition: opacity 0.45s ease-out, transform 0.45s ease-out;
}

.two-track-3d-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
}

.two-track-3d-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.55rem;
}

.two-track-3d-tags li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 16%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, transparent);
  padding: 0.2rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 600;
  color: color-mix(in oklab, var(--primary) 80%, var(--foreground));
}

.two-track-3d-badge {
  position: absolute;
  right: 1.1rem;
  bottom: 1.1rem;
  z-index: 5;
  display: flex;
  height: 2.35rem;
  width: 2.35rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  color: var(--primary);
  box-shadow: 0 10px 24px -16px oklch(0.28 0.04 160 / 0.45);
}

.two-track-3d-copy {
  margin-top: 1.25rem;
  padding-inline: 0.25rem;
}

.two-track-stat-value {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--foreground);
}

.two-track-stat-label {
  margin-top: 0.2rem;
  font-size: 10px;
  line-height: 1.3;
  color: var(--muted-foreground);
}

.two-track-cta {
  margin-top: 0.85rem;
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 0.45rem;
  border-bottom: 1px solid transparent;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--primary);
  transition: border-color 0.25s ease;
}

.two-track-cta:hover {
  border-color: color-mix(in oklab, var(--primary) 45%, transparent);
}

/* Console dashboards */

.two-track-console {
  display: flex;
  flex-direction: column;
  gap: var(--tt-console-gap);
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.two-track-console-broker {
  flex: 1 1 auto;
}

.two-track-console-travel {
  flex: 1 1 auto;
}

.two-track-console-top,
.two-track-console-split {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.two-track-search-bar,
.two-track-pipeline,
.two-track-module-rail {
  flex-shrink: 0;
}

.two-track-panel-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.45rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: 0.07em;
  text-transform: none;
  color: var(--muted-foreground);
  flex-shrink: 0;
}

.two-track-console-top {
  display: grid;
  gap: 0.6rem;
  align-items: stretch;
  height: 100%;
  min-height: 0;
}

@media (min-width: 480px) {
  .two-track-console-top {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  }
}

.two-track-hub-panel,
.two-track-log-panel,
.two-track-pricing-panel,
.two-track-inventory-panel,
.two-track-quote-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, var(--card) 88%, white);
  padding: var(--tt-panel-pad);
  box-shadow: 0 1px 0 oklch(1 0 0 / 0.65) inset;
}

.two-track-hub-panel {
  min-height: 0;
  height: 100%;
}

.two-track-hub-panel .two-track-panel-kicker {
  flex-shrink: 0;
}

.two-track-hub-panel .two-track-inventory-strip {
  flex-shrink: 0;
  margin-top: auto;
}

.two-track-hub-viz {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.two-track-hub-viz-stage {
  position: relative;
  width: 100%;
  height: 7rem;
  flex-shrink: 0;
  --tt-orbit-radius: 2.85rem;
}

.two-track-hub-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.two-track-hub-svg .two-track-orbit-ring {
  transform-origin: 100px 50px;
  animation: two-track-orbit-spin 24s linear infinite;
}

.two-track-hub-svg .two-track-orbit-ring-inner {
  animation-direction: reverse;
  animation-duration: 18s;
}

.two-track-hub-svg .two-track-spoke {
  transition:
    stroke 0.4s ease,
    stroke-width 0.4s ease,
    opacity 0.4s ease;
}

.two-track-hub-svg .two-track-spoke[data-active="true"] {
  stroke: color-mix(in oklab, var(--primary) 75%, white);
  stroke-width: 1.35;
  opacity: 1;
  animation: two-track-spoke-flow 1.4s ease-in-out infinite;
}

.two-track-orbit-core-sm {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 3;
  display: flex;
  height: 2.5rem;
  width: 2.5rem;
  translate: -50% -50%;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow:
    0 0 0 5px color-mix(in oklab, var(--primary) 14%, transparent),
    0 0 22px color-mix(in oklab, var(--primary) 24%, transparent);
  animation: two-track-core-sync 3.2s ease-in-out infinite;
}

.two-track-hub-viz-stage .two-track-orbit-core-sm {
  height: 2.65rem;
  width: 2.65rem;
}

.two-track-orbit-node-sm {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 2;
  display: flex;
  font-size: 8px;
  height: 1.75rem;
  width: 1.75rem;
  translate: -50% -50%;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: white;
  font-family: var(--font-mono);
  font-weight: 700;
  line-height: 1;
  color: var(--muted-foreground);
  box-shadow: 0 0 0 1px var(--border);
  animation: two-track-orbit-travel-sm 14s linear infinite;
  animation-delay: calc(var(--orbit-i) * -2.3s);
  transition:
    color 0.35s ease,
    box-shadow 0.35s ease,
    background 0.35s ease;
}

.two-track-hub-viz-stage .two-track-orbit-node-sm {
  height: 1.85rem;
  width: 1.85rem;
  font-size: 9px;
  animation-name: two-track-orbit-travel-hub;
}

.two-track-orbit-node-sm[data-active="true"] {
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 6%, white);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--primary) 45%, var(--border)),
    0 0 14px color-mix(in oklab, var(--primary) 28%, transparent);
  z-index: 4;
}

.two-track-orbit-node-sm[data-status="Live"],
.two-track-orbit-node-sm[data-status="Synced"] {
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 18%, var(--border));
}

.two-track-orbit-node-sm[data-status="Pushing"] {
  animation:
    two-track-orbit-travel-sm 14s linear infinite,
    two-track-node-push 1.6s ease-in-out infinite;
  animation-delay: calc(var(--orbit-i) * -2.3s), 0s;
}

.two-track-hub-viz-stage .two-track-orbit-node-sm[data-status="Pushing"] {
  animation:
    two-track-orbit-travel-hub 14s linear infinite,
    two-track-node-push 1.6s ease-in-out infinite;
  animation-delay: calc(var(--orbit-i) * -2.3s), 0s;
}

.two-track-orbit-node-sm[data-status="Queued"] {
  opacity: 0.72;
}

.two-track-inventory-strip {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.45rem;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.35;
  color: var(--muted-foreground);
  min-width: 0;
}

.two-track-inventory-strip > span:not(.two-track-inventory-dot) {
  flex-shrink: 0;
}

.two-track-inventory-strip > span:last-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.two-track-inventory-dot {
  width: 0.2rem;
  height: 0.2rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 50%, var(--border));
}

.two-track-side-stack {
  display: grid;
  grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.55rem;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.two-track-log-panel,
.two-track-pricing-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  height: 100%;
}

.two-track-log-panel .two-track-panel-kicker,
.two-track-pricing-head {
  flex-shrink: 0;
}

.two-track-log-viewport {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  mask-image: linear-gradient(180deg, black 82%, transparent 100%);
}

.two-track-log-track {
  display: flex;
  flex-direction: column;
  gap: 0.32rem;
  animation: two-track-log-scroll 10s linear infinite;
}

.two-track-log-row {
  display: grid;
  grid-template-columns: 3.5rem minmax(0, 1fr);
  gap: 0.45rem;
  align-items: baseline;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.two-track-log-row span:first-child {
  flex-shrink: 0;
  color: color-mix(in oklab, var(--foreground) 38%, transparent);
  font-variant-numeric: tabular-nums;
}

.two-track-log-row span:last-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.two-track-log-row[data-ok="true"] span:last-child {
  color: color-mix(in oklab, var(--primary) 85%, var(--foreground));
}

.two-track-pricing-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.two-track-best-tag {
  border-radius: 0.25rem;
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.1rem 0.35rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--primary);
  animation: two-track-best-glow 2.5s ease-in-out infinite;
}

.two-track-pricing-asks {
  display: flex;
  gap: 1.15rem;
  margin-top: 0.25rem;
}

.two-track-pricing-label {
  display: block;
  margin-bottom: 0.1rem;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.3;
  color: var(--muted-foreground);
}

.two-track-pricing-asks strong {
  display: block;
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--foreground);
  font-variant-numeric: tabular-nums;
}

.two-track-pricing-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.25rem;
  flex-shrink: 0;
  height: 2.5rem;
  margin-top: auto;
}

.two-track-pricing-bar {
  flex: 1;
  border-radius: 0.15rem 0.15rem 0 0;
  background: linear-gradient(180deg, var(--primary), color-mix(in oklab, var(--primary) 45%, white));
  animation: two-track-bar-breathe 2.8s ease-in-out infinite;
}

.two-track-module-rail {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.two-track-module-rail li {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  padding: 0.28rem 0.58rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 600;
  line-height: 1.25;
  color: var(--muted-foreground);
  white-space: nowrap;
  transition:
    border-color 0.35s ease,
    color 0.35s ease,
    background 0.35s ease,
    box-shadow 0.35s ease;
}

.two-track-module-rail li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 35%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--primary);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--primary) 12%, transparent),
    0 0 16px color-mix(in oklab, var(--primary) 10%, transparent);
}

.two-track-module-rail li[data-active="true"] svg {
  animation: two-track-icon-spin 2.4s linear infinite;
}

.two-track-search-bar {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  padding: 0.5rem 0.65rem;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.35;
  color: var(--foreground);
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 6%, transparent);
}

.two-track-search-query {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.two-track-search-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-left: auto;
  flex-shrink: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  padding: 0.15rem 0.5rem;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--primary);
}

.two-track-search-badge::before {
  content: "";
  width: 0.34rem;
  height: 0.34rem;
  border-radius: 999px;
  background: var(--primary);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.two-track-console-split {
  display: grid;
  gap: 0.55rem;
  align-items: stretch;
  height: 100%;
  min-height: 0;
}

@media (min-width: 480px) {
  .two-track-console-split {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  }
}

.two-track-inventory-panel {
  justify-content: flex-start;
  height: 100%;
  min-height: 0;
  gap: 0.35rem;
}

.two-track-inventory-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 5%, transparent);
  background: white;
  padding: 0.48rem 0.58rem;
}

.two-track-inventory-row + .two-track-inventory-row {
  margin-top: 0;
}

.two-track-inventory-row-main {
  flex: 1 1 auto;
  min-width: 0;
}

.two-track-inventory-section {
  display: block;
  font-size: 10px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.two-track-inventory-seats {
  display: block;
  margin-top: 0.14rem;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.3;
  color: var(--muted-foreground);
}

.two-track-inventory-prices {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.22rem;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.25;
  color: var(--foreground);
  font-variant-numeric: tabular-nums;
}

.two-track-margin-pill {
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  padding: 0.1rem 0.42rem;
  font-size: 9px;
  line-height: 1.2;
  color: var(--primary);
  white-space: nowrap;
}

.two-track-quote-panel {
  justify-content: flex-start;
  height: 100%;
  min-height: 0;
  gap: 0.1rem;
}

.two-track-quote-rows,
.two-track-quote-actions {
  flex-shrink: 0;
}

.two-track-quote-event {
  font-size: 0.84rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--foreground);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
}

.two-track-quote-venue,
.two-track-quote-line {
  margin-top: 0.12rem;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.35;
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.two-track-quote-rows {
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
  margin-top: auto;
  padding-top: 0.48rem;
  border-top: 1px dashed color-mix(in oklab, var(--foreground) 10%, transparent);
}

.two-track-quote-rows div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.55rem;
  min-width: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.35;
  color: var(--muted-foreground);
}

.two-track-quote-rows div > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.two-track-quote-rows strong {
  flex-shrink: 0;
  font-size: 10px;
  line-height: 1.25;
  color: var(--foreground);
  font-variant-numeric: tabular-nums;
}

.two-track-quote-total strong {
  font-size: 0.92rem;
  color: var(--primary);
}

.two-track-quote-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.45rem;
}

.two-track-quote-action {
  border-radius: 999px;
  border: 1px solid var(--border);
  padding: 0.22rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 600;
  line-height: 1.25;
  color: var(--muted-foreground);
  white-space: nowrap;
}

.two-track-quote-action[data-ready="true"] {
  border-color: color-mix(in oklab, var(--primary) 30%, var(--border));
  color: var(--primary);
}

.two-track-quote-action-wa {
  animation: two-track-wa-pulse 3s ease-in-out infinite;
}

.two-track-pipeline {
  display: grid;
  flex-shrink: 0;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.35rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.two-track-pipeline li {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.2rem;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 6%, transparent);
  background: white;
  padding: 0.45rem 0.3rem;
  text-align: center;
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease,
    background 0.35s ease;
}

.two-track-pipeline li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 35%, var(--border));
  background: color-mix(in oklab, var(--primary) 4%, white);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--primary) 12%, transparent),
    0 0 14px color-mix(in oklab, var(--primary) 8%, transparent);
}

.two-track-pipeline-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 20%, transparent);
}

.two-track-pipeline li[data-active="true"] .two-track-pipeline-dot {
  background: var(--primary);
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.two-track-pipeline-label {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--muted-foreground);
}

.two-track-pipeline li[data-active="true"] .two-track-pipeline-label {
  color: var(--primary);
}

.two-track-pipeline-detail {
  font-family: var(--font-mono);
  font-size: 9px;
  line-height: 1.25;
  color: color-mix(in oklab, var(--foreground) 42%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.two-track-pipeline li[data-active="true"] .two-track-pipeline-detail {
  color: color-mix(in oklab, var(--primary) 75%, var(--foreground));
}

/* Console responsive + motion polish */

@media (max-width: 1023px) {
  .two-track-stage {
    --tt-screen-h: auto;
  }

  .two-track-cinema {
    overflow: hidden;
  }

  .two-track-panel {
    min-height: 0;
    align-items: stretch;
    padding-block: 2.5rem 3rem;
  }

  .two-track-3d-headline,
  .two-track-3d-stage,
  .two-track-3d-footer {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .two-track-3d-bezel,
  .two-track-3d-screen {
    height: auto;
    min-height: 0;
    max-height: none;
  }

  .two-track-3d-inner {
    overflow: visible;
  }

  .two-track-console {
    overflow: visible;
  }

  .two-track-3d-card {
    transform: none;
    transition: none;
  }
}

@media (max-width: 639px) {
  .two-track-panel > .container-page {
    padding-inline: clamp(1rem, 4.5vw, 1.35rem);
  }

  .two-track-stage {
    --tt-screen-h: auto;
    --tt-panel-pad: 0.75rem 0.9rem;
    padding-inline: 0.15rem;
  }

  .two-track-3d-card,
  .two-track-3d-bezel,
  .two-track-3d-screen,
  .two-track-3d-inner,
  .two-track-console,
  .two-track-side-stack,
  .two-track-hub-panel,
  .two-track-log-panel,
  .two-track-pricing-panel {
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
  }

  .two-track-3d-bezel {
    padding: 0.7rem;
  }

  .two-track-3d-inner {
    padding-inline: 1.125rem;
    padding-block: 0.9rem;
    overflow: hidden;
  }

  .two-track-log-row span:last-child,
  .two-track-pricing-head,
  .two-track-pricing-bars {
    padding-right: 0.2rem;
  }

  .two-track-3d-line {
    font-size: 1.05rem;
  }

  .two-track-3d-accent {
    font-size: 1.2rem;
  }

  .two-track-3d-fade {
    font-size: 0.88rem;
  }

  .two-track-pipeline {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .two-track-module-rail li {
    font-size: 8px;
    padding: 0.24rem 0.48rem;
  }

  .two-track-stat-value {
    font-size: 0.95rem;
  }

  .two-track-stat-label {
    font-size: 9px;
  }

  .two-track-search-query {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .two-track-inventory-strip {
    flex-wrap: wrap;
  }

  .two-track-search-badge {
    display: none;
  }
}

@media (max-width: 479px) {
  .two-track-panel > .container-page {
    padding-inline: clamp(1.125rem, 5.2vw, 1.35rem);
  }

  .two-track-stage {
    padding-inline: 0.25rem;
    --tt-panel-pad: 0.8rem 0.95rem;
  }

  .two-track-3d-inner {
    padding-inline: 1.25rem;
  }

  .two-track-log-row span:last-child,
  .two-track-pricing-head,
  .two-track-pricing-bars {
    padding-right: 0.2rem;
  }

  .two-track-console-top,
  .two-track-console-split {
    grid-template-columns: minmax(0, 1fr);
  }

  .two-track-side-stack {
    min-height: 11.5rem;
  }

  .two-track-hub-viz-stage {
    height: 6.25rem;
    --tt-orbit-radius: 2.55rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .two-track-log-track,
  .two-track-orbit-node-sm,
  .two-track-orbit-core-sm,
  .two-track-hub-svg .two-track-orbit-ring,
  .two-track-hub-svg .two-track-spoke,
  .two-track-3d-scan,
  .two-track-chrome-pulse,
  .two-track-chrome-pulse::after,
  .two-track-search-badge::before,
  .two-track-module-rail li[data-active="true"] svg,
  .two-track-pipeline li[data-active="true"] .two-track-pipeline-dot,
  .two-track-best-tag,
  .two-track-pricing-bar,
  .two-track-quote-action-wa {
    animation: none !important;
  }

  .two-track-orbit-node-sm[data-status="Pushing"] {
    animation: none !important;
  }
}

@keyframes two-track-live-pulse {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes two-track-log-scroll {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-50%);
  }
}

@keyframes two-track-best-glow {
  0%,
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
  50% {
    box-shadow: 0 0 12px color-mix(in oklab, var(--primary) 30%, transparent);
  }
}

@keyframes two-track-bar-breathe {
  0%,
  100% {
    opacity: 0.65;
  }
  50% {
    opacity: 1;
  }
}

@keyframes two-track-wa-pulse {
  0%,
  100% {
    border-color: var(--border);
  }
  50% {
    border-color: color-mix(in oklab, var(--primary) 45%, var(--border));
    color: var(--primary);
  }
}

/* Legacy illustration helpers (orbit/spoke) */

.two-track-illus {
  position: relative;
  height: 100%;
  min-height: 7rem;
  width: 100%;
}

.two-track-illus-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.two-track-orbit-ring {
  fill: none;
  stroke: color-mix(in oklab, var(--border) 80%, var(--primary));
  stroke-width: 1;
  stroke-dasharray: 4 6;
  transform-origin: 160px 58px;
  animation: two-track-orbit-spin 22s linear infinite;
}

.two-track-orbit-ring-inner {
  animation-direction: reverse;
  animation-duration: 16s;
}

.two-track-spoke {
  stroke: color-mix(in oklab, var(--primary) 22%, var(--border));
  stroke-width: 1;
  stroke-dasharray: 3 5;
  animation: two-track-spoke-pulse 2.4s ease-in-out infinite;
}

.two-track-orbit-core {
  position: absolute;
  left: 50%;
  top: 48%;
  z-index: 3;
  display: flex;
  height: 2rem;
  width: 2rem;
  translate: -50% -50%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.05rem;
  border-radius: 999px;
  background: var(--primary);
  color: var(--primary-foreground);
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 800;
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--primary) 14%, transparent);
}

.two-track-orbit-node {
  --orbit-angle: calc(var(--orbit-i) * 60deg - 90deg);
  position: absolute;
  left: 50%;
  top: 48%;
  z-index: 2;
  display: flex;
  height: 1.35rem;
  width: 1.35rem;
  translate: -50% -50%;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: white;
  font-family: var(--font-mono);
  font-size: 6px;
  font-weight: 700;
  color: var(--muted-foreground);
  box-shadow: 0 0 0 1px var(--border);
  animation: two-track-orbit-travel 14s linear infinite;
  animation-delay: calc(var(--orbit-i) * -2.3s);
}

.two-track-ticker {
  position: absolute;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  width: min(10rem, 48%);
}

.two-track-ticker-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  border-radius: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 6%, transparent);
  background: oklch(1 0 0 / 0.82);
  padding: 0.25rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 7px;
  color: var(--muted-foreground);
  animation: two-track-ticker-pulse 6s ease-in-out infinite;
}

.two-track-ticker-row:nth-child(2) {
  animation-delay: -1.5s;
}

.two-track-ticker-row:nth-child(3) {
  animation-delay: -3s;
}

.two-track-ticker-row:nth-child(4) {
  animation-delay: -4.5s;
}

.two-track-ticker-row[data-ok="true"] span:last-child {
  color: var(--primary);
  font-weight: 700;
}

.two-track-illus-travel {
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: 0.65rem;
  align-items: stretch;
}

.two-track-flow {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  justify-content: center;
}

.two-track-flow-step {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0.35rem;
  border-radius: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 6%, transparent);
  background: oklch(1 0 0 / 0.82);
  padding: 0.28rem 0.45rem;
  animation: two-track-step-glow 4s ease-in-out infinite;
}

.two-track-flow-dot {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--primary);
}

.two-track-flow-label {
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--muted-foreground);
}

.two-track-flow-value {
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 700;
  color: var(--primary);
}

.two-track-quote-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: white;
  padding: 0.65rem 0.75rem;
  box-shadow: 0 14px 28px -24px color-mix(in oklab, var(--primary) 45%, transparent);
  animation: two-track-quote-float 5s ease-in-out infinite;
}

.two-track-quote-kicker {
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.two-track-quote-title {
  margin-top: 0.2rem;
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--foreground);
}

.two-track-quote-meta {
  margin-top: 0.35rem;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 7px;
  color: var(--muted-foreground);
}

.two-track-quote-meta strong {
  font-size: 0.78rem;
  color: var(--primary);
}

.two-track-quote-bar {
  margin-top: 0.45rem;
  height: 0.18rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--muted) 60%, white);
  overflow: hidden;
}

.two-track-quote-bar span {
  display: block;
  width: 72%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--primary), color-mix(in oklab, var(--primary) 55%, white));
  animation: two-track-bar-fill 3.5s ease-in-out infinite alternate;
}

@keyframes two-track-screen-scan {
  0%,
  100% {
    translate: 0 -100%;
    opacity: 0;
  }
  45%,
  55% {
    translate: 0 100%;
    opacity: 0.2;
  }
}

@keyframes two-track-orbit-spin {
  to {
    rotate: 360deg;
  }
}

@keyframes two-track-orbit-travel-sm {
  from {
    transform: rotate(0deg) translateX(2.15rem) rotate(0deg);
  }
  to {
    transform: rotate(360deg) translateX(2.15rem) rotate(-360deg);
  }
}

@keyframes two-track-orbit-travel-hub {
  from {
    transform: rotate(0deg) translateX(var(--tt-orbit-radius, 2.85rem)) rotate(0deg);
  }
  to {
    transform: rotate(360deg) translateX(var(--tt-orbit-radius, 2.85rem)) rotate(-360deg);
  }
}

@keyframes two-track-orbit-travel {
  from {
    transform: rotate(0deg) translateX(3.1rem) rotate(0deg);
  }
  to {
    transform: rotate(360deg) translateX(3.1rem) rotate(-360deg);
  }
}

@keyframes two-track-spoke-pulse {
  0%,
  100% {
    opacity: 0.35;
  }
  50% {
    opacity: 1;
  }
}

@keyframes two-track-spoke-flow {
  0%,
  100% {
    opacity: 0.55;
    stroke-dasharray: 3 8;
  }
  50% {
    opacity: 1;
    stroke-dasharray: 8 3;
  }
}

@keyframes two-track-core-sync {
  0%,
  100% {
    box-shadow:
      0 0 0 4px color-mix(in oklab, var(--primary) 14%, transparent),
      0 0 12px color-mix(in oklab, var(--primary) 16%, transparent);
  }
  50% {
    box-shadow:
      0 0 0 6px color-mix(in oklab, var(--primary) 10%, transparent),
      0 0 22px color-mix(in oklab, var(--primary) 28%, transparent);
  }
}

@keyframes two-track-node-push {
  0%,
  100% {
    box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 25%, var(--border));
  }
  50% {
    box-shadow:
      0 0 0 1px color-mix(in oklab, var(--primary) 45%, var(--border)),
      0 0 10px color-mix(in oklab, var(--primary) 20%, transparent);
  }
}

@keyframes two-track-pulse-ring {
  0% {
    opacity: 0.75;
    transform: scale(0.85);
  }
  70%,
  100% {
    opacity: 0;
    transform: scale(1.45);
  }
}

@keyframes two-track-icon-spin {
  from {
    rotate: 0deg;
  }
  to {
    rotate: 360deg;
  }
}

@keyframes two-track-ticker-pulse {
  0%,
  80%,
  100% {
    opacity: 0.55;
  }
  10% {
    opacity: 1;
    transform: translateY(-1px);
  }
}

@keyframes two-track-step-glow {
  0%,
  100% {
    border-color: color-mix(in oklab, var(--foreground) 6%, transparent);
  }
  50% {
    border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  }
}

@keyframes two-track-quote-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-3px);
  }
}

@keyframes two-track-bar-fill {
  from {
    width: 58%;
  }
  to {
    width: 88%;
  }
}

@media (max-width: 640px) {
  .two-track-illus-travel {
    grid-template-columns: 1fr;
  }

  .two-track-ticker {
    position: relative;
    width: 100%;
    margin-top: 0.35rem;
  }

  .two-track-orbit-node {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .two-track-3d-card,
  .two-track-3d-headline,
  .two-track-3d-stage,
  .two-track-3d-footer {
    opacity: 1;
    transform: none !important;
    transition: none !important;
  }

  .two-track-chrome-pulse,
  .two-track-log-track,
  .two-track-best-tag,
  .two-track-pricing-bar,
  .two-track-quote-action-wa,
  .two-track-3d-scan,
  .two-track-orbit-ring,
  .two-track-orbit-node,
  .two-track-spoke,
  .two-track-ticker-row,
  .two-track-flow-step,
