/* Broker live consoles ------------------------------------------------ */

.lc-frame {
  width: 100%;
  max-width: 100%;
}

.lc-bezel {
  border-radius: 1.25rem;
  padding: 0.6rem;
  background: linear-gradient(145deg, oklch(0.92 0.01 155), oklch(0.86 0.015 155));
  box-shadow:
    0 28px 64px -36px oklch(0.28 0.04 160 / 0.35),
    0 0 0 1px oklch(1 0 0 / 0.5) inset;
}

.lc-screen {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 0.9rem;
  border: 1px solid oklch(0.88 0.012 155);
  background: oklch(0.995 0.003 155);
  height: clamp(28rem, 46vh, 34rem);
  min-height: clamp(28rem, 46vh, 34rem);
  max-height: clamp(28rem, 46vh, 34rem);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.9) inset,
    0 20px 48px -32px color-mix(in oklab, var(--foreground) 14%, transparent);
}

.lc-grid {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.4;
  background-image: radial-gradient(oklch(0.72 0.02 155 / 0.55) 1px, transparent 1px);
  background-size: 16px 16px;
  mask-image: linear-gradient(180deg, black 35%, transparent 100%);
}

.lc-glare {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  background: radial-gradient(circle at 28% 16%, oklch(1 0 0 / 0.55), transparent 42%);
}

.lc-scan {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 3;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 8%, transparent) 50%,
    transparent
  );
  opacity: 0.3;
  animation: two-track-screen-scan 5.5s ease-in-out infinite;
}

.lc-body {
  position: relative;
  z-index: 2;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 0.75rem;
  min-height: 0;
  overflow: hidden;
  padding: clamp(0.75rem, 1.6vw, 1rem);
}

.lc-pos-stats,
.lc-intel-context,
.lc-intel-metrics {
  flex-shrink: 0;
}

.lc-mono {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.06em;
}

.lc-stat {
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.55rem 0.65rem;
}

.lc-stat-label {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.lc-stat-value {
  font-family: var(--font-mono);
  font-size: clamp(0.92rem, 1.5vw, 1.1rem);
  font-weight: 700;
  color: var(--foreground);
}

.lc-panel {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.65rem 0.7rem;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.lc-panel-accent {
  border-color: color-mix(in oklab, var(--primary) 22%, var(--border));
  background: color-mix(in oklab, var(--primary) 4%, white);
}

.lc-panel-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.lc-panel-badge {
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.12rem 0.45rem;
  font-size: 9px;
  color: var(--foreground);
}

.lc-panel-badge-live {
  border-color: color-mix(in oklab, var(--primary) 24%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--primary);
}

.lc-panel-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.lc-panel-feed {
  flex: 0 0 auto;
  min-height: 0;
}

.lc-pos-active {
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--background) 80%, white);
  padding: 0.65rem 0.75rem;
  flex-shrink: 0;
}

.lc-pos-stats,
.lc-intel-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

@media (min-width: 640px) {
  .lc-pos-stats,
  .lc-intel-metrics {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.lc-pos-grid,
.lc-intel-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.65rem;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.lc-pos-queue {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.lc-pos-queue-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  border-radius: 0.6rem;
  border: 1px solid transparent;
  padding: 0.5rem 0.6rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    transform 0.25s ease;
}

.lc-pos-queue-row[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 24%, var(--border));
  background: color-mix(in oklab, var(--primary) 7%, transparent);
  transform: translateX(2px);
}

.lc-pos-queue-main {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

.lc-pos-queue-event {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.82rem;
  font-weight: 650;
  color: var(--foreground);
}

.lc-pos-queue-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.1rem;
  flex-shrink: 0;
  font-size: 0.75rem;
  color: var(--muted-foreground);
}

.lc-pos-queue-meta strong {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--foreground);
}

.lc-pos-active-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.lc-pos-active-head strong {
  font-family: var(--font-mono);
  font-size: 1rem;
  color: var(--primary);
}

.lc-pos-active-event {
  margin: 0.45rem 0 0;
  font-size: 0.92rem;
  font-weight: 650;
  color: var(--foreground);
}

.lc-pos-active-detail,
.lc-pos-active-buyer {
  margin: 0.2rem 0 0;
  font-size: 0.78rem;
  color: var(--muted-foreground);
}

.lc-pos-pipeline {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.lc-pos-pipeline-step {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  border-radius: 0.5rem;
  padding: 0.3rem 0.4rem;
  transition: background 0.25s ease;
}

.lc-pos-pipeline-step[data-current="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.lc-pos-pipeline-step[data-done="true"] .lc-pos-pipeline-label {
  color: var(--primary);
}

.lc-pos-pipeline-icon {
  display: inline-flex;
  flex-shrink: 0;
  margin-top: 0.1rem;
  color: color-mix(in oklab, var(--foreground) 28%, transparent);
}

.lc-pos-pipeline-step[data-done="true"] .lc-pos-pipeline-icon {
  color: var(--primary);
}

.lc-pos-pipeline-step[data-current="true"] .lc-pos-pipeline-icon {
  color: var(--primary);
}

.lc-pos-pipeline-label {
  display: block;
  font-size: 0.78rem;
  font-weight: 650;
  color: var(--foreground);
}

.lc-pos-pipeline-detail {
  display: block;
  margin-top: 0.06rem;
  font-size: 0.68rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.lc-spin {
  animation: lc-spin 1s linear infinite;
}

@keyframes lc-spin {
  to {
    transform: rotate(360deg);
  }
}

.lc-feed-viewport {
  position: relative;
  overflow: hidden;
  height: 5.5rem;
  flex-shrink: 0;
  mask-image: linear-gradient(180deg, transparent, black 12%, black 88%, transparent);
}

.lc-feed-viewport-sm {
  height: 4.75rem;
}

.lc-pos[data-live="true"] .lc-feed-list,
.lc-intel[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 18s linear infinite;
}

.lc-feed-list {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.lc-feed-row {
  display: grid;
  grid-template-columns: 4.5rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.65rem;
  font-size: 0.75rem;
}

.lc-feed-time {
  color: var(--muted-foreground);
}

.lc-feed-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--foreground);
}

.lc-feed-ok {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 18%, transparent);
}

.lc-feed-ok[data-ok="true"] {
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 16%, transparent);
}

@keyframes lc-feed-scroll {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-50%);
  }
}

.lc-intel-context {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.lc-intel-event {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
  color: var(--foreground);
}

.lc-intel-meta {
  margin: 0.2rem 0 0;
  font-size: 0.78rem;
  color: var(--muted-foreground);
}

.lc-intel-tag {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 20%, var(--border));
  background: color-mix(in oklab, var(--primary) 6%, transparent);
  padding: 0.25rem 0.6rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.lc-intel-metric {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas:
    "icon label"
    "icon value"
    "icon change";
  column-gap: 0.4rem;
  row-gap: 0.04rem;
  align-items: center;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.55rem 0.65rem;
}

.lc-intel-metric svg {
  grid-area: icon;
  color: var(--primary);
}

.lc-intel-metric .lc-stat-label {
  grid-area: label;
}

.lc-intel-metric .lc-stat-value {
  grid-area: value;
}

.lc-intel-change {
  grid-area: change;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--primary);
}

.lc-intel-bars {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.lc-intel-bar-row[data-active="true"] .lc-intel-bar-fill {
  background: var(--primary);
  box-shadow: 0 0 12px color-mix(in oklab, var(--primary) 35%, transparent);
}

.lc-intel-bar-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.3rem;
  font-size: 0.78rem;
}

.lc-intel-bar-head strong {
  font-family: var(--font-mono);
  font-size: 0.82rem;
}

.lc-intel-bar-track {
  height: 0.35rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

.lc-intel-bar-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: color-mix(in oklab, var(--primary) 55%, var(--foreground));
  transition:
    width 0.4s ease,
    background 0.25s ease,
    box-shadow 0.25s ease;
}

.lc-intel-chart {
  display: flex;
  align-items: flex-end;
  gap: 0.3rem;
  height: 7.5rem;
  padding-top: 0.25rem;
  flex-shrink: 0;
}

.lc-intel-chart-bar {
  flex: 1 1 0;
  min-width: 0;
  border-radius: 0.25rem 0.25rem 0.05rem 0.05rem;
  background: color-mix(in oklab, var(--primary) 45%, var(--foreground));
  transition: background 0.25s ease, opacity 0.25s ease;
}

.lc-intel-chart-bar[data-peak="true"] {
  background: var(--primary);
}

.lc-intel-chart-foot {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.45rem;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--muted-foreground);
}

.lc-intel-chart-mid {
  color: var(--primary);
}

/* Split layout + tilt showcase */

.lc-section {
  display: grid;
  gap: 2rem;
  align-items: start;
}

.lc-section-copy {
  position: relative;
  max-width: 38rem;
}

/* Copy panel — simple */

.lc-copy-title {
  margin-top: 1rem;
  max-width: 20ch;
  font-size: clamp(1.875rem, 2.8vw, 2.5rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.lc-copy-dark .lc-copy-title {
  color: var(--background);
}

.lc-copy-body {
  margin-top: 1rem;
  max-width: 42ch;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.lc-copy-dark .lc-copy-body {
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.lc-copy-detail {
  margin: 0;
  max-width: 44ch;
  font-size: 0.875rem;
  line-height: 1.65;
  color: color-mix(in oklab, var(--muted-foreground) 92%, var(--foreground));
}

.lc-copy-dark .lc-copy-detail {
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.lc-copy-detail-block {
  margin-top: 0.85rem;
}

.lc-copy-detail-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 0;
  background: transparent;
  padding: 0;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.lc-copy-detail-toggle:hover {
  opacity: 0.8;
}

.lc-copy-detail-toggle svg {
  transition: transform 0.25s ease;
}

.lc-copy-detail-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.28s ease;
}

.lc-copy-detail-panel[data-open="true"] {
  grid-template-rows: 1fr;
}

.lc-copy-detail-panel-inner {
  overflow: hidden;
}

.lc-copy-detail-panel[data-open="true"] .lc-copy-detail {
  margin-top: 0.65rem;
}

.lc-copy-accordion-wrap {
  margin-top: 1.35rem;
}

.lc-copy-accordion-label {
  margin: 0 0 0.65rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.lc-copy-dark .lc-copy-accordion-label {
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.lc-copy-accordion {
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 50%, transparent);
  overflow: hidden;
}

.lc-copy-dark .lc-copy-accordion {
  border-color: color-mix(in oklab, var(--background) 14%, transparent);
  background: color-mix(in oklab, var(--background) 4%, transparent);
}

.lc-copy-accordion-item {
  border-color: color-mix(in oklab, var(--foreground) 8%, transparent) !important;
}

.lc-copy-dark .lc-copy-accordion-item {
  border-color: color-mix(in oklab, var(--background) 10%, transparent) !important;
}

.lc-copy-accordion-item:last-child {
  border-bottom: 0 !important;
}

.lc-copy-accordion-trigger {
  gap: 0.65rem !important;
  padding: 0.75rem 0.85rem !important;
  font-size: 0.9375rem !important;
  font-weight: 600 !important;
  text-decoration: none !important;
  color: var(--foreground) !important;
}

.lc-copy-dark .lc-copy-accordion-trigger {
  color: var(--background) !important;
}

.lc-copy-accordion-trigger:hover {
  background: color-mix(in oklab, var(--primary) 5%, transparent);
}

.lc-copy-accordion-trigger[data-state="open"] {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
}

.lc-copy-accordion-index {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
  flex-shrink: 0;
}

.lc-copy-accordion-title {
  flex: 1;
  text-align: left;
}

.lc-copy-accordion-content {
  font-size: inherit !important;
}

.lc-copy-accordion-body {
  margin: 0;
  padding: 0 0.85rem 0.85rem 2.35rem;
  max-width: 44ch;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--muted-foreground);
}

.lc-copy-dark .lc-copy-accordion-body {
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.lc-copy-highlights {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 1.25rem 0 0;
}

.lc-copy-highlight {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, transparent);
  padding: 0.45rem 0.65rem;
}

.lc-copy-highlight-value {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary);
}

.lc-copy-highlight-label {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.lc-copy-dark .lc-copy-highlight-label {
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .lc-copy-detail-panel,
  .lc-copy-detail-toggle svg,
  .lc-copy-accordion-trigger svg {
    transition: none;
  }
}

.lc-section-stage {
  min-width: 0;
  align-self: start;
}

.lc-tilt-wrap {
  position: relative;
  perspective: 1400px;
  perspective-origin: 42% 50%;
}

.lc-tilt-card {
  position: relative;
  transform-style: preserve-3d;
  transform: rotateY(var(--lc-tilt-y, -12deg)) rotateX(var(--lc-tilt-x, 4deg));
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform;
}

.lc-section-stage:hover .lc-tilt-card,
.lc-tilt-wrap:focus-within .lc-tilt-card {
  transform: rotateY(calc(var(--lc-tilt-y, -12deg) * 0.45)) rotateX(calc(var(--lc-tilt-x, 4deg) * 0.6))
    translateY(-2px);
}

.lc-tilt-card .lc-frame,
.lc-tilt-card .ap-shell,
.lc-tilt-card .qb-shell {
  position: relative;
  z-index: 2;
}

.lc-tilt-badge {
  position: absolute;
  top: -0.55rem;
  right: -0.55rem;
  z-index: 5;
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  color: var(--primary);
  box-shadow: 0 10px 24px -16px oklch(0.28 0.04 160 / 0.45);
  transform: translateZ(24px);
}

.lc-tilt-shadow {
  pointer-events: none;
  position: absolute;
  z-index: 0;
  inset: auto 8% -1.25rem 12%;
  height: 2.5rem;
  border-radius: 50%;
  background: radial-gradient(
    ellipse at center,
    color-mix(in oklab, var(--foreground) 18%, transparent),
    transparent 70%
  );
  filter: blur(8px);
  transform: rotateX(72deg) translateZ(-12px);
}

@media (min-width: 1024px) {
  .lc-section {
    grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.28fr);
    gap: 2.5rem 3.5rem;
    align-items: start;
  }

  .lc-section-copy {
    position: sticky;
    top: 6rem;
    align-self: start;
  }

  .lc-section-stage {
    position: sticky;
    top: 6rem;
    align-self: start;
  }

  .lc-tilt-wrap {
    margin-left: auto;
    width: 100%;
    max-width: min(100%, 46rem);
  }
}

/* Brokers hero — live console wall.
   Shared padding-top clears the 4.5rem fixed light nav + 1.25rem gap
   (`clamp(5.75rem, 8vh, 7.5rem)`). Product/company heroes inherit this
   (abt/bdm/plt/faq/legal/ct + PageHero). Contact desktop zeros section
   padding and applies the same value on `.ct-hero-copy`. */

.bh-hero {
  padding-top: clamp(5.75rem, 8vh, 7.5rem);
  padding-bottom: clamp(4.5rem, 10vw, 7rem);
  margin-top: clamp(0.25rem, 0.65vw, 0.5rem);
}

.bh-layout {
  display: grid;
  gap: clamp(2.5rem, 5vw, 4rem);
  align-items: center;
}

@media (min-width: 1024px) {
  .bh-layout {
    grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
    gap: clamp(2rem, 4vw, 3.5rem);
  }
}

.bh-copy {
  max-width: 36rem;
}

.bh-copy-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.35rem;
  height: 2.35rem;
  margin-bottom: 1rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
  box-shadow: 0 0 24px color-mix(in oklab, var(--primary) 22%, transparent);
}

.bh-title {
  margin-top: 1rem;
  font-size: clamp(2rem, 4.2vw, 3.35rem);
  font-weight: 700;
  line-height: 1.06;
  letter-spacing: -0.03em;
}

.bh-subhead {
  margin-top: 1rem;
  font-size: clamp(1rem, 1.8vw, 1.2rem);
  font-weight: 600;
  line-height: 1.45;
  color: color-mix(in oklab, var(--background) 92%, var(--primary));
}

.bh-body {
  margin-top: 1rem;
  max-width: 34rem;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.bh-points {
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.45rem;
}

.bh-points li {
  position: relative;
  padding-left: 1rem;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.bh-points li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 8px color-mix(in oklab, var(--primary) 45%, transparent);
}

.bh-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.75rem;
}

.bh-stage {
  min-width: 0;
  position: relative;
}

.bh-wall {
  position: relative;
  perspective: 1200px;
  perspective-origin: 42% 50%;
}

.bh-wall-glow {
  pointer-events: none;
  position: absolute;
  inset: 8% 10%;
  border-radius: 2rem;
  background: radial-gradient(
    ellipse at center,
    color-mix(in oklab, var(--primary) 16%, transparent),
    transparent 68%
  );
  filter: blur(18px);
}

.bh-wall-bridge {
  pointer-events: none;
  position: absolute;
  top: 12%;
  bottom: 12%;
  left: 50%;
  z-index: 2;
  width: 1px;
  transform: translateX(-50%);
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 35%, transparent) 20%,
    color-mix(in oklab, var(--primary) 45%, transparent) 50%,
    color-mix(in oklab, var(--primary) 35%, transparent) 80%,
    transparent
  );
  opacity: 0.55;
}

.bh-wall-bridge::before,
.bh-wall-bridge::after {
  content: "";
  position: absolute;
  left: 50%;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  transform: translateX(-50%);
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 50%, transparent);
  animation: bh-bridge-pulse 3.2s ease-in-out infinite;
}

.bh-wall-bridge::before {
  top: 18%;
}

.bh-wall-bridge::after {
  bottom: 22%;
  animation-delay: 1.6s;
}

.bh-wall-mask {
  position: relative;
  overflow: hidden;
  height: clamp(22rem, 52vh, 34rem);
  border-radius: 1.25rem;
  mask-image: linear-gradient(
    180deg,
    transparent,
    black 10%,
    black 90%,
    transparent
  );
  -webkit-mask-image: linear-gradient(
    180deg,
    transparent,
    black 10%,
    black 90%,
    transparent
  );
}

.bh-wall-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
  height: 100%;
  padding-inline: 0.15rem;
  transform: rotateY(-10deg) rotateX(5deg);
  transform-style: preserve-3d;
}

.bh-col {
  position: relative;
  min-width: 0;
  overflow: hidden;
}

.bh-track {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  will-change: transform;
}

.bh-track-group {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.bh-col-up .bh-track {
  animation: bh-scroll-up var(--bh-duration, 23s) linear infinite;
}

.bh-col-down .bh-track {
  animation: bh-scroll-down var(--bh-duration, 27s) linear infinite;
}

@keyframes bh-scroll-up {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(0, -50%, 0);
  }
}

@keyframes bh-scroll-down {
  from {
    transform: translate3d(0, -50%, 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

@keyframes bh-bridge-pulse {
  0%,
  100% {
    opacity: 0.45;
    transform: translateX(-50%) scale(0.85);
  }
  50% {
    opacity: 1;
    transform: translateX(-50%) scale(1);
  }
}

.bh-card {
  flex-shrink: 0;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--background) 14%, transparent);
  background: color-mix(in oklab, var(--background) 7%, oklch(0.2 0.015 160 / 0.72));
  box-shadow:
    0 1px 0 color-mix(in oklab, var(--background) 8%, transparent) inset,
    0 18px 40px -28px oklch(0 0 0 / 0.55);
  backdrop-filter: blur(10px);
  padding: 0.65rem 0.7rem 0.7rem;
}

.bh-card-accent {
  border-color: color-mix(in oklab, var(--primary) 28%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, oklch(0.2 0.015 160 / 0.78));
}

.bh-card-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.55rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.bh-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--primary);
}

.bh-card-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bh-card-live {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 24%, transparent);
  padding: 0.08rem 0.38rem;
  font-size: 8px;
  color: var(--primary);
}

.bh-card-live-dot {
  width: 0.34rem;
  height: 0.34rem;
  border-radius: 999px;
  background: var(--primary);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.bh-card-body {
  display: grid;
  gap: 0.45rem;
}

.bh-metrics {
  display: grid;
  gap: 0.35rem;
}

.bh-metrics-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.bh-metrics-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.bh-metric-label {
  display: block;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.bh-metric-value {
  display: block;
  margin-top: 0.08rem;
  font-family: var(--font-mono);
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--background);
}

.bh-metric-sm {
  font-size: 0.72rem;
}

.bh-metric-up {
  color: var(--primary);
}

.bh-tick {
  animation: bh-value-glow 4s ease-in-out infinite;
}

@keyframes bh-value-glow {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.82;
    text-shadow: 0 0 12px color-mix(in oklab, var(--primary) 35%, transparent);
  }
}

.bh-card-title {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 650;
  line-height: 1.3;
  color: var(--background);
}

.bh-card-title-sm {
  font-size: 0.76rem;
}

.bh-card-meta,
.bh-card-event,
.bh-card-foot {
  margin: 0;
  font-size: 0.68rem;
  line-height: 1.4;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.bh-bar-stack {
  display: grid;
  gap: 0.22rem;
}

.bh-bar-fill {
  display: block;
  height: 0.28rem;
  width: var(--bh-bar, 50%);
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 70%, transparent),
    color-mix(in oklab, var(--primary) 35%, transparent)
  );
  animation: bh-bar-breathe 3.6s ease-in-out infinite;
}

.bh-bar-fill-delay {
  animation-delay: 0.6s;
}

.bh-bar-fill-delay-2 {
  animation-delay: 1.2s;
}

@keyframes bh-bar-breathe {
  0%,
  100% {
    transform: scaleX(0.92);
    opacity: 0.75;
  }
  50% {
    transform: scaleX(1);
    opacity: 1;
  }
}

.bh-mp-list {
  display: grid;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bh-mp-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border-radius: 0.45rem;
  padding: 0.28rem 0.35rem;
  font-size: 0.68rem;
  color: color-mix(in oklab, var(--background) 72%, transparent);
  background: color-mix(in oklab, var(--background) 4%, transparent);
}

.bh-mp-row[data-status="pushing"] {
  border: 1px solid color-mix(in oklab, var(--primary) 22%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.bh-mp-meta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.bh-mp-count {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--background);
}

.bh-mp-status {
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.bh-mp-row[data-status="pushing"] .bh-mp-status {
  animation: bh-status-blink 2.4s ease-in-out infinite;
}

@keyframes bh-status-blink {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

.bh-ai-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
}

.bh-ai-badge {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  padding: 0.12rem 0.42rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.bh-price-live {
  animation: bh-price-shift 5s ease-in-out infinite;
}

@keyframes bh-price-shift {
  0%,
  100% {
    color: var(--background);
  }
  50% {
    color: var(--primary);
  }
}

.bh-sparkline {
  width: 100%;
  height: 1.75rem;
}

.bh-sparkline-line {
  fill: none;
  stroke: var(--primary);
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 140;
  animation: bh-sparkline-draw 4.5s ease-in-out infinite;
}

@keyframes bh-sparkline-draw {
  0% {
    stroke-dashoffset: 140;
    opacity: 0.45;
  }
  50% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
  100% {
    stroke-dashoffset: -40;
    opacity: 0.55;
  }
}

.bh-log-list {
  position: relative;
  display: grid;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bh-log-row {
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: 0.35rem;
  align-items: baseline;
  border-radius: 0.35rem;
  padding: 0.15rem 0.2rem;
  font-size: 0.62rem;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.bh-log-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: color-mix(in oklab, var(--background) 82%, transparent);
}

.bh-log-dot {
  width: 0.3rem;
  height: 0.3rem;
  margin-top: 0.2rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 35%, transparent);
}

.bh-log-dot[data-ok="true"] {
  background: var(--primary);
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--primary) 18%, transparent);
}

.bh-log-time {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: color-mix(in oklab, var(--background) 45%, transparent);
}

.bh-log-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bh-log-scan {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 10%, transparent) 50%,
    transparent
  );
  opacity: 0.35;
  animation: bh-log-scan 4s ease-in-out infinite;
  pointer-events: none;
}

@keyframes bh-log-scan {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(100%);
  }
}

.bh-flow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.15rem 0.1rem;
}

.bh-flow-node {
  position: relative;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  padding: 0.18rem 0.42rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 600;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.bh-flow-node[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, transparent);
  color: var(--background);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.bh-flow-link {
  position: relative;
  display: inline-block;
  width: 0.85rem;
  height: 1px;
  margin-inline: 0.08rem;
  background: color-mix(in oklab, var(--primary) 35%, transparent);
}

.bh-flow-packet {
  position: absolute;
  top: 50%;
  left: 0;
  width: 0.28rem;
  height: 0.28rem;
  border-radius: 999px;
  background: var(--primary);
  transform: translate(-50%, -50%);
  animation: bh-packet-move 2.2s linear infinite;
}

@keyframes bh-packet-move {
  from {
    left: 0;
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  80% {
    opacity: 1;
  }
  to {
    left: 100%;
    opacity: 0;
  }
}

.bh-chart-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.18rem;
  height: 2rem;
}

.bh-chart-bar {
  flex: 1 1 0;
  height: var(--bh-h, 50%);
  border-radius: 0.2rem 0.2rem 0.05rem 0.05rem;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--primary) 72%, transparent),
    color-mix(in oklab, var(--primary) 28%, transparent)
  );
  transform-origin: bottom;
  animation: bh-chart-pulse 3s ease-in-out infinite;
  animation-delay: calc(var(--bh-i, 0) * 0.12s);
}

@keyframes bh-chart-pulse {
  0%,
  100% {
    transform: scaleY(0.88);
    opacity: 0.7;
  }
  50% {
    transform: scaleY(1);
    opacity: 1;
  }
}

.bh-desk-pulse {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, transparent);
  padding: 0.18rem 0.45rem;
  font-size: 0.6rem;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.bh-desk-pulse svg {
  color: var(--primary);
  animation: bh-desk-icon 2.8s ease-in-out infinite;
}

@keyframes bh-desk-icon {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

@media (max-width: 1023px) {
  .bh-wall-mask {
    height: clamp(18rem, 42vh, 26rem);
  }

  .bh-wall-grid {
    transform: rotateY(-6deg) rotateX(3deg);
    gap: 0.65rem;
  }
}

@media (max-width: 639px) {
  .bh-wall-grid {
    grid-template-columns: 1fr;
    transform: none;
  }

  .bh-col-down {
    display: none;
  }

  .bh-wall-bridge {
    display: none;
  }

  .bh-wall-mask {
    height: clamp(16rem, 38vh, 22rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bh-col-up .bh-track,
  .bh-col-down .bh-track,
  .bh-bar-fill,
  .bh-sparkline-line,
  .bh-log-scan,
  .bh-flow-packet,
  .bh-chart-bar,
  .bh-card-live-dot,
  .bh-desk-pulse svg,
  .bh-wall-bridge::before,
  .bh-wall-bridge::after,
  .bh-tick,
  .bh-price-live,
  .bh-mp-row[data-status="pushing"] .bh-mp-status {
    animation: none !important;
  }

  .bh-col-down {
    display: block;
  }

  .bh-wall-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Event catalog — centered copy + flat console */

.ec-section {
  height: auto;
  min-height: 0;
  overflow: visible;
}

.ec-head {
  margin-inline: auto;
  max-width: 44rem;
  text-align: center;
}

.ec-title {
  margin-top: 1rem;
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.ec-lead {
  margin: 1rem auto 0;
  max-width: 42rem;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.ec-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.45rem;
  margin: 1.5rem 0 0;
  padding: 0;
  list-style: none;
}

.ec-tags li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, transparent);
  padding: 0.35rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: color-mix(in oklab, var(--foreground) 82%, var(--primary));
}

.ec-console-wrap {
  margin-top: 2.75rem;
  width: 100%;
  height: auto;
  overflow: visible;
}

.ec-catalog {
  width: 100%;
}

.ec-catalog .lc-frame {
  max-width: 100%;
}

.ec-catalog .lc-screen {
  height: auto;
  min-height: 0;
  max-height: none;
  overflow: visible;
}

@media (min-width: 1024px) {
  .ec-catalog .lc-screen {
    height: auto;
    min-height: 0;
    max-height: none;
  }
}

.ec-catalog .lc-body {
  display: grid;
  grid-template-rows: auto auto auto auto;
  gap: 0.55rem;
  padding: clamp(0.7rem, 1.4vw, 0.95rem);
  flex: 0 0 auto;
  height: auto;
  min-height: 0;
  overflow: visible;
}

.ec-catalog-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
}

@media (min-width: 640px) {
  .ec-catalog-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.ec-catalog-toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

@media (min-width: 768px) {
  .ec-catalog-toolbar {
    flex-direction: row;
    align-items: center;
    gap: 0.75rem;
  }
}

.ec-catalog-search {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.48rem 0.65rem;
  color: var(--muted-foreground);
  font-size: 0.78rem;
}

@media (min-width: 768px) {
  .ec-catalog-search {
    flex: 0 1 17rem;
  }
}

.ec-catalog-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

@media (min-width: 768px) {
  .ec-catalog-pills {
    flex: 1 1 auto;
    justify-content: flex-end;
  }
}

.ec-catalog-pill {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.2rem 0.52rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}

.ec-catalog-pill[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--primary);
}

.ec-catalog-workspace {
  display: grid;
  grid-template-columns: minmax(8.5rem, 10.5rem) minmax(0, 1fr);
  gap: 0.6rem;
  min-height: 0;
  height: auto;
  overflow: visible;
  align-items: start;
}

.ec-catalog-sidebar {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.6rem 0.5rem;
  min-height: 0;
  height: auto;
  overflow: visible;
}

.ec-catalog-sidebar-list {
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex: 0 0 auto;
  min-height: 0;
  overflow: visible;
  overscroll-behavior: auto;
}

.ec-catalog-sidebar-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  border-radius: 0.5rem;
  padding: 0.38rem 0.42rem;
  font-size: 0.72rem;
  color: var(--muted-foreground);
  transition:
    background 0.25s ease,
    color 0.25s ease;
}

.ec-catalog-sidebar-item strong {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  color: color-mix(in oklab, var(--foreground) 55%, transparent);
}

.ec-catalog-sidebar-item[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--foreground);
}

.ec-catalog-sidebar-item[data-active="true"] strong {
  color: var(--primary);
}

.ec-catalog-sidebar-label {
  margin: 0;
  padding-inline: 0.35rem;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ec-catalog-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.6rem;
  min-width: 0;
  min-height: 0;
  height: auto;
  overflow: visible;
  align-items: start;
}

.ec-catalog .lc-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: auto;
  overflow: visible;
}

.ec-catalog .lc-pos-queue,
.ec-catalog-queue {
  flex: 0 0 auto;
  min-height: 0;
  overflow: visible;
  overscroll-behavior: auto;
}

.ec-catalog .lc-pos-queue-row[data-active="true"] {
  transform: none;
}

.ec-catalog-row-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.ec-catalog-onsale {
  display: inline-flex;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.08rem 0.38rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: none;
}

.ec-catalog-active {
  margin-bottom: 0.4rem;
  padding: 0.45rem 0.55rem;
}

.ec-catalog .lc-panel-accent {
  gap: 0.35rem;
}

.ec-catalog-detail {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  gap: 0.4rem;
  min-height: 0;
