  min-width: 0;
}

.ec-catalog-detail-card-label {
  display: inline-flex;
  align-items: center;
  gap: 0.22rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ec-catalog-detail-card strong {
  font-size: 0.68rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--foreground);
}

.ec-catalog-intel-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

@media (min-width: 640px) {
  .ec-catalog-intel-cards {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.ec-catalog-intel-card {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--primary) 16%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, white);
  padding: 0.35rem 0.42rem;
  min-width: 0;
}

.ec-catalog-intel-card span {
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ec-catalog-intel-card strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--foreground);
}

.ec-catalog-sections {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.ec-catalog-section-bars {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
}

.ec-catalog-section-bar {
  display: block;
  height: 0.3rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 10%, transparent);
  transition: background 0.25s ease;
}

.ec-catalog-section-bar[data-peak="true"] {
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 72%, transparent),
    color-mix(in oklab, var(--primary) 38%, transparent)
  );
}

.ec-catalog-pipeline {
  display: flex;
  flex: none;
  flex-direction: row;
  flex-wrap: nowrap;
  gap: 0.35rem;
  margin: 0;
  min-height: 4.75rem;
  padding: 0.12rem 0 0.65rem;
  max-height: none;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior: auto;
}

.ec-catalog-pipeline .lc-pos-pipeline-step {
  flex: 0 0 auto;
  min-width: 6.75rem;
  max-width: 8.25rem;
  min-height: 4.1rem;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.38rem 0.42rem;
}

.ec-catalog-pipeline .lc-pos-pipeline-detail {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 0.62rem;
  line-height: 1.35;
}

.ec-catalog-scroll {
  overflow: visible;
  overscroll-behavior: auto;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--primary) 42%, transparent) transparent;
}

.ec-catalog-scroll-x {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--primary) 32%, transparent) transparent;
}

.ec-catalog-scroll::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

.ec-catalog-scroll-x::-webkit-scrollbar {
  width: 0;
  height: 4px;
}

.ec-catalog-scroll::-webkit-scrollbar-thumb,
.ec-catalog-scroll-x::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 38%, transparent);
}

.ec-catalog-scroll::-webkit-scrollbar-track,
.ec-catalog-scroll-x::-webkit-scrollbar-track {
  background: transparent;
}

.ec-catalog .lc-panel-feed {
  min-height: 0;
  overflow: visible;
}

.ec-catalog .lc-feed-viewport-sm {
  height: 3.5rem;
  max-height: 3.5rem;
}

.ec-catalog[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 18s linear infinite;
}

@media (max-width: 1023px) {
  .ec-catalog-workspace {
    grid-template-columns: 1fr;
  }

  .ec-catalog-sidebar {
    max-height: none;
    align-self: stretch;
  }

  .ec-catalog-sidebar-list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ec-catalog-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 767px) {
