/* Inventory management — centered copy + layered console */

.inv-section {
  overflow: hidden;
}

.inv-head {
  margin-inline: auto;
  max-width: 44rem;
  text-align: center;
}

.inv-title {
  margin-top: 1rem;
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.inv-lead {
  margin: 1rem auto 0;
  max-width: 42rem;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.inv-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.45rem;
  margin: 1.5rem 0 0;
  padding: 0;
  list-style: none;
}

.inv-tags li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, transparent);
  padding: 0.35rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: color-mix(in oklab, var(--foreground) 82%, var(--primary));
}

.inv-console-wrap {
  margin-top: 2rem;
  width: 100%;
}

.inv-features {
  display: grid;
  gap: 0.55rem;
  margin: 1.5rem 0 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 768px) {
  .inv-features {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.65rem;
  }
}

.inv-feature {
  padding: 0.75rem 0.85rem;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--border) 92%, transparent);
  background: color-mix(in oklab, var(--card) 96%, white);
}

.inv-feature-title {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--foreground);
}

.inv-feature-body {
  margin: 0.35rem 0 0;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

.inv-console {
  width: 100%;
}

.inv-stack {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(15.5rem, 20.5rem);
  column-gap: clamp(0.45rem, 1.2vw, 0.75rem);
  align-items: center;
  width: 100%;
}

.inv-console-base {
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  z-index: 1;
}

.inv-console-detail {
  grid-column: 2;
  grid-row: 1;
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: none;
  margin: 0 0 0 clamp(-0.85rem, -1.8vw, -0.35rem);
  align-self: center;
  transform: translateY(0.15rem);
}

.inv-console-base,
.inv-console-detail {
  width: 100%;
}

.inv-console-base .lc-frame,
.inv-console-detail .lc-frame {
  max-width: 100%;
}

.inv-console-base .lc-screen {
  min-height: clamp(15rem, 30vw, 18rem);
  height: auto;
  overflow: hidden;
}

.inv-console-base .lc-body {
  gap: 0.45rem;
  padding: clamp(0.5rem, 1.1vw, 0.7rem);
  flex: 0 1 auto;
  height: auto;
  overflow: visible;
}

.inv-console-detail .lc-bezel {
  padding: 0.45rem;
  box-shadow:
    0 32px 64px -28px color-mix(in oklab, var(--foreground) 28%, transparent),
    0 0 0 1px color-mix(in oklab, white 70%, transparent) inset;
}

.inv-console-detail .lc-screen {
  min-height: 0;
  height: max-content;
  overflow: hidden;
  border-color: color-mix(in oklab, var(--primary) 14%, var(--border));
  box-shadow:
    0 1px 0 color-mix(in oklab, white 92%, transparent) inset,
    0 24px 48px -20px color-mix(in oklab, var(--primary) 18%, transparent);
}

.inv-console-detail .lc-body {
  gap: 0.4rem;
  padding: 0.55rem 0.6rem 0.6rem;
  flex: 0 1 auto;
  height: auto;
}

.inv-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
  flex-shrink: 0;
}

.inv-stat {
  padding: 0.42rem 0.55rem;
  gap: 0.1rem;
}

.inv-stat .lc-stat-value {
  font-size: 0.88rem;
}

@media (min-width: 640px) {
  .inv-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.inv-base-grid {
  display: grid;
  grid-template-columns: 8rem minmax(0, 1fr);
  gap: 0.5rem;
  align-items: start;
  min-width: 0;
}

.inv-base-main {
  min-width: 0;
}

.inv-base-nav {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0.45rem;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, var(--border));
  background: color-mix(in oklab, var(--foreground) 7%, var(--card));
  color: color-mix(in oklab, var(--foreground) 92%, white);
  box-shadow: 0 10px 24px -18px color-mix(in oklab, var(--foreground) 20%, transparent);
}

.inv-base-foot {
  margin-top: 0.45rem;
}

.inv-base-foot .lc-panel {
  padding: 0.45rem 0.5rem;
  gap: 0.28rem;
}

.inv-nav-brand {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.45rem;
  padding-bottom: 0.4rem;
  border-bottom: 1px solid color-mix(in oklab, white 8%, transparent);
  font-size: 0.66rem;
  font-weight: 700;
}

.inv-nav-mark {
  display: grid;
  place-items: center;
  width: 1.45rem;
  height: 1.45rem;
  border-radius: 0.4rem;
  background: color-mix(in oklab, var(--primary) 22%, transparent);
  color: var(--primary);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 800;
}

.inv-nav-list {
  display: grid;
  gap: 0.12rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.inv-nav-item {
  padding: 0.24rem 0.38rem;
  border-radius: 0.38rem;
  font-size: 0.58rem;
  font-weight: 600;
  color: color-mix(in oklab, white 72%, var(--foreground));
}

.inv-nav-item[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 18%, transparent);
  color: white;
}

.inv-layer-dash {
  display: none;
}

.inv-console-detail .inv-detail-head {
  flex-direction: column;
  align-items: stretch;
  gap: 0.35rem;
}

.inv-console-detail .inv-detail-head-copy {
  min-width: 0;
}

.inv-console-detail .inv-detail-account {
  align-self: flex-start;
  max-width: 100%;
  white-space: normal;
}

.inv-console-detail .inv-detail-account > span:last-child {
