.inv-detail-account,
.inv-modal-account {
  display: flex;
  align-items: center;
  gap: 0.32rem;
  flex-shrink: 0;
  padding: 0.24rem 0.38rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 92%, white);
  font-size: 0.52rem;
  text-align: left;
  white-space: nowrap;
}

.inv-detail-account strong,
.inv-modal-account strong {
  display: block;
  font-size: 0.54rem;
  font-weight: 700;
  color: var(--foreground);
