.inv-detail-search,
.inv-modal-search {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 0.32rem;
  min-width: 0;
  padding: 0.28rem 0.4rem;
  border-radius: 0.45rem;
  border: 1px solid var(--border);
  background: var(--background);
  font-size: 0.56rem;
  color: var(--muted-foreground);
}

.inv-detail-filter,
.inv-modal-filter {
