/* FeatureGrid — infinity dual-lobe orbit (light theme) */

.fg-orbit-panel {
  position: relative;
  overflow: hidden;
  border-radius: 1.5rem;
  border: 1px solid color-mix(in oklab, var(--border) 88%, transparent);
  background:
    radial-gradient(
      ellipse 72% 58% at 50% 42%,
      color-mix(in oklab, var(--primary) 6%, transparent),
      transparent 74%
    ),
    var(--background);
  box-shadow: 0 32px 72px -52px color-mix(in oklab, var(--foreground) 16%, transparent);
}

.fg-orbit-panel::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    color-mix(in oklab, var(--foreground) 7%, transparent) 1px,
    transparent 1px
  );
  background-size: 24px 24px;
  mask-image: radial-gradient(ellipse 88% 78% at 50% 48%, black 12%, transparent 80%);
  opacity: 0.4;
}

.fg-infinity {
  position: relative;
  padding: clamp(1.5rem, 3vw, 2.25rem) clamp(0.75rem, 2vw, 1.25rem);
}

.fg-infinity-viewport {
  position: relative;
  width: min(100%, 42rem);
  margin-inline: auto;
  aspect-ratio: 2 / 1;
  min-height: clamp(14rem, 38vw, 18rem);
  overflow: hidden;
  mask-image: linear-gradient(
    180deg,
    transparent,
    black 10%,
    black 90%,
    transparent
  );
  -webkit-mask-image: linear-gradient(
    180deg,
    transparent,
    black 10%,
    black 90%,
    transparent
  );
}

.fg-infinity-track {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.fg-infinity-loop {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 72%, transparent);
  stroke-width: 0.85;
  vector-effect: non-scaling-stroke;
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--primary) 28%, transparent));
}

.fg-infinity-loop-glow {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 18%, transparent);
  stroke-width: 2.2;
  vector-effect: non-scaling-stroke;
  opacity: 0.55;
}

.fg-infinity-join {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 6;
  display: grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  translate: -50% -50%;
  pointer-events: none;
}

.fg-infinity-arrow {
  width: 1.1rem;
  height: 1.1rem;
  color: var(--primary);
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 24%, transparent));
}

.fg-infinity-join-packet {
  position: absolute;
  left: -0.55rem;
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 14%, transparent);
  animation: fg-infinity-packet 5.5s ease-in-out infinite;
}

@keyframes fg-infinity-packet {
  0% {
    left: -0.55rem;
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  88% {
    opacity: 1;
  }
  100% {
    left: 1.15rem;
    opacity: 0;
  }
}

.fg-infinity-lobe {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}

.fg-infinity-lobe-rings {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.fg-infinity-ring {
  fill: none;
  vector-effect: non-scaling-stroke;
}

.fg-infinity-ring-outer {
  stroke: color-mix(in oklab, var(--foreground) 10%, transparent);
  stroke-width: 0.42;
  stroke-dasharray: 2.5 3.5;
}

.fg-infinity-ring-mid {
  stroke: color-mix(in oklab, var(--primary) 18%, transparent);
  stroke-width: 0.35;
  stroke-dasharray: 2 3;
}

.fg-infinity-ring-inner {
  stroke: color-mix(in oklab, var(--foreground) 7%, transparent);
  stroke-width: 0.28;
}

.fg-infinity-spoke {
  stroke: color-mix(in oklab, var(--foreground) 8%, transparent);
  stroke-width: 0.24;
  stroke-dasharray: 1.2 2;
  animation: fg-infinity-spoke-flow 7s linear infinite;
  animation-delay: calc(var(--fg-spoke-i, 0) * 0.35s);
}

@keyframes fg-infinity-spoke-flow {
  to {
    stroke-dashoffset: -7;
  }
}

.fg-orbit-drift {
  will-change: transform;
  padding-block: 2.25rem;
}

.fg-orbit-drift-left {
  animation: fg-orbit-slide-down var(--fg-duration, 20s) ease-in-out infinite alternate;
  animation-delay: var(--fg-delay, 0s);
}

.fg-orbit-drift-right {
  animation: fg-orbit-slide-up var(--fg-duration, 24s) ease-in-out infinite alternate;
  animation-delay: var(--fg-delay, 0s);
}

@keyframes fg-orbit-slide-down {
  from {
    transform: translate3d(0, -1.75rem, 0);
  }
  to {
    transform: translate3d(0, 1.75rem, 0);
  }
}

@keyframes fg-orbit-slide-up {
  from {
    transform: translate3d(0, 1.75rem, 0);
  }
  to {
    transform: translate3d(0, -1.75rem, 0);
  }
}

.fg-infinity-node {
  position: absolute;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  width: clamp(4.75rem, 12vw, 6.25rem);
  translate: -50% -50%;
  text-align: center;
  pointer-events: auto;
}

.fg-infinity-node-bubble {
  display: grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
  box-shadow:
    0 1px 0 color-mix(in oklab, white 80%, transparent) inset,
    0 12px 28px -20px color-mix(in oklab, var(--foreground) 16%, transparent);
}

.fg-infinity-node[data-side="left"] .fg-infinity-node-bubble {
  background: color-mix(in oklab, var(--foreground) 4%, white);
  border-color: color-mix(in oklab, var(--foreground) 12%, transparent);
  color: color-mix(in oklab, var(--foreground) 78%, transparent);
}

.fg-infinity-node[data-side="right"] .fg-infinity-node-bubble {
  background: color-mix(in oklab, var(--primary) 10%, white);
  border-color: color-mix(in oklab, var(--primary) 22%, transparent);
  color: var(--primary);
}

.fg-infinity-node-title {
  margin: 0;
  font-size: clamp(0.58rem, 1.35vw, 0.68rem);
  font-weight: 600;
  line-height: 1.2;
  color: var(--foreground);
}

@media (max-width: 639px) {
  .fg-orbit-panel {
    border-radius: 1.1rem;
  }

  .fg-infinity {
    padding-inline: 0.35rem;
  }

  .fg-infinity-viewport {
    min-height: clamp(12rem, 52vw, 15rem);
  }

  .fg-infinity-node {
    width: 4.25rem;
  }

  .fg-infinity-node-bubble {
    width: 2.35rem;
    height: 2.35rem;
  }

  .fg-infinity-node-title {
    font-size: 0.54rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fg-orbit-drift-left,
  .fg-orbit-drift-right,
  .fg-infinity-spoke,
  .fg-infinity-join-packet {
    animation: none !important;
  }
}

/* Payment infrastructure ---------------------------------------------- */

.pay-infra-backdrop {
  pointer-events: none;
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.pay-infra-backdrop-grid {
  position: absolute;
  inset: 0;
  opacity: 0.35;
  background-image: radial-gradient(color-mix(in oklab, var(--primary) 16%, transparent) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(ellipse 80% 60% at 70% 40%, black, transparent 72%);
}

.pay-infra-backdrop-glow {
  position: absolute;
  top: 8%;
  right: -8%;
  width: min(42rem, 70vw);
  height: min(42rem, 70vw);
  border-radius: 999px;
