}

.pay-dash {
  width: 100%;
}

.pay-dash-shell {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--muted) 28%, white);
  padding: clamp(0.75rem, 1.6vw, 0.95rem);
  box-shadow:
