}

.pay-dash-top-band .pay-dash-kpis {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (min-width: 1280px) {
  .pay-dash-top-band .pay-dash-kpis {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.pay-dash-main-grid {
  display: grid;
  gap: 0.6rem;
  min-width: 0;
}

@media (min-width: 1024px) {
  .pay-dash-main-grid {
    grid-template-columns: minmax(0, 1.42fr) minmax(0, 0.78fr);
    align-items: stretch;
  }
}

.pay-dash-main-col,
.pay-dash-side-stack {
  display: grid;
  gap: 0.6rem;
  min-width: 0;
  align-content: start;
}

.pay-dash-live-bar {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 6%, white);
  padding: 0.42rem 0.65rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.pay-dash-live-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
}

.pay-dash[data-live="true"] .pay-dash-live-dot {
  animation: pay-dash-live-pulse 2s ease-in-out infinite;
}

@keyframes pay-dash-live-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }

  50% {
    opacity: 0.55;
    transform: scale(0.88);
  }
}

.pay-dash-live-label {
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

.pay-dash-live-msg {
