  color: var(--foreground);
}

.pay-dash[data-live="true"] .pay-dash-live-msg {
  animation: pay-dash-feed-fade 0.45s ease;
}

@keyframes pay-dash-feed-fade {
  from {
    opacity: 0;
    transform: translateY(3px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.pay-dash-overview-head,
.pay-dash-module-head {
