}

@keyframes pay-dash-spark-draw {
  0% {
    stroke-dashoffset: 120;
    opacity: 0.45;
  }

  45%,
  100% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}

.pay-dash-module-cards {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  min-width: 0;
}

.pay-dash-cards-table {
