  flex-direction: column;
  gap: 0.5rem;
  min-width: 0;
  overflow: hidden;
}

.pay-dash-card-stage {
  position: relative;
  width: 100%;
  min-width: 0;
  aspect-ratio: 1.9;
  perspective: 900px;
  isolation: isolate;
}

.pay-dash-card-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.3rem;
}

.pay-dash-card-tab {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
