  padding: 0.22rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.04em;
  color: var(--muted-foreground);
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}

.pay-dash-card-tab[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, white);
  color: var(--primary);
}

.pay-card-real {
  position: relative;
  overflow: hidden;
  color: white;
  box-shadow:
    0 16px 32px -20px color-mix(in oklab, black 45%, transparent),
    0 0 0 1px color-mix(in oklab, white 14%, transparent) inset;
  transition:
    transform 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.45s ease,
    filter 0.45s ease;
}

.pay-card-real--stage {
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  width: min(88%, 13rem);
  margin-inline: auto;
  aspect-ratio: 1.586;
  padding: 0.72rem 0.78rem;
  border-radius: 0.8rem;
  transform-origin: center center;
  transform: translateY(-50%) rotateY(-10deg) rotateX(6deg) scale(0.9);
  opacity: 0;
}

.pay-card-real--stage[data-stack="back"] {
  transform: translateY(-38%) rotateY(-16deg) rotateX(8deg) scale(0.84);
  opacity: 0.4;
  filter: saturate(0.82);
}

.pay-card-real--stage[data-stack="mid"] {
  transform: translateY(-44%) rotateY(-13deg) rotateX(7deg) scale(0.9);
  opacity: 0.66;
  filter: saturate(0.92);
}

.pay-card-real--stage[data-stack="front"],
.pay-card-real--stage[data-active="true"] {
  z-index: 3;
  opacity: 1;
  transform: translateY(-52%) rotateY(-6deg) rotateX(3deg) scale(1);
  filter: none;
}

.pay-card-real--thumb {
  flex-shrink: 0;
  width: 4.35rem;
  aspect-ratio: 1.586;
  padding: 0.38rem 0.42rem;
  border-radius: 0.45rem;
  transform: none;
  opacity: 1;
}

.pay-card-real--visa {
  background:
    radial-gradient(circle at 88% 12%, color-mix(in oklab, white 20%, transparent), transparent 42%),
    linear-gradient(135deg, #1a1f71 0%, #2d4aa3 52%, #1434a4 100%);
}

.pay-card-real--mastercard {
  background:
    radial-gradient(circle at 12% 88%, color-mix(in oklab, white 12%, transparent), transparent 38%),
    linear-gradient(135deg, #1c1c1c 0%, #3d3d3d 48%, #1a1a1a 100%);
}

.pay-card-real--amex {
  background:
    radial-gradient(circle at 80% 18%, color-mix(in oklab, white 16%, transparent), transparent 40%),
    linear-gradient(135deg, #006fcf 0%, #009cde 55%, #004a8f 100%);
}

.pay-card-real-shimmer {
  position: absolute;
  inset: -40% -20%;
  background: linear-gradient(
    105deg,
    transparent 38%,
    color-mix(in oklab, white 26%, transparent) 50%,
    transparent 62%
  );
  transform: translateX(-120%);
  pointer-events: none;
}

.pay-dash[data-live="true"] .pay-card-real[data-active="true"] .pay-card-real-shimmer {
  animation: pay-card-shimmer 4.5s ease-in-out infinite;
}

@keyframes pay-card-shimmer {
  0%,
  100% {
    transform: translateX(-120%);
  }

  50% {
    transform: translateX(120%);
  }
}

.pay-card-real-glow {
  position: absolute;
  inset: auto -15% -25% -15%;
  height: 50%;
  background: radial-gradient(circle, color-mix(in oklab, white 22%, transparent), transparent 68%);
  opacity: 0.22;
  pointer-events: none;
}

.pay-card-real-texture {
  position: absolute;
  inset: 0;
  opacity: 0.12;
  background-image: radial-gradient(color-mix(in oklab, white 35%, transparent) 0.6px, transparent 0.6px);
  background-size: 5px 5px;
  pointer-events: none;
}

.pay-card-real-chip {
  display: block;
  width: 1.65rem;
  height: 1.2rem;
  border-radius: 0.28rem;
  background: linear-gradient(
    135deg,
    color-mix(in oklab, #f5d76e 88%, white),
    color-mix(in oklab, #d4af37 72%, #8b6914)
  );
  box-shadow: inset 0 0 0 1px color-mix(in oklab, white 24%, transparent);
}

.pay-card-real--thumb .pay-card-real-chip {
  width: 0.95rem;
  height: 0.68rem;
  border-radius: 0.16rem;
}

.pay-card-real-contactless {
  position: absolute;
  top: 0.95rem;
  left: 2.65rem;
  width: 0.75rem;
  height: 0.75rem;
  color: color-mix(in oklab, white 72%, transparent);
  transform: rotate(90deg);
}

.pay-card-real--thumb .pay-card-real-contactless {
  top: 0.38rem;
  left: 1.45rem;
  width: 0.45rem;
  height: 0.45rem;
}

.pay-card-real-network {
