}

.pay-dash-ghost-btn {
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: white;
  padding: 0.28rem 0.55rem;
  color: var(--foreground);
}

.pay-dash-icon-btn {
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: white;
  padding: 0.28rem;
  color: var(--muted-foreground);
}

.pay-dash-link-btn {
  margin-top: 0.15rem;
  padding: 0;
  color: var(--primary);
}

.pay-dash-chart-wrap {
  position: relative;
  margin-top: 0.15rem;
}

.pay-dash-chart {
  width: 100%;
  height: auto;
}

.pay-dash-chart-grid {
  stroke: color-mix(in oklab, var(--foreground) 8%, transparent);
  stroke-width: 1;
}

.pay-dash-chart-area {
  fill: color-mix(in oklab, var(--primary) 14%, transparent);
}

.pay-dash-chart-line {
  stroke: var(--primary);
}

.pay-dash-chart-dot {
  fill: white;
  stroke: var(--primary);
  stroke-width: 2;
}

.pay-dash[data-live="true"] .pay-dash-chart-dot {
  animation: pay-dash-pulse 2.4s ease-in-out infinite;
}

@keyframes pay-dash-pulse {
  0%,
  100% {
    r: 5;
  }

  50% {
    r: 6.5;
  }
}

.pay-dash-chart-tooltip {
  position: absolute;
  top: 18%;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: white;
  padding: 0.35rem 0.5rem;
  box-shadow: 0 10px 24px -18px color-mix(in oklab, var(--foreground) 20%, transparent);
  transform: translateX(-50%);
  pointer-events: none;
  white-space: nowrap;
}

.pay-dash-chart-tooltip strong {
  font-size: 0.68rem;
  font-weight: 650;
  color: var(--foreground);
}

.pay-dash-chart-tooltip span {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--primary);
}

.pay-dash-chart-axis {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.25rem;
  margin-top: 0.35rem;
  padding-inline: 1.4rem;
}

.pay-dash-chart-axis span {
  font-family: var(--font-mono);
  font-size: 9px;
  text-align: center;
  color: var(--muted-foreground);
}

.pay-dash-tx-list {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.pay-dash-tx-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem;
  border-radius: 0.55rem;
  padding: 0.42rem 0.35rem;
  transition: background 0.25s ease;
}

.pay-dash-tx-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 6%, white);
}

.pay-dash-tx-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 999px;
}

.pay-dash-tx-icon[data-dir="in"] {
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.pay-dash-tx-icon[data-dir="out"] {
  background: color-mix(in oklab, #ea580c 12%, transparent);
  color: #c2410c;
}

.pay-dash-tx-copy strong {
  display: block;
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--foreground);
}

.pay-dash-tx-copy span {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.pay-dash-tx-meta {
  text-align: right;
}

.pay-dash-tx-meta strong {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.74rem;
  font-weight: 700;
}

.pay-dash-tx-meta strong[data-dir="in"] {
  color: var(--primary);
}

.pay-dash-tx-meta strong[data-dir="out"] {
  color: #c2410c;
}

.pay-dash-tx-status {
  display: inline-flex;
  margin-top: 0.12rem;
  border-radius: 999px;
  padding: 0.08rem 0.38rem;
  font-size: 0.65rem;
  font-weight: 600;
}

.pay-dash-tx-status[data-status="settled"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--primary);
}

.pay-dash-tx-status[data-status="processing"] {
  background: color-mix(in oklab, #ea580c 10%, transparent);
  color: #c2410c;
}

.pay-dash-tx-status[data-status="refunded"] {
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  color: var(--muted-foreground);
}

.pay-dash-scroll-x {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--primary) 32%, transparent) transparent;
}

.pay-dash-scroll-x::-webkit-scrollbar {
  height: 4px;
}

.pay-dash-scroll-x::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 32%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .pay-dash[data-live="true"] .pay-dash-chart-dot,
  .pay-dash[data-live="true"] .pay-dash-live-dot,
  .pay-dash[data-live="true"] .pay-card-real[data-active="true"] .pay-card-real-shimmer,
  .pay-dash-spark[data-live="true"] .pay-dash-spark-line {
    animation: none !important;
  }

  .pay-card-real--stage {
    transition: none;
  }
}

/* WorkflowSteps — glow cards */

.ws-flow-panel {
  position: relative;
}

.ws-flow-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15.5rem), 1fr));
  gap: clamp(1rem, 2.5vw, 1.35rem);
}

.ws-flow-card-outer {
  position: relative;
  min-height: 14.5rem;
  border-radius: 0.85rem;
  padding: 1px;
  background: radial-gradient(
    circle 12rem at 0% 0%,
    color-mix(in oklab, var(--primary) 24%, white),
    color-mix(in oklab, var(--border) 72%, white)
  );
}

@media (min-width: 768px) {
  .ws-flow-card-outer.is-featured {
    grid-column: span 2;
  }
}

.ws-flow-card-dot {
  position: absolute;
  z-index: 2;
  top: 10%;
  right: 10%;
  width: 5px;
  aspect-ratio: 1;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 55%, transparent);
  animation: ws-flow-dot 6s linear infinite;
  animation-delay: var(--ws-delay, 0s);
}

@keyframes ws-flow-dot {
  0%,
  100% {
    top: 10%;
    right: 10%;
  }

  25% {
    top: 10%;
    right: calc(100% - 1.25rem);
  }

  50% {
    top: calc(100% - 1.15rem);
    right: calc(100% - 1.25rem);
  }

  75% {
    top: calc(100% - 1.15rem);
    right: 10%;
  }
}

.ws-flow-card {
  position: relative;
  z-index: 1;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 14rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 1.85rem 1.35rem 1.55rem;
  border: 1px solid color-mix(in oklab, var(--border) 88%, transparent);
  border-radius: calc(0.85rem - 1px);
  background: radial-gradient(
    circle 18rem at 0% 0%,
    color-mix(in oklab, var(--primary) 9%, white),
    color-mix(in oklab, var(--card) 98%, white)
  );
  text-align: center;
}

.ws-flow-card-ray {
  position: absolute;
  top: 0;
  left: 0;
  width: 12rem;
  height: 2.75rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 32%, white);
  opacity: 0.38;
  filter: blur(10px);
  box-shadow: 0 0 40px color-mix(in oklab, var(--primary) 22%, white);
  transform: rotate(40deg);
  transform-origin: 10% 50%;
  pointer-events: none;
}

.ws-flow-card-step {
  margin-bottom: 0.45rem;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--primary) 78%, var(--foreground));
}

.ws-flow-card-mark {
  display: grid;
  place-items: center;
  width: 2.35rem;
  height: 2.35rem;
  margin-bottom: 0.55rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--border));
  background: radial-gradient(
    circle at 28% 22%,
    color-mix(in oklab, var(--primary) 42%, white),
    color-mix(in oklab, var(--primary) 16%, transparent) 58%,
    color-mix(in oklab, var(--card) 96%, white)
  );
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: white;
  box-shadow: 0 10px 24px -16px color-mix(in oklab, var(--primary) 42%, transparent);
}

.ws-flow-card-title {
  margin: 0;
  max-width: 16rem;
  font-size: clamp(1.02rem, 2.1vw, 1.32rem);
  font-weight: 800;
  line-height: 1.22;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.ws-flow-card-outer.is-featured .ws-flow-card-title {
  font-size: clamp(1.15rem, 2.4vw, 1.55rem);
  background: linear-gradient(
    135deg,
    var(--foreground) 8%,
    color-mix(in oklab, var(--primary) 72%, var(--foreground)) 48%,
    var(--foreground) 92%
  );
  background-clip: text;
  color: transparent;
}

.ws-flow-card-body {
  margin: 0.5rem 0 0;
  max-width: 15.5rem;
  font-size: clamp(0.78rem, 1.5vw, 0.86rem);
  line-height: 1.48;
  color: var(--muted-foreground);
}

.ws-flow-card-line {
  position: absolute;
  pointer-events: none;
}

.ws-flow-card-line-top {
  top: 10%;
  right: 10%;
  left: 10%;
  height: 1px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 34%, var(--border)) 30%,
    color-mix(in oklab, var(--border) 62%, transparent) 70%
  );
}

.ws-flow-card-line-bottom {
  right: 10%;
  bottom: 10%;
  left: 10%;
  height: 1px;
  background: color-mix(in oklab, var(--border) 78%, transparent);
}

.ws-flow-card-line-left {
  top: 10%;
  bottom: 10%;
  left: 10%;
  width: 1px;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--primary) 30%, var(--border)) 30%,
    color-mix(in oklab, var(--border) 58%, transparent) 70%
  );
}

.ws-flow-card-line-right {
  top: 10%;
  right: 10%;
  bottom: 10%;
  width: 1px;
  background: color-mix(in oklab, var(--border) 72%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .ws-flow-card-dot {
    animation: none !important;
    top: 10%;
    right: 10%;
  }
}

/* ── Section connector ─────────────────────────────────────────── */

.sx-connector {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding-block: clamp(1.75rem, 4.5vw, 2.75rem);
  background: var(--surface);
  color: var(--foreground);
}

.sx-connector[data-tone="dark"] {
  background: var(--dark);
  color: color-mix(in oklab, white 88%, transparent);
}

.sx-connector::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image:
    linear-gradient(currentColor 1px, transparent 1px),
    linear-gradient(90deg, currentColor 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: 0.045;
  mask-image: radial-gradient(ellipse 70% 100% at 50% 50%, black, transparent 78%);
}

.sx-connector-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.9rem;
  align-items: stretch;
}

@media (min-width: 900px) {
  .sx-connector-grid {
    grid-template-columns: minmax(0, 1fr) minmax(11rem, 0.9fr) minmax(0, 1fr);
    gap: clamp(1rem, 2.5vw, 1.75rem);
    align-items: center;
  }
}

.sx-connector-node {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, currentColor 14%, transparent);
  background: color-mix(in oklab, currentColor 4%, transparent);
  padding: 0.8rem 0.9rem;
  backdrop-filter: blur(6px);
}

.sx-connector[data-tone="light"] .sx-connector-node {
  background: color-mix(in oklab, white 92%, var(--surface));
  box-shadow: 0 12px 28px -24px color-mix(in oklab, var(--dark) 60%, transparent);
}

.sx-connector-node-target {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
}

.sx-connector-node-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.sx-connector[data-tone="dark"] .sx-connector-node-icon {
  color: color-mix(in oklab, var(--primary) 55%, white);
}

.sx-connector-node-copy {
  min-width: 0;
}

.sx-connector-node-kicker {
  display: block;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: none;
  opacity: 0.55;
}

.sx-connector-node-copy strong {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.sx-connector-node-copy p {
  margin: 0.2rem 0 0;
  font-size: 0.75rem;
  line-height: 1.5;
  opacity: 0.68;
}

.sx-connector-rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
}

.sx-connector-step {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, currentColor 18%, transparent);
  padding: 0.1rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  opacity: 0.7;
}

.sx-connector-track {
  position: relative;
  width: 100%;
  height: 1.6rem;
}

.sx-connector-track-line {
  position: absolute;
  inset-inline: 0;
  top: 50%;
  height: 1px;
  transform: translateY(-50%);
  background: repeating-linear-gradient(
    90deg,
    currentColor 0 5px,
    transparent 5px 11px
  );
  opacity: 0.35;
}

.sx-connector-packet {
  position: absolute;
  top: 50%;
  left: 0;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 20%, transparent);
  transform: translate(-50%, -50%);
  animation: sx-packet-travel 2.7s linear infinite;
}

@keyframes sx-packet-travel {
  0% {
    left: 0;
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  88% {
    opacity: 1;
  }
  100% {
    left: calc(100% - 1.35rem);
    opacity: 0;
  }
}

.sx-connector-arrow {
  position: absolute;
  right: 0;
  top: 50%;
  display: grid;
  place-items: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 34%, transparent);
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  color: var(--primary);
  transform: translateY(-50%);
}

.sx-connector[data-tone="light"] .sx-connector-arrow {
  background: color-mix(in oklab, var(--primary) 10%, white);
}

.sx-connector-payload {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sx-connector-payload li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, currentColor 14%, transparent);
  background: color-mix(in oklab, currentColor 6%, transparent);
  padding: 0.14rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.06em;
  opacity: 0.75;
  white-space: nowrap;
}

.sync-diagram {
  position: relative;
  margin-inline: auto;
  max-width: 56rem;
  padding-block: clamp(2rem, 5vw, 3.5rem);
}

.sync-diagram-lines {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.sync-diagram-lines path {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 55%, transparent);
  stroke-width: 1.5;
  stroke-dasharray: 6 8;
  vector-effect: non-scaling-stroke;
}

.sync-diagram-hub {
  position: relative;
}

.sync-diagram-hub-glow {
  position: absolute;
  inset: -1.35rem;
  border-radius: 999px;
  background: radial-gradient(
    circle,
    color-mix(in oklab, var(--primary) 42%, transparent) 0%,
    transparent 72%
  );
  filter: blur(8px);
}

.sync-diagram-hub-core {
  position: relative;
  display: grid;
  place-items: center;
  width: 3.25rem;
  height: 3.25rem;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--background));
  background: color-mix(in oklab, var(--background) 92%, white);
  color: var(--primary);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--primary) 12%, transparent),
    0 12px 28px color-mix(in oklab, var(--primary) 18%, transparent);
}

.sync-diagram-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  gap: clamp(1rem, 2.5vw, 1.75rem) clamp(1.25rem, 4vw, 3rem);
  align-items: stretch;
}

.sync-diagram-card-wrap {
  min-width: 0;
}

.sync-diagram-card-tl {
  grid-column: 1;
  grid-row: 1;
}

.sync-diagram-card-tr {
  grid-column: 3;
  grid-row: 1;
}

.sync-diagram-hub-cell {
  grid-column: 2;
  grid-row: 2;
  display: grid;
  place-items: center;
  align-self: center;
  min-width: 4.5rem;
}

.sync-diagram-card-bl {
  grid-column: 1;
  grid-row: 3;
}

.sync-diagram-card-br {
  grid-column: 3;
  grid-row: 3;
}

.sync-diagram-card {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  height: 100%;
  min-height: 7.5rem;
  border-radius: 1rem;
  border: 1px solid color-mix(in oklab, var(--primary) 34%, transparent);
  background:
    radial-gradient(
      ellipse 120% 80% at 0% 0%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 55%
    ),
    color-mix(in oklab, var(--background) 8%, var(--dark));
  padding: 1.1rem 1.15rem;
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--background) 8%, transparent);
}

.sync-diagram-card-icon {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--primary) 24%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.sync-diagram-card-copy {
  min-width: 0;
}

.sync-diagram-card-title {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--background);
}

.sync-diagram-card-body {
  margin: 0.45rem 0 0;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.sync-diagram-footer {
  margin-top: 2rem;
  width: fit-content;
  max-width: 100%;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  padding: 0.75rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

@media (max-width: 767px) {
  .sync-diagram {
    padding-block: 0;
  }

  .sync-diagram-lines {
    display: none;
  }

  .sync-diagram-grid {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    gap: 0.85rem;
  }

  .sync-diagram-card-tl,
  .sync-diagram-card-tr,
  .sync-diagram-card-bl,
  .sync-diagram-card-br,
  .sync-diagram-hub-cell {
    grid-column: 1;
    grid-row: auto;
  }

  .sync-diagram-hub-cell {
    order: -1;
    margin-bottom: 0.25rem;
  }

  .sync-diagram-card,
  .sync-diagram-card-wrap .sync-diagram-card {
    min-height: 0;
  }
}

.lc-ai-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.65rem;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.lc-ai-pipeline {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.lc-ai-pipeline-step {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  border-radius: 0.55rem;
  padding: 0.42rem 0.5rem;
  transition: background 0.25s ease;
}

.lc-ai-pipeline-step[data-current="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.lc-ai-pipeline-step[data-done="true"] .lc-ai-pipeline-label {
  color: var(--primary);
}

.lc-ai-pipeline-icon {
  display: inline-flex;
  flex-shrink: 0;
  margin-top: 0.1rem;
  color: var(--muted-foreground);
}

.lc-ai-pipeline-step[data-done="true"] .lc-ai-pipeline-icon,
.lc-ai-pipeline-step[data-current="true"] .lc-ai-pipeline-icon {
  color: var(--primary);
}

.lc-ai-pipeline-copy {
  min-width: 0;
}

.lc-ai-pipeline-label {
  display: block;
  font-size: 0.78rem;
  font-weight: 650;
  color: var(--foreground);
}

.lc-ai-pipeline-detail {
  display: block;
  margin-top: 0.06rem;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.lc-ai-rec {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-height: 0;
}

.lc-ai-rec-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.lc-ai-rec-price {
  display: block;
  margin-top: 0.15rem;
  font-family: var(--font-mono);
  font-size: clamp(1.35rem, 2.4vw, 1.65rem);
  font-weight: 700;
  color: var(--foreground);
}

.lc-ai-confidence {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.1rem;
  min-width: 4.5rem;
}

.lc-ai-confidence-ring {
  display: block;
  width: 3.1rem;
  height: 3.1rem;
  border-radius: 999px;
  background: conic-gradient(
    var(--primary) var(--lc-conf),
    color-mix(in oklab, var(--foreground) 8%, transparent) 0
  );
  mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4px));
}

.lc-ai-confidence-value {
  position: absolute;
  top: 1.05rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--primary);
}

.lc-ai-override {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 16%, var(--border));
  background: color-mix(in oklab, var(--background) 82%, white);
  padding: 0.65rem 0.7rem;
}

.lc-ai-override-tag {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.lc-ai-override-prices {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

.lc-ai-override-col {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.45rem 0.55rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease;
}

.lc-ai-override-col strong {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
}

.lc-ai-override-col[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.lc-ai-override-col[data-active="true"] strong {
  color: var(--primary);
}

.lc-ai-actions {
  display: flex;
  gap: 0.45rem;
}

.lc-ai-action {
  flex: 1 1 0;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.42rem 0.5rem;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}

.lc-ai-action[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--primary);
}

.lc-ai-action-override[data-active="true"] {
  border-color: color-mix(in oklab, var(--foreground) 18%, var(--border));
  background: color-mix(in oklab, var(--foreground) 6%, transparent);
  color: var(--foreground);
}

.lc-ai[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 18s linear infinite;
}

/* ── Market intelligence terminal ──────────────────────────────── */

.mi-console {
  width: 100%;
  container-type: inline-size;
}

.mi-console .lc-screen {
  height: clamp(30rem, 50vh, 36rem);
  min-height: clamp(30rem, 50vh, 36rem);
  max-height: clamp(30rem, 50vh, 36rem);
}

.mi-console .lc-body {
  gap: 0.55rem;
}

.mi-label {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.mi-mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.mi-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.6rem;
  flex-shrink: 0;
}

.mi-head-title {
  margin: 0;
  font-size: 0.86rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.mi-head-meta {
  margin: 0.12rem 0 0;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}

.mi-head-price {
  text-align: right;
  margin-left: auto;
}

.mi-head-price-row {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 0.4rem;
  margin-top: 0.1rem;
}

.mi-head-price-row strong {
  font-family: var(--font-mono);
  font-size: clamp(1.05rem, 2vw, 1.35rem);
  font-weight: 700;
  color: var(--foreground);
}

.mi-delta {
  display: inline-flex;
  align-items: center;
  gap: 0.1rem;
  border-radius: 999px;
  padding: 0.1rem 0.35rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
}

.mi-delta[data-direction="up"],
.mi-ladder-delta[data-direction="up"] {
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.mi-delta[data-direction="down"],
.mi-ladder-delta[data-direction="down"] {
  color: oklch(0.57 0.19 25);
  background: oklch(0.57 0.19 25 / 0.1);
}

.mi-ladder-delta[data-direction="flat"] {
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--foreground) 6%, transparent);
}

.mi-band {
  flex-shrink: 0;
}

.mi-band-track {
  position: relative;
  height: 0.4rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.mi-band-fill {
  position: absolute;
  inset-block: 0;
  left: 0;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 30%, transparent),
    var(--primary)
  );
}

.mi-band-marker {
  position: absolute;
  top: 50%;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 999px;
  border: 2px solid var(--primary);
  background: white;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 14%, transparent);
}

.mi-band-legend {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.32rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.mi-band-legend-mid {
  font-weight: 700;
  color: var(--primary);
}

.mi-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.6rem;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

@container (min-width: 32rem) {
  .mi-grid {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr);
  }
}

.mi-panel {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.6rem 0.65rem;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.mi-panel-head {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.mi-panel-note {
  margin-left: auto;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: color-mix(in oklab, var(--muted-foreground) 80%, transparent);
}

.mi-panel-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.mi-ladder-cols,
.mi-ladder-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 3rem 2.4rem 3.4rem;
  align-items: center;
  gap: 0.35rem;
}

.mi-ladder-cols {
  flex-shrink: 0;
  padding-inline: 0.35rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: color-mix(in oklab, var(--muted-foreground) 75%, transparent);
}

.mi-ladder-cols > span:not(:first-child),
.mi-ladder-ask,
.mi-ladder-qty {
  text-align: right;
}

.mi-ladder {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 0.16rem;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;
}

.mi-ladder-row {
  position: relative;
  isolation: isolate;
  flex-shrink: 0;
  border-radius: 0.4rem;
  padding: 0.3rem 0.35rem;
  font-size: 0.73rem;
  color: var(--foreground);
  transition:
    background 0.25s ease,
    box-shadow 0.25s ease;
}

.mi-ladder-depth {
  position: absolute;
  inset-block: 0;
  left: 0;
  z-index: -1;
  border-radius: 0.4rem;
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}

.mi-ladder-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 22%, transparent);
}

.mi-ladder-name {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mi-ladder-row[data-own="true"] .mi-ladder-name {
  font-weight: 700;
  color: var(--primary);
}

.mi-ladder-own-dot {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--primary);
  flex-shrink: 0;
}

.mi-ladder-ask {
  font-weight: 700;
}

.mi-ladder-qty {
  color: var(--muted-foreground);
  font-size: 0.7rem;
}

.mi-ladder-delta {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.05rem;
  border-radius: 999px;
  padding: 0.08rem 0.28rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
}

@container (max-width: 21rem) {
  .mi-ladder-cols,
  .mi-ladder-row {
    grid-template-columns: minmax(0, 1fr) 2.8rem 3.2rem;
  }

  .mi-ladder-cols > span:nth-child(3),
  .mi-ladder-qty {
    display: none;
  }
}

.mi-chart {
  position: relative;
}

.mi-chart-svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

.mi-chart-gridline {
  stroke: color-mix(in oklab, var(--foreground) 9%, transparent);
  stroke-width: 1;
  stroke-dasharray: 3 5;
}

.mi-chart-line {
  fill: none;
  stroke: var(--primary);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.mi-chart-dot {
  fill: var(--primary);
}

.mi-chart-dot-halo {
  fill: color-mix(in oklab, var(--primary) 22%, transparent);
  animation: mi-halo 2.4s ease-out infinite;
}

@keyframes mi-halo {
  0% {
    opacity: 0.5;
    transform-box: fill-box;
    transform-origin: center;
    transform: scale(0.55);
  }
  70%,
  100% {
    opacity: 0;
    transform-box: fill-box;
    transform-origin: center;
    transform: scale(1.5);
  }
}

.mi-chart-axis {
  display: flex;
  justify-content: space-between;
  gap: 0.4rem;
  margin-top: 0.3rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.mi-chart-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  margin-top: auto;
}

.mi-chart-stats > div {
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, white 70%, transparent);
  padding: 0.32rem 0.4rem;
}

.mi-chart-stats strong {
  display: block;
  margin-top: 0.1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--foreground);
}

.mi-range {
  display: flex;
  align-items: center;
  gap: 0.12rem;
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  background: color-mix(in oklab, white 70%, transparent);
  padding: 0.1rem;
}

.mi-range-btn {
  border-radius: 999px;
  padding: 0.1rem 0.36rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
  cursor: pointer;
  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.mi-range-btn:hover {
  color: var(--foreground);
}

.mi-range-btn[data-active="true"] {
  background: var(--primary);
  color: white;
}

.mi-range-btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.mi-panel-signals {
  flex: 0 0 auto;
  position: relative;
  z-index: 1;
  overflow: hidden;
  background: color-mix(in oklab, var(--background) 92%, white);
}

.mi-feed-viewport {
  position: relative;
  flex-shrink: 0;
  height: 4.5rem;
  overflow: hidden;
  mask-image: linear-gradient(180deg, transparent, black 14%, black 86%, transparent);
}

.mi-console[data-live="true"] .mi-feed-list {
  animation: lc-feed-scroll 20s linear infinite;
}

.mi-feed-list {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mi-feed-row {
  display: grid;
  grid-template-columns: 0.4rem 4.2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.5rem;
  font-size: 0.72rem;
}

.mi-feed-level {
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 22%, transparent);
}

.mi-feed-row[data-level="high"] .mi-feed-level {
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 15%, transparent);
}

.mi-feed-row[data-level="warn"] .mi-feed-level {
  background: oklch(0.74 0.16 65);
  box-shadow: 0 0 0 3px oklch(0.74 0.16 65 / 0.15);
}

.mi-feed-time {
  font-size: 10.5px;
  color: var(--muted-foreground);
}

.mi-feed-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--foreground) 85%, transparent);
}

/* ── AI pricing cockpit ────────────────────────────────────────── */

.ap-console {
  width: 100%;
  container-type: inline-size;
}

.ap-label {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ap-mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.ap-shell {
  display: flex;
  flex-direction: column;
  gap: clamp(0.6rem, 1.4vw, 0.85rem);
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  background:
    radial-gradient(120% 100% at 100% 0%, color-mix(in oklab, var(--primary) 7%, transparent), transparent 60%),
    linear-gradient(180deg, white, color-mix(in oklab, var(--surface) 70%, white));
  padding: clamp(0.8rem, 1.8vw, 1.15rem);
  box-shadow:
    0 30px 70px -44px color-mix(in oklab, var(--dark) 60%, transparent),
    0 0 0 1px color-mix(in oklab, white 60%, transparent) inset;
}

.ap-shell-head {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  border-bottom: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding-bottom: 0.7rem;
}

.ap-model {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 26%, transparent);
  background: color-mix(in oklab, var(--primary) 11%, transparent);
  color: var(--primary);
}

.ap-shell-copy {
  min-width: 0;
}

.ap-shell-copy strong {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.ap-shell-copy span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}

.ap-version {
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.1rem 0.4rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-foreground);
}

.ap-status {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  padding: 0.12rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--muted-foreground);
}

.ap-status i {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: currentColor;
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.ap-status[data-decision="approved"],
.ap-status[data-decision="override"] {
  border-color: color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  color: var(--primary);
}

.ap-stepper {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@container (min-width: 30rem) {
  .ap-stepper {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 0.35rem;
  }
}

.ap-step {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
  padding-top: 1.15rem;
  min-width: 0;
}

.ap-step-rail {
  position: absolute;
  top: 0.4rem;
  left: 0;
  right: 0;
  height: 2px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.ap-step[data-done="true"] .ap-step-rail,
.ap-step[data-current="true"] .ap-step-rail {
  background: color-mix(in oklab, var(--primary) 45%, transparent);
}

.ap-step-node {
  position: absolute;
  top: 0;
  left: 0;
  display: grid;
  place-items: center;
  width: 0.9rem;
  height: 0.9rem;
  border-radius: 999px;
  border: 2px solid color-mix(in oklab, var(--foreground) 13%, transparent);
  background: white;
  color: white;
}

.ap-step-node i {
  display: block;
  width: 0.26rem;
  height: 0.26rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 25%, transparent);
}

.ap-step[data-done="true"] .ap-step-node {
  border-color: var(--primary);
  background: var(--primary);
}

.ap-step[data-current="true"] .ap-step-node {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--primary) 14%, transparent);
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.ap-step[data-current="true"] .ap-step-node i {
  background: var(--primary);
}

.ap-step-label {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--foreground);
}

.ap-step-detail {
  font-size: 0.68rem;
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ap-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.7rem;
}

@container (min-width: 42rem) {
  .ap-hero {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  }
}

.ap-rec,
.ap-guards {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  padding: 0.75rem 0.8rem;
  min-width: 0;
}

.ap-rec {
  border-color: color-mix(in oklab, var(--primary) 20%, transparent);
  background: linear-gradient(160deg, color-mix(in oklab, var(--primary) 7%, white), white);
}

.ap-guards {
  background: white;
}

.ap-panel-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ap-panel-note {
  margin-left: auto;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  padding: 0.08rem 0.35rem;
  font-size: 9px;
  color: var(--primary);
}

.ap-panel-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.ap-rec-body {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
}

.ap-rec-price {
  min-width: 0;
}

.ap-rec-price strong {
  display: block;
  font-family: var(--font-mono);
  font-size: clamp(1.6rem, 3.4vw, 2.15rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.ap-rec-price p {
  margin: 0.3rem 0 0;
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.ap-rec-delta {
  font-weight: 700;
  color: var(--primary);
}

.ap-rec-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin: 0.45rem 0 0;
  padding: 0;
  list-style: none;
}

.ap-rec-tags li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, white 70%, transparent);
  padding: 0.1rem 0.38rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.ap-gauge {
  position: relative;
  flex-shrink: 0;
  width: 4.6rem;
  height: 4.6rem;
}

.ap-gauge svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.ap-gauge-track {
  fill: none;
  stroke: color-mix(in oklab, var(--foreground) 9%, transparent);
  stroke-width: 6;
}

.ap-gauge-fill {
  fill: none;
  stroke: var(--primary);
  stroke-width: 6;
  stroke-linecap: round;
  transition: stroke-dasharray 0.6s ease;
}

.ap-gauge-value {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  text-align: center;
}

.ap-gauge-value strong {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--foreground);
}

.ap-gauge-value span {
  display: block;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ap-drivers {
  display: grid;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ap-driver-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.7rem;
  color: var(--foreground);
}

.ap-driver-note {
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--muted-foreground);
  white-space: nowrap;
}

.ap-driver-track {
  height: 0.25rem;
  margin-top: 0.18rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

.ap-driver-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 45%, white),
    var(--primary)
  );
}

.ap-scale {
  padding-top: 1.15rem;
}

.ap-scale-track {
  position: relative;
  height: 0.45rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.ap-scale-safe {
  position: absolute;
  inset-block: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 20%, transparent);
}

.ap-scale-marker {
  position: absolute;
  top: 50%;
  width: 0.2rem;
  height: 1.05rem;
  border-radius: 999px;
  transform: translate(-50%, -50%);
  transition: left 0.35s ease;
}

.ap-scale-marker b {
  position: absolute;
  bottom: calc(100% + 0.25rem);
  left: 50%;
  transform: translateX(-50%);
  border-radius: 0.25rem;
  padding: 0.05rem 0.25rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  white-space: nowrap;
}

.ap-scale-marker-ai {
  background: var(--primary);
}

.ap-scale-marker-ai b {
  background: color-mix(in oklab, var(--primary) 12%, white);
  color: var(--primary);
}

.ap-scale-marker-you {
  background: var(--foreground);
}

.ap-scale-marker-you b {
  background: color-mix(in oklab, var(--foreground) 10%, white);
  color: var(--foreground);
}

.ap-scale-legend {
  display: flex;
  justify-content: space-between;
  margin-top: 0.3rem;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.ap-guard-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  margin: 0;
}

.ap-guard-stats > div {
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 65%, white);
  padding: 0.4rem 0.45rem;
  min-width: 0;
}

.ap-guard-stats dt {
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ap-guard-stats dd {
  margin: 0.15rem 0 0;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--foreground);
}

.ap-decision {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-top: auto;
  border-top: 1px dashed color-mix(in oklab, var(--foreground) 12%, transparent);
  padding-top: 0.6rem;
}

.ap-decision-tag {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.ap-decision-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
}

@container (max-width: 24rem) {
  .ap-decision-actions {
    grid-template-columns: minmax(0, 1fr);
  }

  .ap-guard-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.ap-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  background: white;
  padding: 0.45rem 0.5rem;
  font-size: 0.72rem;
  font-weight: 650;
  color: var(--foreground);
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.ap-btn:hover {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
  transform: translateY(-1px);
}

.ap-btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.ap-btn-approve[data-active="true"] {
  border-color: var(--primary);
  background: var(--primary);
  color: white;
  box-shadow: 0 12px 26px -18px color-mix(in oklab, var(--primary) 90%, transparent);
}

.ap-btn-override[data-active="true"] {
  border-color: var(--foreground);
  background: var(--foreground);
  color: white;
}

.ap-override {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  border-radius: 0.55rem;
  border: 1px solid transparent;
  padding: 0 0.55rem;
  transition:
    max-height 0.3s ease,
    opacity 0.25s ease,
    padding 0.3s ease;
}

.ap-override[data-open="true"] {
  max-height: 3.5rem;
  opacity: 1;
  border-color: color-mix(in oklab, var(--foreground) 11%, transparent);
  background: color-mix(in oklab, var(--surface) 70%, white);
  padding: 0.4rem 0.55rem;
}

.ap-stepper-input {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  border-radius: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 11%, transparent);
  background: white;
  padding: 0.14rem;
}

.ap-stepper-input button {
  display: grid;
  place-items: center;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 0.3rem;
  color: var(--muted-foreground);
  cursor: pointer;
  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.ap-stepper-input button:hover {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--primary);
}

.ap-stepper-input button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.ap-stepper-input strong {
  min-width: 3rem;
  text-align: center;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--foreground);
}

.ap-decision-status {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.ap-decision-status[data-decision="approved"] {
  font-weight: 600;
  color: var(--primary);
}

.ap-decision-status[data-decision="override"] {
  font-weight: 600;
  color: var(--foreground);
}

.ap-log {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 55%, white);
  padding: 0.55rem 0.65rem;
}

.ap-log-viewport {
  position: relative;
  height: 3.6rem;
  overflow: hidden;
  mask-image: linear-gradient(180deg, transparent, black 16%, black 84%, transparent);
}

.ap-console[data-live="true"] .ap-log-list {
  animation: lc-feed-scroll 20s linear infinite;
}

.ap-log-list {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ap-log-row {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.5rem;
  font-size: 0.72rem;
}

.ap-log-time {
  font-size: 10.5px;
  color: var(--muted-foreground);
}

.ap-log-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--foreground) 82%, transparent);
}

/* ── /brokers mobile cascade (after unscoped bh/lc/mi/ap/pay/sx) ──
   Desktop ≥1024px is unchanged. Placed here so phone rules win. */
@media (max-width: 639px) {
  .bh-hero {
    padding-bottom: clamp(3.25rem, 12vw, 4.35rem);
  }

  .bh-stage,
  .lc-section-stage,
  .pay-infra-dashboard,
  .inv-console-wrap {
    overflow-x: clip;
    max-width: 100%;
    min-width: 0;
  }

  .bh-wall-mask {
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
  }

  .bh-orb {
    display: none;
  }

  .lc-tilt-wrap,
  .pay-infra-stage.lc-tilt-wrap {
    width: 100%;
    max-width: 100%;
    margin-inline: 0;
    perspective: none;
  }

  .lc-tilt-card,
  .lc-section-stage:hover .lc-tilt-card,
  .lc-tilt-wrap:focus-within .lc-tilt-card,
  .pay-infra-dashboard:hover .lc-tilt-card,
  .pay-infra-dashboard:focus-within .lc-tilt-card {
    transform: none;
  }

  .lc-tilt-badge {
    top: 0.35rem;
    right: 0.35rem;
    transform: none;
  }

  .mi-console .lc-screen {
    height: clamp(22rem, 68vh, 28rem);
    min-height: clamp(22rem, 68vh, 28rem);
    max-height: clamp(22rem, 68vh, 28rem);
  }

  .mi-grid {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  }

  .ec-catalog .lc-screen {
    height: auto;
    min-height: 0;
    max-height: none;
    overflow: visible;
  }

  .ec-catalog .lc-body {
    grid-template-rows: auto auto auto auto;
    padding: 0.55rem;
    height: auto;
    overflow: visible;
  }

  .ap-shell {
    padding: 0.7rem;
  }

  .ap-shell-head {
    flex-wrap: wrap;
  }

  .ap-version {
    display: none;
  }

  .pay-dash-shell {
    padding: 0.6rem;
  }

  .pay-dash-kpis,
  .pay-dash-top-band .pay-dash-kpis {
    grid-template-columns: minmax(0, 1fr);
  }

  .pay-dash-live-bar,
  .pay-dash-live-msg {
    min-width: 0;
  }

  .pay-dash-live-msg {
    flex: 1 1 auto;
  }

  .pay-dash-table-wrap,
  .pay-dash-scroll-x {
    max-width: 100%;
    overflow-x: auto;
  }

  .pay-card-real--stage,
  .pay-card-real--stage[data-stack="back"],
  .pay-card-real--stage[data-stack="mid"] {
    transform: translateY(-50%) scale(0.9);
  }

  .pay-card-real--stage[data-stack="front"],
  .pay-card-real--stage[data-active="true"] {
    transform: translateY(-50%) scale(1);
  }

  .sx-connector {
    overflow-x: clip;
  }

  .sync-diagram-footer {
    width: 100%;
    letter-spacing: 0.06em;
    overflow-wrap: break-word;
    white-space: normal;
  }

  .ws-flow-panel,
  .ws-flow-card-outer,
  .ws-flow-grid {
    max-width: 100%;
    min-width: 0;
  }
}

@media (max-width: 639px) and (prefers-reduced-motion: reduce) {
  .bh-col-down {
    display: none;
  }

  .bh-wall-grid {
    grid-template-columns: 1fr;
    transform: none;
  }

  .lc-tilt-card,
  .lc-section-stage:hover .lc-tilt-card,
  .lc-tilt-wrap:focus-within .lc-tilt-card,
  .pay-infra-dashboard:hover .lc-tilt-card,
  .pay-infra-dashboard:focus-within .lc-tilt-card {
    transform: none;
  }
}

/* ── Travel quotation builder ──────────────────────────────────── */

.qb-console {
  width: 100%;
  container-type: inline-size;
}

.qb-label {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.qb-mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-style: normal;
}

.qb-shell {
  display: flex;
  flex-direction: column;
  gap: clamp(0.6rem, 1.4vw, 0.85rem);
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  background:
    radial-gradient(120% 100% at 0% 0%, color-mix(in oklab, var(--primary) 8%, transparent), transparent 55%),
    linear-gradient(180deg, white, color-mix(in oklab, var(--surface) 70%, white));
  padding: clamp(0.8rem, 1.8vw, 1.15rem);
  box-shadow:
    0 30px 70px -44px color-mix(in oklab, var(--dark) 60%, transparent),
    0 0 0 1px color-mix(in oklab, white 60%, transparent) inset;
}

.qb-shell-head {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  border-bottom: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding-bottom: 0.7rem;
}

.qb-mark {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 26%, transparent);
  background: color-mix(in oklab, var(--primary) 11%, transparent);
  color: var(--primary);
}

.qb-shell-copy {
  min-width: 0;
}

.qb-shell-copy strong {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--foreground);
}

.qb-shell-copy span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}

.qb-quote-id {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.qb-status {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  padding: 0.12rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--muted-foreground);
}

.qb-status i {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: currentColor;
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.qb-status[data-sharing="true"] {
  border-color: color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  color: var(--primary);
}

.qb-stepper {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@container (min-width: 30rem) {
  .qb-stepper {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

.qb-step {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
  padding-top: 1.15rem;
  min-width: 0;
}

.qb-step-rail {
  position: absolute;
  top: 0.4rem;
  left: 0;
  right: 0;
  height: 2px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.qb-step[data-done="true"] .qb-step-rail,
.qb-step[data-current="true"] .qb-step-rail {
  background: color-mix(in oklab, var(--primary) 45%, transparent);
}

.qb-step-node {
  position: absolute;
  top: 0;
  left: 0;
  display: grid;
  place-items: center;
  width: 0.9rem;
  height: 0.9rem;
  border-radius: 999px;
  border: 2px solid color-mix(in oklab, var(--foreground) 13%, transparent);
  background: white;
  color: white;
}

.qb-step-node i {
  display: block;
  width: 0.26rem;
  height: 0.26rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 25%, transparent);
}

.qb-step[data-done="true"] .qb-step-node {
  border-color: var(--primary);
  background: var(--primary);
}

.qb-step[data-current="true"] .qb-step-node {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--primary) 14%, transparent);
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.qb-step[data-current="true"] .qb-step-node i {
  background: var(--primary);
}

.qb-step-label {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--foreground);
}

.qb-step-detail {
  font-size: 0.68rem;
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.qb-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.7rem;
}

@container (min-width: 42rem) {
  .qb-hero {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  }
}

.qb-build,
.qb-preview {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  padding: 0.75rem 0.8rem;
  min-width: 0;
  background: white;
}

.qb-preview {
  border-color: color-mix(in oklab, var(--primary) 20%, transparent);
  background: linear-gradient(160deg, color-mix(in oklab, var(--primary) 6%, white), white);
}

.qb-panel-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.qb-panel-note {
  margin-left: auto;
  font-size: 9px;
  letter-spacing: 0.1em;
}

.qb-panel-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.qb-lines {
  margin: 0;
  padding: 0;
  list-style: none;
}

.qb-line {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.6rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.5rem 0.55rem;
}

.qb-line strong {
  display: block;
  font-size: 0.75rem;
  color: var(--foreground);
}

.qb-line span {
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.qb-margin-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.qb-slider-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.35rem;
}

.qb-slider-row input[type="range"] {
  flex: 1;
  accent-color: var(--primary);
  min-width: 0;
}

.qb-stepper-btn {
  display: grid;
  place-items: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  background: white;
  color: var(--muted-foreground);
  cursor: pointer;
}

.qb-stepper-btn:hover {
  color: var(--primary);
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
}

.qb-stepper-btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.qb-math {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  margin: 0.55rem 0 0;
}

.qb-math > div {
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 70%, white);
  padding: 0.35rem 0.4rem;
  min-width: 0;
}

.qb-math dt {
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.qb-math dd {
  margin: 0.12rem 0 0;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--foreground);
}

.qb-math-margin {
  color: var(--primary);
}

.qb-sheet {
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: white;
  padding: 0.7rem 0.75rem;
  box-shadow: 0 14px 28px -24px color-mix(in oklab, var(--dark) 55%, transparent);
}

.qb-sheet-brand {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--primary);
}

.qb-sheet h3 {
  margin: 0.45rem 0 0;
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--foreground);
}

.qb-sheet p {
  margin: 0.15rem 0 0;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}

.qb-sheet ul {
  margin: 0.55rem 0 0;
  padding: 0;
  list-style: none;
}

.qb-sheet li {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  border-top: 1px dashed color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.28rem 0;
  font-size: 0.72rem;
  color: var(--foreground);
}

.qb-sheet-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  margin-top: 0.25rem;
  padding-top: 0.4rem;
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.qb-sheet-total strong {
  font-size: 1.05rem;
  color: var(--foreground);
}

.qb-share {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  opacity: 0.45;
  transition: opacity 0.3s ease;
}

.qb-share[data-active="true"] {
  opacity: 1;
}

.qb-share-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  background: white;
  padding: 0.4rem 0.35rem;
  font-size: 0.7rem;
  font-weight: 650;
  color: var(--foreground);
}

.qb-share-btn[data-active="true"] {
  border-color: var(--primary);
  background: var(--primary);
  color: white;
}

.qb-foot {
  display: grid;
  gap: 0.6rem;
}

@container (min-width: 42rem) {
  .qb-foot {
    grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.28fr);
    align-items: start;
  }
}

.qb-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  margin: 0;
}

.qb-stats > div {
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 60%, white);
  padding: 0.4rem 0.45rem;
}

.qb-stats dt {
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.qb-stats dd {
  margin: 0.15rem 0 0;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--foreground);
}

.qb-recent {
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 55%, white);
  padding: 0.5rem 0.6rem;
  min-width: 0;
}

.qb-recent-list {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  margin: 0.4rem 0 0;
  padding: 0;
  list-style: none;
}

.qb-recent-row {
  display: grid;
  grid-template-columns: 3.6rem minmax(0, 1fr) minmax(0, 0.9fr) 4.2rem 3rem;
  align-items: center;
  gap: 0.35rem;
  border-radius: 0.4rem;
  padding: 0.28rem 0.35rem;
  font-size: 0.7rem;
}

.qb-recent-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}

.qb-recent-customer,
.qb-recent-event {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.qb-recent-event {
  color: var(--muted-foreground);
}

.qb-recent-status {
  justify-self: end;
  border-radius: 999px;
  padding: 0.08rem 0.32rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
}

.qb-recent-row[data-status="accepted"] .qb-recent-status {
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.qb-recent-row[data-status="viewed"] .qb-recent-status {
  color: oklch(0.55 0.12 250);
  background: oklch(0.55 0.12 250 / 0.1);
}

.qb-recent-row[data-status="sent"] .qb-recent-status {
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--foreground) 6%, transparent);
}

.qb-recent-row strong {
  justify-self: end;
}

@container (max-width: 28rem) {
  .qb-recent-row {
    grid-template-columns: 3.4rem minmax(0, 1fr) 4rem 2.8rem;
  }

  .qb-recent-event {
    display: none;
  }

  .qb-math,
  .qb-stats {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ── Travel inventory access ───────────────────────────────────── */

.ia-console {
  width: 100%;
  container-type: inline-size;
}

.ia-console .lc-body {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.ia-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
}

@container (min-width: 28rem) {
  .ia-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.ia-toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

@container (min-width: 32rem) {
  .ia-toolbar {
    flex-direction: row;
    align-items: center;
  }
}

.ia-search {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, white 82%, var(--surface));
  padding: 0.45rem 0.65rem;
  font-size: 0.76rem;
  color: var(--muted-foreground);
}

.ia-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.28rem;
}

.ia-pill {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: white;
  padding: 0.2rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ia-pill[data-active="true"] {
  border-color: var(--primary);
  background: var(--primary);
  color: white;
}

.ia-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
}

@container (min-width: 42rem) {
  .ia-workspace {
    grid-template-columns: minmax(7.5rem, 9.5rem) minmax(0, 1fr);
  }
}

.ia-sidebar {
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 74%, white);
  padding: 0.5rem;
}

.ia-sidebar-label {
  margin: 0 0 0.35rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ia-sidebar-list {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: thin;
}

@container (min-width: 42rem) {
  .ia-sidebar-list {
    flex-direction: column;
    flex-wrap: nowrap;
    overflow-x: visible;
    overflow-y: auto;
    max-height: 14.5rem;
  }
}

.ia-sidebar-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-shrink: 0;
  border-radius: 0.55rem;
  padding: 0.35rem 0.45rem;
  font-size: 0.72rem;
  color: var(--muted-foreground);
  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.ia-sidebar-item strong {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  color: var(--foreground);
}

.ia-sidebar-item[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--foreground);
}

.ia-sidebar-item[data-active="true"] strong {
  color: var(--primary);
}

.ia-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  min-width: 0;
}

@container (min-width: 36rem) {
  .ia-grid {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  }
}

.ia-console .lc-panel {
  min-height: 0;
}

.ia-queue {
  max-height: 11.5rem;
}

.ia-queue-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.5rem;
  align-items: center;
  border-radius: 0.6rem;
  border: 1px solid transparent;
  padding: 0.45rem 0.5rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    box-shadow 0.25s ease;
}

.ia-queue-row[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 26%, transparent);
  background: color-mix(in oklab, var(--primary) 6%, white);
}

.ia-queue-row[data-synced="true"] {
  animation: ia-sync-in 1.2s ease;
}

@keyframes ia-sync-in {
  0% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--primary) 35%, transparent);
  }
  100% {
    box-shadow: 0 0 0 8px transparent;
  }
}

.ia-row-meta {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.65rem;
  color: var(--muted-foreground);
}

.ia-synced {
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.06rem 0.32rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.ia-status {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

.ia-seats {
  font-size: 0.64rem;
  color: var(--muted-foreground);
}

.ia-detail {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 12rem;
  overflow-y: auto;
  scrollbar-width: thin;
}

.ia-active {
  margin-bottom: 0.1rem;
}

.ia-detail-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

.ia-detail-card {
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, white 88%, var(--surface));
  padding: 0.35rem 0.45rem;
}

.ia-detail-card-label {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ia-detail-card strong {
  display: block;
  margin-top: 0.12rem;
  font-size: 0.72rem;
  line-height: 1.35;
  color: var(--foreground);
}

.ia-margin {
  border-radius: 0.6rem;
  border: 1px dashed color-mix(in oklab, var(--primary) 28%, transparent);
  background: color-mix(in oklab, var(--primary) 5%, white);
  padding: 0.4rem 0.5rem;
}

.ia-margin-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.5rem;
  margin-top: 0.25rem;
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.ia-margin-row strong {
  color: var(--foreground);
}

.ia-margin-plus {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--primary);
}

.ia-sections {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.ia-section-list {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ia-section-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 0.45rem;
  align-items: center;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: white;
  padding: 0.3rem 0.45rem;
  font-size: 0.7rem;
}

.ia-section-row strong {
  font-family: var(--font-mono);
  font-size: 0.74rem;
  color: var(--foreground);
}

.ia-section-seats {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--muted-foreground);
}

.ia-intel {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.3rem;
}

.ia-intel-card {
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, var(--background) 80%, white);
  padding: 0.3rem 0.4rem;
}

.ia-intel-card span {
  display: block;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ia-intel-card strong {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.76rem;
  color: var(--foreground);
}

.ia-pipeline-foot {
  margin-top: 0.45rem;
  padding-top: 0.45rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
}

.ia-pipeline {
  margin-top: 0.35rem;
}

.ia-scroll-x {
  overflow-x: auto;
  scrollbar-width: thin;
}

.ia-scroll {
  scrollbar-width: thin;
}

@container (max-width: 24rem) {
  .ia-queue-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .lc-pos-queue-meta {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-start;
    gap: 0.35rem;
  }
}

/* ── Travel inventory access showcase (stacked cards) ──────────── */

.ia-showcase {
  width: 100%;
}

.ia-showcase-head {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 0.35rem;
}

.ia-showcase-title {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.ia-showcase-filters {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

.ia-showcase-field {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 0;
  padding: 0.32rem 0.42rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 88%, white);
}

.ia-showcase-field span {
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ia-showcase-field strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.58rem;
  font-weight: 600;
  color: var(--foreground);
}

.ia-showcase-table td:first-child {
  white-space: normal;
}

.ia-showcase-event {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}

.ia-showcase-section {
  display: block;
  margin-top: 0.06rem;
  font-size: 0.52rem;
  color: var(--muted-foreground);
}

.ia-showcase-detail-head {
  align-items: flex-start;
}

.ia-showcase-title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
}

.ia-showcase-badge {
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.1rem 0.38rem;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.ia-showcase-actions {
  display: flex;
  gap: 0.22rem;
  flex-shrink: 0;
}

.ia-showcase-action {
  display: grid;
  place-items: center;
  width: 1.45rem;
  height: 1.45rem;
  border-radius: 0.4rem;
  border: 1px solid var(--border);
  background: var(--background);
  color: var(--muted-foreground);
}

.ia-showcase-table-wrap {
  overflow-x: auto;
  border-radius: 0.55rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 92%, white);
}

.ia-showcase-detail-table {
  width: 100%;
  min-width: 16rem;
  border-collapse: collapse;
  font-size: 0.54rem;
}

.ia-showcase-detail-table th,
.ia-showcase-detail-table td {
  padding: 0.28rem 0.35rem;
  text-align: left;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 75%, transparent);
}

.ia-showcase-detail-table th {
  font-family: var(--font-mono);
  font-size: 0.46rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--surface) 88%, white);
}

.ia-showcase-detail-table tr[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}

.ia-showcase-detail-table tr:last-child td {
  border-bottom: 0;
}

.ia-showcase-detail-table strong {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--foreground);
}

/* ── Travel search filter zoom (diagonal glass cards) ─────────── */

.sf-wrap {
  margin-top: 2rem;
}

.sf-stage {
  position: relative;
  isolation: isolate;
  overflow: visible;
  min-height: clamp(32rem, 50vw, 42rem);
  padding: clamp(1.75rem, 4vw, 3.25rem) clamp(1.5rem, 4vw, 3rem) clamp(5.5rem, 10vw, 8rem);
  border-radius: 1.6rem;
  border: 1px solid color-mix(in oklab, var(--border) 90%, transparent);
}

.sf-mesh {
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  background:
    radial-gradient(ellipse 70% 60% at 18% 18%, color-mix(in oklab, var(--primary) 14%, transparent), transparent 62%),
    radial-gradient(ellipse 65% 55% at 88% 82%, color-mix(in oklab, var(--primary-soft) 80%, transparent), transparent 58%),
    linear-gradient(165deg, var(--background), var(--surface));
}

.sf-mesh::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(color-mix(in oklab, var(--foreground) 10%, transparent) 1px, transparent 1px);
  background-size: 16px 16px;
  opacity: 0.45;
}

.sf-card {
  container-type: inline-size;
  border-radius: 1.15rem;
}

.sf-card-back {
  position: relative;
  z-index: 1;
  width: min(82%, 46rem);
  margin-inline: auto;
  padding: 0.85rem 0.95rem 0.95rem;
  border: 1px solid color-mix(in oklab, var(--border) 88%, var(--foreground));
  background: color-mix(in oklab, white 78%, var(--surface));
  backdrop-filter: blur(18px) saturate(0.88);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.7) inset,
    0 18px 40px -28px color-mix(in oklab, var(--foreground) 22%, transparent);
  color: var(--foreground);
}

.sf-back-head {
  margin-bottom: 0.45rem;
}

.sf-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

.sf-stats .lc-stat {
  padding: 0.32rem 0.42rem;
  gap: 0.08rem;
}

.sf-stats .lc-stat-value {
  font-size: 0.72rem;
}

.sf-back-body {
  position: relative;
}

.sf-back-body::after {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: 0.55rem;
  backdrop-filter: blur(6px) saturate(0.5);
  background: color-mix(in oklab, var(--surface) 35%, transparent);
}

.sf-fields {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.35rem;
  margin-top: 0.55rem;
}

.sf-field {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 0;
  padding: 0.32rem 0.42rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 88%, white);
}

.sf-field span {
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.sf-field strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.58rem;
  font-weight: 600;
  color: var(--foreground);
}

.sf-back-controls {
  margin: 0.55rem 0 0.45rem;
}

.sf-card-front {
  position: absolute;
  z-index: 2;
  right: clamp(0.35rem, 2vw, 1.25rem);
  bottom: clamp(-0.35rem, 1.2vw, 0.75rem);
  width: min(58%, 32rem);
  padding: 0.9rem 1rem 0.95rem;
  overflow: hidden;
  border: 1px solid oklch(1 0 0 / 0.9);
  background:
    linear-gradient(180deg, color-mix(in oklab, var(--primary-soft) 55%, white), transparent 38%),
    var(--background);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.95) inset,
    0 24px 48px -18px color-mix(in oklab, var(--foreground) 28%, transparent),
    0 48px 90px -30px color-mix(in oklab, var(--foreground) 22%, transparent);
}

.sf-glare {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, oklch(1 0 0 / 0.42) 0%, transparent 38%);
}

.sf-front-head,
.sf-card-front .sf-cost,
.sf-card-front .sf-table-wrap,
.sf-front-foot {
  position: relative;
  z-index: 1;
}

.sf-front-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.55rem;
}

.sf-front-id {
  display: block;
  margin-bottom: 0.18rem;
  color: var(--muted-foreground);
}

.sf-front-title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
}

.sf-front-title {
  margin: 0;
  font-family: var(--font-display), var(--font-sans);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.sf-front-meta {
  margin: 0.18rem 0 0;
}

.sf-front-actions {
  display: flex;
  gap: 0.32rem;
  flex-shrink: 0;
}

.sf-icon-btn {
  display: grid;
  place-items: center;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 0.4rem;
  border: 1px solid var(--border);
  background: var(--background);
  color: var(--muted-foreground);
}

.sf-cost {
  margin-bottom: 0.55rem;
  padding: 0.32rem 0.42rem;
}

.sf-cost .ia-margin-row {
  font-size: 0.62rem;
}

.sf-cost .ia-margin-plus {
  font-size: 0.58rem;
}

.sf-front-foot {
  margin-top: 0.45rem;
}

.sf-table-wrap {
  overflow-x: auto;
  border-radius: 0.55rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 92%, white);
}

.sf-table {
  width: 100%;
  min-width: 18rem;
  border-collapse: collapse;
  font-size: 0.54rem;
  table-layout: fixed;
}

.sf-table th:nth-child(1),
.sf-table td:nth-child(1) {
  width: 34%;
}

.sf-table th:nth-child(2),
.sf-table td:nth-child(2) {
  width: 24%;
}

.sf-table th:nth-child(3),
.sf-table td:nth-child(3),
.sf-table th:nth-child(4),
.sf-table td:nth-child(4),
.sf-table th:nth-child(5),
.sf-table td:nth-child(5) {
  width: 14%;
}

.sf-table th,
.sf-table td {
  padding: 0.26rem 0.32rem;
  text-align: left;
  vertical-align: middle;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 75%, transparent);
}

.sf-table th {
  font-family: var(--font-mono);
  font-size: 0.46rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--surface) 88%, white);
}

.sf-table td {
  color: var(--foreground);
}

.sf-table tr[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}

.sf-table tr:last-child td {
  border-bottom: 0;
}

.sf-source {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
}

.sf-source-copy {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
}

.sf-source-copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.54rem;
  font-weight: 600;
}

.sf-source-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.22rem;
  font-size: 0.48rem;
  color: var(--muted-foreground);
}

.sf-cell-stack {
  display: grid;
  gap: 0.04rem;
  min-width: 0;
}

.sf-cell-stack .lc-mono {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.5rem;
}

.sf-partner {
  font-family: var(--font-mono);
  font-size: 0.54rem;
  font-weight: 700;
  color: var(--primary);
}

.sf-mark {
  display: grid;
  place-items: center;
  width: 1.05rem;
  height: 1.05rem;
  flex-shrink: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 18%, transparent);
  font-family: var(--font-mono);
  font-size: 0.44rem;
  font-style: normal;
  font-weight: 800;
  color: var(--primary);
}

.sf-card-back .sf-mark {
  background: color-mix(in oklab, var(--primary) 14%, transparent);
}

@container (min-width: 22rem) {
  .sf-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .sf-fields {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1023px) {
  .sf-wrap {
    min-width: 0;
    max-width: 100%;
    overflow-x: clip;
  }

  .sf-stage {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    min-height: 0;
    padding: 1.15rem;
    overflow: hidden;
  }

  .sf-card-back {
    width: 100%;
    margin-top: 0;
    order: 2;
  }

  .sf-back-body::after {
    backdrop-filter: blur(2px);
  }

  .sf-card-front {
    position: relative;
    right: auto;
    bottom: auto;
    width: 100%;
    order: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sf-back-body::after {
    backdrop-filter: none;
  }
}

/* ── Travel partner orders — fulfillment desk ─────────────────── */

.po-console {
  width: 100%;
  container-type: inline-size;
}

.po-console .lc-body {
  gap: 0.48rem;
}

.po-label {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.po-mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-style: normal;
}

.po-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
  flex-shrink: 0;
}

@container (min-width: 28rem) {
  .po-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.po-stat {
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.35rem 0.5rem;
}

.po-stat strong {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--foreground);
}

.po-lanes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.38rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex-shrink: 0;
}

@container (min-width: 32rem) {
  .po-lanes {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.po-lane {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  min-width: 0;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 70%, white);
  padding: 0.38rem 0.4rem 0.42rem;
  overflow: hidden;
}

.po-lane-rail {
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: color-mix(in oklab, var(--foreground) 12%, transparent);
}

.po-lane[data-done="true"] .po-lane-rail {
  background: var(--primary);
}

.po-lane[data-current="true"] .po-lane-rail {
  background: var(--primary);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.po-lane[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 6%, white);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 12%, transparent);
}

.po-lane[data-status="invoiced"][data-current="true"] {
  border-color: color-mix(in oklab, oklch(0.55 0.12 250) 32%, var(--border));
  background: color-mix(in oklab, oklch(0.55 0.12 250) 7%, white);
}

.po-lane[data-status="invoiced"][data-current="true"] .po-lane-rail,
.po-lane[data-status="invoiced"][data-done="true"] .po-lane-rail {
  background: oklch(0.55 0.12 250);
}

.po-lane-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.3rem;
  margin-top: 0.15rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--foreground);
}

.po-lane-count {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.02rem 0.32rem;
  font-size: 8.5px;
  color: var(--muted-foreground);
}

.po-lane[data-current="true"] .po-lane-count {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  color: var(--primary);
}

.po-lane-short {
  font-size: 0.58rem;
  line-height: 1.2;
  color: var(--muted-foreground);
}

.po-lane-list {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  margin: 0.08rem 0 0;
  padding: 0;
  list-style: none;
}

.po-card {
  display: flex;
  flex-direction: column;
  gap: 0.02rem;
  min-width: 0;
  border-radius: 0.4rem;
  background: color-mix(in oklab, var(--background) 88%, white);
  padding: 0.22rem 0.32rem;
}

.po-card[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 10%, white);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 22%, transparent);
}

.po-card .po-mono {
  font-size: 8.5px;
  letter-spacing: 0.04em;
  color: var(--muted-foreground);
}

.po-card strong {
  overflow: hidden;
  font-size: 0.64rem;
  font-weight: 650;
  color: var(--foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.po-work {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.45rem;
  flex: 1 1 auto;
  min-height: 0;
}

@container (min-width: 36rem) {
  .po-work {
    grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.98fr);
  }
}

.po-dossier,
.po-dock,
.po-panel {
  display: flex;
  flex-direction: column;
  gap: 0.42rem;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.5rem 0.55rem;
}

.po-dossier {
  border-color: color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 4%, white);
}

.po-panel-head {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.po-badge {
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.08rem 0.38rem;
  font-size: 9px;
  text-transform: none;
}

.po-badge[data-status="pending"] {
  color: var(--muted-foreground);
}

.po-badge[data-status="confirmed"],
.po-badge[data-status="delivered"],
.po-badge-live {
  border-color: color-mix(in oklab, var(--primary) 24%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--primary);
}

.po-badge[data-status="invoiced"] {
  color: oklch(0.55 0.12 250);
  background: oklch(0.55 0.12 250 / 0.1);
  border-color: oklch(0.55 0.12 250 / 0.28);
}

.po-dossier-meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 0.5rem;
}

.po-dossier-meta .po-mono {
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.po-dossier-meta strong {
  display: block;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--foreground);
}

.po-dossier-meta span {
  display: block;
  overflow: hidden;
  font-size: 0.62rem;
  color: var(--muted-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.po-dossier-meta em {
  flex-shrink: 0;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--foreground);
}

.po-slip {
  border-radius: 0.5rem;
  border: 1px dashed color-mix(in oklab, var(--foreground) 16%, transparent);
  background: color-mix(in oklab, var(--background) 90%, white);
  padding: 0.42rem 0.5rem 0.45rem;
  box-shadow: inset 3px 0 0 var(--primary);
}

.po-slip[data-state="awaiting"] {
  box-shadow: inset 3px 0 0 color-mix(in oklab, var(--foreground) 22%, transparent);
  opacity: 0.78;
}

.po-slip[data-state="generating"] {
  box-shadow: inset 3px 0 0 var(--primary);
  animation: po-slip-pulse 1.8s ease-in-out infinite;
}

.po-slip-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.32rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.po-stamp {
  margin-left: auto;
  border-radius: 0.28rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent);
  padding: 0.06rem 0.32rem;
  font-size: 8.5px;
}

.po-stamp[data-state="generating"] {
  border-color: color-mix(in oklab, var(--primary) 30%, var(--border));
  color: var(--primary);
}

.po-stamp[data-state="issued"] {
  border-color: color-mix(in oklab, var(--primary) 36%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  color: var(--primary);
}

.po-slip ul {
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.po-slip li {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.68rem;
  color: var(--foreground);
}

.po-slip-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-top: 0.32rem;
  padding-top: 0.28rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  font-size: 0.68rem;
  font-weight: 650;
  color: var(--foreground);
}

.po-slip-total strong {
  font-size: 0.82rem;
}

.po-pos-note {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.po-methods {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.32rem;
}

.po-method {
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 82%, white);
  padding: 0.38rem 0.32rem;
  color: var(--muted-foreground);
}

.po-method strong {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--foreground);
}

.po-method span:last-child {
  overflow: hidden;
  font-size: 0.58rem;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.po-method[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 32%, var(--border));
  background: color-mix(in oklab, var(--primary) 9%, white);
  color: var(--primary);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 12%, transparent);
}

.po-confirm {
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  margin: 0;
}

.po-confirm strong {
  overflow: hidden;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.po-settle {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.po-settle-head {
  display: flex;
  align-items: center;
  gap: 0.32rem;
}

.po-settle-head .po-mono {
  margin-left: auto;
  font-size: 0.62rem;
  color: var(--foreground);
}

.po-t3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.po-t3 li {
  display: grid;
  place-items: center;
  border-radius: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, var(--background) 80%, white);
  padding: 0.22rem 0;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.po-t3 li[data-filled="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 12%, white);
  color: var(--primary);
}

.po-t3 li[data-next="true"] {
  border-color: color-mix(in oklab, var(--primary) 18%, var(--border));
  color: var(--foreground);
}

.po-holds {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  min-height: 0;
}

.po-hold-list {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.po-hold {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.38rem;
  border-radius: 0.45rem;
  background: color-mix(in oklab, var(--background) 82%, white);
  padding: 0.28rem 0.38rem;
  color: var(--muted-foreground);
}

.po-hold[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 9%, white);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 20%, transparent);
  color: var(--primary);
}

.po-hold strong {
  display: block;
  overflow: hidden;
  font-size: 0.64rem;
  font-weight: 650;
  color: var(--foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.po-hold .po-mono {
  font-size: 8.5px;
  color: var(--muted-foreground);
}

.po-hold em {
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--foreground);
}

.po-panel-feed {
  flex-shrink: 0;
}

.po-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.po-feed-viewport {
  height: 3.35rem;
  overflow: hidden;
  mask-image: linear-gradient(180deg, transparent, black 16%, black 84%, transparent);
}

.po-console[data-live="true"] .po-feed-list {
  animation: lc-feed-scroll 20s linear infinite;
}

.po-feed-list {
  display: flex;
  flex-direction: column;
  gap: 0.24rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.po-feed-row {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr);
  gap: 0.45rem;
  font-size: 0.68rem;
}

.po-feed-row span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--foreground) 85%, transparent);
}

@keyframes po-slip-pulse {
  0%,
  100% {
    background: color-mix(in oklab, var(--background) 90%, white);
  }
  50% {
    background: color-mix(in oklab, var(--primary) 8%, white);
  }
}

/* ── Marketplace connectivity consoles ─────────────────────────── */

.ch-console,
.ld-console,
.pc-console {
  width: 100%;
  container-type: inline-size;
}

.ch-stats,
.ld-stats,
.pc-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
  flex-shrink: 0;
}

@container (min-width: 28rem) {
  .ch-stats,
  .ld-stats,
  .pc-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.ch-panel,
.ld-panel,
.pc-panel {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  min-width: 0;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.55rem 0.6rem;
}

.ch-panel-head,
.ld-panel-head,
.pc-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ch-badge,
.ld-badge,
.pc-badge {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.12rem 0.45rem;
  font-size: 9px;
  letter-spacing: 0.08em;
}

.pc-badge-live {
  border-color: color-mix(in oklab, var(--primary) 35%, transparent);
  color: var(--primary);
}

.ch-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  min-height: 0;
  flex: 1 1 auto;
}

.ch-workspace > .ch-panel {
  min-height: 0;
}

@container (min-width: 36rem) {
  .ch-workspace {
    grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  }
}

.ch-map-panel {
  min-height: 0;
}

.ch-map {
  position: relative;
  aspect-ratio: 1;
  width: min(100%, 11.5rem);
  margin: 0.15rem auto 0;
}

.ch-map-ring {
  position: absolute;
  inset: 10%;
  border-radius: 999px;
  border: 1px dashed color-mix(in oklab, var(--primary) 32%, transparent);
  animation: constellation-spin 18s linear infinite;
}

.ch-map-ring-2 {
  inset: 24%;
  border-style: solid;
  border-color: color-mix(in oklab, var(--primary) 16%, transparent);
  animation-direction: reverse;
  animation-duration: 24s;
}

.ch-hub {
  position: absolute;
  inset: 36%;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary-soft) 70%, white);
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--foreground);
  box-shadow: 0 0 22px color-mix(in oklab, var(--primary) 22%, transparent);
}

.ch-hub small {
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--primary);
}

.ch-node {
  --ch-i: 0;
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 1.55rem;
  height: 1.55rem;
  margin: -0.775rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--background) 88%, white);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 18%, transparent);
  transform: rotate(calc(var(--ch-i) * 45deg)) translateX(4.85rem) rotate(calc(var(--ch-i) * -45deg));
}

.ch-node em {
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--primary);
}

.ch-node[data-status="pushing"] {
  border-color: color-mix(in oklab, var(--primary) 70%, transparent);
  background: color-mix(in oklab, var(--primary) 16%, white);
}

.ch-node[data-status="queued"] {
  border-color: color-mix(in oklab, var(--foreground) 18%, transparent);
  box-shadow: none;
}

.ch-node[data-status="queued"] em {
  color: var(--muted-foreground);
}

.ch-node[data-active="true"] {
  outline: 2px solid color-mix(in oklab, var(--primary) 55%, transparent);
  outline-offset: 2px;
}

.ch-map-caption {
  margin: 0.35rem 0 0;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  color: var(--muted-foreground);
}

.ch-list,
.pc-holds,
.pc-delist {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
  min-height: 0;
  overflow: auto;
  flex: 1 1 auto;
}

.ch-row {
  display: grid;
  grid-template-columns: 3.1rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.5rem;
  padding: 0.28rem 0.4rem;
  font-size: 0.68rem;
}

.ch-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.ch-row-code {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.ch-row-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
  color: var(--foreground);
}

.ch-row-meta {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.ch-row-status {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.ch-row[data-status="queued"] .ch-row-status {
  color: var(--muted-foreground);
}

.ch-dot,
.ld-dot,
.pc-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 0 color-mix(in oklab, var(--primary) 45%, transparent);
  animation: two-track-live-pulse 1.8s ease-out infinite;
}

.ch-feed-panel,
.ld-feed-panel,
.pc-feed-panel {
  flex-shrink: 0;
}

.ch-feed-viewport,
.ld-feed-viewport,
.pc-feed-viewport {
  height: 4.2rem;
  overflow: hidden;
  mask-image: linear-gradient(180deg, transparent, black 16%, black 84%, transparent);
}

.ch-console[data-live="true"] .ch-feed-list,
.ld-console[data-live="true"] .ld-feed-list,
.pc-console[data-live="true"] .pc-feed-list {
  animation: lc-feed-scroll 18s linear infinite;
}

.ch-feed-list,
.ld-feed-list,
.pc-feed-list {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ch-feed-row,
.ld-feed-row,
.pc-feed-row {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr) 0.55rem;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.68rem;
}

.ch-feed-row span:nth-child(2),
.ld-feed-row span:nth-child(2),
.pc-feed-row span:nth-child(2) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--foreground) 85%, transparent);
}

.ld-context {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  flex-shrink: 0;
}

.ld-context > div {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}

.ld-context strong {
  font-size: 0.92rem;
  color: var(--foreground);
}

.ld-context span {
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.ld-chip {
  flex-shrink: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  padding: 0.22rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.ld-pipeline {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex-shrink: 0;
}

@container (min-width: 32rem) {
  .ld-pipeline {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.ld-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 0.4rem;
  row-gap: 0.08rem;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.4rem 0.45rem;
}

.ld-step[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.ld-step-icon {
  grid-row: 1 / span 2;
  color: var(--muted-foreground);
}

.ld-step[data-done="true"] .ld-step-icon,
.ld-step[data-current="true"] .ld-step-icon {
  color: var(--primary);
}

.ld-step-label {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--foreground);
}

.ld-step-detail {
  grid-column: 2;
  font-size: 0.58rem;
  line-height: 1.3;
  color: var(--muted-foreground);
}

.ld-fan {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
  overflow: hidden;
}

@container (min-width: 30rem) {
  .ld-fan {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.ld-fan-node {
  display: grid;
  gap: 0.08rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.4rem 0.45rem;
}

.ld-fan-node[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.ld-fan-node strong {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--foreground);
}

.ld-fan-node em {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.ld-fan-node[data-status="queued"] em {
  color: var(--muted-foreground);
}

.ld-fan-qty {
  font-size: 0.58rem;
  color: var(--muted-foreground);
}

.pc-price {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.6rem;
  flex-shrink: 0;
}

.pc-price-event {
  margin: 0.15rem 0 0;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--foreground);
}

.pc-delta {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  font-family: var(--font-mono);
}

.pc-from {
  font-size: 0.85rem;
  color: var(--muted-foreground);
  text-decoration: line-through;
}

.pc-arrow {
  color: var(--primary);
}

.pc-to {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--foreground);
}

.pc-acks {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@container (min-width: 32rem) {
  .pc-acks {
    grid-template-columns: repeat(8, minmax(0, 1fr));
  }
}

.pc-ack {
  display: grid;
  justify-items: center;
  gap: 0.12rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.35rem 0.2rem;
}

.pc-ack strong {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
}

.pc-ack span {
  font-family: var(--font-mono);
  font-size: 0.48rem;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.pc-ack[data-status="pending"] span {
  color: var(--muted-foreground);
}

.pc-ack[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.pc-split {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  min-height: 0;
  flex: 1 1 auto;
}

@container (min-width: 32rem) {
  .pc-split {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  }
}

.pc-panel-accent {
  background: color-mix(in oklab, var(--primary-soft) 55%, white);
}

.pc-hold-row,
.pc-delist-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  border-radius: 0.45rem;
  padding: 0.28rem 0.35rem;
  font-size: 0.68rem;
}

.pc-hold-row[data-active="true"],
.pc-delist-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.pc-hold-row em,
.pc-delist-row span {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-style: normal;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

.pc-hold-row[data-state="sold"] em {
  color: var(--muted-foreground);
}

.pc-delist-lead {
  margin: 0;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

@media (max-width: 24rem) {
  .ch-map {
    width: min(100%, 9.5rem);
  }

  .ch-node {
    transform: rotate(calc(var(--ch-i) * 45deg)) translateX(3.85rem) rotate(calc(var(--ch-i) * -45deg));
  }
}

@media (prefers-reduced-motion: reduce) {
  .lc-scan,
  .lc-panel-dot,
  .mi-panel-dot,
  .ap-panel-dot,
  .qb-panel-dot,
  .qb-status i,
  .qb-step[data-current="true"] .qb-step-node,
  .po-dot,
  .po-lane[data-current="true"] .po-lane-rail,
  .po-slip[data-state="generating"],
  .ch-dot,
  .ld-dot,
  .pc-dot,
  .ch-map-ring,
  .ap-status i,
  .ap-step[data-current="true"] .ap-step-node,
  .mi-chart-dot-halo,
  .sx-connector-packet,
  .lc-pos[data-live="true"] .lc-feed-list,
  .mi-console[data-live="true"] .mi-feed-list,
  .ap-console[data-live="true"] .ap-log-list,
  .po-console[data-live="true"] .po-feed-list,
  .ch-console[data-live="true"] .ch-feed-list,
  .ld-console[data-live="true"] .ld-feed-list,
  .pc-console[data-live="true"] .pc-feed-list,
  .ia-queue-row[data-synced="true"],
  .ia-console[data-live="true"] .lc-feed-list,
  .lc-intel[data-live="true"] .lc-feed-list,
  .lc-ai[data-live="true"] .lc-feed-list,
  .ec-catalog[data-live="true"] .lc-feed-list,
  .abt-ops[data-live="true"] .abt-ops-feed,
  .lc-spin,
  .lc-tilt-card {
    animation: none;
    transition: none;
  }

  .lc-section-stage:hover .lc-tilt-card,
  .lc-tilt-wrap:focus-within .lc-tilt-card {
    transform: none;
  }

  .ap-btn:hover {
    transform: none;
  }
}

/* ── Travel partners: Partner Terms & Settlement ───────────────── */

.pt-layout {
  display: grid;
  gap: clamp(1.5rem, 3vw, 2.5rem);
  align-items: start;
}

@media (min-width: 1024px) {
  .pt-layout {
    grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
    gap: clamp(1.75rem, 2.4vw, 2.75rem);
  }

  .pt-stage {
    position: sticky;
    top: 6.5rem;
  }
}

.pt-copy {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
  min-width: 0;
}

.pt-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.pt-title {
  max-width: 22ch;
  font-family: var(--font-display);
  font-size: clamp(1.85rem, 3.2vw, 2.65rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.pt-title em {
  display: block;
  font-style: italic;
}

.pt-lead {
  max-width: 58ch;
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.pt-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.7rem;
  margin: 0.15rem 0 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 720px) {
  .pt-tiles {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.pt-tile {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  min-width: 0;
  border-radius: 0.875rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 0.85rem 0.9rem;
}

.pt-tile-icon {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  margin-bottom: 0.2rem;
  border-radius: 0.55rem;
  background: var(--primary-soft);
  color: var(--primary);
}

.pt-tile strong {
  font-size: 0.82rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--foreground);
}

.pt-tile span:last-child {
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.pt-table-card {
  border-radius: 1rem;
  border: 1px solid var(--border);
  background: var(--card);
  overflow: hidden;
}

.pt-table-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  padding: 1rem 1.05rem 0.85rem;
  border-bottom: 1px solid var(--border);
}

.pt-table-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.92rem;
  font-weight: 650;
  color: var(--foreground);
}

.pt-table-head-copy p {
  margin: 0.2rem 0 0;
  font-size: 0.78rem;
  color: var(--muted-foreground);
}

.pt-download {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: transparent;
  padding: 0.38rem 0.75rem;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--foreground);
  cursor: default;
}

.pt-table-wrap {
  overflow-x: auto;
  scrollbar-width: thin;
}

.pt-table {
  width: 100%;
  min-width: 32rem;
  border-collapse: collapse;
}

.pt-table th,
.pt-table td {
  padding: 0.7rem 1.05rem;
  text-align: left;
  vertical-align: middle;
}

.pt-table th {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--surface) 80%, white);
}

.pt-table td {
  font-size: 0.8rem;
  color: var(--foreground);
  border-top: 1px solid var(--border);
}

.pt-table td:first-child {
  font-weight: 600;
}

.pt-table tbody tr {
  transition: background 0.25s ease;
}

.pt-table tbody tr[data-status="progress"] {
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}

.pt-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  border: 1px solid transparent;
  padding: 0.16rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  white-space: nowrap;
}

.pt-pill[data-status="completed"] {
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  border-color: color-mix(in oklab, var(--primary) 22%, var(--border));
}

.pt-pill[data-status="progress"] {
  color: color-mix(in oklab, var(--foreground) 55%, var(--primary));
  background: color-mix(in oklab, var(--primary-soft) 70%, var(--surface));
  border-color: color-mix(in oklab, var(--primary) 18%, var(--border));
}

.pt-pill[data-status="upcoming"] {
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--foreground) 5%, transparent);
  border-color: var(--border);
}

.pt-banner {
  border-radius: 1rem;
  background: var(--primary-soft);
  padding: 1rem 1.1rem 1.05rem;
}

.pt-banner-lead {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin-bottom: 0.85rem;
}

.pt-banner-icon {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  flex-shrink: 0;
  border-radius: 0.55rem;
  background: color-mix(in oklab, white 55%, var(--primary-soft));
  color: var(--primary);
}

.pt-banner-lead strong {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--foreground);
}

.pt-checks {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.65rem 1rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 640px) {
  .pt-checks {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.pt-checks li {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
}

.pt-checks svg {
  flex-shrink: 0;
  margin-top: 0.12rem;
  color: var(--primary);
}

.pt-checks strong {
  display: block;
  font-size: 0.8rem;
  font-weight: 650;
  color: var(--foreground);
}

.pt-checks span {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.pt-console {
  width: 100%;
  container-type: inline-size;
}

.pt-console .lc-screen {
  height: auto;
  min-height: 0;
  max-height: none;
}

.pt-console .lc-body {
  gap: 0.65rem;
}

.pt-desk-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.55rem 0.85rem;
  flex-shrink: 0;
}

.pt-desk-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--foreground);
}

.pt-desk-demo {
  display: block;
  margin-top: 0.18rem;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.pt-live-view {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 24%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  padding: 0.22rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.pt-live-dot {
  position: relative;
  flex-shrink: 0;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.pt-live-dot::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  animation: two-track-pulse-ring 2.4s ease-out infinite;
}

.pt-desk-cards {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.pt-desk-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.55rem 0.65rem;
  transition: background 0.25s ease, border-color 0.25s ease;
}

.pt-desk-card[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 7%, white);
}

.pt-desk-card-icon {
  display: grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 0.5rem;
  background: var(--primary-soft);
  color: var(--primary);
}

.pt-desk-card-copy strong {
  display: block;
  font-size: 0.78rem;
  font-weight: 650;
  color: var(--foreground);
}

.pt-desk-card-copy p {
  margin: 0.12rem 0 0;
  font-size: 0.68rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.pt-desk-chevron {
  color: color-mix(in oklab, var(--foreground) 28%, transparent);
}

.pt-desk-card[data-active="true"] .pt-desk-chevron {
  color: var(--primary);
}

.pt-pipe-panel {
  flex: 0 0 auto;
}

.pt-pipeline {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@container (min-width: 22rem) {
  .pt-pipeline {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.35rem;
  }
}

.pt-pipeline-step {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.12rem;
  min-width: 0;
  border-radius: 0.55rem;
  padding: 0.35rem 0.4rem;
  transition: background 0.25s ease;
}

.pt-pipeline-step[data-current="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.pt-pipeline-icon {
  color: color-mix(in oklab, var(--foreground) 28%, transparent);
}

.pt-pipeline-step[data-done="true"] .pt-pipeline-icon,
.pt-pipeline-step[data-current="true"] .pt-pipeline-icon {
  color: var(--primary);
}

.pt-pipeline-label {
  font-size: 0.68rem;
  font-weight: 650;
  line-height: 1.3;
  color: var(--foreground);
}

.pt-pipeline-step[data-done="true"] .pt-pipeline-label {
  color: var(--primary);
}

.pt-pipeline-detail {
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.pt-console[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 18s linear infinite;
}

.pt-contact {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.45rem 0.65rem;
  align-items: start;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, white);
  padding: 0.7rem 0.75rem;
}

.pt-contact-icon {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 0.55rem;
  background: var(--primary-soft);
  color: var(--primary);
}

.pt-contact-copy strong {
  display: block;
  font-size: 0.78rem;
  font-weight: 650;
  color: var(--foreground);
}

.pt-contact-copy p {
  margin: 0.12rem 0 0;
  font-size: 0.68rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.pt-contact-btn {
  grid-column: 1 / -1;
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border-radius: 0.5rem;
  background: var(--primary);
  padding: 0.42rem 0.75rem;
  font-size: 0.72rem;
  font-weight: 650;
  color: var(--primary-foreground);
}

@container (min-width: 26rem) {
  .pt-contact {
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
  }

  .pt-contact-btn {
    grid-column: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pt-live-dot,
  .pt-live-dot::after,
  .pt-console[data-live="true"] .lc-feed-list,
  .pt-table tbody tr {
    animation: none;
    transition: none;
  }
}

/* == Event intelligence page (radar, demand signals, forecast, venue map) == */

.er-console,
.ds-console,
.fc-console,
.vm-console {
  width: 100%;
  container-type: inline-size;
}

.er-scroll,
.ds-scroll {
  overflow-y: auto;
  min-height: 0;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--foreground) 18%, transparent) transparent;
}

/* -- Event radar console -- */

.er-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
  flex-shrink: 0;
}

@container (min-width: 28rem) {
  .er-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.er-cal-panel {
  flex-shrink: 0;
}

.er-cal {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.er-cal-day {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.16rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, var(--background) 76%, white);
  padding: 0.3rem 0.15rem 0.28rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    transform 0.25s ease;
}

.er-cal-day[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 34%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, white);
  transform: translateY(-1px);
}

.er-cal-dow {
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.er-cal-date {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--foreground);
}

.er-cal-bars {
  display: grid;
  gap: 1.5px;
  width: 100%;
  padding-inline: 0.2rem;
}

.er-cal-bars i {
  display: block;
  height: 2px;
  width: var(--er-heat, 40%);
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 55%, transparent);
}

.er-cal-day[data-active="true"] .er-cal-bars i {
  background: var(--primary);
}

.er-cal-count {
  font-size: 9px;
  color: var(--muted-foreground);
}

.er-cal-caption {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.er-cal-caption svg {
  flex-shrink: 0;
  color: var(--primary);
}

.er-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  flex: 1 1 auto;
  min-height: 0;
}

@container (min-width: 36rem) {
  .er-workspace {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  }
}

.er-queue-panel,
.er-detail-panel {
  min-height: 0;
}

.er-cols {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr) 3.6rem;
  gap: 0.45rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--muted-foreground) 80%, transparent);
}

.er-cols span:last-child {
  text-align: right;
}

.er-queue {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.er-row {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr) 3.6rem;
  align-items: center;
  gap: 0.45rem;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  padding: 0.3rem 0.35rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease;
}

.er-row[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 26%, transparent);
  background: color-mix(in oklab, var(--primary) 6%, transparent);
}

.er-row-window {
  color: var(--muted-foreground);
}

.er-row-main {
  min-width: 0;
}

.er-row-main strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.75rem;
  font-weight: 650;
  color: var(--foreground);
}

.er-row-main span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.65rem;
  color: var(--muted-foreground);
}

.er-row-score {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.18rem;
}

.er-row-track {
  display: block;
  width: 100%;
  height: 3px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

.er-row-track i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 55%, transparent);
}

.er-row[data-band="peak"] .er-row-track i {
  background: var(--primary);
}

.er-row[data-band="steady"] .er-row-track i {
  background: color-mix(in oklab, var(--primary) 38%, transparent);
}

.er-row-score b {
  font-size: 10px;
  font-weight: 700;
  color: var(--foreground);
}

.er-detail {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.er-detail-head {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--background) 82%, white);
  padding: 0.45rem 0.55rem;
}

.er-detail-head > span:first-child {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.er-detail-head strong {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--foreground);
}

.er-detail-head > span:last-child {
  font-size: 0.65rem;
  color: var(--muted-foreground);
}

.er-meter {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.er-meter-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.er-meter-head strong {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--foreground);
}

.er-meter-track {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  gap: 2px;
}

.er-meter-seg {
  height: 0.5rem;
  border-radius: 2px;
  background: color-mix(in oklab, var(--foreground) 7%, transparent);
  transition: background 0.3s ease;
}

.er-meter-seg[data-on="true"] {
  background: color-mix(in oklab, var(--primary) 55%, transparent);
}

.er-meter-seg[data-on="true"][data-band="peak"] {
  background: var(--primary);
}

.er-meter-seg[data-on="true"][data-band="steady"] {
  background: color-mix(in oklab, var(--primary) 40%, transparent);
}

.er-meter-band {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.er-meter-band[data-band="peak"] {
  color: var(--primary);
}

.er-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

.er-tile {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, var(--background) 74%, white);
  padding: 0.35rem 0.45rem;
  min-width: 0;
}

.er-tile-label {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.er-tile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--foreground);
}

.er-signals {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.er-signal {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 3.2rem auto;
  align-items: center;
  gap: 0.4rem;
}

.er-signal-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.66rem;
  color: var(--muted-foreground);
}

.er-signal-track {
  display: block;
  height: 3px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

.er-signal-track i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--primary);
}

.er-signal b {
  font-size: 10px;
  color: var(--foreground);
}

.er-console[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 19s linear infinite;
}

/* -- Demand signal console -- */

.ds-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
  flex-shrink: 0;
}

.ds-head-title {
  margin: 0;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--foreground);
}

.ds-head-meta {
  margin: 0.1rem 0 0;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.ds-switch {
  display: inline-flex;
  gap: 0.25rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 70%, white);
  padding: 0.15rem;
}

.ds-switch-btn {
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0.2rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
  cursor: pointer;
  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.ds-switch-btn[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  color: var(--primary);
}

.ds-head-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.45rem;
  flex-shrink: 0;
}

.ds-head-stat {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0.25rem;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, var(--background) 74%, white);
  padding: 0.35rem 0.5rem;
}

.ds-head-stat .lc-stat-label {
  grid-column: 1 / -1;
}

.ds-head-stat strong {
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--foreground);
}

.ds-head-stat-dir {
  display: inline-flex;
  align-items: center;
  color: var(--primary);
}

.ds-head-stat-dir[data-direction="down"] {
  color: color-mix(in oklab, var(--foreground) 55%, transparent);
}

.ds-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  flex: 1 1 auto;
  min-height: 0;
}

@container (min-width: 36rem) {
  .ds-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  }
}

.ds-chart-panel,
.ds-comp-panel {
  min-height: 0;
}

.ds-chart {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  overflow: hidden;
}

.ds-chart-svg {
  width: 100%;
  height: auto;
  min-height: 0;
  max-height: 8.5rem;
}

.ds-chart-gridline {
  stroke: color-mix(in oklab, var(--foreground) 8%, transparent);
  stroke-width: 1;
  stroke-dasharray: 3 4;
}

.ds-chart-bar {
  fill: color-mix(in oklab, var(--primary) 22%, transparent);
}

.ds-chart-bar[data-last="true"] {
  fill: color-mix(in oklab, var(--primary) 45%, transparent);
}

.ds-chart-line {
  fill: none;
  stroke: var(--primary-deep);
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ds-chart-dot {
  fill: var(--primary-deep);
}

.ds-chart-axis {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--muted-foreground);
}

.ds-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 0.62rem;
  color: var(--muted-foreground);
}

.ds-legend li {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.ds-legend li::before {
  content: "";
  width: 0.55rem;
  height: 0.35rem;
  border-radius: 2px;
  background: color-mix(in oklab, var(--primary) 30%, transparent);
}

.ds-legend li[data-kind="ask"]::before {
  height: 2px;
  background: var(--primary-deep);
}

.ds-comp-cols {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 2.4rem 5.2rem;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--muted-foreground) 80%, transparent);
}

.ds-comp-list {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ds-comp-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 2.4rem 5.2rem;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  padding: 0.3rem 0.35rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease;
}

.ds-comp-row[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 24%, transparent);
  background: color-mix(in oklab, var(--primary) 6%, transparent);
}

.ds-comp-name {
  min-width: 0;
}

.ds-comp-name strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--foreground);
}

.ds-comp-name span {
  font-size: 9px;
  color: var(--muted-foreground);
}

.ds-comp-match {
  font-size: 10px;
  font-weight: 700;
  color: var(--primary);
}

.ds-comp-outcome {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.1rem 0.35rem;
  font-size: 9px;
  text-align: center;
  color: var(--muted-foreground);
}

.ds-comp-row[data-tone="soldout"] .ds-comp-outcome {
  border-color: color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--primary);
}

.ds-comp-row[data-tone="softened"] .ds-comp-outcome {
  border-style: dashed;
}

.ds-band-panel {
  flex-shrink: 0;
}

.ds-bands {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ds-band {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 3rem 2.8rem;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.45rem;
  padding: 0.22rem 0.3rem;
  transition: background 0.25s ease;
}

@container (min-width: 30rem) {
  .ds-band {
    grid-template-columns: 9.5rem minmax(0, 1fr) 2.8rem 3.4rem;
  }
}

.ds-band[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
}

.ds-band-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.68rem;
  color: var(--foreground);
}

.ds-band-track {
  display: none;
  height: 4px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

@container (min-width: 30rem) {
  .ds-band-track {
    display: block;
  }
}

.ds-band-track i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 58%, transparent);
}

.ds-band[data-active="true"] .ds-band-track i {
  background: var(--primary);
}

.ds-band-ask {
  font-size: 10px;
  font-weight: 700;
  text-align: right;
  color: var(--foreground);
}

.ds-band-delta {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.12rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  color: var(--primary);
}

.ds-band-delta[data-direction="down"] {
  color: color-mix(in oklab, var(--foreground) 58%, transparent);
}

.ds-band-delta[data-direction="flat"] {
  color: var(--muted-foreground);
}

.ds-feed-viewport {
  position: relative;
  height: 4.6rem;
  overflow: hidden;
  flex-shrink: 0;
  mask-image: linear-gradient(180deg, transparent, black 14%, black 86%, transparent);
}

.ds-console[data-live="true"] .ds-feed-list {
  animation: lc-feed-scroll 20s linear infinite;
}

.ds-feed-list {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ds-feed-row {
  display: grid;
  grid-template-columns: 0.4rem 4.2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.45rem;
  font-size: 0.7rem;
}

.ds-feed-level {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 20%, transparent);
}

.ds-feed-row[data-level="high"] .ds-feed-level {
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 16%, transparent);
}

.ds-feed-row[data-level="warn"] .ds-feed-level {
  background: color-mix(in oklab, var(--primary-deep) 60%, var(--foreground));
}

.ds-feed-time {
  color: var(--muted-foreground);
}

.ds-feed-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--foreground) 85%, transparent);
}

/* -- Forecast cockpit -- */

.fc-shell {
  display: flex;
  flex-direction: column;
  gap: clamp(0.6rem, 1.4vw, 0.85rem);
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  background:
    radial-gradient(120% 100% at 0% 0%, color-mix(in oklab, var(--primary) 7%, transparent), transparent 58%),
    linear-gradient(180deg, white, color-mix(in oklab, var(--surface) 70%, white));
  padding: clamp(0.8rem, 1.8vw, 1.15rem);
  box-shadow:
    0 30px 70px -44px color-mix(in oklab, var(--dark) 60%, transparent),
    0 0 0 1px color-mix(in oklab, white 60%, transparent) inset;
}

.fc-head {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  border-bottom: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding-bottom: 0.7rem;
}

.fc-model {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--primary) 26%, transparent);
  background: color-mix(in oklab, var(--primary) 11%, transparent);
  color: var(--primary);
}

.fc-head-copy {
  min-width: 0;
}

.fc-head-copy strong {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.fc-head-copy span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}

.fc-version {
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.1rem 0.4rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-foreground);
}

.fc-status {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  padding: 0.12rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  white-space: nowrap;
  color: var(--primary);
}

.fc-status i {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: currentColor;
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.fc-inputs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fc-input {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 76%, white);
  padding: 0.18rem 0.5rem;
  font-size: 0.66rem;
  color: var(--muted-foreground);
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}

.fc-input svg {
  color: color-mix(in oklab, var(--primary) 65%, transparent);
}

.fc-input[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--foreground);
}

.fc-input em {
  font-style: normal;
  font-size: 9px;
  color: var(--muted-foreground);
}

.fc-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.6rem;
}

@container (min-width: 34rem) {
  .fc-grid {
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  }
}

.fc-panel {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-width: 0;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, white 82%, var(--surface));
  padding: 0.65rem 0.7rem;
}

.fc-panel-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.fc-panel-note {
  margin-left: auto;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  padding: 0.08rem 0.4rem;
  font-size: 9px;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--primary);
}

.fc-panel-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.fc-cone {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.fc-cone-svg {
  width: 100%;
  height: auto;
}

.fc-cone-gridline {
  stroke: color-mix(in oklab, var(--foreground) 7%, transparent);
  stroke-width: 1;
}

.fc-cone-band {
  stroke: color-mix(in oklab, var(--primary) 26%, transparent);
  stroke-width: 0.8;
}

.fc-cone-history {
  fill: none;
  stroke: color-mix(in oklab, var(--foreground) 45%, transparent);
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.fc-cone-median {
  fill: none;
  stroke: var(--primary);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 5 3;
}

.fc-cone-now {
  stroke: color-mix(in oklab, var(--foreground) 22%, transparent);
  stroke-width: 1;
  stroke-dasharray: 2 3;
}

.fc-cone-dot {
  fill: var(--primary);
}

.fc-cone-axis {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--muted-foreground);
}

.fc-cone-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.4rem;
  margin: 0;
}

.fc-cone-stats div {
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, white 70%, var(--surface));
  padding: 0.35rem 0.45rem;
}

.fc-cone-stats dt {
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.fc-cone-stats dd {
  margin: 0.1rem 0 0;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--foreground);
}

.fc-risk-total {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 0.15rem 0.6rem;
}

.fc-risk-total strong {
  grid-row: span 2;
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1;
  color: var(--foreground);
}

.fc-risk-meter {
  height: 0.4rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

.fc-risk-meter span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 45%, transparent),
    var(--primary)
  );
  transition: width 0.4s ease;
}

.fc-risk-total > span:last-child {
  font-size: 0.66rem;
  color: var(--muted-foreground);
}

.fc-risk-list {
  display: flex;
  flex-direction: column;
  gap: 0.26rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fc-risk-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 3.4rem 2.2rem;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.45rem;
  padding: 0.2rem 0.3rem;
  transition: background 0.25s ease;
}

.fc-risk-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
}

.fc-risk-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.68rem;
  color: var(--foreground);
}

.fc-risk-track {
  display: block;
  height: 4px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  overflow: hidden;
}

.fc-risk-track i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 40%, transparent);
  transition: width 0.4s ease;
}

.fc-risk-row[data-level="high"] .fc-risk-track i {
  background: var(--primary);
}

.fc-risk-row[data-level="mid"] .fc-risk-track i {
  background: color-mix(in oklab, var(--primary) 62%, transparent);
}

.fc-risk-row b {
  font-size: 10px;
  font-weight: 700;
  text-align: right;
  color: var(--foreground);
}

.fc-scenario-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.4rem;
}

@container (min-width: 30rem) {
  .fc-scenario-row {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.fc-scenario {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  background: color-mix(in oklab, white 72%, var(--surface));
  padding: 0.45rem 0.55rem;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    transform 0.25s ease;
}

.fc-scenario:hover {
  transform: translateY(-1px);
}

.fc-scenario[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 38%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, white);
}

.fc-scenario-name {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--foreground);
}

.fc-scenario-note {
  font-size: 0.64rem;
  color: var(--muted-foreground);
}

.fc-outcome {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
  margin: 0;
}

@container (min-width: 30rem) {
  .fc-outcome {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.fc-outcome div {
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--primary) 14%, transparent);
  background: color-mix(in oklab, var(--primary) 4%, white);
  padding: 0.35rem 0.45rem;
}

.fc-outcome dt {
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.fc-outcome dd {
  margin: 0.1rem 0 0;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--foreground);
}

.fc-log {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 55%, white);
  padding: 0.55rem 0.65rem;
}

.fc-log-viewport {
  position: relative;
  height: 3.6rem;
  overflow: hidden;
  mask-image: linear-gradient(180deg, transparent, black 16%, black 84%, transparent);
}

.fc-console[data-live="true"] .fc-log-list {
  animation: lc-feed-scroll 21s linear infinite;
}

.fc-log-list {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fc-log-row {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.5rem;
  font-size: 0.72rem;
}

.fc-log-time {
  font-size: 10.5px;
  color: var(--muted-foreground);
}

.fc-log-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--foreground) 82%, transparent);
}

.fc-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding-top: 0.65rem;
}

.fc-foot p {
  margin: 0;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}

.fc-foot-link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--primary) 30%, transparent);
  padding: 0.3rem 0.6rem;
  font-size: 0.72rem;
  font-weight: 650;
  color: var(--primary);
  transition: background 0.2s ease;
}

.fc-foot-link:hover {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

/* -- Venue & category intelligence section -- */

.vi-layout {
  display: grid;
  gap: 2rem;
  align-items: start;
}

@media (min-width: 1024px) {
  .vi-layout {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
    gap: 2.5rem 3.5rem;
  }

  .vi-stage {
    position: sticky;
    top: 6.5rem;
  }
}

.vi-copy {
  max-width: 40rem;
}

.vi-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.vi-title {
  margin-top: 1rem;
  font-size: clamp(1.875rem, 2.8vw, 2.5rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.vi-lead {
  margin-top: 1rem;
  max-width: 46ch;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.vi-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  margin: 1.5rem 0 0;
  padding: 0;
  list-style: none;
}

.vi-tile {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  border-radius: 0.85rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 60%, white);
  padding: 0.75rem 0.85rem;
}

.vi-tile-icon {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  margin-bottom: 0.25rem;
  border-radius: 0.55rem;
  background: var(--primary-soft);
  color: var(--primary);
}

.vi-tile strong {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--foreground);
}

.vi-tile span:last-child {
  font-size: 0.72rem;
  line-height: 1.45;
  color: var(--muted-foreground);
}

.vi-table-card {
  margin-top: 1.25rem;
  border-radius: 1rem;
  border: 1px solid var(--border);
  background: var(--card);
  overflow: hidden;
}

.vi-table-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border);
  padding: 0.85rem 1rem;
}

.vi-table-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.vi-table-head p {
  margin: 0;
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.vi-table-wrap {
  overflow-x: auto;
}

.vi-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.75rem;
}

.vi-table th,
.vi-table td {
  padding: 0.55rem 0.75rem;
  text-align: left;
  white-space: nowrap;
}

.vi-table th {
  border-bottom: 1px solid var(--border);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.vi-table td {
  border-bottom: 1px solid color-mix(in oklab, var(--border) 60%, transparent);
  color: var(--foreground);
}

.vi-table tbody tr {
  transition: background 0.3s ease;
}

.vi-table tbody tr[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
}

.vi-table tbody tr:last-child td {
  border-bottom: 0;
}

.vi-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  border: 1px solid var(--border);
  padding: 0.1rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.vi-pill[data-availability="available"] {
  border-color: color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--primary);
}

.vi-pill[data-availability="low"] {
  border-style: dashed;
  border-color: color-mix(in oklab, var(--primary) 30%, transparent);
  color: var(--primary-deep);
}

.vi-banner {
  display: grid;
  gap: 0.85rem;
  margin-top: 1.25rem;
  border-radius: 1rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  background: color-mix(in oklab, var(--primary) 4%, white);
  padding: 1rem;
}

.vi-checks {
  display: grid;
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 640px) {
  .vi-checks {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.vi-checks li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.4rem;
}

.vi-checks svg {
  margin-top: 0.15rem;
  color: var(--primary);
}

.vi-checks strong {
  display: block;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--foreground);
}

.vi-checks span {
  font-size: 0.7rem;
  line-height: 1.45;
  color: var(--muted-foreground);
}

.vi-banner-btn {
  justify-self: start;
  border-radius: 0.5rem;
  background: var(--primary);
  padding: 0.5rem 0.9rem;
  font-size: 0.78rem;
  font-weight: 650;
  color: var(--primary-foreground);
}

.vi-stage {
  min-width: 0;
}

/* -- Venue map console -- */

.vm-console .lc-screen {
  height: auto;
  min-height: 0;
  max-height: none;
}

.vm-console .lc-body {
  gap: 0.65rem;
}

.vm-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-shrink: 0;
}

.vm-head-copy {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.vm-head-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--foreground);
}

.vm-head-kicker svg {
  color: var(--primary);
}

.vm-head-demo {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.1rem 0.4rem;
  font-size: 8.5px;
  letter-spacing: 0.12em;
  color: var(--muted-foreground);
}

.vm-live {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

.vm-live-dot {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 16%, transparent);
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.vm-map-panel {
  flex: 1 1 auto;
  min-height: 0;
}

.vm-map {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  place-items: center;
}

.vm-map-svg {
  width: 100%;
  max-width: 22rem;
  height: auto;
  max-height: 100%;
}

.vm-map-pitch {
  fill: color-mix(in oklab, var(--primary) 8%, transparent);
  stroke: color-mix(in oklab, var(--primary) 22%, transparent);
  stroke-width: 0.8;
}

.vm-map-pitch-line {
  stroke: color-mix(in oklab, var(--primary) 26%, transparent);
  stroke-width: 0.6;
}

.vm-map-section {
  fill: color-mix(in oklab, var(--primary) calc(var(--vm-heat, 0.4) * 62%), white);
  stroke: color-mix(in oklab, var(--foreground) 10%, transparent);
  stroke-width: 0.6;
  transition:
    fill 0.3s ease,
    stroke 0.3s ease;
}

.vm-map-section[data-listed="true"] {
  stroke: color-mix(in oklab, var(--primary) 45%, transparent);
  stroke-width: 1;
}

.vm-map-section[data-active="true"] {
  fill: var(--primary);
  stroke: var(--primary-deep);
  stroke-width: 1.4;
  animation: vm-section-pulse 2.4s ease-in-out infinite;
}

@keyframes vm-section-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.vm-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 0.62rem;
  color: var(--muted-foreground);
}

.vm-legend li {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.vm-legend li::before {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 2px;
  background: color-mix(in oklab, var(--primary) 55%, white);
}

.vm-legend li[data-heat="mid"]::before {
  background: color-mix(in oklab, var(--primary) 32%, white);
}

.vm-legend li[data-heat="low"]::before {
  background: color-mix(in oklab, var(--primary) 14%, white);
}

.vm-legend li[data-heat="listed"]::before {
  background: transparent;
  border: 1px solid color-mix(in oklab, var(--primary) 55%, transparent);
}

.vm-readout-panel {
  flex-shrink: 0;
}

.vm-readout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
  margin: 0;
}

@container (min-width: 26rem) {
  .vm-readout {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

.vm-readout-field {
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  background: color-mix(in oklab, var(--background) 78%, white);
  padding: 0.35rem 0.45rem;
  min-width: 0;
}

.vm-readout-field dt {
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.vm-readout-field dd {
  margin: 0.1rem 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--foreground);
}

.vm-console[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 22s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .er-console[data-live="true"] .lc-feed-list,
  .ds-console[data-live="true"] .ds-feed-list,
  .fc-console[data-live="true"] .fc-log-list,
  .vm-console[data-live="true"] .lc-feed-list,
  .fc-status i,
  .fc-panel-dot,
  .vm-live-dot,
  .vm-map-section[data-active="true"] {
    animation: none;
  }

  .er-cal-day,
  .er-row,
  .er-meter-seg,
  .ds-comp-row,
  .ds-band,
  .ds-switch-btn,
  .fc-input,
  .fc-risk-row,
  .fc-risk-meter span,
  .fc-risk-track i,
  .fc-scenario,
  .vm-map-section,
  .vi-table tbody tr {
    transition: none;
  }

  .fc-scenario:hover {
    transform: none;
  }
}

/* Travel hero — partner desk dashboard (TravelPartnersHero right stage) */

.tpd-stage {
  position: relative;
  padding: 0.35rem 0.55rem 0.85rem;
}

.tpd-board {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 2.15rem minmax(0, 1fr);
  overflow: hidden;
  min-height: clamp(22rem, 52vh, 34rem);
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      color-mix(in oklab, var(--background) 3%, transparent)
    ),
    color-mix(in oklab, black 46%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-9deg) rotateX(4.5deg);
  transform-origin: 52% 46%;
  transform-style: preserve-3d;
}

.tpd-rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.45rem;
  padding: 0.7rem 0.28rem 0.65rem;
  border-right: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  background: color-mix(in oklab, black 22%, transparent);
}

.tpd-rail-btn {
  display: grid;
  place-items: center;
  width: 1.55rem;
  height: 1.55rem;
  border-radius: 0.45rem;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.tpd-rail-btn[data-active="true"] {
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 16%, transparent);
  box-shadow: 0 0 14px color-mix(in oklab, var(--primary) 28%, transparent);
}

.tpd-rail-foot {
  margin-top: auto;
}

.tpd-main {
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  gap: 0.55rem;
  min-width: 0;
  padding: 0.55rem 0.65rem 0.7rem;
}

.tpd-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  min-width: 0;
}

.tpd-brand {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}

.tpd-brand-mark {
  display: grid;
  place-items: center;
  width: 1.45rem;
  height: 1.45rem;
  flex-shrink: 0;
  border-radius: 0.4rem;
  background: color-mix(in oklab, var(--primary) 18%, transparent);
  color: var(--primary);
  box-shadow: 0 0 12px color-mix(in oklab, var(--primary) 30%, transparent);
}

.tpd-stage[data-live="true"] .tpd-brand-mark {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.tpd-brand-title {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--background);
}

.tpd-brand-path {
  margin: 0.08rem 0 0;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: lowercase;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.tpd-utils {
  display: flex;
  align-items: center;
  gap: 0.28rem;
  flex-shrink: 0;
}

.tpd-util,
.tpd-avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 1.45rem;
  border-radius: 999px;
  color: color-mix(in oklab, var(--background) 62%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
  border: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
}

.tpd-util {
  width: 1.45rem;
}

.tpd-util-dot {
  position: absolute;
  top: 0.18rem;
  right: 0.18rem;
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  background: oklch(0.68 0.18 25);
  box-shadow: 0 0 0 1.5px color-mix(in oklab, black 40%, var(--dark));
}

.tpd-avatar {
  gap: 0.12rem;
  width: auto;
  padding: 0 0.38rem 0 0.42rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 78%, var(--primary));
}

.tpd-kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.38rem;
}

.tpd-kpi {
  min-width: 0;
  padding: 0.42rem 0.4rem 0.45rem;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--background) 9%, transparent);
  background: color-mix(in oklab, var(--background) 5.5%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--background) 6%, transparent);
}

.tpd-kpi-label {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 46%, transparent);
}

.tpd-kpi-value {
  margin: 0.22rem 0 0;
  font-size: clamp(0.82rem, 1.5vw, 1.05rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1;
  color: var(--background);
}

.tpd-charts {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: 0.45rem;
  min-height: 0;
}

.tpd-panel,
.tpd-list,
.tpd-float {
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--background) 9%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
}

.tpd-chart {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  padding: 0.5rem 0.55rem 0.45rem;
}

.tpd-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.4rem;
  margin-bottom: 0.35rem;
}

.tpd-panel-title {
  margin: 0;
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: color-mix(in oklab, var(--background) 86%, transparent);
}

.tpd-panel-hint {
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 38%, transparent);
}

.tpd-week {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  align-items: end;
  gap: 0.28rem;
  flex: 1;
  min-height: 6.4rem;
}

.tpd-week-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 0.28rem;
  height: 100%;
}

.tpd-week-bar {
  display: flex;
  align-items: flex-end;
  width: 100%;
  max-width: 0.72rem;
  height: 100%;
}

.tpd-week-bar i {
  display: block;
  width: 100%;
  height: var(--tpd-h, 50%);
  border-radius: 0.28rem 0.28rem 0.12rem 0.12rem;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--primary) 92%, white),
    var(--primary)
  );
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 28%, transparent);
  transform-origin: bottom;
}

.tpd-stage[data-live="true"] .tpd-week-bar i,
.tpd-stage[data-live="true"] .tpd-status-bar i {
  animation: tpd-bar-grow 0.75s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: var(--tpd-delay, 0ms);
}

.tpd-week-day {
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.tpd-fill {
  display: grid;
  grid-template-columns: 1.35rem minmax(0, 1fr);
  gap: 0.2rem;
  flex: 1;
  min-height: 5.6rem;
}

.tpd-fill-y {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding-block: 0.15rem 0.35rem;
  font-family: var(--font-mono);
  font-size: 7.5px;
  font-weight: 600;
  color: color-mix(in oklab, var(--background) 34%, transparent);
}

.tpd-fill-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.tpd-fill-grid {
  stroke: color-mix(in oklab, var(--background) 10%, transparent);
  stroke-width: 1;
}

.tpd-fill-line {
  stroke: var(--primary);
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.tpd-fill-dot {
  fill: var(--primary);
  stroke: color-mix(in oklab, black 35%, var(--dark));
  stroke-width: 1.5;
}

.tpd-stage[data-live="true"] .tpd-fill-dot {
  animation: two-track-live-pulse 2.2s ease-in-out infinite;
}

.tpd-fill-x {
  display: flex;
  justify-content: space-between;
  padding-left: 1.55rem;
  margin-top: 0.12rem;
  font-family: var(--font-mono);
  font-size: 7.5px;
  font-weight: 600;
  color: color-mix(in oklab, var(--background) 34%, transparent);
}

.tpd-lists {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.42rem;
}

.tpd-list {
  min-width: 0;
  padding: 0.48rem 0.5rem 0.52rem;
}

.tpd-list .tpd-panel-title {
  margin-bottom: 0.38rem;
}

.tpd-meters {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.38rem;
}

.tpd-meter-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.35rem;
}

.tpd-meter-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.62rem;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.tpd-meter-row strong {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  color: color-mix(in oklab, var(--background) 82%, transparent);
}

.tpd-meter {
  margin-top: 0.18rem;
  height: 0.32rem;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 8%, transparent);
}

.tpd-meter i {
  display: block;
  height: 100%;
  width: var(--tpd-pct, 50%);
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 70%, transparent),
    var(--primary)
  );
  transform-origin: left center;
}

.tpd-stage[data-live="true"] .tpd-meter i {
  animation: tpd-meter-fill 0.85s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: var(--tpd-delay, 0ms);
}

.tpd-float {
  position: absolute;
  z-index: 4;
  padding: 0.7rem 0.75rem 0.72rem;
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 11%, transparent),
      color-mix(in oklab, var(--background) 6%, transparent)
    ),
    color-mix(in oklab, black 28%, var(--dark));
  border-color: color-mix(in oklab, var(--background) 14%, var(--primary) 12%);
  box-shadow:
    0 18px 40px color-mix(in oklab, black 46%, transparent),
    0 0 0 1px color-mix(in oklab, var(--primary) 10%, transparent);
  backdrop-filter: blur(16px);
}

.tpd-float-earn {
  left: -0.15rem;
  top: 34%;
  width: min(11.4rem, 46%);
  transform: rotateY(-11deg) rotateX(5deg) translateZ(40px);
}

.tpd-float-status {
  right: -0.05rem;
  top: 39%;
  width: min(10.6rem, 42%);
  transform: rotateY(-7deg) rotateX(3deg) translateZ(36px);
}

.tpd-float-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.68rem;
  font-weight: 600;
  color: color-mix(in oklab, var(--background) 78%, transparent);
}

.tpd-float-icon {
  display: grid;
  place-items: center;
  width: 1.45rem;
  height: 1.45rem;
  border-radius: 0.45rem;
  background: color-mix(in oklab, var(--primary) 18%, transparent);
  color: var(--primary);
}

.tpd-float-value {
  margin: 0.45rem 0 0;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
  color: var(--background);
}

.tpd-float-delta {
  display: flex;
  align-items: center;
  gap: 0.28rem;
  margin: 0.42rem 0 0;
  font-size: 0.68rem;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.tpd-float-delta svg,
.tpd-float-delta strong {
  color: var(--primary);
}

.tpd-float-status .tpd-panel-title {
  margin-bottom: 0.45rem;
}

.tpd-status-bars {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: 0.4rem;
  height: 4.4rem;
}

.tpd-status-bar {
  display: flex;
  align-items: flex-end;
  height: 100%;
}

.tpd-status-bar i {
  display: block;
  width: 100%;
  height: var(--tpd-h, 50%);
  border-radius: 0.28rem 0.28rem 0.1rem 0.1rem;
  transform-origin: bottom;
}

.tpd-status-bar[data-tone="ok"] i {
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 30%, transparent);
}

.tpd-status-bar[data-tone="warn"] i {
  background: oklch(0.78 0.12 85);
}

.tpd-status-bar[data-tone="muted"] i {
  background: color-mix(in oklab, var(--background) 38%, var(--primary));
}

.tpd-status-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.55rem;
  margin: 0.5rem 0 0;
  padding: 0;
  list-style: none;
}

.tpd-status-legend li {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  font-size: 0.58rem;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.tpd-status-legend li::before {
  content: "";
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: currentColor;
}

.tpd-status-legend li[data-tone="ok"]::before {
  background: var(--primary);
}

.tpd-status-legend li[data-tone="warn"]::before {
  background: oklch(0.78 0.12 85);
}

.tpd-status-legend li[data-tone="muted"]::before {
  background: color-mix(in oklab, var(--background) 38%, var(--primary));
}

@keyframes tpd-bar-grow {
  from {
    transform: scaleY(0.12);
  }
  to {
    transform: scaleY(1);
  }
}

@keyframes tpd-meter-fill {
  from {
    transform: scaleX(0.12);
  }
  to {
    transform: scaleX(1);
  }
}

@media (min-width: 1024px) {
  .tpd-stage {
    padding: 0.15rem 0.2rem 0.4rem 0;
  }

  .tpd-float-earn {
    left: -1.15rem;
    top: 33%;
  }

  .tpd-float-status {
    right: -0.85rem;
    top: 38%;
  }
}

@media (max-width: 1023px) {
  .tpd-stage {
    overflow: hidden;
    width: 100%;
    max-width: 100%;
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
  }

  .tpd-board {
    min-height: 0;
    height: 100%;
    max-height: 100%;
    overflow: hidden;
    transform: rotateY(-6deg) rotateX(3deg);
  }
}

@media (max-width: 639px) {
  .tpd-stage {
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    padding: 0;
  }

  .tpd-board {
    grid-template-columns: minmax(0, 1fr);
    transform: none;
  }

  .tpd-rail,
  .tpd-utils,
  .tpd-lists,
  .tpd-float {
    display: none;
  }

  .tpd-main {
    gap: 0.4rem;
    padding: 0.45rem 0.5rem 0.5rem;
    min-width: 0;
  }

  .tpd-brand-path {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .tpd-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .tpd-kpi-value {
    overflow-wrap: anywhere;
  }

  .tpd-charts {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .tpd-fill {
    min-height: 3.4rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tpd-board,
  .tpd-float,
  .tpd-float-earn,
  .tpd-float-status {
    transform: none;
  }

  .tpd-stage[data-live="true"] .tpd-brand-mark,
  .tpd-stage[data-live="true"] .tpd-fill-dot,
  .tpd-stage[data-live="true"] .tpd-week-bar i,
  .tpd-stage[data-live="true"] .tpd-status-bar i,
  .tpd-stage[data-live="true"] .tpd-meter i {
    animation: none;
  }
}

/* Marketplace hero — channel operations mosaic (MarketplaceHero right stage) */

.mkh-stage {
  position: relative;
  padding: 0.2rem 0.15rem 0.35rem;
}

.mkh-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  gap: 0.4rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.58rem 0.7rem 0.62rem;
  overflow: hidden;
  container: mkh / size;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--background) 9%, transparent),
      transparent 46%
    ),
    color-mix(in oklab, black 48%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
}

.mkh-room::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: radial-gradient(
    circle,
    color-mix(in oklab, var(--primary) 28%, transparent) 0.65px,
    transparent 0.7px
  );
  background-size: 13px 13px;
  opacity: 0.28;
  z-index: 0;
}

.mkh-head,
.mkh-body,
.mkh-timeline,
.mkh-align {
  position: relative;
  z-index: 1;
}

.mkh-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.mkh-head-copy {
  min-width: 0;
}

.mkh-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.mkh-head-meta {
  margin: 0.18rem 0 0;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.02em;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.mkh-live {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  flex-shrink: 0;
  padding: 0.22rem 0.5rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.mkh-live-dot {
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 8px color-mix(in oklab, var(--primary) 55%, transparent);
}

.mkh-stage[data-live="true"] .mkh-live-dot {
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.mkh-body {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.18fr);
  gap: 0.4rem;
  min-height: 0;
  overflow: hidden;
}

.mkh-fan {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.mkh-origin {
  position: relative;
  z-index: 2;
  padding: 0.4rem 0.5rem 0.38rem;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--primary) 32%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--primary) 14%, transparent),
      color-mix(in oklab, black 28%, transparent)
    );
  box-shadow: 0 10px 24px color-mix(in oklab, black 28%, transparent);
  transform: rotate(-1.6deg);
}

.mkh-origin-id {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.mkh-origin-event {
  margin: 0.22rem 0 0;
  font-size: 0.78rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--background);
}

.mkh-origin-section {
  margin: 0.08rem 0 0;
  font-size: 0.62rem;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.mkh-origin-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.28rem;
  margin: 0.32rem 0 0;
}

.mkh-origin-stats div {
  min-width: 0;
}

.mkh-origin-stats dt {
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.mkh-origin-stats dd {
  margin: 0.08rem 0 0;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--background);
}

.mkh-fan-svg {
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.mkh-fan-path {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 28%, transparent);
  stroke-width: 1.15;
  stroke-dasharray: 3 5;
  stroke-linecap: round;
}

.mkh-fan-path[data-active="true"] {
  stroke: color-mix(in oklab, var(--primary) 78%, transparent);
  stroke-width: 1.45;
}

.mkh-stage[data-live="true"] .mkh-fan-path {
  animation: mkh-dash 2.4s linear infinite;
}

.mkh-fan-packet {
  fill: var(--primary);
  opacity: 0.35;
}

.mkh-fan-packet[data-active="true"] {
  opacity: 1;
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 70%, transparent));
}

.mkh-fan-hub {
  fill: var(--primary);
}

.mkh-fan-ring {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 55%, transparent);
  stroke-width: 1.1;
  transform-box: fill-box;
  transform-origin: center;
}

.mkh-stage[data-live="true"] .mkh-fan-ring {
  animation: mkh-ring 2.2s ease-out infinite;
}

.mkh-mosaic {
  position: relative;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.mkh-tile {
  position: absolute;
  width: 51%;
  padding: 0.36rem 0.42rem 0.32rem;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, black 38%, var(--dark));
  box-shadow: 0 12px 28px color-mix(in oklab, black 32%, transparent);
  backdrop-filter: blur(8px);
}

.mkh-tile:nth-child(1) {
  top: 0;
  left: 0;
  z-index: 3;
  transform: rotate(-3.4deg);
}

.mkh-tile:nth-child(2) {
  top: 0.2rem;
  left: 49%;
  z-index: 4;
  transform: rotate(2.8deg);
}

.mkh-tile:nth-child(3) {
  top: 33%;
  left: 3%;
  z-index: 5;
  transform: rotate(1.7deg);
}

.mkh-tile:nth-child(4) {
  top: 31%;
  left: 48%;
  z-index: 2;
  transform: rotate(-2.2deg);
}

.mkh-tile:nth-child(5) {
  top: 65%;
  left: -1%;
  z-index: 6;
  transform: rotate(2.4deg);
}

.mkh-tile:nth-child(6) {
  top: 63%;
  left: 50%;
  z-index: 7;
  transform: rotate(-1.5deg);
}

.mkh-tile[data-status="synced"] {
  border-color: color-mix(in oklab, var(--primary) 22%, transparent);
}

.mkh-tile[data-status="lagging"] {
  border-color: color-mix(in oklab, oklch(0.74 0.14 70) 42%, transparent);
}

.mkh-tile[data-status="conflict"] {
  border-color: color-mix(in oklab, var(--destructive) 45%, transparent);
}

.mkh-tile[data-active="true"] {
  z-index: 8;
  border-color: color-mix(in oklab, var(--primary) 55%, transparent);
  box-shadow:
    0 16px 32px color-mix(in oklab, black 36%, transparent),
    0 0 0 1px color-mix(in oklab, var(--primary) 28%, transparent);
}

.mkh-tile-head {
  display: flex;
  align-items: center;
  gap: 0.32rem;
}

.mkh-tile-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 7px color-mix(in oklab, var(--primary) 50%, transparent);
}

.mkh-tile[data-status="lagging"] .mkh-tile-dot {
  background: oklch(0.74 0.14 70);
  box-shadow: 0 0 7px color-mix(in oklab, oklch(0.74 0.14 70) 50%, transparent);
}

.mkh-tile[data-status="conflict"] .mkh-tile-dot {
  background: var(--destructive);
  box-shadow: 0 0 7px color-mix(in oklab, var(--destructive) 45%, transparent);
}

.mkh-stage[data-live="true"] .mkh-tile[data-active="true"] .mkh-tile-dot {
  animation: two-track-live-pulse 1.6s ease-in-out infinite;
}

.mkh-tile-code {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: color-mix(in oklab, var(--background) 78%, transparent);
}

.mkh-tile-state {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.mkh-tile[data-status="lagging"] .mkh-tile-state {
  color: oklch(0.78 0.12 70);
}

.mkh-tile[data-status="conflict"] .mkh-tile-state {
  color: color-mix(in oklab, var(--destructive) 85%, var(--background));
}

.mkh-tile-name {
  margin: 0.16rem 0 0;
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  color: var(--background);
}

.mkh-pips {
  display: grid;
  grid-template-columns: repeat(6, 0.36rem);
  gap: 0.14rem;
  margin-top: 0.26rem;
}

.mkh-pips i {
  width: 0.36rem;
  height: 0.36rem;
  border-radius: 1px;
  background: color-mix(in oklab, var(--background) 12%, transparent);
}

.mkh-pips i[data-on="true"] {
  background: color-mix(in oklab, var(--primary) 78%, var(--background));
  box-shadow: 0 0 5px color-mix(in oklab, var(--primary) 35%, transparent);
}

.mkh-tile-foot {
  display: flex;
  justify-content: space-between;
  gap: 0.4rem;
  margin-top: 0.22rem;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.02em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.mkh-timeline {
  padding: 0.32rem 0.45rem 0.28rem;
  max-height: 5.1rem;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 9%, transparent);
  background: color-mix(in oklab, black 22%, transparent);
}

.mkh-panel-label {
  margin: 0 0 0.22rem;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.mkh-ticks {
  position: relative;
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
}

.mkh-ticks::before {
  content: "";
  position: absolute;
  left: 6%;
  right: 6%;
  top: 1.05rem;
  height: 1px;
  background: color-mix(in oklab, var(--primary) 28%, transparent);
}

.mkh-ticks li {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 0.14rem;
  min-width: 0;
}

.mkh-tick-time {
  font-family: var(--font-mono);
  font-size: 0.48rem;
  letter-spacing: 0.02em;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.mkh-tick-node {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 28%, transparent);
  box-shadow: 0 0 0 3px color-mix(in oklab, black 35%, var(--dark));
}

.mkh-ticks li[data-active="true"] .mkh-tick-node {
  background: var(--primary);
  box-shadow:
    0 0 0 3px color-mix(in oklab, black 35%, var(--dark)),
    0 0 8px color-mix(in oklab, var(--primary) 55%, transparent);
}

.mkh-stage[data-live="true"] .mkh-ticks li[data-active="true"] .mkh-tick-node {
  animation: two-track-live-pulse 1.6s ease-in-out infinite;
}

.mkh-tick-event {
  max-width: 100%;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.mkh-ticks li[data-active="true"] .mkh-tick-event {
  color: var(--primary);
}

.mkh-align {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: 0.4rem;
  min-height: 0;
  max-height: 7.4rem;
  overflow: hidden;
}

.mkh-compare {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: stretch;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, black 24%, transparent);
}

.mkh-compare-side {
  display: grid;
  gap: 0.06rem;
  padding: 0.38rem 0.5rem 0.36rem;
}

.mkh-compare-side[data-side="floor"] {
  text-align: right;
  background: color-mix(in oklab, var(--background) 4%, transparent);
}

.mkh-compare-label,
.mkh-compare-hint {
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.mkh-compare-value {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.04em;
  color: var(--background);
}

.mkh-compare-spread {
  display: grid;
  place-content: center;
  gap: 0.08rem;
  padding: 0 0.35rem;
  border-inline: 1px dashed color-mix(in oklab, var(--primary) 32%, transparent);
  text-align: center;
}

.mkh-compare-spread span {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--primary);
}

.mkh-compare-spread em {
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-style: normal;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.mkh-queue {
  display: grid;
  gap: 0.18rem;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
  list-style: none;
}

.mkh-queue li {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.32rem;
  min-width: 0;
  padding: 0.22rem 0.4rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  background: color-mix(in oklab, black 22%, transparent);
}

.mkh-queue-pip {
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: var(--primary);
}

.mkh-queue li[data-state="lagging"] .mkh-queue-pip {
  background: oklch(0.74 0.14 70);
}

.mkh-queue li[data-state="conflict"] .mkh-queue-pip {
  background: var(--destructive);
}

.mkh-queue li[data-state="queued"] .mkh-queue-pip {
  background: color-mix(in oklab, var(--background) 38%, transparent);
}

.mkh-queue-code {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.mkh-queue-name {
  overflow: hidden;
  font-size: 0.62rem;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.mkh-queue-issue {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 650;
  letter-spacing: 0.02em;
  color: var(--primary);
}

.mkh-queue li[data-state="lagging"] .mkh-queue-issue,
.mkh-queue li[data-state="conflict"] .mkh-queue-issue {
  color: oklch(0.78 0.12 70);
}

@keyframes mkh-dash {
  to {
    stroke-dashoffset: -32;
  }
}

@keyframes mkh-ring {
  0% {
    opacity: 0.85;
    transform: scale(0.86);
  }
  100% {
    opacity: 0;
    transform: scale(1.55);
  }
}

@container mkh (max-height: 26rem) {
  .mkh-head-meta {
    display: none;
  }

  .mkh-origin-section {
    display: none;
  }

  .mkh-pips {
    margin-top: 0.16rem;
  }

  .mkh-tile-foot {
    display: none;
  }

  .mkh-timeline {
    max-height: 4.4rem;
  }

  .mkh-align {
    max-height: 6.2rem;
  }

  .mkh-compare-value {
    font-size: 0.88rem;
  }
}

@container mkh (max-height: 20rem) {
  .mkh-origin-stats {
    display: none;
  }

  .mkh-tile-name {
    font-size: 0.62rem;
  }

  .mkh-queue li:last-child {
    display: none;
  }
}

@media (min-width: 1024px) {
  .mkh-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }
}

@media (max-width: 1023px) {
  .mkh-stage {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    overflow-x: clip;
    overflow-y: visible;
    padding: 0;
  }

  .mkh-room {
    height: auto;
    max-height: none;
    min-height: 0;
    grid-template-rows: none;
    gap: 0.5rem;
    transform: rotateY(-5deg) rotateX(2.5deg);
    overflow: hidden;
    /* size containment + height:auto collapses the content box to 0, so
       CHANNEL MESH / LIVE sit on a zero-height row and clip at the top. */
    container: mkh / inline-size;
    padding-top: 0.7rem;
  }

  .mkh-head {
    align-items: center;
    flex-shrink: 0;
    min-height: 2.25rem;
    padding-block: 0.18rem;
    overflow: visible;
  }

  .mkh-kicker {
    line-height: 1.35;
    overflow: visible;
  }

  .mkh-kicker svg {
    flex-shrink: 0;
    overflow: visible;
  }

  .mkh-live {
    align-items: center;
    padding: 0.28rem 0.55rem;
    line-height: 1.25;
  }

  .mkh-head-meta {
    display: none;
  }

  .mkh-head,
  .mkh-head-copy,
  .mkh-origin,
  .mkh-tile,
  .mkh-queue,
  .mkh-compare {
    min-width: 0;
  }

  .mkh-body,
  .mkh-align {
    grid-template-columns: minmax(0, 1fr);
    max-height: none;
    overflow: visible;
  }

  .mkh-fan {
    min-height: 0;
    height: auto;
    overflow: visible;
  }

  .mkh-fan-svg {
    display: none;
  }

  .mkh-origin {
    transform: none;
  }

  .mkh-timeline,
  .mkh-align {
    max-height: none;
    overflow: visible;
  }

  .mkh-mosaic {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
    min-height: 0;
    height: auto;
    overflow: visible;
  }

  .mkh-tile,
  .mkh-tile:nth-child(n) {
    position: relative;
    top: auto;
    left: auto;
    width: auto;
    transform: none;
  }

  .mkh-head-meta,
  .mkh-tile-name,
  .mkh-queue-name,
  .mkh-queue-issue,
  .mkh-tick-event {
    overflow-wrap: anywhere;
  }
}

@media (max-width: 639px) {
  .mkh-room {
    transform: none;
    gap: 0.55rem;
    padding: 0.85rem 0.75rem 0.85rem;
  }

  .mkh-head {
    flex-wrap: wrap;
    align-items: center;
    min-height: 2.5rem;
    padding-block: 0.22rem 0.12rem;
    row-gap: 0.3rem;
    overflow: visible;
  }

  .mkh-kicker {
    font-size: 0.68rem;
    line-height: 1.4;
    letter-spacing: 0.1em;
  }

  .mkh-live {
    padding: 0.32rem 0.58rem;
    font-size: 0.62rem;
    line-height: 1.25;
  }

  .mkh-ticks {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.45rem 0;
  }

  .mkh-ticks li:nth-child(n + 5) {
    display: none;
  }

  .mkh-compare-value {
    font-size: 0.88rem;
  }

  .mkh-queue li {
    grid-template-columns: auto auto minmax(0, 1fr);
  }

  .mkh-queue-issue {
    grid-column: 2 / -1;
    padding-left: 0.05rem;
    white-space: normal;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mkh-room,
  .mkh-origin,
  .mkh-tile,
  .mkh-tile:nth-child(n) {
    transform: none;
  }

  .mkh-stage[data-live="true"] .mkh-live-dot,
  .mkh-stage[data-live="true"] .mkh-fan-path,
  .mkh-stage[data-live="true"] .mkh-fan-ring,
  .mkh-stage[data-live="true"] .mkh-tile[data-active="true"] .mkh-tile-dot,
  .mkh-stage[data-live="true"] .mkh-ticks li[data-active="true"] .mkh-tick-node {
    animation: none;
  }

  .mkh-fan-packet {
    display: none;
  }
}

/* ── WorkflowInfraCanvas glass + hover two-shade overlay (wic-glass-*) ──
   Idle: glass surface only (no orbs). Hover: two static corner blobs —
   gray top-left, pale teal bottom-right — clipped, copy stays clear. */

.ws-flow-card-outer.wic-glass-host {
  overflow: hidden;
  border-radius: 10px;
  padding: 0;
  background: none;
  box-shadow: 0 4px 30px color-mix(in oklab, var(--foreground) 10%, transparent);
  transition: box-shadow 0.3s ease;
}

.ws-flow-card-outer.wic-glass-host:hover {
  box-shadow:
    0 8px 32px color-mix(in oklab, var(--primary) 36%, transparent),
    0 0 24px color-mix(in oklab, var(--primary) 16%, transparent);
}

.ws-flow-card.wic-glass {
  overflow: hidden;
  isolation: isolate;
  border-radius: 10px;
  border: 1px solid color-mix(in oklab, white 42%, transparent);
  background: color-mix(in oklab, var(--card) 55%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, white 32%, transparent);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  transition:
    border-color 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}

.ws-flow-card-outer.wic-glass-host:hover .ws-flow-card.wic-glass {
  border-color: color-mix(in oklab, white 52%, var(--primary) 10%);
  background: color-mix(in oklab, var(--card) 46%, transparent);
}

.ws-flow-card.wic-glass > :not(.ws-flow-card-line):not(.ws-flow-card-ray):not(.wic-glass-shade) {
  position: relative;
  z-index: 2;
}

.ws-flow-card.wic-glass .ws-flow-card-line {
  z-index: 2;
}

.ws-flow-card.wic-glass .ws-flow-card-ray {
  display: none;
}

.wic-glass-shade {
  position: absolute;
  z-index: 0;
  width: 8.25rem;
  height: 6.75rem;
  pointer-events: none;
  border-radius: 3rem;
  opacity: 0;
  transform: rotate(25deg);
  transition: opacity 0.28s ease;
}

.wic-glass-shade-back {
  z-index: 0;
  top: auto;
  left: auto;
  right: -2.85rem;
  bottom: -2.6rem;
  background: #4be5ae59;
}

.wic-glass-shade-front {
  z-index: 1;
  top: -2.6rem;
  left: -2.85rem;
  right: auto;
  bottom: auto;
  background: color-mix(in oklab, #d1d5db 68%, transparent);
}

.ws-flow-card-outer.wic-glass-host:hover .wic-glass-shade {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .wic-glass-shade {
    transition: none;
  }
}

/* Event intelligence hero — AI forecast lens (EventIntelHero right stage)
   Prefix: eih-*  Distinct from tpd-* (partner desk), mkh-* (channel mosaic),
   wic-glass-* (workflow canvas), and fc-* (below-the-fold forecast console). */

.eih-stage {
  position: relative;
  padding: 0.2rem 0.15rem 0.35rem;
}

.eih-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0.42rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.58rem 0.68rem 0.6rem;
  overflow: hidden;
  container: eih / size;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 42%
    ),
    color-mix(in oklab, black 50%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
}

.eih-room::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image:
    linear-gradient(
      color-mix(in oklab, var(--primary) 16%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      color-mix(in oklab, var(--primary) 16%, transparent) 1px,
      transparent 1px
    );
  background-size: 22px 22px;
  mask-image: radial-gradient(ellipse at 62% 48%, black 18%, transparent 78%);
  -webkit-mask-image: radial-gradient(ellipse at 62% 48%, black 18%, transparent 78%);
  opacity: 0.34;
  z-index: 0;
}

.eih-scan,
.eih-node,
.eih-head,
.eih-body,
.eih-foot {
  position: relative;
  z-index: 1;
}

.eih-scan {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 2;
  overflow: hidden;
  border-radius: inherit;
}

.eih-scan::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 18%;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 18%, transparent),
    transparent
  );
  opacity: 0;
}

.eih-stage[data-live="true"] .eih-scan::after {
  animation: eih-scan 5.6s linear infinite;
}

.eih-node {
  pointer-events: none;
  position: absolute;
  z-index: 0;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 70%, white);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 45%, transparent);
  opacity: 0.45;
}

.eih-node-a {
  top: 22%;
  right: 18%;
}

.eih-node-b {
  top: 58%;
  right: 8%;
}

.eih-node-c {
  bottom: 28%;
  left: 38%;
}

.eih-stage[data-live="true"] .eih-node {
  animation: eih-node 3.4s ease-in-out infinite;
}

.eih-stage[data-live="true"] .eih-node-b {
  animation-delay: 1.1s;
}

.eih-stage[data-live="true"] .eih-node-c {
  animation-delay: 2s;
}

.eih-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem;
  min-width: 0;
}

.eih-head-copy {
  min-width: 0;
}

.eih-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.eih-event {
  margin: 0.16rem 0 0;
  font-family: var(--font-display);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--background);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.eih-event span {
  display: block;
  margin-top: 0.08rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.eih-head-meta {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.eih-horizon {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.eih-live {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.2rem 0.48rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  font-family: var(--font-mono);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.eih-live-dot {
  width: 0.36rem;
  height: 0.36rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 8px color-mix(in oklab, var(--primary) 55%, transparent);
}

.eih-stage[data-live="true"] .eih-live-dot {
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.eih-body {
  display: grid;
  grid-template-columns: 6.35rem minmax(0, 1fr);
  gap: 0.5rem;
  min-height: 0;
  overflow: hidden;
}

.eih-models {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.22rem;
  min-height: 0;
  margin: 0;
  padding: 0.1rem 0 0.1rem 0.15rem;
  list-style: none;
}

.eih-bus {
  position: absolute;
  top: 0.85rem;
  bottom: 0.85rem;
  left: 0.72rem;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 45%, transparent) 18%,
    color-mix(in oklab, var(--primary) 45%, transparent) 82%,
    transparent
  );
  opacity: 0.7;
}

.eih-models li {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.05rem minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 0.32rem;
  align-items: center;
  min-width: 0;
  padding: 0.18rem 0.22rem 0.18rem 0;
  border-radius: 0.45rem;
  transition:
    background 0.35s ease,
    box-shadow 0.35s ease;
}

.eih-models li[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.eih-model-dot {
  grid-row: 1 / span 2;
  display: grid;
  place-items: center;
  width: 1.05rem;
  height: 1.05rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, black 35%, var(--dark));
  color: color-mix(in oklab, var(--background) 70%, var(--primary));
}

.eih-models li[data-active="true"] .eih-model-dot {
  border-color: var(--primary);
  color: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 40%, transparent);
}

.eih-model-copy {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem;
  min-width: 0;
}

.eih-model-copy em {
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.eih-model-copy strong {
  font-size: 0.68rem;
  color: var(--background);
}

.eih-model-age {
  grid-column: 2;
  font-size: 0.52rem;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.eih-field {
  position: relative;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  background: color-mix(in oklab, black 28%, transparent);
}

.eih-cone {
  width: 100%;
  height: 100%;
  min-height: 0;
  display: block;
}

.eih-gridline {
  stroke: color-mix(in oklab, var(--background) 12%, transparent);
  stroke-width: 1;
}

.eih-band {
  opacity: 0.95;
}

.eih-stage[data-live="true"] .eih-band,
.eih-stage[data-live="true"] .eih-band-inner {
  animation: eih-breathe 4.2s ease-in-out infinite;
}

.eih-mesh {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 28%, transparent);
  stroke-width: 0.8;
}

.eih-mesh-outer {
  stroke: color-mix(in oklab, var(--primary) 55%, transparent);
  stroke-width: 1.15;
}

.eih-hist {
  fill: none;
  stroke: color-mix(in oklab, var(--background) 55%, transparent);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.eih-median {
  fill: none;
  stroke: var(--primary);
  stroke-width: 1.85;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 45%, transparent));
}

.eih-now-line {
  stroke: color-mix(in oklab, var(--background) 42%, transparent);
  stroke-width: 1;
  stroke-dasharray: 2.5 3;
}

.eih-now-dot {
  fill: var(--primary);
}

.eih-now-ring {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 55%, transparent);
  stroke-width: 1;
  transform-box: fill-box;
  transform-origin: center;
}

.eih-stage[data-live="true"] .eih-now-ring {
  animation: eih-now 2.4s ease-out infinite;
}

.eih-axis {
  display: flex;
  justify-content: space-between;
  padding: 0 0.45rem 0.28rem 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.eih-bands {
  pointer-events: none;
  position: absolute;
  top: 0.35rem;
  right: 0.4rem;
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.eih-bands li {
  display: flex;
  align-items: baseline;
  gap: 0.32rem;
}

.eih-bands em {
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.eih-bands strong {
  font-size: 0.62rem;
  color: var(--background);
}

.eih-bands li[data-band="p50"] strong {
  color: var(--primary);
}

.eih-ask {
  position: absolute;
  left: 0.45rem;
  top: 0.35rem;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}

.eih-ask span {
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 46%, transparent);
}

.eih-ask strong {
  font-size: 0.82rem;
  color: var(--background);
}

.eih-ring {
  position: absolute;
  right: 0.28rem;
  bottom: 1.15rem;
  width: 4.55rem;
  height: 4.55rem;
}

.eih-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.eih-ring-track {
  fill: none;
  stroke: color-mix(in oklab, var(--background) 14%, transparent);
  stroke-width: 3.4;
}

.eih-ring-value {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3.4;
  stroke-linecap: round;
  stroke-dashoffset: 40;
}

.eih-stage[data-live="true"] .eih-ring-value {
  animation: eih-ring 1.6s ease-out forwards;
}

.eih-ring-copy {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.02rem;
  pointer-events: none;
}

.eih-ring-copy strong {
  font-size: 0.72rem;
  color: var(--background);
  line-height: 1;
}

.eih-ring-copy span {
  font-family: var(--font-mono);
  font-size: 0.46rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 50%, transparent);
}

.eih-risk {
  position: absolute;
  left: 50%;
  top: calc(100% - 0.12rem);
  transform: translateX(-50%);
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.02rem;
  font-family: var(--font-mono);
  font-size: 0.48rem;
  letter-spacing: 0.04em;
  white-space: nowrap;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.eih-risk em {
  font-style: normal;
  font-weight: 700;
  color: var(--primary);
}

.eih-foot {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: 0.45rem;
  min-width: 0;
  align-items: stretch;
}

.eih-comps,
.eih-scenarios {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
  min-width: 0;
}

.eih-comps {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.32rem;
}

.eih-comps li {
  display: grid;
  gap: 0.04rem;
  min-width: 0;
  padding: 0.28rem 0.38rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
  transition:
    border-color 0.35s ease,
    background 0.35s ease;
}

.eih-comps li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 42%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.eih-comp-match {
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--primary);
}

.eih-comp-name,
.eih-comp-out {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eih-comp-name {
  font-size: 0.58rem;
  font-weight: 600;
  color: var(--background);
}

.eih-comp-out {
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.eih-scenarios {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  overflow: hidden;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
}

.eih-scenarios li {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.04rem;
  min-width: 0;
  padding: 0.28rem 0.4rem;
  border-right: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  transition:
    background 0.35s ease,
    color 0.35s ease;
}

.eih-scenarios li:last-child {
  border-right: 0;
}

.eih-scenarios li span {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.eih-scenarios li em {
  font-style: normal;
  font-size: 0.5rem;
  color: color-mix(in oklab, var(--background) 42%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eih-scenarios li[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 16%, transparent);
}

.eih-scenarios li[data-active="true"] span {
  color: var(--primary);
}

@keyframes eih-scan {
  0% {
    top: -18%;
    opacity: 0;
  }
  12% {
    opacity: 0.85;
  }
  88% {
    opacity: 0.55;
  }
  100% {
    top: 100%;
    opacity: 0;
  }
}

@keyframes eih-node {
  0%,
  100% {
    opacity: 0.28;
    transform: scale(1);
  }
  50% {
    opacity: 0.7;
    transform: scale(1.35);
  }
}

@keyframes eih-breathe {
  0%,
  100% {
    opacity: 0.82;
  }
  50% {
    opacity: 1;
  }
}

@keyframes eih-now {
  0% {
    opacity: 0.7;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(2.4);
  }
}

@keyframes eih-ring {
  from {
    stroke-dashoffset: 170;
  }
  to {
    stroke-dashoffset: 0;
  }
}

@container eih (max-height: 24rem) {
  .eih-comp-out,
  .eih-scenarios li em,
  .eih-risk,
  .eih-ask span {
    display: none;
  }

  .eih-ring {
    width: 3.9rem;
    height: 3.9rem;
    bottom: 0.95rem;
  }
}

@container eih (max-height: 20rem) {
  .eih-event span,
  .eih-bands,
  .eih-ask {
    display: none;
  }

  .eih-comps {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@container eih (max-width: 28rem) {
  .eih-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 0.32rem;
  }

  .eih-models {
    flex-direction: row;
    justify-content: space-between;
    padding: 0;
    gap: 0.25rem;
  }

  .eih-bus {
    display: none;
  }

  .eih-models li {
    flex: 1;
    grid-template-columns: auto minmax(0, 1fr);
    padding: 0.1rem 0.15rem;
  }

  .eih-foot {
    grid-template-columns: 1fr;
    gap: 0.32rem;
  }
}

@media (min-width: 1024px) {
  .eih-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }
}

@media (max-width: 1023px) {
  .eih-room {
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
    transform: rotateY(-5deg) rotateX(2.5deg);
  }
}

@media (max-width: 639px) {
  .eih-room {
    transform: none;
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    gap: 0.32rem;
    padding: 0.55rem 0.6rem 0.5rem;
  }

  .eih-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .eih-models {
    flex-direction: row;
    padding: 0;
  }

  .eih-bus,
  .eih-model-age,
  .eih-comp-out,
  .eih-scenarios li em,
  .eih-event span,
  .eih-risk {
    display: none;
  }

  .eih-foot {
    grid-template-columns: 1fr;
  }

  .eih-ring {
    width: 3.6rem;
    height: 3.6rem;
    bottom: 0.85rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .eih-room {
    transform: none;
  }

  .eih-stage[data-live="true"] .eih-scan::after,
  .eih-stage[data-live="true"] .eih-node,
  .eih-stage[data-live="true"] .eih-live-dot,
  .eih-stage[data-live="true"] .eih-band,
  .eih-stage[data-live="true"] .eih-band-inner,
  .eih-stage[data-live="true"] .eih-now-ring,
  .eih-stage[data-live="true"] .eih-ring-value {
    animation: none;
  }

  .eih-scan {
    display: none;
  }
}

/* ── API page ─────────────────────────────────────────────────────
   Hero docs console: apidoc-*
   Auth flow console: apk-*
   Webhook delivery console: whk-*
   Distinct from tpd-* (partner desk), mkh-* (channel mosaic),
   eih-* (forecast lens), and wic-glass-* (workflow canvas). */

.apidoc-stage {
  position: relative;
  padding: 0.2rem 0.15rem 0.35rem;
}

.apidoc-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0.38rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.55rem 0.62rem 0.52rem;
  overflow: hidden;
  container: apidoc / size;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 40%
    ),
    color-mix(in oklab, black 56%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
  font-family: var(--font-mono);
}

.apidoc-room::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 17px,
    color-mix(in oklab, var(--background) 5%, transparent) 18px
  );
  opacity: 0.55;
  z-index: 0;
  mask-image: linear-gradient(90deg, transparent 0%, black 22%, black 100%);
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, black 22%, black 100%);
}

.apidoc-head,
.apidoc-body,
.apidoc-foot {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.apidoc-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-shrink: 0;
}

.apidoc-head-copy {
  min-width: 0;
}

.apidoc-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.apidoc-product {
  margin: 0.12rem 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.78rem;
  font-weight: 650;
  letter-spacing: 0.01em;
  color: var(--background);
}

.apidoc-head-meta {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.apidoc-status {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 45%, transparent);
  background: color-mix(in oklab, var(--primary) 16%, transparent);
  padding: 0.12rem 0.45rem;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.apidoc-live {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: color-mix(in oklab, var(--background) 78%, transparent);
}

.apidoc-live-dot {
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
}

.apidoc-stage[data-live="true"] .apidoc-live-dot {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.apidoc-body {
  display: grid;
  grid-template-columns: 6.6rem minmax(0, 1fr);
  gap: 0.42rem;
  min-height: 0;
}

.apidoc-nav {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-height: 0;
  overflow: hidden;
}

.apidoc-nav-item {
  display: grid;
  grid-template-columns: 2.1rem minmax(0, 1fr);
  align-items: center;
  gap: 0.28rem;
  border-radius: 0.4rem;
  border: 1px solid transparent;
  padding: 0.18rem 0.28rem;
  min-width: 0;
}

.apidoc-nav-item[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.apidoc-nav-method {
  font-size: 0.48rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.apidoc-nav-item[data-method="GET"] .apidoc-nav-method,
.apidoc-nav-item[data-active="true"] .apidoc-nav-method {
  color: var(--primary);
}

.apidoc-nav-item[data-method="POST"] .apidoc-nav-method {
  color: color-mix(in oklab, var(--background) 70%, var(--primary));
}

.apidoc-nav-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.apidoc-nav-item[data-active="true"] .apidoc-nav-label {
  color: var(--background);
}

.apidoc-pane {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 0.32rem;
  min-width: 0;
  min-height: 0;
}

.apidoc-request {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.32rem;
  min-width: 0;
}

.apidoc-method {
  flex-shrink: 0;
  border-radius: 0.28rem;
  border: 1px solid color-mix(in oklab, var(--primary) 45%, transparent);
  padding: 0.1rem 0.38rem;
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.apidoc-method[data-method="POST"] {
  background: color-mix(in oklab, var(--primary) 22%, transparent);
}

.apidoc-path {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.68rem;
  font-weight: 600;
  color: var(--background);
}

.apidoc-keychip {
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--background) 14%, transparent);
  background: color-mix(in oklab, black 28%, transparent);
  padding: 0.1rem 0.42rem;
  font-size: 0.52rem;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.apidoc-params {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.22rem 0.45rem;
  margin: 0;
}

.apidoc-params > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.35rem;
  border-bottom: 1px dashed color-mix(in oklab, var(--background) 12%, transparent);
  padding-bottom: 0.12rem;
}

.apidoc-params dt {
  font-size: 0.52rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.apidoc-params dd {
  margin: 0;
  font-size: 0.62rem;
  color: var(--background);
}

.apidoc-response {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, black 38%, transparent);
}

.apidoc-response-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  flex-shrink: 0;
  padding: 0.28rem 0.45rem 0.18rem;
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.apidoc-ok {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  color: var(--primary);
}

.apidoc-ok i {
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  background: var(--primary);
}

.apidoc-json {
  margin: 0;
  padding: 0 0.35rem 0.4rem;
  list-style: none;
  overflow: hidden;
  font-size: 0.62rem;
  line-height: 1.45;
}

.apidoc-json li {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  min-width: 0;
}

.apidoc-code {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.apidoc-ln {
  flex: 0 0 1.15rem;
  text-align: right;
  font-size: 0.5rem;
  color: color-mix(in oklab, var(--background) 32%, transparent);
  user-select: none;
}

.apidoc-k {
  color: var(--primary);
}

.apidoc-p {
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.apidoc-v-string {
  color: color-mix(in oklab, var(--background) 88%, transparent);
}

.apidoc-v-number,
.apidoc-v-ident {
  color: color-mix(in oklab, var(--primary) 78%, var(--background));
}

.apidoc-cursor {
  display: inline-block;
  width: 0.38rem;
  height: 0.72em;
  margin-left: 0.12rem;
  vertical-align: text-bottom;
  background: var(--primary);
}

.apidoc-stage[data-live="true"] .apidoc-cursor {
  animation: apidoc-blink 1.05s steps(1) infinite;
}

@keyframes apidoc-blink {
  50% {
    opacity: 0;
  }
}

.apidoc-foot {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex-shrink: 0;
  font-size: 0.52rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.apidoc-foot span:first-child {
  color: var(--primary);
}

@media (min-width: 1024px) {
  .apidoc-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }
}

@media (max-width: 1023px) {
  .apidoc-room {
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
    transform: rotateY(-5deg) rotateX(2.5deg);
  }
}

@media (max-width: 639px) {
  .apidoc-room {
    transform: none;
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    gap: 0.28rem;
    padding: 0.5rem 0.55rem 0.45rem;
  }

  .apidoc-keychip,
  .apidoc-params,
  .apidoc-foot span:nth-child(2) {
    display: none;
  }
}

@container apidoc (max-width: 22rem) {
  .apidoc-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .apidoc-nav {
    flex-direction: row;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .apidoc-nav-item {
    grid-template-columns: auto;
    flex: 0 0 auto;
  }

  .apidoc-nav-label {
    display: none;
  }

  .apidoc-keychip {
    display: none;
  }
}

@container apidoc (max-height: 20rem) {
  .apidoc-params {
    display: none;
  }

  .apidoc-json li:nth-child(n + 7) {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .apidoc-room {
    transform: none;
  }

  .apidoc-stage[data-live="true"] .apidoc-live-dot,
  .apidoc-stage[data-live="true"] .apidoc-cursor {
    animation: none;
  }
}

/* Auth flow console */

.apk-console,
.whk-console {
  width: 100%;
  container-type: inline-size;
}

.apk-console .lc-body,
.whk-console .lc-body {
  gap: 0.48rem;
}

.apk-stats,
.whk-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
  flex-shrink: 0;
}

@container (min-width: 28rem) {
  .apk-stats,
  .whk-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.apk-pipeline,
.whk-pipeline {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.32rem;
  margin: 0;
  padding: 0;
  list-style: none;
  flex-shrink: 0;
}

@container (min-width: 32rem) {
  .apk-pipeline,
  .whk-pipeline {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.apk-step,
.whk-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 0.35rem;
  row-gap: 0.04rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.32rem 0.4rem;
}

.apk-step[data-current="true"],
.whk-step[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.apk-step-index,
.whk-step-index {
  grid-row: 1 / span 2;
  align-self: center;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.apk-step[data-done="true"] .apk-step-index,
.apk-step[data-current="true"] .apk-step-index,
.whk-step[data-done="true"] .whk-step-index,
.whk-step[data-current="true"] .whk-step-index {
  color: var(--primary);
}

.apk-step-label,
.whk-step-label {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--foreground);
}

.apk-step-detail,
.whk-step-detail {
  font-size: 0.58rem;
  color: var(--muted-foreground);
}

.apk-workspace,
.whk-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.45rem;
  min-height: 0;
  flex: 1 1 auto;
}

@container (min-width: 30rem) {
  .apk-workspace,
  .whk-workspace {
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.95fr);
  }
}

.apk-workspace > .lc-panel,
.whk-workspace > .lc-panel {
  min-height: 0;
}

.apk-key {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--foreground);
}

.apk-key-meta {
  margin: 0.1rem 0 0.35rem;
  font-size: 0.62rem;
  color: var(--muted-foreground);
}

.apk-scopes,
.apk-roles,
.whk-attempts,
.whk-events {
  display: flex;
  flex-direction: column;
  gap: 0.16rem;
  margin: 0;
  padding: 0;
  list-style: none;
  min-height: 0;
  overflow: hidden;
}

.apk-scopes li,
.apk-roles li,
.whk-attempts li {
  display: grid;
  align-items: center;
  gap: 0.35rem;
  border-radius: 0.42rem;
  padding: 0.18rem 0.32rem;
  font-size: 0.62rem;
}

.apk-scopes li {
  grid-template-columns: auto minmax(0, 1fr) auto;
}

.apk-roles li {
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
}

.apk-scopes li[data-active="true"],
.apk-roles li[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.apk-scope-dot {
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 18%, transparent);
}

.apk-scopes li[data-active="true"] .apk-scope-dot {
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 18%, transparent);
}

.apk-scope-access {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.apk-scopes li[data-active="true"] .apk-scope-access {
  color: var(--primary);
}

.apk-roles li strong {
  grid-column: 1;
  font-size: 0.68rem;
  font-weight: 600;
  color: var(--foreground);
}

.apk-roles li span {
  grid-column: 1;
  font-size: 0.58rem;
  color: var(--muted-foreground);
}

.apk-roles li em {
  grid-column: 2;
  grid-row: 1 / span 2;
  font-style: normal;
  font-size: 0.58rem;
  color: var(--primary);
}

.apk-feed-panel,
.whk-feed-panel {
  flex: 0 0 auto;
}

.apk-console[data-live="true"] .lc-feed-list,
.whk-console[data-live="true"] .lc-feed-list {
  animation: lc-feed-scroll 18s linear infinite;
}

.whk-envelope,
.whk-endpoint {
  margin: 0 0 0.28rem;
  font-size: 0.58rem;
  color: var(--muted-foreground);
}

.whk-json {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  line-height: 1.45;
}

.whk-json-nested {
  padding-left: 0.7rem;
}

.whk-k {
  color: var(--primary);
}

.whk-p {
  color: var(--muted-foreground);
}

.whk-v-string {
  color: var(--foreground);
}

.whk-v-number,
.whk-v-ident {
  color: var(--primary-deep);
}

.whk-attempts li {
  grid-template-columns: auto auto 2.2rem minmax(0, 1fr);
}

.whk-attempt-pip {
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  background: var(--primary);
}

.whk-attempts li[data-state="retry"] .whk-attempt-pip {
  background: color-mix(in oklab, var(--foreground) 35%, transparent);
}

.whk-attempts li[data-state="queued"] .whk-attempt-pip {
  background: color-mix(in oklab, var(--foreground) 18%, transparent);
}

.whk-attempt-code {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  color: var(--foreground);
}

.whk-attempt-state {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.whk-attempts li[data-state="ok"] .whk-attempt-state {
  color: var(--primary);
}

.whk-events {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 0.28rem;
  margin-top: 0.4rem;
}

.whk-events li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.12rem 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  letter-spacing: 0.04em;
  color: var(--muted-foreground);
}

.whk-events li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  color: var(--primary);
}

@media (prefers-reduced-motion: reduce) {
  .apk-console[data-live="true"] .lc-feed-list,
  .whk-console[data-live="true"] .lc-feed-list,
  .apk-scopes li[data-active="true"] .apk-scope-dot {
    animation: none;
  }
}

/* == Event intelligence — category board (ecb-*) == */

.ecb-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.ecb-title {
  margin-top: 1rem;
  max-width: 28ch;
  font-family: var(--font-display);
  font-size: clamp(1.875rem, 2.8vw, 2.55rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.ecb-lead {
  margin-top: 1rem;
  max-width: 54ch;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.ecb-index {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1.25rem;
  margin-bottom: 0.85rem;
  border-radius: 0.9rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 72%, white);
  padding: 0.7rem 0.95rem;
}

.ecb-index-copy {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.45rem 0.85rem;
  margin: 0;
}

.ecb-index-kicker {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--foreground);
}

.ecb-index-count {
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.ecb-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ecb-chips li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, var(--border));
  background: color-mix(in oklab, var(--primary) 7%, white);
  padding: 0.18rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--primary-deep);
}

.ecb-board {
  display: grid;
  gap: 0.75rem;
}

.ecb-card {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  min-width: 0;
  border-radius: 1rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1rem 1.05rem 1.05rem;
  box-shadow: var(--shadow-card);
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.ecb-card-featured {
  gap: 0.9rem;
  padding: 1.2rem 1.25rem 1.25rem;
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 8%, white) 0%,
      var(--card) 42%
    );
}

.ecb-card[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, var(--border));
  box-shadow:
    var(--shadow-card),
    0 0 0 1px color-mix(in oklab, var(--primary) 18%, transparent);
}

.ecb-card-head {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.ecb-card-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 0.65rem;
  background: var(--primary-soft);
  color: var(--primary);
}

.ecb-card-featured .ecb-card-icon {
  width: 2.55rem;
  height: 2.55rem;
  border-radius: 0.75rem;
}

.ecb-card-head-copy {
  min-width: 0;
  flex: 1;
}

.ecb-card-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.ecb-card h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.98rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.ecb-card-featured h3 {
  font-size: 1.45rem;
  line-height: 1.15;
}

.ecb-card-band {
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, white);
  padding: 0.18rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary-deep);
}

.ecb-card-band[data-band="steady"] {
  border-color: var(--border);
  background: var(--surface);
  color: var(--muted-foreground);
}

.ecb-card-score {
  margin-left: auto;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--primary);
}

.ecb-card-body {
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

.ecb-card-featured .ecb-card-body {
  max-width: 42ch;
  font-size: 0.9rem;
  line-height: 1.6;
}

.ecb-heat {
  display: grid;
  gap: 0.35rem;
}

.ecb-heat-track {
  display: block;
  height: 0.38rem;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.ecb-heat-fill {
  display: block;
  width: calc(var(--ecb-heat) * 1%);
  height: 100%;
  border-radius: inherit;
  background: var(--primary);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}

.ecb-heat[data-band="high"] .ecb-heat-fill {
  background: color-mix(in oklab, var(--primary) 78%, var(--primary-deep));
}

.ecb-heat[data-band="steady"] .ecb-heat-fill {
  background: color-mix(in oklab, var(--primary) 55%, var(--foreground));
}

.ecb-section[data-live="true"] .ecb-heat-fill {
  transform: scaleX(1);
}

.ecb-heat-meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.ecb-heat-label {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ecb-heat-score {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--foreground);
}

.ecb-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  margin: 0;
}

.ecb-stats div {
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 70%, white);
  padding: 0.55rem 0.65rem 0.6rem;
}

.ecb-stats dt {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ecb-stats dd {
  margin: 0.22rem 0 0;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.ecb-spark {
  margin-top: auto;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--surface) 55%, white);
  padding: 0.65rem 0.75rem 0.7rem;
}

.ecb-spark-kicker {
  display: block;
  margin-bottom: 0.45rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.ecb-spark-bars {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  align-items: end;
  gap: 0.18rem;
  height: 2.15rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ecb-spark-bars li {
  display: flex;
  align-items: end;
  height: 100%;
}

.ecb-spark-bars span {
  display: block;
  width: 100%;
  height: calc(18% + var(--ecb-spark) * 82%);
  border-radius: 2px 2px 1px 1px;
  background: color-mix(in oklab, var(--primary) calc(28% + var(--ecb-spark) * 55%), var(--border));
  transform: scaleY(0);
  transform-origin: bottom center;
  transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.ecb-section[data-live="true"] .ecb-spark-bars span {
  transform: scaleY(1);
}

.ecb-spark-bars li:nth-child(odd) span {
  transition-delay: 40ms;
}

.ecb-spark-bars li:nth-child(even) span {
  transition-delay: 90ms;
}

.ecb-card-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  margin: auto 0 0;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.ecb-card-foot .lc-mono {
  font-weight: 700;
  color: var(--foreground);
}

@media (min-width: 768px) {
  .ecb-board {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.85rem;
  }

  .ecb-card-featured {
    grid-column: 1 / -1;
  }
}

@media (min-width: 1024px) {
  .ecb-board {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    grid-template-rows: auto auto auto;
    align-items: stretch;
  }

  .ecb-card-featured {
    grid-column: 1 / span 7;
    grid-row: 1 / span 2;
  }

  .ecb-card:nth-child(2),
  .ecb-card:nth-child(3) {
    grid-column: span 5;
  }

  .ecb-card:nth-child(n + 4) {
    grid-column: span 4;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ecb-heat-fill,
  .ecb-spark-bars span,
  .ecb-card {
    transition: none;
  }

  .ecb-heat-fill,
  .ecb-section[data-live="true"] .ecb-heat-fill,
  .ecb-spark-bars span,
  .ecb-section[data-live="true"] .ecb-spark-bars span {
    transform: none;
  }
}

/* == Marketplace connectivity — return-path capability board (mcb-*) == */

.mcb-title {
  margin-top: 1rem;
  max-width: 18ch;
  font-family: var(--font-display);
  font-size: clamp(1.875rem, 2.8vw, 2.55rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.03em;
}

.mcb-intro {
  margin-top: 1rem;
  max-width: 58ch;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: color-mix(in oklab, var(--background) 70%, transparent);
}

.mcb-board {
  display: grid;
  gap: 0.9rem;
  padding: 0.85rem;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 48%
    ),
    color-mix(in oklab, black 38%, var(--dark));
  box-shadow:
    0 24px 56px color-mix(in oklab, black 36%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 8%, transparent);
}

.mcb-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem 0.9rem;
  padding: 0.15rem 0.2rem 0.1rem;
}

.mcb-toolbar-kicker {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.mcb-toolbar-live {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.14rem 0.5rem 0.14rem 0.38rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.mcb-toolbar-live i {
  display: block;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
}

.mcb-section[data-live="true"] .mcb-toolbar-live i {
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.mcb-toolbar-meta {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.mcb-caps {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.7rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mcb-tile {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
  padding: 0.95rem 1rem 1rem;
}

.mcb-tile-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.mcb-tile-index {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.mcb-tile-status {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.12rem 0.48rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.mcb-tile-status[data-status="watching"],
.mcb-tile-status[data-status="audit"] {
  border-color: color-mix(in oklab, var(--background) 16%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
  color: color-mix(in oklab, var(--background) 78%, transparent);
}

.mcb-tile h3 {
  margin: 0.7rem 0 0;
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.mcb-tile p {
  margin: 0.45rem 0 0;
  flex: 1;
  font-size: 0.8rem;
  line-height: 1.55;
  color: color-mix(in oklab, var(--background) 64%, transparent);
}

.mcb-tile-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  margin-top: 0.85rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.mcb-pips {
  display: flex;
  gap: 0.22rem;
}

.mcb-pips i {
  display: block;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 14%, transparent);
}

.mcb-pips i[data-fill="live"] {
  background: var(--primary);
}

.mcb-pips i[data-fill="lag"] {
  background: color-mix(in oklab, var(--primary) 45%, var(--background));
}

.mcb-matrix {
  display: grid;
  gap: 0.38rem;
  overflow-x: auto;
  padding: 0.75rem 0.7rem 0.8rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, black 22%, transparent);
}

.mcb-matrix-row {
  display: grid;
  grid-template-columns: 5.6rem repeat(8, minmax(1.7rem, 1fr));
  align-items: center;
  gap: 0.28rem;
  min-width: 28rem;
}

.mcb-matrix-label {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.mcb-matrix-col {
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
  transition: color 0.35s ease;
}

.mcb-matrix-col[data-active="true"] {
  color: var(--primary);
}

.mcb-matrix-cell {
  display: grid;
  place-items: center;
  height: 1.55rem;
  border-radius: 0.35rem;
  background: color-mix(in oklab, var(--background) 7%, transparent);
  transition:
    background 0.35s ease,
    box-shadow 0.35s ease;
}

.mcb-matrix-cell::after {
  content: "";
  width: 0.48rem;
  height: 0.48rem;
  border-radius: 2px;
  background: color-mix(in oklab, var(--background) 18%, transparent);
}

.mcb-matrix-cell[data-fill="live"]::after {
  background: var(--primary);
}

.mcb-matrix-cell[data-fill="lag"]::after {
  background: color-mix(in oklab, var(--primary) 48%, var(--background));
}

.mcb-matrix-cell[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 35%, transparent);
}

.mcb-dock {
  display: grid;
  gap: 0.7rem;
  align-items: center;
  padding: 0.75rem 0.85rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
}

.mcb-dock-from,
.mcb-dock-hub {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.4rem 0.55rem;
  min-width: 0;
}

.mcb-dock-code {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.mcb-dock-from strong,
.mcb-dock-hub span {
  font-family: var(--font-display);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.mcb-dock-dest {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--background) 14%, transparent);
  padding: 0.08rem 0.42rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.mcb-dock-hub strong {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.mcb-rail {
  position: relative;
  height: 2px;
  overflow: hidden;
  border-radius: 999px;
  background: repeating-linear-gradient(
    90deg,
    color-mix(in oklab, var(--background) 22%, transparent) 0 8px,
    transparent 8px 14px
  );
}

.mcb-rail-packet {
  position: absolute;
  top: 50%;
  left: 0;
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 70%, transparent);
  transform: translate(-50%, -50%);
}

.mcb-section[data-live="true"] .mcb-rail-packet {
  animation: mcb-inbound 2.4s linear infinite;
}

@keyframes mcb-inbound {
  from {
    left: 0;
    opacity: 0.2;
  }
  12% {
    opacity: 1;
  }
  88% {
    opacity: 1;
  }
  to {
    left: 100%;
    opacity: 0.25;
  }
}

