/* ── Homepage hero console — light HUD ───────────────────────────────────
   Light-glass retheme of the tilt stage (.hero-tilt-*) plus `hero-hud-*`
   internals. White/off-white panels, light gray chrome, dark text, primary
   green accents. The console index follows the hero slide:
     [data-mode="platform"] → platform layers + system feed
     [data-mode="broker"]   → one catalog distributed across channels
     [data-mode="travel"]   → partner margin / quote desk
   All three share the same fixed --hero-card-h box, so switching slides
   never resizes the hero. Mobile scale/centering rules live in the
   `hero-fit` block above and still apply (class names unchanged).
   Legacy .hero-shell-* / .hero-intel-* / .hero-price-* / .hero-sync-* /
   .hero-mode-* rules are no longer referenced by any component. */

/* Headline reserve — ghost holds the longest phrase so the typewriter line
   box never grows or shrinks while typing or switching slides. */
.hero-copy-typeline {
  position: relative;
  padding-right: 0.2em;
  white-space: nowrap;
}

.hero-copy-typeline-ghosts {
  display: grid;
}

.hero-copy-typeline-ghost {
  grid-area: 1 / 1;
  visibility: hidden;
  white-space: nowrap;
}

.hero-copy-typeline-text {
  position: absolute;
  left: 0;
  top: 0;
  display: inline;
  width: max-content;
  overflow: visible;
  white-space: nowrap;
}

/* Light glass stage */
.hero-tilt-card {
  /* Fixed console frame shared by all three designs */
  --hero-card-h: 28rem;
  --ht-bg: oklch(0.99 0.006 155 / 0.9);
  --ht-panel: oklch(0.985 0.007 155);
  --ht-elevated: oklch(0.972 0.01 155);
  --ht-border: oklch(0.88 0.016 155);
  --ht-text: oklch(0.24 0.03 160);
  --ht-muted: oklch(0.42 0.02 160);
  --ht-faint: oklch(0.55 0.018 160);
  --ht-glass: oklch(1 0 0 / 0.58);
  --ht-well: oklch(0.96 0.01 155 / 0.82);
  border-color: color-mix(in oklab, var(--primary) 22%, var(--ht-border));
  background: var(--ht-bg);
  box-shadow:
    0 1px 0 oklch(1 0 0 / 0.92) inset,
    0 28px 64px -28px oklch(0.18 0.04 160 / 0.5),
    0 0 0 1px oklch(1 0 0 / 0.7) inset,
    0 0 48px -10px color-mix(in oklab, var(--primary) 26%, transparent);
}

.hero-tilt-card[data-mode="platform"] {
  border-color: color-mix(in oklab, var(--primary) 26%, var(--ht-border));
  background:
    radial-gradient(
      ellipse 90% 60% at 10% 0%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 62%
    ),
    linear-gradient(180deg, oklch(1 0 0 / 0.94), var(--ht-bg) 58%);
}

.hero-tilt-card[data-mode="broker"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--ht-border));
  background:
    radial-gradient(
      ellipse 80% 55% at 92% 0%,
      color-mix(in oklab, var(--primary) 11%, transparent),
      transparent 60%
    ),
    linear-gradient(180deg, oklch(0.995 0.008 155 / 0.95), var(--ht-bg) 55%);
}

.hero-tilt-card[data-mode="travel"] {
  border-color: color-mix(in oklab, var(--primary) 26%, var(--ht-border));
  background:
    radial-gradient(
      circle at 70% 82%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 55%
    ),
    linear-gradient(180deg, oklch(0.992 0.01 155 / 0.94), var(--ht-bg) 52%);
}

.hero-tilt-grid-bg {
  opacity: 0.42;
  background-image:
    linear-gradient(oklch(0.78 0.02 155 / 0.38) 1px, transparent 1px),
    linear-gradient(90deg, oklch(0.78 0.02 155 / 0.38) 1px, transparent 1px);
}

.hero-tilt-glare {
  background: radial-gradient(
    circle at var(--tilt-glare-x) var(--tilt-glare-y),
    oklch(1 0 0 / 0.72),
    transparent 46%
  );
  mix-blend-mode: soft-light;
}

.hero-tilt-scan {
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 14%, transparent),
    transparent
  );
}

/* Slide swap — quick jump-up / slide-in (no crossfade blur) */
.hero-hud-swap {
  position: relative;
  z-index: 2;
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  animation: hero-hud-jump 0.42s cubic-bezier(0.2, 0.9, 0.22, 1) both;
}

@keyframes hero-hud-jump {
  0% {
    opacity: 0;
    transform: translateY(24%);
  }
  50% {
    opacity: 1;
  }
  78% {
    transform: translateY(-1.5%);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Shared HUD chrome */
.hero-hud {
  display: flex;
  height: 100%;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
}

.hero-hud-bar {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  padding: 0.55rem 0.75rem;
  border-bottom: 1px solid var(--ht-border);
  background: var(--ht-glass);
}

.hero-hud-dots {
  display: inline-flex;
  flex-shrink: 0;
  gap: 0.28rem;
}

.hero-hud-dots i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 999px;
  background: oklch(0.82 0.012 155);
}

.hero-hud-dots i:first-child {
  background: color-mix(in oklab, var(--primary) 60%, transparent);
}

.hero-hud-path {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.32rem;
  overflow: hidden;
  border-radius: 999px;
  border: 1px solid var(--ht-border);
  background: var(--ht-well);
  padding: 0.24rem 0.6rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.1em;
  text-transform: none;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ht-muted);
}

.hero-hud-badge {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.35rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.hero-hud-pip {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 20%, transparent);
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.hero-hud-body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  gap: 0.45rem;
  padding: 0.6rem 0.75rem 0.55rem;
  overflow: hidden;
}

.hero-hud-foot {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.4rem 0.75rem 0.5rem;
  border-top: 1px solid var(--ht-border);
  background: var(--ht-glass);
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--ht-faint);
}

.hero-hud-foot > span {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.hero-hud-foot-accent {
  color: var(--primary);
}

.hero-hud-foot-icon {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}

.hero-hud-head {
  display: flex;
  flex-shrink: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.6rem;
}

.hero-hud-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.hero-hud-title {
  margin-top: 0.15rem;
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1.25;
  color: var(--ht-text);
}

.hero-hud-chip {
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 32%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  padding: 0.24rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
  box-shadow: 0 0 18px color-mix(in oklab, var(--primary) 18%, transparent);
}

.hero-hud-mini {
  margin-bottom: 0.3rem;
  font-family: var(--font-mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--ht-faint);
}

.hero-hud-panel {
  position: relative;
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  border-radius: 0.5rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-well);
  padding: 0.4rem 0.45rem;
  overflow: hidden;
}

/* Label floats so the bar track keeps a definite height for % bar values */
.hero-hud-chart .hero-hud-mini {
  position: absolute;
  top: 0.4rem;
  left: 0.45rem;
  z-index: 1;
  margin-bottom: 0;
}

/* 1 — Platform layers + system feed */
.hero-hud-split {
  display: grid;
  flex: 1 1 auto;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  gap: 0.45rem;
  min-height: 0;
}

.hero-hud-stack {
  position: relative;
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 0.3rem;
  padding-left: 0.9rem;
}

.hero-hud-stack-rail {
  position: absolute;
  top: 0.3rem;
  bottom: 0.3rem;
  left: 0.32rem;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 45%, transparent),
    transparent
  );
}

.hero-hud-packet {
  position: absolute;
  left: -2.5px;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 65%, transparent);
  animation: hero-hud-packet 3.4s linear infinite;
}

@keyframes hero-hud-packet {
  0% {
    top: -3%;
    opacity: 0;
  }
  14% {
    opacity: 1;
  }
  86% {
    opacity: 1;
  }
  100% {
    top: 100%;
    opacity: 0;
  }
}

.hero-hud-layer {
  display: grid;
  flex: 1 1 0;
  min-height: 0;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-glass);
  padding: 0.28rem 0.42rem;
  animation: hero-tilt-row-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
  transition:
    border-color 0.35s ease,
    background 0.35s ease,
    box-shadow 0.35s ease;
}

.hero-hud-layer[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  box-shadow:
    inset 2px 0 0 var(--primary),
    0 0 22px -6px color-mix(in oklab, var(--primary) 35%, transparent);
}

.hero-hud-layer-icon {
  display: grid;
  place-items: center;
  width: 1.4rem;
  height: 1.4rem;
  flex-shrink: 0;
  border-radius: 0.35rem;
  border: 1px solid var(--ht-border);
  color: var(--ht-faint);
  transition:
    color 0.35s ease,
    border-color 0.35s ease,
    background 0.35s ease;
}

.hero-hud-layer[data-active="true"] .hero-hud-layer-icon {
  color: var(--primary);
  border-color: color-mix(in oklab, var(--primary) 45%, transparent);
  background: color-mix(in oklab, var(--primary) 16%, transparent);
}

.hero-hud-layer-label {
  min-width: 0;
  overflow: hidden;
  font-size: 10.5px;
  font-weight: 600;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ht-text);
}

.hero-hud-layer-meta {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  white-space: nowrap;
  color: var(--ht-faint);
}

.hero-hud-layer[data-active="true"] .hero-hud-layer-meta {
  color: var(--primary);
}

.hero-hud-side {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 0.45rem;
}

.hero-hud-bars {
  min-height: 0 !important;
  height: 100%;
  padding-top: 0.85rem;
  gap: 0.22rem;
}

.hero-hud-tiles {
  display: grid;
  flex-shrink: 0;
  grid-template-columns: 1fr 1fr;
  gap: 0.4rem;
}

.hero-hud-tiles div {
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-glass);
  padding: 0.32rem 0.4rem;
}

.hero-hud-tiles strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.95rem;
  line-height: 1.1;
  color: var(--ht-text);
}

.hero-hud-tiles span {
  font-family: var(--font-mono);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--ht-faint);
}

.hero-hud-feed {
  flex-shrink: 0;
  height: 3.55rem;
  border-radius: 0.5rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-well);
  padding: 0.25rem 0.45rem;
  overflow: hidden;
}

.hero-hud-feed-mask {
  position: relative;
  height: 100%;
  overflow: hidden;
  mask-image: linear-gradient(180deg, transparent, #000 22%, #000 78%, transparent);
}

.hero-hud-feed-track {
  display: flex;
  flex-direction: column;
  animation: lc-feed-scroll 17s linear infinite;
}

.hero-hud-feed-row {
  display: flex;
  height: 1.15rem;
  flex-shrink: 0;
  align-items: center;
  gap: 0.3rem;
  overflow: hidden;
  font-size: 9.5px;
  color: var(--ht-muted);
}

.hero-hud-feed-row b {
  min-width: 0;
  overflow: hidden;
  font-weight: 400;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.hero-hud-feed-row i {
  width: 4px;
  height: 4px;
  flex-shrink: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 70%, transparent);
}

.hero-hud-feed-row em {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 7.5px;
  font-style: normal;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

/* 2 — Distribution matrix */
.hero-hud-listing {
  display: flex;
  flex-shrink: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.6rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--primary) 24%, var(--ht-border));
  background: linear-gradient(
    120deg,
    color-mix(in oklab, var(--primary) 14%, transparent),
    transparent 62%
  );
  padding: 0.42rem 0.55rem;
}

.hero-hud-listing-num {
  flex-shrink: 0;
  text-align: right;
}

.hero-hud-listing-num span {
  display: block;
  font-family: var(--font-mono);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--ht-faint);
}

.hero-hud-listing-num strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.1;
  color: var(--ht-text);
}

.hero-hud-flash {
