}

@keyframes hero-hud-flash {
  0% {
    color: var(--primary);
    text-shadow: 0 0 14px color-mix(in oklab, var(--primary) 60%, transparent);
  }
  100% {
    color: var(--ht-text);
    text-shadow: none;
  }
}

.hero-hud-matrix {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  gap: 0.26rem;
}

.hero-hud-matrix-head,
.hero-hud-matrix-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 1.3rem 2.5rem auto;
  align-items: center;
  gap: 0.35rem;
}

.hero-hud-matrix-head {
