}

.hero-hud-matrix-qty,
.hero-hud-matrix-ask {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  text-align: right;
  color: var(--ht-text);
}

.hero-hud-matrix-chan {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.2rem;
}

.hero-hud-matrix-chan em {
  width: 0.85rem;
  font-family: var(--font-mono);
  font-size: 6.5px;
  font-style: normal;
  letter-spacing: 0.04em;
  text-align: center;
  color: var(--ht-faint);
}

.hero-hud-matrix-chan i {
  width: 0.85rem;
  height: 0.5rem;
  border-radius: 0.15rem;
  background: oklch(0.9 0.012 155);
  transition:
    background 0.4s ease,
    box-shadow 0.4s ease;
}

.hero-hud-matrix-chan i[data-state="ok"] {
  background: color-mix(in oklab, var(--primary) 80%, transparent);
  box-shadow: 0 0 8px color-mix(in oklab, var(--primary) 40%, transparent);
}

.hero-hud-matrix-chan i[data-state="push"] {
  background: color-mix(in oklab, var(--primary) 45%, transparent);
