}

.hero-hud-export {
  display: grid;
  flex-shrink: 0;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.5rem;
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-glass);
  padding: 0.4rem 0.5rem;
}

.hero-hud-export .hero-hud-mini {
  margin-bottom: 0;
}

.hero-hud-export-bar {
  position: relative;
  height: 0.35rem;
  border-radius: 999px;
  background: oklch(0.91 0.012 155);
  overflow: hidden;
}

.hero-hud-export-bar i {
  position: absolute;
  inset-block: 0;
  left: 0;
