}

/* 3 — Partner quote desk */
.hero-hud-chips {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  gap: 0.28rem;
}

.hero-hud-chips span {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  border-radius: 0.35rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-glass);
  padding: 0.22rem 0.42rem;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  white-space: nowrap;
  color: var(--ht-muted);
}

.hero-hud-quote {
  display: grid;
  flex: 1 1 auto;
  grid-template-columns: minmax(0, 0.86fr) minmax(0, 1.14fr);
  gap: 0.45rem;
