}

.hero-hud-steps {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 0.3rem;
}

.hero-hud-step {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.45rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-glass);
  padding: 0.28rem 0.4rem;
  animation: hero-tilt-row-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
  transition:
    border-color 0.35s ease,
    background 0.35s ease,
    box-shadow 0.35s ease;
}

.hero-hud-step-dot {
  display: grid;
  place-items: center;
  width: 1.1rem;
  height: 1.1rem;
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid var(--ht-border);
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  color: var(--ht-faint);
  transition:
    color 0.35s ease,
    border-color 0.35s ease,
    background 0.35s ease;
}

.hero-hud-step-label {
  min-width: 0;
  overflow: hidden;
  font-size: 9.5px;
  font-weight: 600;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ht-muted);
}

.hero-hud-step[data-state="active"] {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--ht-border));
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  box-shadow: 0 0 22px -6px color-mix(in oklab, var(--primary) 35%, transparent);
}

.hero-hud-step[data-state="active"] .hero-hud-step-dot {
