}

.hero-hud-step[data-state="done"] .hero-hud-step-dot {
  color: var(--primary);
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 14%, transparent);
}

.hero-hud-avail {
  gap: 0.22rem;
}

.hero-hud-avail-row {
  display: grid;
  flex: 1 1 0;
  min-height: 0;
  grid-template-columns: minmax(0, 1fr) 2.4rem auto;
  align-items: center;
  gap: 0.3rem;
}

.hero-hud-avail-row span {
  min-width: 0;
  overflow: hidden;
  font-size: 9px;
  font-weight: 600;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ht-muted);
}

.hero-hud-avail-row i {
  display: block;
  height: 0.28rem;
  border-radius: 999px;
  background: oklch(0.91 0.012 155);
  overflow: hidden;
}

.hero-hud-avail-row i b {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 80%, transparent);
}

.hero-hud-avail-row em {
  font-family: var(--font-mono);
  font-size: 8.5px;
  font-style: normal;
  font-weight: 700;
  color: var(--primary);
}

.hero-hud-money {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 0.3rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--primary) 26%, var(--ht-border));
  background: linear-gradient(
    140deg,
    color-mix(in oklab, var(--primary) 16%, transparent),
    transparent 68%
  );
  padding: 0.45rem 0.55rem;
  overflow: hidden;
}

.hero-hud-money-value {
  display: flex;
  align-items: baseline;
  gap: 0.1rem;
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3.2vw, 2.15rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--ht-text);
  animation: hero-hud-value-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes hero-hud-value-in {
  from {
    opacity: 0.2;
    transform: translateY(30%);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-hud-money-value span {
  font-size: 0.52em;
  color: var(--primary);
}

.hero-hud-money-value em {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.32em;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--primary);
}

.hero-hud-lines {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  justify-content: center;
  gap: 0.22rem;
}

.hero-hud-lines div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  border-radius: 0.35rem;
  background: var(--ht-well);
  padding: 0.26rem 0.4rem;
}

.hero-hud-lines span {
  min-width: 0;
  overflow: hidden;
  font-size: 9px;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ht-muted);
}

.hero-hud-lines strong {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  color: var(--ht-text);
}

.hero-hud-lines div[data-total="true"] {
  border: 1px solid color-mix(in oklab, var(--primary) 30%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.hero-hud-lines div[data-total="true"] strong {
  color: var(--primary);
}

.hero-hud-math {
  display: grid;
  flex-shrink: 0;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.3rem;
}

.hero-hud-math div {
  border-radius: 0.4rem;
  border: 1px solid var(--ht-border);
  background: var(--ht-well);
  padding: 0.26rem 0.32rem;
}

.hero-hud-math span {
  display: block;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: none;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ht-faint);
}

.hero-hud-math strong {
  display: block;
  margin-top: 0.08rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  color: var(--ht-text);
}

.hero-hud-margin {
  flex-shrink: 0;
  height: 0.3rem;
  border-radius: 999px;
  background: oklch(0.91 0.012 155);
  overflow: hidden;
}

.hero-hud-margin i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--primary-deep), var(--primary));
  box-shadow: 0 0 12px color-mix(in oklab, var(--primary) 45%, transparent);
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.hero-hud-quote-foot {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
}

.hero-hud-stamp {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.3rem;
  overflow: hidden;
  border-radius: 0.35rem;
  border: 1px dashed color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  padding: 0.26rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--primary);
}

.hero-hud-send {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.28rem;
  border-radius: 0.35rem;
  background: var(--primary);
  padding: 0.28rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary-foreground);
  box-shadow: 0 0 18px -4px color-mix(in oklab, var(--primary) 55%, transparent);
}

/* Phone console box (<480px): the breadcrumb is a bare text node inside an
   inline-flex, so text-overflow can't ellipsise it — it hard-cut against the LIVE
   badge. Tighten the tracking so the full path fits, and fade the tail as a guard. */
@media (max-width: 479px) {
  .hero-hud-path {
    flex: 0 1 auto;
    font-size: 7.5px;
    letter-spacing: 0;
    padding-inline: 0.4rem;
    -webkit-mask-image: linear-gradient(90deg, #000 92%, transparent);
    mask-image: linear-gradient(90deg, #000 92%, transparent);
  }
}

/* Narrow console box (small phones, ~300–375px card width) */
@media (max-width: 400px) {
  .hero-hud-chips span:last-child {
    display: none;
  }

  .hero-hud-matrix-chan i,
  .hero-hud-matrix-chan em {
    width: 0.7rem;
  }

  .hero-hud-path {
    font-size: 7px;
  }

  /* 320px card headers can't hold dots + full breadcrumb + LIVE badge; the globe
     is the least informative of the three, so it goes before the words do. */
  .hero-hud-path > svg {
    display: none;
  }

  /* Give the whole left column to the layer name — with the meta column in
     place the labels ellipsised down to a single letter. */
  .hero-hud-layer-meta {
    display: none;
  }
}

@media (max-width: 340px) {
  .hero-hud-path {
    font-size: 6.5px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-hud-swap,
  .hero-hud-layer,
  .hero-hud-matrix-row,
  .hero-hud-matrix-chan i,
  .hero-hud-step,
  .hero-hud-money-value,
  .hero-hud-flash,
  .hero-hud-feed-track,
  .hero-hud-pip,
  .hero-hud-export-bar i {
    animation: none;
  }

  .hero-hud-packet {
    display: none;
  }

  .hero-hud-export-bar i {
    width: 74%;
  }
}

/* ------------------------------------------------------------------ */
/* Marketplace hub — homepage Marketplaces.tsx (mps-hub-*)            */
/* Full-width center logo + glass pods; dual inward marquees.         */
/* ------------------------------------------------------------------ */

.mps-hub {
  --mps-pod-fill: color-mix(in oklab, white 82%, var(--surface));
  --mps-pod-border: color-mix(in oklab, var(--border) 70%, white);
  --mps-nock: 1.35rem;
  --mps-item-gap: 1.35rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.7rem;
  margin-top: 1.75rem;
  min-width: 0;
  width: 100%;
}

.mps-hub-pod {
  display: flex;
  align-items: stretch;
  min-width: 0;
  width: 100%;
  filter: drop-shadow(0 14px 32px oklch(0 0 0 / 0.09));
}

.mps-hub-pod--in {
  flex-direction: column;
}

.mps-hub-pod--out {
  flex-direction: column-reverse;
}

.mps-hub-pod-body {
  position: relative;
  z-index: 1;
  min-width: 0;
  overflow: hidden;
  flex: 1 1 auto;
  background: var(--mps-pod-fill);
  backdrop-filter: blur(18px) saturate(1.2);
  -webkit-backdrop-filter: blur(18px) saturate(1.2);
  border: 1px solid var(--mps-pod-border);
  box-shadow: inset 0 1px 0 color-mix(in oklab, white 78%, transparent);
}

.mps-hub-pod--in .mps-hub-pod-body {
  border-radius: 1.35rem 1.35rem 0.45rem 0.45rem;
  border-bottom-color: transparent;
}

.mps-hub-pod--out .mps-hub-pod-body {
  border-radius: 0.45rem 0.45rem 1.35rem 1.35rem;
  border-top-color: transparent;
}

.mps-hub-pod-nock {
  position: relative;
  z-index: 0;
  flex-shrink: 0;
  width: var(--mps-nock);
  height: var(--mps-nock);
  margin-block: calc(var(--mps-nock) / -2);
  margin-inline: auto;
  background: var(--mps-pod-fill);
  border: 1px solid var(--mps-pod-border);
  border-radius: 0.22rem;
  transform: rotate(45deg);
}

.mps-hub-viewport {
  overflow: hidden;
  width: 100%;
  mask-image: linear-gradient(
    90deg,
    transparent,
    #000 8%,
    #000 92%,
    transparent
  );
}

.mps-hub-track {
  display: flex;
  width: max-content;
  animation: mps-hub-flow-out 28s linear infinite;
  will-change: transform;
}

.mps-hub-pod--in .mps-hub-track {
  animation-name: mps-hub-flow-in;
}

.mps-hub-pod:hover .mps-hub-track {
  animation-play-state: paused;
}

@keyframes mps-hub-flow-out {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(-50%, 0, 0);
  }
}

@keyframes mps-hub-flow-in {
  from {
    transform: translate3d(-50%, 0, 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

.mps-hub-items {
  display: flex;
  flex-shrink: 0;
  flex-wrap: nowrap;
  align-items: center;
  gap: var(--mps-item-gap);
  margin: 0;
  padding: 0.85rem var(--mps-item-gap) 0.85rem 0;
  list-style: none;
}

.mps-hub-item {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.45rem;
}

.mps-hub-icon {
  display: grid;
  flex-shrink: 0;
  width: 1.7rem;
  height: 1.7rem;
  place-items: center;
  border-radius: 0.42rem;
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow: 0 4px 10px -4px color-mix(in oklab, var(--primary) 55%, transparent);
}

.mps-hub-icon svg {
  width: 0.88rem;
  height: 0.88rem;
}

.mps-hub-label {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--foreground);
  white-space: nowrap;
}

.mps-hub-label-short {
  display: none;
}

.mps-hub-mark {
  position: relative;
  z-index: 2;
  display: grid;
  flex-shrink: 0;
  width: 5.75rem;
  height: 5.75rem;
  place-items: center;
  border-radius: 1.45rem;
  background: #fff;
  box-shadow:
    0 10px 24px -12px oklch(0 0 0 / 0.18),
    0 0 44px -8px color-mix(in oklab, var(--primary) 40%, transparent);
}

.mps-hub-mark img {
  height: auto;
  width: auto;
  max-width: 72%;
  max-height: 2.55rem;
  object-fit: contain;
}

@media (max-width: 639px) {
  .mps-hub-label-full:not(:only-child) {
    display: none;
  }

  .mps-hub-label-short {
    display: inline;
  }

  .mps-hub {
    --mps-item-gap: 1.1rem;
  }

  .mps-hub-label {
    font-size: 0.75rem;
  }
}

@media (min-width: 1024px) {
  .mps-hub {
    --mps-nock: 1.5rem;
    --mps-item-gap: 1.75rem;
    flex-direction: row;
    gap: 0.55rem;
    margin-top: 2rem;
  }

  .mps-hub-pod {
    flex: 1 1 0;
    width: auto;
    max-width: none;
  }

  .mps-hub-pod--in {
    flex-direction: row;
  }

  .mps-hub-pod--out {
    flex-direction: row-reverse;
  }

  .mps-hub-pod--in .mps-hub-pod-body {
    border-radius: 999px 0.4rem 0.4rem 999px;
    border-bottom-color: var(--mps-pod-border);
    border-right-color: transparent;
  }

  .mps-hub-pod--out .mps-hub-pod-body {
    border-radius: 0.4rem 999px 999px 0.4rem;
    border-top-color: var(--mps-pod-border);
    border-left-color: transparent;
  }

  .mps-hub-pod-nock {
    margin-block: auto;
    margin-inline: calc(var(--mps-nock) / -2);
  }

  .mps-hub-pod--in .mps-hub-viewport {
    mask-image: linear-gradient(
      90deg,
      transparent,
      #000 6%,
      #000 78%,
      transparent 100%
    );
  }

  .mps-hub-pod--out .mps-hub-viewport {
    mask-image: linear-gradient(
      90deg,
      transparent 0%,
      #000 22%,
      #000 94%,
      transparent
    );
  }

  .mps-hub-items {
    padding-block: 0.9rem;
  }

  .mps-hub-icon {
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 0.5rem;
  }

  .mps-hub-icon svg {
    width: 0.98rem;
    height: 0.98rem;
  }

  .mps-hub-label {
    font-size: 0.9375rem;
  }

  .mps-hub-mark {
    width: 6.75rem;
    height: 6.75rem;
    border-radius: 1.7rem;
  }

  .mps-hub-mark img {
    max-width: 74%;
    max-height: 2.85rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mps-hub-track {
    animation: none;
    transform: none;
    width: 100%;
    justify-content: center;
  }

  .mps-hub-items:nth-child(n + 2) {
    display: none;
  }

  .mps-hub-item:nth-child(n + 4) {
    display: none;
  }

  .mps-hub-items {
    width: 100%;
    justify-content: center;
    padding-inline: 1rem;
  }

  .mps-hub-viewport {
    mask-image: none;
  }

  .mps-hub-pod:hover .mps-hub-track {
    animation-play-state: paused;
  }
}

/* ── /about — company atlas + journey + ops (abt-*) ───────────────
   Unique atlas hero (not a clone of bh-wall / mkh / eih / apidoc).
   Room frame matches other product heroes:
   clamp(22rem, 52vh, 34rem) / tablet 18–26 / phone 16–22.
   Extra hero padding clears the overlay nav (including MacBook heights).
   Ops console is company coverage — not a channel/price ticker.
   Distinct from tpd-* mkh-* eih-* apidoc-* wic-glass-* mps-hub-*. */

.bh-hero.abt-hero {
  padding-bottom: clamp(2.75rem, 5.5vw, 5rem);
}

@media (min-width: 1024px) {
  .bh-hero.abt-hero {
    padding-bottom: clamp(3.25rem, 5vh, 5.25rem);
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .bh-hero.abt-hero {
    padding-bottom: clamp(2.25rem, 3.5vh, 3.25rem);
  }
}

@media (max-width: 639px) {
  .bh-hero.abt-hero {
    padding-bottom: clamp(2.35rem, 8vw, 3.5rem);
  }
}

.abt-stage {
  position: relative;
  min-width: 0;
  max-width: 100%;
  padding: 0.2rem 0.15rem 0.35rem;
}

.abt-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  gap: 0.42rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.55rem 0.62rem 0.52rem;
  overflow: hidden;
  container: abt / size;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    radial-gradient(
      ellipse at 72% 18%,
      color-mix(in oklab, var(--primary) 18%, transparent),
      transparent 42%
    ),
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 42%
    ),
    color-mix(in oklab, black 52%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
}

.abt-room::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background-image: radial-gradient(
    circle,
    color-mix(in oklab, var(--primary) 22%, transparent) 0.7px,
    transparent 0.75px
  );
  background-size: 16px 16px;
  opacity: 0.22;
  mask-image: radial-gradient(ellipse at 58% 52%, black 12%, transparent 78%);
  -webkit-mask-image: radial-gradient(ellipse at 58% 52%, black 12%, transparent 78%);
}

.abt-head,
.abt-body,
.abt-foot,
.abt-atlas-wrap,
.abt-rail,
.abt-coverage {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.abt-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 0.75rem;
  flex-shrink: 0;
}

.abt-head-copy {
  min-width: 0;
}

.abt-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.abt-live-dot {
  width: 0.38rem;
  height: 0.38rem;
  flex-shrink: 0;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
}

.abt-stage[data-live="true"] .abt-live-dot {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.abt-head-title {
  margin: 0.12rem 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.82rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--background);
}

.abt-head-stamp {
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.14rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.abt-body {
  display: grid;
  grid-template-columns: 7.4rem minmax(0, 1fr);
  gap: 0.45rem;
  min-height: 0;
}

.abt-rail {
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
  list-style: none;
}

.abt-rail li {
  min-width: 0;
}

.abt-rail button {
  display: grid;
  grid-template-columns: 1.55rem minmax(0, 1fr);
  align-items: center;
  gap: 0.28rem;
  width: 100%;
  min-width: 0;
  cursor: pointer;
  text-align: left;
  border-radius: 0.45rem;
  border: 1px solid transparent;
  background: transparent;
  padding: 0.22rem 0.32rem;
  color: inherit;
}

.abt-rail button:hover,
.abt-rail button:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 22%, transparent);
  outline: none;
}

.abt-rail li[data-active="true"] button {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.abt-rail-index {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.abt-rail li[data-active="true"] .abt-rail-index {
  color: var(--primary);
}

.abt-rail-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.05rem;
}

.abt-rail-copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: color-mix(in oklab, var(--background) 82%, transparent);
}

.abt-rail li[data-active="true"] .abt-rail-copy strong {
  color: var(--background);
}

.abt-rail-copy em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-style: normal;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.abt-atlas-wrap {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  min-height: 0;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background:
    radial-gradient(
      ellipse at 50% 58%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 58%
    ),
    color-mix(in oklab, black 28%, transparent);
}

.abt-atlas {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 0;
}

.abt-grid {
  fill: none;
  stroke: color-mix(in oklab, var(--background) 12%, transparent);
  stroke-width: 0.6;
}

.abt-arc {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 58%, transparent);
  stroke-width: 1.35;
  stroke-linecap: round;
  stroke-dasharray: 5 9;
}

.abt-arc-long {
  stroke: color-mix(in oklab, var(--background) 26%, transparent);
  stroke-dasharray: 2 10;
}

.abt-stage[data-live="true"] .abt-arc {
  animation: abt-arc-flow 14s linear infinite;
}

.abt-packet {
  fill: var(--primary);
  filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 70%, transparent));
}

.abt-city-ring {
  fill: color-mix(in oklab, var(--primary) 10%, transparent);
  stroke: var(--primary);
  stroke-width: 1.2;
}

.abt-stage[data-live="true"] .abt-city-ring {
  animation: abt-ring 2.6s ease-in-out infinite;
}

.abt-city[data-active="true"] .abt-city-ring {
  stroke-width: 1.8;
  opacity: 1;
}

.abt-city[data-active="true"] .abt-city-code {
  fill: var(--background);
}

.abt-city-core {
  fill: var(--primary);
}

.abt-city-code {
  fill: var(--primary);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.abt-city-name {
  fill: color-mix(in oklab, var(--background) 72%, transparent);
  font-family: var(--font-sans);
  font-size: 8px;
  font-weight: 500;
}

.abt-atlas-caption {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  margin: 0;
  padding: 0.42rem 0.55rem 0.48rem;
  border-top: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  font-size: 0.68rem;
  line-height: 1.45;
  color: color-mix(in oklab, var(--background) 70%, transparent);
}

.abt-atlas-caption span {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.abt-coverage {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.3rem;
  flex-shrink: 0;
}

.abt-coverage > div {
  min-width: 0;
  border-radius: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
  padding: 0.22rem 0.38rem 0.26rem;
}

.abt-coverage > div[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 36%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.abt-coverage strong {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.abt-coverage span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.46rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.abt-foot {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  flex-shrink: 0;
}

.abt-foot > div {
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  background: color-mix(in oklab, var(--background) 5%, transparent);
  padding: 0.32rem 0.45rem 0.38rem;
}

.abt-foot strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--background);
}

.abt-foot span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

@keyframes abt-arc-flow {
  to {
    stroke-dashoffset: -140;
  }
}

@keyframes abt-ring {
  0%,
  100% {
    opacity: 0.4;
    stroke-width: 1.1;
  }
  50% {
    opacity: 0.95;
    stroke-width: 1.7;
  }
}

/* Journey facts + chapter ledger */

.abt-facts {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  margin: 1.75rem 0 0;
  padding: 0;
  list-style: none;
}

.abt-facts li {
  min-width: 0;
  border-radius: 1rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1.1rem 1.15rem 1.15rem;
  box-shadow: var(--shadow-card);
}

.abt-facts strong {
  display: block;
  font-family: var(--font-display);
  font-size: clamp(1.35rem, 2vw, 1.7rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--foreground);
}

.abt-facts span {
  display: block;
  margin-top: 0.28rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.abt-facts p {
  margin: 0.55rem 0 0;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

.abt-journey {
  display: grid;
  gap: 1.15rem;
  margin-top: 2rem;
  min-width: 0;
}

.abt-journey-list,
.abt-journey-panel {
  min-width: 0;
}

.abt-journey-list {
  --abt-journey-num-pad: 1rem;
  --abt-journey-num-col: 2.4rem;
  /* border 1px + pad + half of the 2.4rem index column */
  --abt-journey-line-x: calc(1px + var(--abt-journey-num-pad) + (var(--abt-journey-num-col) / 2));
}

.abt-journey-ledger-kicker {
  margin: 0 0 0.7rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.abt-journey-list ol {
  position: relative;
  display: grid;
  gap: 0.55rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-journey-list ol::before {
  content: "";
  pointer-events: none;
  position: absolute;
  top: 1.1rem;
  bottom: 1.1rem;
  left: var(--abt-journey-line-x);
  width: 1px;
  transform: translateX(-50%);
  background: color-mix(in oklab, var(--primary) 28%, var(--border));
}

.abt-journey-list button {
  display: grid;
  grid-template-columns: var(--abt-journey-num-col) minmax(0, 1fr);
  align-items: center;
  gap: 0.85rem;
  width: 100%;
  min-width: 0;
  cursor: pointer;
  text-align: left;
  border-radius: 0.95rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 0.85rem var(--abt-journey-num-pad);
  box-shadow: var(--shadow-card);
  color: inherit;
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}

.abt-journey-list button:hover,
.abt-journey-list button:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 38%, var(--border));
  outline: none;
}

.abt-journey-list button[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--border));
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 8%, white) 0%,
      var(--card) 48%
    );
  box-shadow:
    var(--shadow-card),
    0 0 0 1px color-mix(in oklab, var(--primary) 16%, transparent);
}

.abt-journey-index {
  position: relative;
  z-index: 1;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: color-mix(in oklab, var(--muted-foreground) 80%, transparent);
}

.abt-journey-list button[data-active="true"] .abt-journey-index {
  color: var(--primary);
}

.abt-journey-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.12rem;
}

.abt-journey-copy em {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.abt-journey-copy strong {
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--foreground);
}

.abt-journey-stack-inline {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-journey-panel {
  display: flex;
  flex-direction: column;
  min-height: 100%;
  border-radius: 1.15rem;
  border: 1px solid var(--border);
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 7%, white) 0%,
      var(--card) 46%
    );
  padding: 1.15rem 1.25rem 1.2rem;
  box-shadow: var(--shadow-card);
}

.abt-journey-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  margin-bottom: 0.85rem;
}

.abt-journey-path {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin: 0;
  min-width: 0;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-journey[data-live="true"] .abt-journey-path .abt-live-dot {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.abt-journey-pin {
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--muted-foreground) 8%, transparent);
  padding: 0.12rem 0.48rem;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-journey-pin[data-pinned="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.abt-journey-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.abt-journey-panel h3 {
  margin: 0.55rem 0 0;
  font-family: var(--font-display);
  font-size: clamp(1.45rem, 2.4vw, 2.05rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--foreground);
}

.abt-journey-kicker-sub {
  margin: 0.45rem 0 0;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-journey-body {
  margin: 0.85rem 0 0;
  max-width: 48ch;
  font-size: 0.9rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.abt-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.85rem 0 0;
  padding: 0;
  list-style: none;
}

.abt-chips li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  padding: 0.16rem 0.52rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

.abt-journey-signals {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.45rem;
  margin: 0.95rem 0 0;
}

.abt-journey-signals > div {
  min-width: 0;
  border-radius: 0.65rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 70%, white);
  padding: 0.45rem 0.5rem 0.5rem;
}

.abt-journey-signals dt {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-journey-signals dd {
  margin: 0.22rem 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.abt-journey-operates {
  margin: 0.9rem 0 0;
  flex: 1;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--foreground);
}

.abt-journey-progress {
  display: flex;
  gap: 0.35rem;
  margin: 1.35rem 0 0;
  padding: 0;
  list-style: none;
}

.abt-journey-progress li {
  height: 0.28rem;
  flex: 1;
  border-radius: 999px;
  background: color-mix(in oklab, var(--border) 80%, var(--foreground));
}

.abt-journey-progress li[data-active="true"] {
  background: var(--primary);
}

/* Overview board */

.abt-overview-board {
  margin-top: 1.75rem;
  min-width: 0;
}

.abt-surfaces {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.8rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-surfaces > li {
  min-width: 0;
  height: 100%;
}

.abt-surface {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  min-width: 0;
  cursor: pointer;
  text-align: left;
  font: inherit;
  color: inherit;
  border-radius: 1.05rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1.1rem 1.15rem 1.05rem;
  box-shadow: var(--shadow-card);
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    transform 0.25s ease;
}

.abt-surface:hover,
.abt-surface:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 40%, var(--border));
  box-shadow: var(--shadow-lift);
  outline: none;
  transform: translateY(-2px);
}

.abt-surface[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 48%, var(--border));
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 8%, white) 0%,
      var(--card) 52%
    );
  box-shadow:
    var(--shadow-card),
    0 0 0 1px color-mix(in oklab, var(--primary) 16%, transparent);
}

.abt-surface-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
}

.abt-surface-meta span:first-child {
  color: var(--primary);
}

.abt-surface-meta span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted-foreground);
}

.abt-surface strong {
  display: block;
  margin-top: 0.7rem;
  font-family: var(--font-display);
  font-size: 1.08rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--foreground);
}

.abt-surface p {
  margin: 0.45rem 0 0;
  flex: 1;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

.abt-surface-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  width: fit-content;
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

.abt-surface-cta:hover,
.abt-surface-cta:focus-visible {
  text-decoration: underline;
  text-underline-offset: 0.16em;
  outline: none;
}

.abt-surface-dock {
  margin-top: 0.9rem;
  border-radius: 1.15rem;
  border: 1px solid var(--border);
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 7%, white) 0%,
      var(--card) 48%
    );
  padding: 1.15rem 1.2rem 1.2rem;
  box-shadow: var(--shadow-card);
}

.abt-surface-dock-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem 1rem;
}

.abt-surface-dock-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.abt-surface-dock h3 {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin: 0.35rem 0 0;
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2vw, 1.55rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.2;
  color: var(--foreground);
}

.abt-surface-dock h3 span {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  color: var(--primary);
}

.abt-surface-dock-body {
  margin: 0.7rem 0 0;
  max-width: 72ch;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--muted-foreground);
}

.abt-surface-dock .abt-chips {
  margin-top: 0.75rem;
}

.abt-readout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.45rem;
  margin: 0.9rem 0 0;
}

.abt-readout > div {
  min-width: 0;
  border-radius: 0.65rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 70%, white);
  padding: 0.5rem 0.6rem 0.55rem;
}

.abt-readout dt {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-readout dd {
  margin: 0.2rem 0 0;
  font-family: var(--font-display);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.abt-audiences {
  margin-top: 1.75rem;
  padding: 1.15rem 1.2rem 1.2rem;
  border-radius: 1.15rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--primary-soft) 55%, var(--card));
}

.abt-audiences-kicker {
  margin: 0 0 0.85rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.abt-audiences ul {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.65rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-audiences li {
  min-width: 0;
}

.abt-audience {
  display: block;
  height: 100%;
  min-width: 0;
  text-decoration: none;
  color: inherit;
  border-radius: 0.85rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 0.9rem 1rem;
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.abt-audience:hover,
.abt-audience:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 38%, var(--border));
  box-shadow: var(--shadow-card);
  outline: none;
}

.abt-audience strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.98rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.abt-audience p {
  margin: 0.35rem 0 0;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

/* Principles */

.abt-principles-board {
  margin-top: 2rem;
  min-width: 0;
}

.abt-principles {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-principles li {
  min-width: 0;
  border-radius: 1.05rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1.25rem 1.3rem 1.3rem;
  box-shadow: var(--shadow-card);
}

.abt-principles li > span {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--primary);
}

.abt-principles h3 {
  margin: 0.55rem 0 0;
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--foreground);
}

.abt-principles p {
  margin: 0.55rem 0 0;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--muted-foreground);
}

.abt-principles .abt-chips {
  margin-top: 0.85rem;
}

.abt-principle-contract {
  margin: 0.75rem 0 0 !important;
  padding-top: 0.7rem;
  border-top: 1px solid var(--border);
  font-size: 0.8rem !important;
  line-height: 1.5 !important;
  color: var(--foreground) !important;
}

.abt-principles-spine {
  margin-top: 0.85rem;
  border-radius: 1.05rem;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--border));
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 8%, white) 0%,
      var(--card) 55%
    );
  padding: 1.05rem 1.15rem 1.1rem;
}

.abt-principles-spine-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.abt-principles-spine > p:last-child {
  margin: 0.45rem 0 0;
  max-width: 78ch;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--muted-foreground);
}

/* Presence — dark offices band */

.abt-presence {
  display: grid;
  gap: 1.75rem;
  min-width: 0;
}

.abt-presence-sun {
  margin: 1rem 0 0;
  max-width: 42ch;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  line-height: 1.55;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.abt-presence-mail {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  margin: 1.35rem 0 0;
}

.abt-presence-mail span {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.abt-presence-mail a {
  width: fit-content;
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--primary);
  text-decoration: none;
}

.abt-presence-mail a:hover,
.abt-presence-mail a:focus-visible {
  text-decoration: underline;
  text-underline-offset: 0.18em;
}

.abt-offices {
  display: grid;
  gap: 0.7rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-offices li {
  display: grid;
  grid-template-columns: 2.1rem minmax(0, 1fr) auto;
  grid-template-rows: auto auto auto auto;
  column-gap: 0.75rem;
  row-gap: 0.18rem;
  align-items: start;
  min-width: 0;
  border-radius: 0.95rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
  padding: 0.95rem 1.05rem;
}

.abt-office-index {
  grid-row: 1 / span 2;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.abt-offices strong {
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--background);
}

.abt-offices em {
  grid-column: 2;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.abt-office-code {
  grid-column: 3;
  grid-row: 1 / span 2;
  align-self: center;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.18rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--primary);
}

.abt-office-window,
.abt-office-coverage {
  grid-column: 2 / -1;
  margin: 0;
}

.abt-office-window {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.abt-office-coverage {
  font-size: 0.78rem;
  line-height: 1.45;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

@media (min-width: 640px) {
  .abt-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .abt-surfaces {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .abt-audiences ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .abt-readout {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .abt-journey-signals {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .abt-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }

  .abt-facts {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.85rem;
  }

  .abt-journey {
    grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
    gap: clamp(1.1rem, 2.2vw, 1.75rem);
    align-items: stretch;
  }

  .abt-surfaces {
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 0.85rem;
  }

  .abt-surfaces > li:nth-child(-n + 3) {
    grid-column: span 2;
  }

  .abt-surfaces > li:nth-child(n + 4) {
    grid-column: span 3;
  }

  .abt-audiences ul {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .abt-principles {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.95rem;
  }

  .abt-presence {
    grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
    gap: clamp(1.5rem, 3vw, 2.75rem);
    align-items: center;
  }

  .abt-readout {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* 1280–1512: keep 3+2 tiles and journey columns from overflowing */
@media (min-width: 1024px) and (max-width: 1512px) {
  .abt-facts {
    gap: 0.7rem;
  }

  .abt-facts strong {
    font-size: clamp(1.2rem, 1.6vw, 1.5rem);
  }

  .abt-surface,
  .abt-journey-panel,
  .abt-principles li,
  .abt-surface-dock {
    padding-inline: 1.05rem;
  }

  .abt-surface strong {
    font-size: 1.02rem;
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .abt-room {
    height: clamp(18rem, 48vh, 26rem);
    max-height: clamp(18rem, 48vh, 26rem);
  }
}

@media (max-width: 1023px) {
  .abt-stage,
  .abt-room,
  .abt-facts,
  .abt-journey,
  .abt-surfaces,
  .abt-audiences,
  .abt-principles,
  .abt-presence,
  .abt-offices,
  .abt-ops,
  .abt-surface-dock,
  .abt-overview-board {
    min-width: 0;
    max-width: 100%;
  }

  .abt-stage {
    overflow-x: clip;
    padding: 0;
  }

  .abt-room {
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
    transform: rotateY(-5deg) rotateX(2.5deg);
  }

  .abt-head-title,
  .abt-rail-copy strong,
  .abt-atlas-caption,
  .abt-surface p,
  .abt-audience p,
  .abt-principles p,
  .abt-facts p {
    overflow-wrap: anywhere;
  }
}

@media (max-width: 639px) {
  .abt-room {
    transform: none;
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    gap: 0.32rem;
    padding: 0.5rem 0.55rem 0.48rem;
  }

  .abt-head {
    flex-wrap: wrap;
  }

  .abt-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 0.32rem;
  }

  .abt-rail {
    flex-direction: row;
    overflow-x: auto;
    overflow-y: hidden;
    gap: 0.2rem;
  }

  .abt-rail li {
    flex: 0 0 auto;
    padding: 0;
  }

  .abt-rail button {
    grid-template-columns: auto;
    padding: 0.18rem 0.4rem;
  }

  .abt-rail-copy {
    display: none;
  }

  .abt-atlas-caption,
  .abt-city-name,
  .abt-coverage {
    display: none;
  }

  .abt-atlas-wrap {
    grid-template-rows: minmax(0, 1fr);
  }

  .abt-foot > div {
    padding: 0.28rem 0.32rem;
  }

  .abt-journey-list button,
  .abt-surface,
  .abt-audience,
  .abt-principles li,
  .abt-offices li,
  .abt-surface-dock,
  .abt-ops {
    overflow-wrap: anywhere;
  }

  .abt-journey-signals,
  .abt-readout {
    grid-template-columns: 1fr;
  }

  .abt-journey-stack-inline {
    white-space: normal;
  }
}

@container abt (max-width: 22rem) {
  .abt-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .abt-rail {
    flex-direction: row;
    overflow-x: auto;
  }

  .abt-rail-copy {
    display: none;
  }

  .abt-city-name,
  .abt-atlas-caption,
  .abt-coverage {
    display: none;
  }
}

@container abt (max-height: 20rem) {
  .abt-atlas-caption,
  .abt-city-name,
  .abt-head-stamp,
  .abt-coverage {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .abt-room {
    transform: none;
  }

  .abt-stage[data-live="true"] .abt-live-dot,
  .abt-stage[data-live="true"] .abt-city-ring,
  .abt-stage[data-live="true"] .abt-arc,
  .abt-journey[data-live="true"] .abt-journey-path .abt-live-dot,
  .abt-ops[data-live="true"] .abt-ops-feed,
  .abt-ops[data-live="true"] .abt-ops-sun li[data-status="live"] i {
    animation: none;
  }

  .abt-surface:hover,
  .abt-surface:focus-visible {
    transform: none;
  }

  .abt-ops .lc-tilt-card,
  .abt-ops .lc-tilt-wrap {
    transform: none;
  }
}

/* Company ops console — unique to /about (not a channel/price ticker) */

.abt-ops {
  width: 100%;
  min-width: 0;
  container: abt-ops / inline-size;
}

.abt-ops .lc-body {
  gap: 0.55rem;
}

.abt-ops-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.4rem;
}

.abt-ops-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.abt-ops-sun {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.55rem 0.6rem 0.6rem;
  min-width: 0;
}

.abt-ops-sun ul {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-ops-sun li {
  display: grid;
  grid-template-columns: 2.4rem minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 0.45rem;
  row-gap: 0.18rem;
  align-items: center;
  min-width: 0;
  border-radius: 0.55rem;
  border: 1px solid transparent;
  padding: 0.32rem 0.4rem 0.38rem;
}

.abt-ops-sun li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.abt-ops-sun strong {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--foreground);
}

.abt-ops-sun em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-style: normal;
  font-weight: 650;
  color: var(--muted-foreground);
}

.abt-ops-sun li > span {
  grid-column: 3;
  grid-row: 1;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-foreground);
}

.abt-ops-sun li[data-status="live"] > span {
  color: var(--primary);
}

.abt-ops-sun li > i {
  grid-column: 1 / -1;
  grid-row: 2;
  display: block;
  height: 0.28rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--border) 80%, var(--foreground));
  overflow: hidden;
}

.abt-ops-sun li > i::after {
  content: "";
  display: block;
  height: 100%;
  width: 34%;
  border-radius: inherit;
  background: color-mix(in oklab, var(--muted-foreground) 35%, transparent);
}

.abt-ops-sun li[data-status="covering"] > i::after {
  width: 62%;
  background: color-mix(in oklab, var(--primary) 55%, transparent);
}

.abt-ops-sun li[data-status="live"] > i::after {
  width: 100%;
  background: var(--primary);
}

.abt-ops[data-live="true"] .abt-ops-sun li[data-status="live"] i::after {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.abt-ops-work {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  min-width: 0;
  min-height: 0;
  flex: 1;
}

.abt-ops-desks,
.abt-ops-feed-panel {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  min-width: 0;
  min-height: 0;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 68%, white);
  padding: 0.55rem 0.6rem 0.6rem;
}

.abt-ops-table {
  display: grid;
  gap: 0.18rem;
  min-width: 0;
}

.abt-ops-row {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1.1fr) minmax(0, 0.9fr) 4.4rem;
  gap: 0.35rem;
  align-items: center;
  min-width: 0;
  border-radius: 0.45rem;
  padding: 0.28rem 0.35rem;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}

.abt-ops-row-head {
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
}

.abt-ops-row[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 9%, transparent);
  color: var(--foreground);
}

.abt-ops-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.abt-ops-row strong {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--foreground);
}

.abt-ops-row [data-status] {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.abt-ops-row [data-status="live"] {
  color: var(--primary);
}

.abt-ops-handoff,
.abt-ops-selected {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.45;
  color: var(--muted-foreground);
}

.abt-ops-handoff span,
.abt-ops-selected strong {
  display: inline-block;
  margin-right: 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.abt-ops[data-live="true"] .abt-ops-feed {
  animation: lc-feed-scroll 18s linear infinite;
}

@container abt-ops (min-width: 28rem) {
  .abt-ops-sun ul {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .abt-ops-work {
    grid-template-columns: minmax(0, 1.25fr) minmax(0, 0.9fr);
  }
}

@media (max-width: 639px) {
  .abt-ops .lc-screen {
    height: auto;
    min-height: 0;
    max-height: none;
  }

  .abt-ops-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .abt-ops-row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto;
  }

  .abt-ops-row-head {
    display: none;
  }

  .abt-ops-row span:nth-child(2),
  .abt-ops-row span:nth-child(3) {
    display: none;
  }
}

/* ── /book-demo — session briefing hero (bdm-*) ────────────────────
   Unique briefing desk (calendar slots + agenda). Not a clone of
   bh-wall / tpd / mkh / eih / apidoc / abt atlas. Room frame matches
   other product heroes: clamp(22rem, 52vh, 34rem) / tablet 18–26 /
   phone 16–22. Extra hero padding clears the overlay nav. */

.bh-hero.bdm-hero,
.bh-hero.plt-hero {
  padding-bottom: clamp(2.75rem, 5.5vw, 5rem);
}

@media (min-width: 1024px) {
  .bh-hero.bdm-hero,
  .bh-hero.plt-hero {
    padding-bottom: clamp(3.25rem, 5vh, 5.25rem);
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .bh-hero.bdm-hero,
  .bh-hero.plt-hero {
    padding-bottom: clamp(2.25rem, 3.5vh, 3.25rem);
  }
}

@media (max-width: 639px) {
  .bh-hero.bdm-hero,
  .bh-hero.plt-hero {
    padding-bottom: clamp(2.35rem, 8vw, 3.5rem);
  }
}

.bdm-stage {
  position: relative;
  min-width: 0;
  max-width: 100%;
  padding: 0.2rem 0.15rem 0.35rem;
}

.bdm-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0.42rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.55rem 0.62rem 0.52rem;
  overflow: hidden;
  container: bdm / size;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 16%, transparent) 0%,
      transparent 38%
    ),
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 42%
    ),
    color-mix(in oklab, black 54%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
  font-family: var(--font-sans);
}

.bdm-room::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background-image: repeating-linear-gradient(
    90deg,
    transparent,
    transparent 11px,
    color-mix(in oklab, var(--background) 5%, transparent) 12px
  );
  opacity: 0.35;
  mask-image: linear-gradient(180deg, transparent 0%, black 28%, black 100%);
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, black 28%, black 100%);
}

.bdm-head,
.bdm-body,
.bdm-foot,
.bdm-slots,
.bdm-brief {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.bdm-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 0.75rem;
  flex-shrink: 0;
}

.bdm-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.bdm-live-dot {
  width: 0.38rem;
  height: 0.38rem;
  flex-shrink: 0;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
}

.bdm-stage[data-live="true"] .bdm-live-dot {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.bdm-head-title {
  margin: 0.12rem 0 0;
  font-family: var(--font-display);
  font-size: 0.82rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--background);
}

.bdm-head-meta {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.35rem;
}

.bdm-chip {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--background) 14%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
  padding: 0.14rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.bdm-chip-live {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.bdm-chip-live i {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--primary);
}

.bdm-stage[data-live="true"] .bdm-chip-live i {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.bdm-body {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: 0.45rem;
  min-height: 0;
}

.bdm-slots {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  min-height: 0;
  margin: 0;
  padding: 0.35rem;
  overflow: hidden;
  list-style: none;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, black 28%, transparent);
}

.bdm-slots li {
  display: grid;
  grid-template-columns: 2.7rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  padding: 0.32rem 0.4rem;
}

.bdm-slots li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 38%, transparent);
  background: color-mix(in oklab, var(--primary) 14%, transparent);
}

.bdm-slot-time {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: color-mix(in oklab, var(--background) 78%, transparent);
}

.bdm-slots li[data-active="true"] .bdm-slot-time {
  color: var(--primary);
}

.bdm-slot-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.04rem;
}

.bdm-slot-copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.72rem;
  font-weight: 650;
  color: color-mix(in oklab, var(--background) 86%, transparent);
}

.bdm-slot-copy em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-style: normal;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.bdm-slot-zone {
  border-radius: 0.3rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  padding: 0.08rem 0.32rem;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.bdm-slots li[data-active="true"] .bdm-slot-zone {
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  color: var(--primary);
}

.bdm-brief {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--primary) 8%, transparent),
      transparent 40%
    ),
    color-mix(in oklab, black 22%, transparent);
  padding: 0.45rem 0.5rem 0.48rem;
}

.bdm-brief-kicker {
  margin: 0 0 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.bdm-agenda {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.22rem;
  min-height: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bdm-agenda li {
  display: grid;
  grid-template-columns: 1.55rem minmax(0, 1fr);
  align-items: start;
  gap: 0.4rem;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  padding: 0.28rem 0.35rem;
}

.bdm-agenda li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.bdm-agenda-index {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 42%, transparent);
}

.bdm-agenda li[data-active="true"] .bdm-agenda-index {
  color: var(--primary);
}

.bdm-agenda strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.72rem;
  font-weight: 650;
  color: color-mix(in oklab, var(--background) 88%, transparent);
}

.bdm-agenda em {
  display: block;
  margin-top: 0.08rem;
  font-size: 0.62rem;
  font-style: normal;
  line-height: 1.35;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.bdm-attend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin-top: 0.4rem;
}

.bdm-attend span {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
  padding: 0.16rem 0.48rem;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.bdm-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.25rem 0.75rem;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.bdm-who {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.9rem;
  margin: 1.75rem 0 0;
  padding: 0;
  list-style: none;
}

.bdm-who > li {
  min-width: 0;
  height: 100%;
}

.bdm-who-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  border-radius: 1.1rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1.25rem 1.3rem 1.2rem;
  box-shadow: var(--shadow-card);
}

.bdm-who-card[data-track="travel"] {
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 7%, white) 0%,
      var(--card) 48%
    );
}

.bdm-who-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.bdm-who-card h3 {
  margin: 0.55rem 0 0;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.2;
  color: var(--foreground);
}

.bdm-who-card > p {
  margin: 0.55rem 0 0;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--muted-foreground);
}

.bdm-who-card ul {
  display: grid;
  gap: 0.35rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
}

.bdm-who-card ul li {
  position: relative;
  padding-left: 0.9rem;
  font-size: 0.8125rem;
  color: var(--foreground);
}

.bdm-who-card ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5em;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--primary);
}

.bdm-who-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  margin-top: 1.1rem;
  width: fit-content;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
  text-decoration: none;
}

.bdm-who-cta:hover,
.bdm-who-cta:focus-visible {
  text-decoration: underline;
  text-underline-offset: 0.18em;
  outline: none;
}

.bdm-who-also {
  margin: 1.35rem 0 0;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

.bdm-who-also a {
  color: var(--foreground);
  text-decoration: none;
  font-weight: 600;
}

.bdm-who-also a:hover,
.bdm-who-also a:focus-visible {
  color: var(--primary);
  outline: none;
}

.bdm-field-error {
  display: block;
  margin-top: 0.35rem;
  font-size: 0.75rem;
  line-height: 1.4;
  color: oklch(0.52 0.16 25);
}

.bdm-success-dl {
  display: grid;
  gap: 0.65rem;
  margin: 1.15rem 0 0;
}

.bdm-success-dl div {
  display: grid;
  gap: 0.12rem;
  padding-bottom: 0.55rem;
  border-bottom: 1px solid var(--border);
}

.bdm-success-dl dt {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.bdm-success-dl dd {
  margin: 0;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--foreground);
}

@media (min-width: 768px) {
  .bdm-who {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .bdm-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .bdm-room {
    height: clamp(18rem, 48vh, 26rem);
    max-height: clamp(18rem, 48vh, 26rem);
  }
}

@media (max-width: 1023px) {
  .bdm-stage,
  .bdm-room,
  .bdm-who {
    min-width: 0;
    max-width: 100%;
  }

  .bdm-stage {
    overflow-x: clip;
    padding: 0;
  }

  .bdm-room {
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
    transform: rotateY(-5deg) rotateX(2.5deg);
  }

  .bdm-head-title,
  .bdm-slot-copy strong,
  .bdm-agenda strong,
  .bdm-who-card h3,
  .bdm-who-card > p {
    overflow-wrap: anywhere;
  }
}

@media (max-width: 639px) {
  .bdm-room {
    transform: none;
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    gap: 0.32rem;
    padding: 0.5rem 0.55rem 0.48rem;
  }

  .bdm-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 0.32rem;
  }

  .bdm-slots {
    flex-direction: row;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .bdm-slots li {
    flex: 0 0 auto;
    grid-template-columns: auto;
    padding: 0.18rem 0.45rem;
  }

  .bdm-slot-copy,
  .bdm-agenda em,
  .bdm-attend,
  .bdm-foot span:last-child {
    display: none;
  }

  .bdm-who-card {
    overflow-wrap: anywhere;
  }
}

@container bdm (max-width: 22rem) {
  .bdm-body {
    grid-template-columns: 1fr;
  }

  .bdm-slot-copy,
  .bdm-agenda em {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bdm-room {
    transform: none;
  }

  .bdm-stage[data-live="true"] .bdm-live-dot,
  .bdm-stage[data-live="true"] .bdm-chip-live i {
    animation: none;
  }
}

/* ── /platform — stack map hero (plt-*) ───────────────────────────
   Unique hub + spine (not a dashboard, mosaic, docs console, atlas
   or briefing desk). Same room clamps as other product heroes. */

.plt-stage {
  position: relative;
  min-width: 0;
  max-width: 100%;
  padding: 0.2rem 0.15rem 0.35rem;
}

.plt-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0.42rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.55rem 0.62rem 0.52rem;
  overflow: hidden;
  container: plt / size;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    radial-gradient(
      ellipse at 18% 88%,
      color-mix(in oklab, var(--primary) 16%, transparent),
      transparent 46%
    ),
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 42%
    ),
    color-mix(in oklab, black 54%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
}

.plt-room::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 13px,
    color-mix(in oklab, var(--background) 5%, transparent) 14px
  );
  opacity: 0.28;
  mask-image: linear-gradient(90deg, black 0%, transparent 72%);
  -webkit-mask-image: linear-gradient(90deg, black 0%, transparent 72%);
}

.plt-head,
.plt-body,
.plt-foot,
.plt-spine,
.plt-hub {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.plt-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 0.75rem;
  flex-shrink: 0;
}

.plt-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.plt-live-dot {
  width: 0.38rem;
  height: 0.38rem;
  flex-shrink: 0;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
}

.plt-stage[data-live="true"] .plt-live-dot {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.plt-head-title {
  margin: 0.12rem 0 0;
  font-family: var(--font-display);
  font-size: 0.82rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--background);
}

.plt-head-stamp {
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  padding: 0.14rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--primary);
}

.plt-body {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  min-height: 0;
}

.plt-hub {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-shrink: 0;
  border-radius: 0.7rem;
  border: 1px solid color-mix(in oklab, var(--primary) 38%, transparent);
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  padding: 0.42rem 0.55rem;
}

.plt-hub-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  flex-shrink: 0;
  border-radius: 0.4rem;
  background: var(--primary);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--primary-foreground);
}

.plt-hub strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--background);
}

.plt-hub em {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  font-style: normal;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.plt-spine {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.16rem;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
  list-style: none;
}

.plt-spine li {
  display: grid;
  grid-template-columns: 0.7rem 1.7rem minmax(0, 1fr);
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  padding: 0.28rem 0.4rem 0.28rem 0.2rem;
}

.plt-spine li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 34%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.plt-spine-rail {
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
}

.plt-spine-rail i {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 28%, transparent);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--background) 6%, transparent);
}

.plt-spine li[data-active="true"] .plt-spine-rail i {
  background: var(--primary);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--primary) 22%, transparent);
}

.plt-stage[data-live="true"] .plt-spine li[data-active="true"] .plt-spine-rail i {
  animation: two-track-live-pulse 2s ease-in-out infinite;
}

.plt-spine-index {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 40%, transparent);
}

.plt-spine li[data-active="true"] .plt-spine-index {
  color: var(--primary);
}

.plt-spine-copy {
  display: flex;
  min-width: 0;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.plt-spine-copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.74rem;
  font-weight: 650;
  color: color-mix(in oklab, var(--background) 84%, transparent);
}

.plt-spine li[data-active="true"] .plt-spine-copy strong {
  color: var(--background);
}

.plt-spine-copy em {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.48rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 40%, transparent);
}

.plt-spine li[data-active="true"] .plt-spine-copy em {
  color: var(--primary);
}

.plt-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.25rem 0.75rem;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.plt-map {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.8rem;
  margin: 1.75rem 0 0;
  padding: 0;
  list-style: none;
}

.plt-map > li {
  min-width: 0;
  height: 100%;
}

.plt-map-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  text-decoration: none;
  color: inherit;
  border-radius: 1.05rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 6%, transparent);
  padding: 1.1rem 1.15rem 1.05rem;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    transform 0.25s ease;
}

.plt-map-card:hover,
.plt-map-card:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 42%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  outline: none;
  transform: translateY(-2px);
}

.plt-map-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
}

.plt-map-meta span:first-child {
  color: var(--primary);
}

.plt-map-meta span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.plt-map-card strong {
  display: block;
  margin-top: 0.7rem;
  font-family: var(--font-display);
  font-size: 1.08rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--background);
}

.plt-map-card p {
  margin: 0.45rem 0 0;
  flex: 1;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.plt-map-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  margin-top: 0.95rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--primary);
}

@media (min-width: 640px) {
  .plt-map {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .plt-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }

  .plt-map {
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 0.85rem;
  }

  .plt-map > li:nth-child(-n + 3) {
    grid-column: span 2;
  }

  .plt-map > li:nth-child(n + 4) {
    grid-column: span 3;
  }
}

@media (min-width: 1024px) and (max-width: 1512px) {
  .plt-map-card {
    padding-inline: 1.05rem;
  }

  .plt-map-card strong {
    font-size: 1.02rem;
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .plt-room {
    height: clamp(18rem, 48vh, 26rem);
    max-height: clamp(18rem, 48vh, 26rem);
  }
}

@media (max-width: 1023px) {
  .plt-stage,
  .plt-room,
  .plt-map {
    min-width: 0;
    max-width: 100%;
  }

  .plt-stage {
    overflow-x: clip;
    padding: 0;
  }

  .plt-room {
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
    transform: rotateY(-5deg) rotateX(2.5deg);
  }

  .plt-head-title,
  .plt-spine-copy strong,
  .plt-map-card p {
    overflow-wrap: anywhere;
  }
}

@media (max-width: 639px) {
  .plt-room {
    transform: none;
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    gap: 0.32rem;
    padding: 0.5rem 0.55rem 0.48rem;
  }

  .plt-hub em,
  .plt-spine-copy em,
  .plt-foot span:last-child {
    display: none;
  }

  .plt-map-card {
    overflow-wrap: anywhere;
  }
}

@container plt (max-width: 22rem) {
  .plt-hub em,
  .plt-spine-copy em {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .plt-room {
    transform: none;
  }

  .plt-stage[data-live="true"] .plt-live-dot,
  .plt-stage[data-live="true"] .plt-spine li[data-active="true"] .plt-spine-rail i {
    animation: none;
  }

  .plt-map-card:hover,
  .plt-map-card:focus-visible {
    transform: none;
  }
}

/* ── /book-demo — 45-min session itinerary (bds-*) ─────────────────
   Replaces FeatureGrid on the conversion page. Numbered duration cards
   + proportional minute ruler. Not a live console, not mcb/ecb/orbit. */

.bds-title {
  margin: 1rem 0 0;
  max-width: 38rem;
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 1.4rem + 1.2vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -0.035em;
  line-height: 1.15;
  color: var(--foreground);
}

.bds-intro {
  margin: 1rem 0 0;
  max-width: 36rem;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.bds-board {
  --bds-cols: 10fr 12fr 12fr 11fr;
  display: grid;
  gap: 0.85rem;
  min-width: 0;
  padding: 1rem 1.05rem 1.05rem;
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--primary) 6%, var(--card)) 0%,
      var(--card) 22%
    );
  box-shadow: var(--shadow-card);
}

.bds-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.45rem 0.85rem;
  min-width: 0;
  padding: 0.1rem 0.15rem 0.85rem;
  border-bottom: 1px solid var(--border);
}

.bds-toolbar-kicker {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.bds-toolbar-right {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem 0.7rem;
}

.bds-live {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, white);
  padding: 0.18rem 0.55rem 0.18rem 0.42rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary-deep);
}

.bds-live i {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary) 22%, transparent);
}

.bds-section[data-live="true"] .bds-live i {
  animation: two-track-live-pulse 1.6s ease-out infinite;
}

.bds-toolbar-meta {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  color: var(--muted-foreground);
}

.bds-ruler {
  position: relative;
  display: grid;
  grid-template-columns: var(--bds-cols);
  gap: 0.35rem;
  min-width: 0;
  padding: 0.15rem 0.1rem 0.15rem;
}

.bds-seg {
  position: relative;
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: flex-end;
  gap: 0.28rem;
  padding-top: 1.05rem;
}

.bds-playhead {
  position: absolute;
  top: 0.1rem;
  left: 50%;
  z-index: 2;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 999px;
  background: var(--primary);
  opacity: 0;
  box-shadow:
    0 0 0 4px color-mix(in oklab, var(--primary) 20%, transparent),
    0 4px 10px color-mix(in oklab, var(--primary) 35%, transparent);
  transform: translateX(-50%);
  transition: opacity 0.35s ease;
}

.bds-seg[data-active="true"] .bds-playhead {
  opacity: 1;
}

.bds-playhead::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  width: 1.5px;
  height: 0.55rem;
  background: var(--primary);
  transform: translateX(-50%);
}

.bds-seg-label {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bds-seg[data-active="true"] .bds-seg-label {
  color: var(--primary-deep);
}

.bds-seg-bar {
  height: 0.48rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 16%, var(--surface));
  transition: background 0.35s ease;
}

.bds-seg[data-active="true"] .bds-seg-bar {
  background: var(--primary);
  box-shadow: 0 0 12px color-mix(in oklab, var(--primary) 35%, transparent);
}

.bds-ruler-ends {
  display: flex;
  justify-content: space-between;
  padding: 0 0.1rem 0.15rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.bds-cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.7rem;
  margin: 0.15rem 0 0;
  padding: 0;
  list-style: none;
}

.bds-cards > li {
  min-width: 0;
  height: 100%;
}

.bds-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  padding: 1rem 1.05rem 1.05rem;
  border: 1px solid var(--border);
  border-radius: 1rem;
  background: var(--card);
  box-shadow: var(--shadow-card);
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.bds-card[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--border));
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 8%, white) 0%,
      var(--card) 48%
    );
  box-shadow:
    var(--shadow-card),
    0 0 0 1px color-mix(in oklab, var(--primary) 16%, transparent);
}

.bds-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.bds-card-index {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.bds-card-mins {
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  padding: 0.12rem 0.48rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--muted-foreground);
  white-space: nowrap;
}

.bds-card[data-active="true"] .bds-card-mins {
  border-color: color-mix(in oklab, var(--primary) 30%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, white);
  color: var(--primary-deep);
}

.bds-card h3 {
  margin: 0.7rem 0 0;
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.25;
  color: var(--foreground);
  overflow-wrap: anywhere;
}

.bds-card-body {
  margin: 0.5rem 0 0;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

.bds-outcome {
  display: grid;
  gap: 0.2rem;
  margin-top: auto;
  padding-top: 0.85rem;
}

.bds-outcome span {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.bds-outcome strong {
  font-size: 0.78rem;
  font-weight: 600;
  line-height: 1.45;
  color: var(--foreground);
}

.bds-now {
  display: grid;
  gap: 0.28rem;
  min-width: 0;
  margin-top: 0.15rem;
  padding: 0.85rem 0.95rem;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, var(--border));
  border-radius: 0.9rem;
  background: color-mix(in oklab, var(--primary) 7%, var(--surface));
}

.bds-now-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem 0.7rem;
}

.bds-now-kicker {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.bds-now-chip {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--primary-deep);
}

.bds-now strong {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
  overflow-wrap: anywhere;
}

.bds-now > p {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

@media (min-width: 640px) {
  .bds-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .bds-board {
    padding: 1.15rem 1.2rem 1.2rem;
    gap: 0.95rem;
  }
}

@media (min-width: 1024px) {
  .bds-cards {
    grid-template-columns: var(--bds-cols);
    gap: 0.75rem;
  }

  .bds-card h3 {
    font-size: 1.05rem;
  }

  .bds-now {
    grid-template-columns: minmax(0, 16rem) minmax(0, 1fr);
    grid-template-rows: auto auto;
    column-gap: 1.25rem;
    align-items: start;
  }

  .bds-now-meta {
    grid-column: 1;
    grid-row: 1;
  }

  .bds-now strong {
    grid-column: 1;
    grid-row: 2;
  }

  .bds-now > p {
    grid-column: 2;
    grid-row: 1 / span 2;
    align-self: center;
    font-size: 0.875rem;
  }
}

@media (min-width: 1280px) {
  .bds-card {
    padding: 1.1rem 1.15rem 1.15rem;
  }

  .bds-card h3 {
    font-size: 1.12rem;
  }
}

@media (max-width: 1023px) {
  .bds-section,
  .bds-board,
  .bds-ruler,
  .bds-cards,
  .bds-now {
    min-width: 0;
    max-width: 100%;
  }

  .bds-board {
    overflow-x: clip;
  }

  .bds-title,
  .bds-card h3,
  .bds-now strong,
  .bds-outcome strong {
    overflow-wrap: anywhere;
  }
}

@media (max-width: 639px) {
  .bds-ruler {
    gap: 0.22rem;
  }

  .bds-seg-label {
    font-size: 0.52rem;
  }

  .bds-playhead {
    width: 0.58rem;
    height: 0.58rem;
  }

  .bds-card {
    padding: 0.95rem 1rem 1rem;
  }

  .bds-now-chip {
    margin-left: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bds-playhead,
  .bds-seg-bar,
  .bds-card {
    transition: none;
  }

  .bds-section[data-live="true"] .bds-live i {
    animation: none;
  }
}

/* == Site nav (mobile sheet) ==
   Bar stays 4.5rem (same as .hero-fit-offset / h-18) so heroes are not re-cropped.
   Fixed overlay on heroes with an opaque light bar (not glass/blur). */
.site-nav {
  position: fixed;
  inset-inline: 0;
  top: 0;
  z-index: 50;
  isolation: isolate;
  overflow-x: clip;
}

.site-nav .container-nav {
  padding-inline: max(clamp(0.875rem, 1.5vw, 1.75rem), env(safe-area-inset-left))
    max(clamp(0.875rem, 1.5vw, 1.75rem), env(safe-area-inset-right));
}

.site-nav-bar {
  position: relative;
  z-index: 2;
  border-bottom: 1px solid var(--border);
  background: var(--background);
}

.site-nav-logo {
  max-width: min(100%, 12rem);
}

@media (min-width: 400px) {
  .site-nav-logo {
    max-width: min(100%, 17.5rem);
  }
}

.site-nav a,
.site-nav button {
  -webkit-tap-highlight-color: transparent;
}

.site-nav-toggle {
  touch-action: manipulation;
  -webkit-appearance: none;
  appearance: none;
  border: 0;
  background: transparent;
}

.site-nav-toggle:focus,
.site-nav-sheet:focus {
  outline: none;
}

.site-nav-toggle:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.site-nav-layer {
  position: fixed;
  inset: 0;
  z-index: 1;
  visibility: hidden;
  pointer-events: none;
  transition: visibility 0s 0.3s;
}

.site-nav-layer[data-open="true"] {
  visibility: visible;
  pointer-events: auto;
  transition-delay: 0s;
}

.site-nav-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  padding: 0;
  cursor: pointer;
  background: color-mix(in oklab, var(--dark) 48%, transparent);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.site-nav-layer[data-open="true"] .site-nav-backdrop {
  opacity: 1;
}

.site-nav-sheet {
  position: absolute;
  top: 4.5rem;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  height: calc(100dvh - 4.5rem);
  max-height: calc(100dvh - 4.5rem);
  overflow: hidden;
  background: var(--background);
  opacity: 0;
  transform: translateY(-0.5rem);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.site-nav-layer[data-open="true"] .site-nav-sheet {
  opacity: 1;
  transform: none;
}

.site-nav-links {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding-block: 0.75rem 0.5rem;
}

.site-nav-link {
  display: flex;
  align-items: center;
  min-height: 2.75rem;
  padding: 0.875rem 1rem;
  border: 0;
  border-radius: 0.5rem;
  box-shadow: none;
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  font-size: 1rem;
  font-weight: 600;
  color: var(--foreground);
  text-wrap: balance;
  -webkit-tap-highlight-color: transparent;
}

.site-nav-link:hover {
  background: var(--secondary);
}

.site-nav-link.is-active {
  background: color-mix(in oklab, var(--primary) 5%, transparent);
  color: var(--primary);
}

.site-nav-link.is-active:hover {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.site-nav-link:focus,
.site-nav-cta:focus {
  outline: none;
  box-shadow: none;
}

.site-nav-link:focus-visible,
.site-nav-cta:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* iOS Safari treats tap + programmatic focus as :focus-visible and paints a
   box around the first sheet link (For Brokers). Kill rings on coarse pointers;
   keyboard users on fine pointers still get the outline above. */
@media (hover: none), (pointer: coarse) {
  .site-nav-link:focus,
  .site-nav-link:focus-visible,
  .site-nav-cta:focus,
  .site-nav-cta:focus-visible,
  .site-nav-toggle:focus,
  .site-nav-toggle:focus-visible,
  .site-nav-sheet:focus,
  .site-nav-sheet:focus-visible {
    outline: none;
    box-shadow: none;
  }
}

.site-nav-ctas {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  padding-bottom: max(1rem, env(safe-area-inset-bottom));
}

.site-nav-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.75rem 1rem;
  border: 0;
  border-radius: 0.5rem;
  -webkit-appearance: none;
  appearance: none;
  font-size: 1rem;
  font-weight: 600;
  text-align: center;
  -webkit-tap-highlight-color: transparent;
}

.site-nav-cta-login {
  border: 1px solid var(--border);
  color: var(--foreground);
}

.site-nav-cta-login:hover {
  background: var(--secondary);
}

.site-nav-cta-demo {
  background: var(--primary);
  color: var(--primary-foreground);
}

html.site-nav-locked,
html.site-nav-locked body {
  overflow: hidden !important;
  overscroll-behavior: none;
}

@media (max-width: 359px) {
  .site-nav-logo {
    height: 2.75rem;
    max-width: min(100%, 10.25rem);
  }

  .site-nav-link,
  .site-nav-cta {
    padding-inline: 0.75rem;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .site-nav-sheet {
    left: auto;
    width: min(24rem, 100%);
    border-left: 1px solid var(--border);
    box-shadow: -18px 0 40px -24px color-mix(in oklab, var(--ink) 35%, transparent);
    transform: translateX(1.25rem);
  }

  .site-nav-layer[data-open="true"] .site-nav-sheet {
    transform: none;
  }
}

@media (max-height: 500px) {
  .site-nav-links {
    padding-top: 0.35rem;
    padding-bottom: 0.25rem;
  }

  .site-nav-link {
    padding-block: 0.625rem;
  }

  .site-nav-ctas {
    gap: 0.5rem;
    padding-top: 0.75rem;
    padding-bottom: max(0.75rem, env(safe-area-inset-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  .site-nav-bar,
  .site-nav-backdrop,
  .site-nav-sheet,
  .site-nav-toggle svg {
    transition: none;
  }
}

/* StickyScrollShowcase live consoles (sss-*) ------------------------------- */

.sss-sticky {
  --sss-console-h: clamp(28rem, 58dvh, 34rem);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  height: calc(100dvh - 6rem);
  padding-block: 1.25rem;
  min-height: 0;
}

.sss-sticky-stage {
  flex: 0 0 auto;
  min-width: 0;
  height: var(--sss-console-h);
  min-height: var(--sss-console-h);
  max-height: var(--sss-console-h);
  overflow: hidden;
}

.sss-slider {
  display: flex;
  height: 100%;
  will-change: transform;
}

.sss-slide {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  padding-inline: 0.15rem;
}

.sss-caption {
  position: relative;
  flex-shrink: 0;
  height: 2.75rem;
  overflow: hidden;
}

.sss-caption-line {
  position: absolute;
  inset-inline: 0;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: none;
  color: var(--muted-foreground);
  transition:
    opacity 0.5s ease,
    transform 0.5s ease;
}

.sss-dots {
  display: flex;
  flex-shrink: 0;
  justify-content: center;
  gap: 0.375rem;
}

.sss-dot {
  height: 0.25rem;
  width: 0.5rem;
  border-radius: 999px;
  background: var(--primary);
  opacity: 0.35;
  transition:
    width 0.5s ease,
    opacity 0.5s ease;
}

.sss-dot-on {
  width: 2rem;
  opacity: 1;
}

.sss-mobile,
.sss-stage,
.sss-stage .lc-frame,
.sss-stage .lc-bezel {
  min-width: 0;
  width: 100%;
  max-width: 100%;
}

.sss-stage {
  --sss-console-h: clamp(22.5rem, 58svh, 28rem);
  container-type: inline-size;
  container-name: sss;
  height: var(--sss-console-h);
  min-height: var(--sss-console-h);
  max-height: var(--sss-console-h);
  overflow: hidden;
}

.sss-stage .lc-frame,
.sss-stage .lc-bezel,
.sss-stage .lc-screen {
  height: 100%;
  min-height: 0;
  max-height: 100%;
}

.sss-stage .lc-frame {
  display: flex;
  flex-direction: column;
}

.sss-stage .lc-bezel {
  display: flex;
  flex-direction: column;
  padding: 0.45rem;
}

.sss-stage .lc-screen {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
}

.sss-stage .lc-body {
  flex: 1 1 auto;
  min-height: 0;
  gap: 0.5rem;
  padding: 0.6rem 0.65rem 0.55rem;
}

.sss-stage .two-track-chrome {
  padding: 0.5rem 0.75rem;
}

.sss-stage .two-track-chrome-path {
  font-size: 10px;
}

.sss-mobile .sss-stage .lc-screen {
  height: 100%;
  min-height: 0;
  max-height: 100%;
}

.sss-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.4rem;
  flex-shrink: 0;
}

.sss-stage .lc-stat {
  padding: 0.4rem 0.5rem;
}

.sss-stage .lc-stat-value {
  font-size: clamp(0.82rem, 1.8vw, 1.02rem);
}

.sss-tick {
  color: var(--primary);
}

.sss-context {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  min-width: 0;
}

.sss-context-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--muted-foreground);
}

.sss-context-title {
  margin: 0.12rem 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: clamp(0.78rem, 1.7vw, 0.92rem);
  font-weight: 650;
  color: var(--foreground);
}

.sss-chip {
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  padding: 0.18rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.sss-work {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 0.5rem;
  flex: 1 1 auto;
  min-height: 0;
}

.sss-panel {
  min-height: 0;
  height: 100%;
}

.sss-channels {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sss-channel {
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  min-width: 0;
  border-radius: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 80%, white);
  padding: 0.28rem 0.32rem;
}

.sss-channel strong {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.04em;
  color: var(--foreground);
}

.sss-channel span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  color: var(--muted-foreground);
}

.sss-channel[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 32%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, white);
}

.sss-spark {
  display: flex;
  align-items: flex-end;
  gap: 0.18rem;
  height: 2.35rem;
  margin-top: 0.15rem;
}

.sss-spark i {
  flex: 1 1 auto;
  min-width: 0;
  border-radius: 2px 2px 0 0;
  background: color-mix(in oklab, var(--primary) 22%, var(--muted));
}

.sss-spark i[data-active="true"] {
  background: var(--primary);
}

.sss-table {
  width: 100%;
  border-collapse: collapse;
  font-size: clamp(0.68rem, 1.5vw, 0.75rem);
}

.sss-table th {
  padding: 0.15rem 0.22rem 0.28rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-align: left;
  text-transform: none;
  color: var(--muted-foreground);
}

.sss-table td {
  padding: 0.28rem 0.22rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  color: var(--foreground);
  white-space: nowrap;
}

.sss-table td:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 7.5rem;
}

.sss-table tr[data-active="true"] td {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.sss-status {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 0.08rem 0.4rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.sss-status[data-status="syncing"],
.sss-status[data-status="retry"] {
  color: var(--foreground);
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.sss-status[data-status="hold"] {
  color: var(--muted-foreground);
}

.sss-steps,
.sss-rail {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.3rem;
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sss-steps li,
.sss-rail li {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.28rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.32rem 0.4rem;
  font-size: clamp(0.62rem, 1.4vw, 0.72rem);
  font-weight: 650;
  color: var(--muted-foreground);
}

.sss-steps li span:first-child {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--primary);
}

.sss-steps li[data-active="true"],
.sss-rail li[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, white);
  color: var(--foreground);
}

.sss-rail li {
  flex-direction: column;
  align-items: flex-start;
  gap: 0.1rem;
}

.sss-rail-icon {
  display: inline-flex;
  color: var(--primary);
}

.sss-rail li strong {
  font-size: clamp(0.66rem, 1.5vw, 0.75rem);
  color: var(--foreground);
}

.sss-rail li span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  font-size: 9px;
  font-weight: 500;
  color: var(--muted-foreground);
}

.sss-quote {
  display: grid;
  gap: 0.28rem;
  margin: 0;
}

.sss-quote div {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: clamp(0.7rem, 1.6vw, 0.78rem);
}

.sss-quote dt {
  color: var(--muted-foreground);
}

.sss-quote dd {
  margin: 0;
  font-weight: 650;
  color: var(--foreground);
}

.sss-quote-total dd {
  font-family: var(--font-mono);
  color: var(--primary);
}

.sss-math {
  display: flex;
  overflow: hidden;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.sss-math i[data-tone="cost"] {
  background: color-mix(in oklab, var(--foreground) 22%, transparent);
}

.sss-math i[data-tone="margin"] {
  background: var(--primary);
}

.sss-share {
  display: grid;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sss-share li {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding: 0.38rem 0.5rem;
  font-size: 0.75rem;
  color: var(--foreground);
}

.sss-share li[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, white);
  color: var(--primary);
}

.sss-note {
  margin: 0;
  font-size: 0.68rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.sss-bars {
  display: grid;
  gap: 0.55rem;
}

.sss-bars span {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.22rem;
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.sss-bars strong {
  font-family: var(--font-mono);
  color: var(--foreground);
}

.sss-bars b {
  display: block;
  overflow: hidden;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.sss-bars i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--primary);
}

.sss-bars i[data-tone="floor"] {
  background: color-mix(in oklab, var(--foreground) 28%, transparent);
}

.sss-lags {
  display: grid;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sss-lags li {
  display: grid;
  grid-template-columns: 3.4rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.4rem;
  border-radius: 0.4rem;
  padding: 0.22rem 0.28rem;
  font-size: 0.72rem;
}

.sss-lags li[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 8%, transparent);
}

.sss-lags em {
  font-family: var(--font-mono);
  font-style: normal;
  color: var(--muted-foreground);
}

.sss-endpoints {
  display: grid;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sss-endpoints li {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.4rem;
  overflow: hidden;
  border-radius: 0.4rem;
  padding: 0.22rem 0.3rem;
  font-family: var(--font-mono);
  font-size: clamp(0.62rem, 1.4vw, 0.72rem);
  color: var(--foreground);
}

.sss-endpoints li em {
  flex-shrink: 0;
  font-style: normal;
  font-weight: 700;
  color: var(--primary);
}

.sss-endpoints li[data-active="true"] {
  background: color-mix(in oklab, var(--primary) 10%, white);
}

.sss-json {
  margin: 0;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  font-family: var(--font-mono);
  font-size: clamp(0.62rem, 1.4vw, 0.72rem);
  line-height: 1.45;
  color: var(--foreground);
}

.sss-feed {
  flex-shrink: 0;
}

.sss-stage .lc-feed-row {
  grid-template-columns: 3.6rem minmax(0, 1fr) auto;
  gap: 0.4rem;
}

.sss-stage[data-live="true"] .sss-feed .lc-feed-list {
  animation: lc-feed-scroll 16s linear infinite;
}

.sss-stage .lc-feed-msg {
  overflow: hidden;
  text-overflow: ellipsis;
}

@container sss (max-width: 540px) {
  .sss-work,
  .sss-work-quote,
  .sss-work-api {
    grid-template-columns: minmax(0, 1fr);
  }

  .sss-context-title {
    white-space: normal;
  }

  .sss-table td:first-child {
    max-width: 6.25rem;
  }

  .sss-steps,
  .sss-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sss-rail li span:last-child {
    display: none;
  }
}

@media (max-width: 429px) {
  .sss-stage {
    --sss-console-h: clamp(20.5rem, 56svh, 24.5rem);
  }

  .sss-mobile .sss-stage .lc-bezel {
    padding: 0.35rem;
  }

  .sss-mobile .sss-stage .lc-body {
    gap: 0.42rem;
    padding: 0.5rem 0.5rem 0.45rem;
  }

  .sss-mobile .sss-stage .lc-stat {
    padding: 0.32rem 0.38rem;
  }

  .sss-mobile .two-track-chrome-path {
    font-size: 9px;
  }

  .sss-mobile .sss-feed {
    height: 4.1rem;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .sss-stage {
    --sss-console-h: clamp(26rem, 48vh, 30rem);
  }
}

@media (min-width: 1024px) {
  .sss-stage {
    --sss-console-h: clamp(28rem, 58dvh, 34rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sss-slider {
    transition: none;
  }

  .sss-caption-line,
  .sss-dot {
    transition: none;
  }

  .sss-stage .lc-scan,
  .sss-stage .lc-panel-dot,
  .sss-stage .two-track-chrome-pulse,
  .sss-stage .two-track-chrome-pulse::after,
  .sss-stage .lc-spin,
  .sss-stage[data-live="true"] .sss-feed .lc-feed-list {
    animation: none;
  }
}

/* == FAQ page (faq-*) == */

.faq-hero,
.faq-list,
.faq-help {
  min-width: 0;
  overflow-x: clip;
}

/* Top padding inherits .bh-hero (4.5rem nav + gap). */
.bh-hero.faq-hero {
  padding-bottom: clamp(2.75rem, 5.5vw, 5rem);
}

@media (min-width: 1024px) {
  .bh-hero.faq-hero {
    padding-bottom: clamp(3.25rem, 5vh, 5.25rem);
  }

  .faq-hero .bh-layout {
    grid-template-columns: minmax(0, 1.2fr) minmax(16rem, 0.8fr);
    align-items: center;
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .bh-hero.faq-hero {
    padding-bottom: clamp(2.25rem, 3.5vh, 3.25rem);
  }
}

@media (max-width: 639px) {
  .bh-hero.faq-hero {
    padding-bottom: clamp(2.35rem, 8vw, 3.5rem);
  }
}

.faq-hero-title {
  max-width: 18ch;
  overflow-wrap: anywhere;
}

.faq-hero-em {
  display: inline;
  font-family: inherit;
  font-style: italic;
  font-weight: 500;
  color: var(--primary);
}

.faq-index {
  min-width: 0;
  max-width: 100%;
  border: 1px solid color-mix(in oklab, var(--background) 16%, transparent);
  border-radius: var(--radius);
  background: linear-gradient(
    165deg,
    color-mix(in oklab, var(--background) 10%, transparent),
    color-mix(in oklab, var(--background) 4%, transparent)
  );
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--background) 12%, transparent),
    0 18px 48px color-mix(in oklab, black 28%, transparent);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  padding: 1rem 0.85rem 0.85rem;
}

.faq-index-kicker {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0 0.4rem 0.7rem;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.faq-index-kicker span {
  color: var(--primary);
}

.faq-index-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.faq-index-btn {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 2px);
  background: transparent;
  color: color-mix(in oklab, var(--background) 88%, transparent);
  text-align: left;
  cursor: pointer;
  appearance: none;
  -webkit-tap-highlight-color: transparent;
}

.faq-index-btn:hover,
.faq-index-btn:focus-visible {
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  outline: none;
}

.faq-index-btn[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 45%, transparent);
  background: color-mix(in oklab, var(--primary) 14%, transparent);
  color: var(--background);
}

.faq-index-num {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.faq-index-label {
  min-width: 0;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.25;
}

.faq-list {
  background: var(--background);
  padding-block: clamp(1.75rem, 4vw, 3.5rem) clamp(2.5rem, 5vw, 4.5rem);
}

.faq-accordion {
  max-width: 52rem;
  margin-inline: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--background);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.faq-item {
  border-color: var(--border) !important;
  scroll-margin-top: 5.5rem;
}

.faq-item:last-child {
  border-bottom: 0 !important;
}

.faq-trigger {
  gap: 0.75rem !important;
  align-items: flex-start !important;
  min-height: 2.75rem;
  padding: 1rem 1.05rem !important;
  font-size: 1rem !important;
  font-weight: 600 !important;
  line-height: 1.35 !important;
  text-decoration: none !important;
  color: var(--foreground) !important;
}

.faq-trigger:hover,
.faq-trigger:focus-visible {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
  text-decoration: none !important;
  outline: none;
}

.faq-trigger[data-state="open"] {
  background: var(--primary-soft);
}

.faq-trigger-index {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.faq-trigger-q {
  flex: 1;
  min-width: 0;
  text-align: left;
  overflow-wrap: anywhere;
}

.faq-trigger svg {
  width: 1.125rem;
  height: 1.125rem;
  flex-shrink: 0;
  margin-top: 0.2rem;
  color: var(--primary);
}

.faq-content {
  font-size: inherit !important;
}

.faq-answer {
  margin: 0;
  padding: 0 1.05rem 1.15rem 3.05rem;
  max-width: 62ch;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.faq-help {
  background: var(--dark);
  color: var(--background);
  padding-block: clamp(2.5rem, 5vw, 4.25rem);
}

.faq-help-grid {
  display: grid;
  gap: clamp(1.5rem, 3.5vw, 2.75rem);
  min-width: 0;
}

.faq-help-title {
  margin-top: 1rem;
  max-width: 18ch;
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3.2vw, 2.25rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.faq-help-body {
  margin-top: 0.85rem;
  max-width: 38rem;
  font-size: 0.9375rem;
  line-height: 1.65;
  color: color-mix(in oklab, var(--background) 68%, transparent);
}

.faq-help-cards {
  display: grid;
  gap: 0.75rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.faq-help-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.2rem;
  min-height: 2.75rem;
  min-width: 0;
  padding: 1rem 1.1rem 1rem 3.15rem;
  position: relative;
  border: 1px solid color-mix(in oklab, var(--background) 14%, transparent);
  border-radius: var(--radius);
  background: color-mix(in oklab, var(--background) 5%, transparent);
  color: var(--background);
  text-decoration: none;
  transition: border-color 160ms ease, background 160ms ease;
}

.faq-help-card:hover,
.faq-help-card:focus-visible {
  border-color: var(--primary);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  outline: none;
}

.faq-help-icon {
  position: absolute;
  top: 1.05rem;
  left: 1.05rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 22%, transparent);
  color: var(--primary);
}

.faq-help-card-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.faq-help-card-mail {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.4;
  overflow-wrap: anywhere;
  color: var(--background);
}

@media (min-width: 640px) {
  .faq-index {
    padding: 1.15rem 1rem 1rem;
  }

  .faq-index-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .faq-help-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .faq-index-list {
    grid-template-columns: minmax(0, 1fr);
  }

  .faq-help-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
    align-items: center;
  }

  .faq-trigger {
    padding: 1.1rem 1.25rem !important;
  }

  .faq-answer {
    padding: 0 1.25rem 1.25rem 3.35rem;
  }
}

@media (max-width: 429px) {
  .faq-index-list {
    grid-template-columns: minmax(0, 1fr);
  }

  .faq-answer {
    padding-left: 1.05rem;
  }

  .faq-hero-title {
    max-width: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .faq-help-card {
    transition: none;
  }
}

/* == Contact page (ct-*) ==
   Compact dark split banner. Copy + HUD photo share ONE height
   (product-hero stage clamp). The PNG is cropped into the right half
   and cannot size the section. Left vignette is black → transparent
   so copy reads; no primary-deep green wash. */

.ct-hero {
  min-width: 0;
  overflow: hidden;
}

.bh-hero.ct-hero {
  padding-bottom: 0;
}

.ct-hero-banner {
  gap: 1.25rem;
  padding-inline: clamp(0.875rem, 1.5vw, 1.75rem);
}

.ct-hero-copy {
  position: relative;
  z-index: 2;
}

.ct-hero .bh-body {
  color: color-mix(in oklab, var(--background) 88%, transparent);
}

.ct-hero-title {
  max-width: 12ch;
  overflow-wrap: anywhere;
}

.ct-hero-stage {
  position: relative;
  z-index: 1;
  min-width: 0;
  width: 100%;
  max-width: none;
  height: clamp(14rem, 42vw, 20rem);
  max-height: 20rem;
  overflow: hidden;
  margin-inline: calc(-1 * clamp(0.875rem, 1.5vw, 1.75rem));
}

.ct-hero-media {
  position: absolute;
  inset: 0;
  overflow: hidden;
  width: 100%;
  height: 100%;
  max-height: 100%;
}

.ct-hero-img {
  display: block;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: 100%;
  object-fit: cover;
  object-position: 78% 42%;
}

.ct-hero-vignette {
  pointer-events: none;
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      rgb(0 0 0 / 0.45) 0%,
      transparent 28%
    ),
    linear-gradient(
      90deg,
      rgb(0 0 0 / 0.78) 0%,
      rgb(0 0 0 / 0.32) 28%,
      rgb(0 0 0 / 0.08) 48%,
      transparent 66%
    );
}

@media (min-width: 768px) and (max-width: 1023px) {
  .ct-hero-stage {
    height: clamp(16rem, 38vh, 22rem);
    max-height: 22rem;
  }

  .ct-hero-img {
    object-position: 80% 40%;
  }
}

@media (min-width: 1024px) {
  .bh-hero.ct-hero {
    padding: 0;
  }

  .ct-hero-banner {
    grid-template-columns: minmax(18rem, 0.88fr) minmax(0, 1.22fr);
    gap: 0;
    align-items: stretch;
    min-height: clamp(22rem, 52vh, 34rem);
    height: clamp(22rem, 52vh, 34rem);
    max-height: clamp(22rem, 52vh, 34rem);
    padding-inline: 0;
  }

  .ct-hero-copy {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 0;
    padding-top: clamp(5.75rem, 8vh, 7.5rem);
    padding-bottom: clamp(1.75rem, 3vh, 2.75rem);
    padding-left: clamp(1.5rem, 4.5vw, 4.25rem);
    padding-right: clamp(1rem, 2.5vw, 2rem);
  }

  .ct-hero-stage {
    margin-inline: 0;
    height: 100%;
    min-height: 0;
    max-height: 100%;
    overflow: hidden;
  }

  .ct-hero-img {
    object-position: 82% 44%;
  }

  .ct-hero-vignette {
    background:
      linear-gradient(
        90deg,
        rgb(0 0 0 / 0.94) 0%,
        rgb(0 0 0 / 0.58) 16%,
        rgb(0 0 0 / 0.2) 38%,
        transparent 58%
      ),
      linear-gradient(
        180deg,
        rgb(0 0 0 / 0.22) 0%,
        transparent 18%,
        transparent 82%,
        rgb(0 0 0 / 0.28) 100%
      );
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .ct-hero-banner {
    min-height: clamp(20rem, 48vh, 28rem);
    height: clamp(20rem, 48vh, 28rem);
    max-height: clamp(20rem, 48vh, 28rem);
  }

  .ct-hero-copy {
    padding-top: clamp(5.75rem, 8vh, 7.5rem);
    padding-bottom: clamp(1.25rem, 2.5vh, 2rem);
  }
}

@media (max-width: 639px) {
  .ct-hero-title {
    max-width: none;
  }

  .ct-hero-stage {
    height: clamp(13.5rem, 48vw, 18rem);
    max-height: 18rem;
  }

  .ct-hero-img {
    object-position: 72% 40%;
  }
}

/* == Legal page (legal-*) == */

.legal-hero,
.legal-doc {
  min-width: 0;
  overflow-x: clip;
}

.legal-shell {
  width: 100%;
  max-width: none;
  margin-inline: 0;
  padding-inline: clamp(1rem, 3vw, 2rem);
  box-sizing: border-box;
}

.bh-hero.legal-hero {
  padding-bottom: clamp(2.25rem, 4.5vw, 3.5rem);
}

@media (min-width: 1024px) {
  .bh-hero.legal-hero {
    padding-bottom: clamp(2.75rem, 4.5vh, 4.25rem);
  }
}

@media (min-width: 1024px) and (max-height: 900px) {
  .bh-hero.legal-hero {
    padding-bottom: clamp(2rem, 3vh, 2.75rem);
  }
}

@media (max-width: 639px) {
  .bh-hero.legal-hero {
    padding-bottom: clamp(1.85rem, 6vw, 2.75rem);
  }
}

.legal-hero-copy {
  width: 100%;
  max-width: none;
}

.legal-hero-title {
  max-width: none;
  overflow-wrap: anywhere;
}

.legal-hero .bh-body,
.legal-hero-intro {
  max-width: none;
}

.legal-hero-em {
  display: inline;
  font-family: inherit;
  font-style: italic;
  font-weight: 500;
  color: var(--primary);
}

.legal-hero-updated {
  margin-top: 1.15rem;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: none;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.legal-doc {
  background: var(--background);
  padding-block: clamp(1.5rem, 3.5vw, 2.5rem) clamp(2.5rem, 5vw, 4.5rem);
}

.legal-doc-note {
  margin: 0 0 1.15rem;
  max-width: none;
  font-size: 0.8125rem;
  line-height: 1.6;
  color: var(--muted-foreground);
  overflow-wrap: anywhere;
}

.legal-doc-note a {
  color: var(--foreground);
  text-decoration: none;
}

.legal-doc-note a:hover,
.legal-doc-note a:focus-visible {
  color: var(--primary);
  outline: none;
}

.legal-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  width: 100%;
  margin: 0 0 1.5rem;
  padding: 0;
  scroll-margin-top: 6rem;
}

.legal-tab {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 0.28rem;
  width: 100%;
  min-width: 0;
  min-height: 4.25rem;
  padding: 0.75rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--foreground);
  text-decoration: none;
  text-align: left;
  -webkit-tap-highlight-color: transparent;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease;
}

.legal-tab:hover,
.legal-tab:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 45%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, var(--surface));
  outline: none;
}

.legal-tab[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 55%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, var(--background));
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 22%, transparent);
}

.legal-tab-num {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.legal-tab-copy {
  display: flex;
  min-width: 0;
  width: 100%;
  flex-direction: column;
  gap: 0.12rem;
}

.legal-tab-kicker {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--muted-foreground);
}

.legal-tab[data-active="true"] .legal-tab-kicker {
  color: var(--primary);
}

.legal-tab-label {
  min-width: 0;
  font-size: 0.875rem;
  font-weight: 650;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.legal-chapter {
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  scroll-margin-top: 6rem;
}

.legal-chapter-kicker {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: none;
  color: var(--muted-foreground);
}

.legal-chapter-kicker span {
  color: var(--primary);
}

.legal-chapter-title {
  margin-top: 0.55rem;
  font-family: var(--font-display);
  font-size: clamp(1.65rem, 3.4vw, 2.35rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.legal-chapter-lead {
  margin-top: 0.75rem;
  max-width: none;
  font-size: 1.0125rem;
  line-height: 1.65;
  color: var(--muted-foreground);
}

.legal-blocks {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1.35rem 2rem;
  margin-top: 1.75rem;
}

.legal-block {
  min-width: 0;
}

.legal-subhead {
  margin: 0 0 0.45rem;
  font-family: var(--font-display);
  font-size: 1.0625rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.legal-p {
  margin: 0 0 0.7rem;
  max-width: none;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--muted-foreground);
}

.legal-p:last-child {
  margin-bottom: 0;
}

@media (min-width: 640px) {
  .legal-tabs {
    gap: 0.75rem;
    margin-bottom: 1.85rem;
  }

  .legal-tab {
    min-height: 5.25rem;
    padding: 1rem 1.1rem;
    gap: 0.4rem;
  }

  .legal-tab-label {
    font-size: 1.05rem;
  }
}

@media (min-width: 900px) {
  .legal-blocks {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .legal-tabs {
    gap: 0.9rem;
  }

  .legal-tab {
    min-height: 6rem;
    padding: 1.2rem 1.25rem;
  }
}

@media (max-width: 429px) {
  .legal-tabs {
    gap: 0.4rem;
  }

  .legal-tab {
    min-height: 3.75rem;
    padding: 0.55rem 0.45rem;
    gap: 0.15rem;
  }

  .legal-tab-kicker {
    display: none;
  }

  .legal-tab-label {
    font-size: 0.75rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .legal-tab {
    transition: none;
  }
}

/* ── /about rebuild — intelligence hero + chapter bands (abt-*) ──
   Unique tech-stage (not office atlas, not brokers wall).
   Top padding inherits .bh-hero (4.5rem nav + gap). */

.abt-formula-strip {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.abt-core-ring {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 26%, transparent);
  stroke-width: 0.9;
}

.abt-stage[data-live="true"] .abt-core-ring {
  animation: abt-ring 4.2s ease-in-out infinite;
}

.abt-spoke {
  fill: none;
  stroke: color-mix(in oklab, var(--background) 16%, transparent);
  stroke-width: 0.75;
}

.abt-node[data-active="true"] .abt-spoke {
  stroke: color-mix(in oklab, var(--primary) 58%, transparent);
}

.abt-node-core {
  fill: color-mix(in oklab, var(--background) 42%, transparent);
}

.abt-node[data-active="true"] .abt-node-core {
  fill: var(--primary);
}

.abt-node-label {
  fill: var(--primary);
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 650;
  letter-spacing: 0.04em;
}

.abt-core-glow {
  fill: color-mix(in oklab, var(--primary) 26%, transparent);
}

.abt-core-disc {
  fill: var(--primary);
}

.abt-core-mark {
  fill: var(--primary-foreground);
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 700;
}

.abt-band-kicker {
  margin: 1.75rem 0 0.7rem;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: none;
  color: var(--primary);
}

.abt-band-kicker-center {
  text-align: center;
}

.abt-formula {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem 0.55rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-formula li {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.abt-formula strong {
  border-radius: 0.7rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 0.55rem 0.85rem;
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
  box-shadow: var(--shadow-card);
}

.abt-formula span {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary);
}

.abt-formula-result strong {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--border));
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--primary) 10%, white) 0%,
      var(--card) 55%
    );
  color: var(--foreground);
}

.abt-signals {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.abt-signals li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  padding: 0.28rem 0.7rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: none;
  color: var(--primary);
}

.abt-vision-lines {
  display: grid;
  gap: 0.7rem;
  max-width: 52rem;
  margin: 1.75rem auto 0;
  padding: 0;
  list-style: none;
}

.abt-vision-lines li {
  border-radius: 0.95rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 0.95rem 1.1rem;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--foreground);
  box-shadow: var(--shadow-card);
}

.abt-band-close {
  margin: 1.35rem auto 0;
  max-width: 42rem;
  text-align: center;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.abt-verbs {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  margin: 1.75rem 0 0;
  padding: 0;
  list-style: none;
}

.abt-verbs li {
  min-width: 0;
  border-radius: 1.05rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1.05rem 1.15rem;
  box-shadow: var(--shadow-card);
}

.abt-verbs strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.abt-verbs p {
  margin: 0.4rem 0 0;
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

.abt-transforms {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.65rem;
  max-width: 40rem;
  margin: 1.5rem auto 0;
  padding: 0;
  list-style: none;
}

.abt-transforms li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 0.7rem;
  border-radius: 0.95rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 0.85rem 1rem;
  box-shadow: var(--shadow-card);
}

.abt-transforms span,
.abt-transforms strong {
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.abt-transforms span {
  color: var(--muted-foreground);
}

.abt-transforms strong {
  text-align: right;
  color: var(--foreground);
}

.abt-transforms em {
  font-family: var(--font-mono);
  font-style: normal;
  font-weight: 700;
  color: var(--primary);
}

.abt-future-pairs {
  display: grid;
  gap: 0.75rem;
  max-width: 52rem;
  margin: 1.75rem auto 0;
  padding: 0;
  list-style: none;
}

.abt-future-pairs li {
  border-radius: 1.05rem;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 1.1rem 1.2rem;
  box-shadow: var(--shadow-card);
}

.abt-future-pairs p {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

.abt-future-pairs strong {
  display: block;
  margin-top: 0.45rem;
  font-family: var(--font-display);
  font-size: 1.08rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.abt-close {
  display: grid;
  gap: 1.75rem;
  min-width: 0;
}

.abt-close-pillars {
  display: grid;
  gap: 0.45rem;
  margin: 1.35rem 0 0;
  padding: 0;
  list-style: none;
}

.abt-close-pillars li {
  font-size: 1rem;
  line-height: 1.5;
  color: color-mix(in oklab, var(--background) 82%, transparent);
}

.abt-close-line {
  margin: 1.25rem 0 0;
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--background);
}

.abt-close-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .abt-verbs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .abt-surfaces {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .abt-surfaces > li:nth-child(-n + 3),
  .abt-surfaces > li:nth-child(n + 4) {
    grid-column: auto;
  }

  .abt-audiences ul {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .abt-verbs {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .abt-close {
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
    gap: clamp(1.5rem, 3vw, 2.75rem);
    align-items: end;
  }

  .abt-ops-sun ul {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) and (max-width: 1512px) {
  .abt-audiences ul {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .abt-verbs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1023px) {
  .abt-formula,
  .abt-signals,
  .abt-verbs,
  .abt-transforms,
  .abt-close,
  .abt-vision-lines,
  .abt-future-pairs {
    min-width: 0;
    max-width: 100%;
  }
}

@media (max-width: 639px) {
  .abt-formula-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .abt-ops-sun ul {
    grid-template-columns: 1fr;
  }

  .abt-transforms li {
    grid-template-columns: minmax(0, 1fr);
    text-align: left;
  }

  .abt-transforms em,
  .abt-transforms strong {
    text-align: left;
  }
}

.abt-close-pillars {
  max-width: 40rem;
  margin: 1.5rem auto 0;
  text-align: center;
}

.abt-close-pillars li {
  color: var(--muted-foreground);
}

.abt-close-ctas {
  justify-content: center;
  margin-top: 1.35rem;
}

.abt-pipe-rail {
  min-width: 0;
  border-radius: 0.7rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--primary) 5%, var(--card));
  padding: 0.55rem 0.6rem 0.65rem;
}

.abt-pipe-rail ol {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.3rem;
  margin: 0.45rem 0 0;
  padding: 0;
  list-style: none;
}

.abt-pipe-rail button {
  display: grid;
  gap: 0.12rem;
  width: 100%;
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  background: color-mix(in oklab, var(--background) 70%, transparent);
  padding: 0.4rem 0.35rem;
  text-align: left;
  cursor: pointer;
}

.abt-pipe-rail button span {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-foreground);
}

.abt-pipe-rail button strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-display);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.abt-pipe-rail button[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, var(--border));
  background: color-mix(in oklab, var(--primary) 12%, white);
}

.abt-pipe-rail button[data-active="true"] span {
  color: var(--primary);
}

.abt-pipe-active {
  margin: 0.55rem 0 0;
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

.abt-pipe-active strong {
  display: block;
  margin-bottom: 0.3rem;
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

@media (max-width: 639px) {
  .abt-coverage.abt-formula-strip {
    display: grid;
  }

  .abt-pipe-rail ol {
    grid-template-columns: 1fr;
  }

  .abt-node-label {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .abt-stage[data-live="true"] .abt-core-ring {
    animation: none;
  }
}

/* ── Homepage ToolsGrid seat map & tickets desk (smt-*) ── */

.smt-pipe {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.45rem;
  margin: 0.85rem 0 1rem;
  padding: 0;
  list-style: none;
}

.smt-pipe li {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 2.35rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--background);
  padding: 0.35rem 0.7rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: none;
  color: var(--muted-foreground);
