}

.smt-map-tools {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.smt-map-tools button {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  margin: 0;
  padding: 0;
  border-radius: 0.4rem;
  line-height: 1;
