}

.smt-map-seat .smt-map-label {
  fill: #fff;
  font-family: var(--font-mono);
  font-weight: 700;
  letter-spacing: 0.02em;
  pointer-events: none;
  paint-order: stroke;
  stroke: color-mix(in oklab, black 28%, transparent);
  stroke-width: 0.35;
}

.smt-map-seat .smt-map-stand {
  font-family: var(--font-sans);
  font-weight: 600;
  letter-spacing: 0;
}

.smt-map-ring {
