/* == Homepage TravelTools quote-desk viewport (tpa-section) ==
   ToolsGrid TravelTools only. Rail is its own row; Live console + 2×2
   minis share leftover height. svh, never dvh: dvh remeasures with
   browser chrome and shoves every section below this one. Section is
   not the first homepage band, so 100svh is a min-height, not a nested
   scrollport. No overflow-y-auto on the Live pane (same as HowItWorks:
   wheel anywhere scrolls the page). Mobile already grows. */

.tpa-section {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100svh;
  padding-block: clamp(0.75rem, 1.8vh, 1.25rem);
}

.tpa-shell {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  gap: clamp(0.55rem, 1.2vh, 0.9rem);
}

.tpa-head {
  flex-shrink: 0;
}

.tpa-section .tpa-head h2 {
  margin-top: 0.35rem;
  font-size: clamp(1.35rem, 1.05rem + 1.5vh, 2rem);
  line-height: 1.15;
}

.tpa-lead {
  margin-top: 0.4rem;
  font-size: 0.8125rem;
  line-height: 1.45;
}

.tpa-stage {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  gap: 0.7rem;
}

.tpa-section .tpa-rail {
  grid-row: 1;
  flex-shrink: 0;
  margin: 0;
  min-height: 0;
}

.tpa-section .tpa-steps {
  margin: 0.4rem 0 0.45rem;
}

.tpa-boards {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 0.7rem;
  min-width: 0;
  min-height: 0;
}

.tpa-live,
.tpa-minis,
.tpa-mini {
  min-width: 0;
  min-height: 0;
}

.tpa-live {
  display: flex;
  flex-direction: column;
}

.tpa-minis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: repeat(2, auto);
  gap: 0.65rem;
}

.tpa-mini {
  display: flex;
  flex-direction: column;
}

.tpa-minis .tpa-card {
  min-height: 0;
}

@media (max-width: 479px) {
  .tpa-minis {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: none;
  }
}

@media (min-width: 900px) {
  /* min-height 100svh (not dvh). Do not lock height + overflow:hidden —
     that nested scrollport ate wheel over the Live console / map / table.
     Section grows with the desk; wheel anywhere continues document scroll. */
  .tpa-section {
    height: auto;
    max-height: none;
    min-height: 100vh;
    min-height: 100svh;
    overflow: visible;
  }

  .tpa-shell {
    height: auto;
    max-height: none;
  }

  .tpa-stage {
    grid-template-rows: auto minmax(min-content, 1fr);
    height: auto;
    min-height: 0;
    overflow: visible;
  }

  .tpa-boards {
    grid-template-columns: minmax(0, 1.22fr) minmax(0, 0.78fr);
    grid-template-rows: minmax(min-content, 1fr);
    height: auto;
  }

  .tpa-live,
  .tpa-minis {
    height: auto;
    overflow: visible;
  }

  .tpa-minis {
    grid-template-rows: repeat(2, minmax(min-content, 1fr));
  }

  .tpa-mini {
    height: 100%;
  }

  .tpa-minis .tpa-card {
    --tpa-body-h: 0px;
    height: 100%;
    overflow: visible;
  }

  .tpa-minis .tpa-card-note {
    height: 2.5rem;
    -webkit-line-clamp: 2;
  }

  .tpa-minis .tpa-card-body {
    overflow: visible;
    overscroll-behavior: auto;
  }

  .tpa-minis .tpa-card-metric span:first-child {
    font-size: clamp(1.15rem, 2.2vh, 1.5rem);
  }

  /* Fill the Live column without gutted chrome — wrap the existing desk. */
  .tpa-section .smt-console,
  .tpa-section .smt-console .lc-frame,
  .tpa-section .smt-console .lc-bezel,
  .tpa-section .smt-console .lc-screen {
    display: flex;
    flex: 1 1 auto;
    min-height: min-content;
    height: auto;
    max-height: none;
    flex-direction: column;
  }

  .tpa-section .smt-console .lc-bezel {
    padding: 0.45rem;
  }

  .tpa-section .smt-console .lc-body {
    flex: 1 1 auto;
    min-height: min-content;
    overflow: visible;
    overscroll-behavior: auto;
  }

  .tpa-section .smt-console .two-track-chrome {
    flex-shrink: 0;
  }

  .tpa-section .smt-desk {
    flex: 1 1 auto;
    min-height: min-content;
    gap: 0.5rem;
    padding: 0.65rem 0.7rem 0.7rem;
  }

  .tpa-section .smt-split {
    display: grid;
    flex: 1 1 auto;
    grid-template-columns: minmax(10rem, 0.92fr) minmax(0, 1.18fr);
    min-height: min-content;
  }

  .tpa-section .smt-split[data-map="false"] {
    grid-template-columns: 1fr;
  }

  .tpa-section .smt-map-card,
  .tpa-section .smt-list-card {
    display: flex;
    min-height: min-content;
    flex-direction: column;
    overflow: visible;
  }

  .tpa-section .smt-map-stage {
    flex: 1 1 auto;
    min-height: 7.5rem;
    height: auto;
    overflow: clip;
  }

  .tpa-section .smt-table-wrap {
    flex: 0 0 auto;
    min-height: min-content;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .tpa-section .smt-top,
  .tpa-section .smt-eventbar,
  .tpa-section .smt-filters,
  .tpa-section .smt-stats,
  .tpa-section .smt-share,
  .tpa-section .smt-loaded {
    flex-shrink: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tpa-section .smt-console .lc-body,
  .tpa-minis .tpa-card-body {
    scroll-behavior: auto;
  }
}

/* == Brokers SeatsFunds™ payout desk (sfp-*) 2026-08-19 ==
   Live Console on /brokers after PaymentInfrastructureSection.
   USDT / wallet rail is the hero. Qualitative Standard vs crypto switch.
   No volume ladder, sale maths, or KPI amounts. Reserved path / ledger /
   chips / feed slots so auto-run (sale → withhold → USDT transfer →
   settled, plus a Standard contrast) never shifts layout. */

.sfp-console .lc-screen {
  height: clamp(40.5rem, 68vh, 48rem);
  min-height: clamp(40.5rem, 68vh, 48rem);
  max-height: clamp(40.5rem, 68vh, 48rem);
}

.sfp-body {
  display: grid;
  grid-template-rows: auto auto minmax(min-content, 1fr) auto;
  gap: 0.5rem;
  height: 100%;
  min-height: 0;
}

.sfp-sale {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  flex-shrink: 0;
  min-height: 3.2rem;
}

.sfp-sale-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.12rem;
}

.sfp-sale-copy strong {
  font-size: 0.92rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.sfp-sale-copy span {
  font-size: 0.68rem;
  line-height: 1.35;
  color: var(--muted-foreground);
}

.sfp-sale-rail {
  display: flex;
  flex-shrink: 0;
  min-width: 6.6rem;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.08rem;
}

.sfp-sale-rail span {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--muted-foreground);
}

.sfp-sale-rail strong {
  min-width: 5.5rem;
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
  text-align: right;
  color: var(--foreground);
}

.sfp-sale-rail[data-usdt="true"] strong {
  color: var(--primary);
}

.sfp-pipe {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.35rem;
  flex-shrink: 0;
  margin: 0;
  min-height: 3.55rem;
  list-style: none;
  padding: 0;
}

.sfp-pipe-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 0.35rem;
  row-gap: 0.04rem;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background: color-mix(in oklab, var(--background) 72%, white);
  padding: 0.4rem 0.45rem;
}

.sfp-pipe-step[data-done="true"] {
  border-color: color-mix(in oklab, var(--primary) 22%, var(--border));
}

.sfp-pipe-step[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 34%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, white);
}

.sfp-pipe-icon {
  display: grid;
  grid-row: 1 / span 2;
  place-items: center;
  color: var(--muted-foreground);
}

.sfp-pipe-step[data-done="true"] .sfp-pipe-icon,
.sfp-pipe-step[data-current="true"] .sfp-pipe-icon {
  color: var(--primary);
}

.sfp-pipe-label {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: none;
  color: var(--foreground);
}

.sfp-pipe-detail {
  grid-column: 2;
  overflow: hidden;
  font-size: 0.62rem;
  line-height: 1.3;
  color: var(--muted-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sfp-main {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 0.75fr);
  gap: 0.5rem;
  min-height: min-content;
}

.sfp-canvas,
.sfp-tracks {
  display: flex;
  flex-direction: column;
}

.sfp-canvas {
  min-height: 0;
  height: 100%;
}

.sfp-tracks {
  height: auto;
  min-height: min-content;
  gap: 0.4rem;
  overflow: visible;
  padding: 0.5rem 0.55rem;
}

.sfp-tracks > .lc-panel-head {
  flex-shrink: 0;
  width: 100%;
  min-height: 1.35rem;
  margin: 0;
  padding: 0;
}

.sfp-canvas[data-pulse="true"] {
  border-color: color-mix(in oklab, var(--primary) 34%, var(--border));
}

.sfp-path {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 1.65rem minmax(0, 1fr) 1.65rem minmax(0, 1fr);
  align-items: stretch;
  flex-shrink: 0;
  min-height: 4.55rem;
  margin: 0;
}

.sfp-node {
  display: flex;
  min-width: 0;
  min-height: 4.55rem;
  flex-direction: column;
  justify-content: center;
  gap: 0.18rem;
  border-radius: 0.6rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, var(--background) 80%, white);
  padding: 0.45rem 0.5rem;
}

.sfp-node[data-state="done"] {
  border-color: color-mix(in oklab, var(--primary) 22%, var(--border));
}

.sfp-node[data-state="current"] {
  border-color: color-mix(in oklab, var(--primary) 36%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, white);
}

.sfp-node[data-dest="true"][data-state="current"] {
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 20%, transparent);
}

.sfp-console[data-stage="settle"][data-rail="usdt"] .sfp-node[data-dest="true"] {
  animation: sfp-settle-pulse 1.6s ease-in-out infinite;
}

.sfp-node strong {
  overflow: hidden;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sfp-node span {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.sfp-node[data-state="current"] span,
.sfp-node[data-state="done"] span {
  color: var(--primary);
}

.sfp-link {
  position: relative;
  align-self: center;
  width: 1.65rem;
  height: 2px;
  overflow: hidden;
  background: color-mix(in oklab, var(--foreground) 12%, transparent);
}

.sfp-link[data-live="true"] {
  background: color-mix(in oklab, var(--primary) 38%, transparent);
}

.sfp-packet {
  position: absolute;
  top: 50%;
  left: 0;
  display: none;
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  background: var(--primary);
  transform: translate(-50%, -50%);
}

.sfp-link[data-live="true"] .sfp-packet {
  display: block;
  animation: sfp-packet-move 1.35s linear infinite;
}

.sfp-chips {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  flex-shrink: 0;
  min-height: 1.7rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sfp-chips li {
  display: grid;
  min-height: 1.7rem;
  place-items: center;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: none;
  color: var(--muted-foreground);
}

.sfp-chips li[data-on="true"] {
  border-color: color-mix(in oklab, var(--primary) 34%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, white);
  color: var(--primary);
}

.sfp-ledger {
  display: grid;
  grid-template-rows: repeat(4, 1.4rem);
  gap: 0.2rem;
  min-height: 6.2rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sfp-ledger li {
  display: grid;
  grid-template-columns: 1rem minmax(0, 1fr);
  align-items: center;
  gap: 0.4rem;
  min-height: 1.4rem;
  overflow: hidden;
  font-size: 0.68rem;
  line-height: 1.35;
  color: var(--muted-foreground);
}

.sfp-ledger li[data-done="true"],
.sfp-ledger li[data-current="true"] {
  color: var(--foreground);
}

.sfp-ledger li[data-current="true"] {
  color: var(--primary);
}

.sfp-ledger li span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sfp-track-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-content: start;
  justify-items: stretch;
  gap: 0.45rem;
  width: 100%;
  min-width: 0;
  min-height: 0;
  flex: 0 0 auto;
}

.sfp-track {
  display: flex;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  flex-direction: column;
  align-items: stretch;
  justify-self: stretch;
  align-self: stretch;
  gap: 0.14rem;
  overflow: visible;
  border-radius: 0.65rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, var(--background) 80%, white);
  padding: 0.45rem 0.55rem 0.5rem;
  text-align: left;
  cursor: pointer;
  color: inherit;
  appearance: none;
}

.sfp-track[data-hero="true"] {
  min-height: 0;
}

.sfp-track:hover,
.sfp-track:focus-visible {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  outline: none;
}

.sfp-track[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 36%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, white);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 18%, transparent);
}

.sfp-track-top {
  display: flex;
  flex-shrink: 0;
  width: 100%;
  min-height: 1.2rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
}

.sfp-track-icon {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 1.2rem;
  height: 1.2rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}

.sfp-track-top em {
  flex-shrink: 0;
  max-width: calc(100% - 1.6rem);
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 8px;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2rem;
  text-overflow: ellipsis;
  text-transform: none;
  white-space: nowrap;
  color: var(--muted-foreground);
}

.sfp-track[data-active="true"] .sfp-track-top em {
  color: var(--primary);
}

.sfp-track strong {
  width: 100%;
  margin-top: 0.04rem;
  font-size: 0.74rem;
  font-weight: 700;
  line-height: 1.2;
}

.sfp-track-settle {
  width: 100%;
  overflow: visible;
  font-size: 0.62rem;
  line-height: 1.3;
  color: var(--muted-foreground);
  white-space: normal;
  overflow-wrap: break-word;
}

.sfp-track-fee {
  width: 100%;
  flex-shrink: 0;
  margin-top: 0.08rem;
  padding-top: 0.1rem;
  overflow: visible;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  line-height: 1.3;
  white-space: normal;
  overflow-wrap: break-word;
  color: var(--foreground) !important;
}

.sfp-track[data-active="true"] .sfp-track-fee {
  color: var(--primary) !important;
}

.sfp-confirm {
  flex-shrink: 0;
}

.sfp-confirm[data-pulse="true"] {
  border-color: color-mix(in oklab, var(--primary) 34%, var(--border));
}

.sfp-confirm-line {
  min-height: 2.15rem;
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--foreground);
}

.sfp-feed {
  display: grid;
  grid-template-rows: repeat(4, 1.15rem);
  gap: 0.08rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sfp-feed li {
  overflow: hidden;
  font-size: 0.62rem;
  line-height: 1.15rem;
  color: color-mix(in oklab, var(--muted-foreground) 55%, transparent);
  text-overflow: ellipsis;
  white-space: nowrap;
  opacity: 0.45;
}

.sfp-feed li[data-on="true"] {
  color: var(--foreground);
  opacity: 1;
}

@keyframes sfp-packet-move {
  from {
    left: 0;
    opacity: 0;
  }
  18% {
    opacity: 1;
  }
  82% {
    opacity: 1;
  }
  to {
    left: 100%;
    opacity: 0;
  }
}

@keyframes sfp-settle-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 16%, transparent);
  }
  50% {
    box-shadow: 0 0 0 2px color-mix(in oklab, var(--primary) 32%, transparent);
  }
}

@media (max-width: 1023px) {
  .sfp-console .lc-screen {
    height: clamp(42rem, 84vh, 52rem);
    min-height: clamp(42rem, 84vh, 52rem);
    max-height: clamp(42rem, 84vh, 52rem);
  }

  .sfp-main {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto;
  }

  .sfp-canvas {
    min-height: 16.5rem;
  }

  .sfp-track-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: auto;
    min-height: 0;
  }

  .sfp-track,
  .sfp-track[data-hero="true"] {
    min-height: 0;
  }
}

@media (max-width: 639px) {
  .sfp-console .lc-screen {
    height: auto;
    min-height: 36rem;
    max-height: none;
  }

  .sfp-body {
    grid-template-rows: none;
    height: auto;
  }

  .sfp-pipe {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    min-height: 7.2rem;
  }

  .sfp-pipe-detail {
    white-space: normal;
  }

  .sfp-sale {
    flex-direction: column;
    min-height: 4.6rem;
  }

  .sfp-sale-rail {
    align-items: flex-start;
  }

  .sfp-sale-rail strong {
    text-align: left;
  }

  .sfp-path {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto 0.7rem auto 0.7rem auto;
    min-height: 15.4rem;
  }

  .sfp-link {
    width: 2px;
    height: 0.7rem;
    justify-self: center;
  }

  .sfp-packet {
    left: 50%;
    top: 0;
  }

  .sfp-link[data-live="true"] .sfp-packet {
    animation-name: sfp-packet-move-y;
  }

  .sfp-track-grid {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto;
    min-height: 0;
  }

  .sfp-track,
  .sfp-track[data-hero="true"] {
    min-height: 0;
  }

  .sfp-ledger {
    min-height: 8.4rem;
    grid-template-rows: repeat(4, minmax(1.8rem, auto));
  }

  .sfp-ledger li {
    min-height: 1.8rem;
    align-items: start;
  }

  .sfp-ledger li span:last-child {
    white-space: normal;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sfp-console .lc-spin,
  .sfp-console .lc-panel-dot,
  .sfp-packet,
  .sfp-console[data-stage="settle"][data-rail="usdt"] .sfp-node[data-dest="true"] {
    animation: none;
  }

  .sfp-link[data-live="true"] .sfp-packet {
    display: none;
  }
}

@keyframes sfp-packet-move-y {
  from {
    top: 0;
    opacity: 0;
  }
  18% {
    opacity: 1;
  }
  82% {
    opacity: 1;
  }
  to {
    top: 100%;
    opacity: 0;
  }
}

/* == TravelTools custom scrollbar (tpa-section) 2026-08-19 ==
   Homepage ToolsGrid quote desk only. Reuses the site scrollbar
   vocabulary (scrollbar-width / scrollbar-color / ::-webkit-scrollbar)
   with brand --primary thumb on a light desk track. Covers Live Seat
   Map console body, listings table, map legend, mini-console panes. */

.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body) {
  scrollbar-width: thin;
  scrollbar-color: var(--primary) color-mix(in oklab, var(--surface) 70%, white);
}

.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-track {
  background: color-mix(in oklab, var(--surface) 70%, white);
  border-radius: 999px;
}

.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--primary);
}

.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-thumb:hover {
  background: var(--primary-deep);
}

.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-corner {
  background: color-mix(in oklab, var(--surface) 70%, white);
}

/* == TravelTools margin popover + desk spacing (tpa-section) 2026-08-19 ==
   % Margin card was `position:absolute; right:0` on `.smt-margin-wrap` (the
   button). At 15.5rem it hung left of the listings column and was cropped by
   `.tpa-live` / `.smt-list-card` / `.lc-screen` overflow:hidden. Anchor to the
   full listings header instead. Live/map/table are not nested Y-scrollers —
   wheel over the desk scrolls the page. Absolute overlay does not grow the
   section. */

.smt-list-head {
  position: relative;
  z-index: 6;
  overflow: visible;
}

.smt-margin-wrap {
  position: static;
}

.smt-margin-pop {
  top: calc(100% + 0.45rem);
  right: 0;
  left: auto;
  width: min(17rem, 100%);
  max-width: 100%;
  box-sizing: border-box;
  z-index: 14;
  padding: 0.9rem 1rem 1rem;
}

.smt-margin-title {
  margin: 0 0 0.65rem;
  overflow: visible;
  white-space: normal;
}

.smt-stepper {
  gap: 0.4rem;
}

.smt-margin-note {
  margin: 0.65rem 0 0.8rem;
  overflow: visible;
  white-space: normal;
}

.tpa-section {
  --tpa-gap: 0.75rem;
  --tpa-gap-inner: 0.6rem;
}

.tpa-shell,
.tpa-stage,
.tpa-boards {
  gap: var(--tpa-gap);
}

.tpa-minis {
  gap: var(--tpa-gap-inner);
}

.tpa-section .tpa-rail {
  padding: 0.75rem 0.85rem 0.8rem;
}

@media (min-width: 900px) {
  .tpa-live {
    overflow: visible;
  }

  .tpa-section .smt-list-card {
    overflow: visible;
  }

  .tpa-section .smt-map-card {
    overflow: visible;
  }

  .tpa-section .smt-list-head,
  .tpa-section .smt-map-head {
    flex-shrink: 0;
    padding: 0.6rem 0.75rem 0.5rem;
  }

  .tpa-section .smt-console .lc-bezel {
    padding: 0.5rem;
  }

  .tpa-section .smt-console .lc-body {
    padding: 0;
    overflow: visible;
    overscroll-behavior: auto;
  }

  .tpa-section .smt-desk {
    gap: var(--tpa-gap-inner);
    padding: 0.7rem 0.75rem 0.75rem;
  }

  .tpa-section .smt-split {
    gap: var(--tpa-gap-inner);
  }

  .tpa-section .smt-table-wrap {
    overflow-x: auto;
    overflow-y: hidden;
    border-radius: 0 0 0.85rem 0.85rem;
  }
}

/* == Global custom scrollbar 2026-08-19 ==
   One recipe for html / body / every overflow pane.
   Thumb: --primary (hover --primary-deep). Track: light
   --surface / --background mix. Dark chrome (.bh-hero,
   .bg-dark, .toolkit) swaps only the track to a --dark mix
   so a white gutter does not sit on dark sections; thumb
   stays --primary. Firefox: scrollbar-width thin +
   scrollbar-color. WebKit: ~7px rounded.
   Does not change overflow or layout. Hidden-scrollbar
   hosts (.hero-eco-pipeline, .partner-tabs,
   .how-it-desktop-viewport scrollbar-width: none) stay hidden.
   Class-colored thumbs below are restated so cascade matches. */

:root {
  --sb-thumb: var(--primary);
  --sb-thumb-hover: var(--primary-deep);
  --sb-track: color-mix(in oklab, var(--surface) 70%, var(--background));
}

html,
body,
* {
  scrollbar-width: thin;
  scrollbar-color: var(--sb-thumb) var(--sb-track);
}

::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

::-webkit-scrollbar-track {
  background: var(--sb-track);
  border-radius: 999px;
}

::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--sb-thumb);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--sb-thumb-hover);
}

::-webkit-scrollbar-corner {
  background: var(--sb-track);
}

.bh-hero,
.bg-dark,
.toolkit {
  --sb-track: color-mix(in oklab, var(--dark) 82%, var(--background));
}

.toolkit-rail-list,
.ec-catalog-scroll,
.ec-catalog-scroll-x,
.pay-dash-scroll-x,
.er-scroll,
.ds-scroll,
.apidoc-nav,
.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body) {
  scrollbar-width: thin;
  scrollbar-color: var(--sb-thumb) var(--sb-track);
}

.toolkit-rail-list::-webkit-scrollbar-thumb,
.ec-catalog-scroll::-webkit-scrollbar-thumb,
.ec-catalog-scroll-x::-webkit-scrollbar-thumb,
.pay-dash-scroll-x::-webkit-scrollbar-thumb,
.apidoc-nav::-webkit-scrollbar-thumb,
.how-it-desktop-viewport::-webkit-scrollbar-thumb,
.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--sb-thumb);
}

.toolkit-rail-list::-webkit-scrollbar-thumb:hover,
.ec-catalog-scroll::-webkit-scrollbar-thumb:hover,
.ec-catalog-scroll-x::-webkit-scrollbar-thumb:hover,
.pay-dash-scroll-x::-webkit-scrollbar-thumb:hover,
.apidoc-nav::-webkit-scrollbar-thumb:hover,
.how-it-desktop-viewport::-webkit-scrollbar-thumb:hover,
.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-thumb:hover {
  background: var(--sb-thumb-hover);
}

.toolkit-rail-list::-webkit-scrollbar-track,
.ec-catalog-scroll::-webkit-scrollbar-track,
.ec-catalog-scroll-x::-webkit-scrollbar-track,
.pay-dash-scroll-x::-webkit-scrollbar-track,
.apidoc-nav::-webkit-scrollbar-track,
.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-track,
.tpa-section :is(.smt-table-wrap, .smt-legend, .lc-body, .tpa-card-body)::-webkit-scrollbar-corner {
  background: var(--sb-track);
  border-radius: 999px;
}

/* ── Stats wallet shuffle (homepage #network-stats) ── */
/* Idle: four cards fanned as a deck. On view: peel, riffle, settle into grid.
   Grid cells always occupy the settled height — transforms only. */

.stats-wallet {
  overflow: hidden;
}

.stats-wallet-shade {
  background:
    radial-gradient(
      70% 55% at 88% 108%,
      color-mix(in oklab, var(--primary) 16%, transparent) 0%,
      transparent 62%
    ),
    radial-gradient(
      55% 45% at 8% -8%,
      color-mix(in oklab, var(--surface) 88%, var(--primary) 8%) 0%,
      transparent 70%
    );
}

.stats-wallet-stage {
  --sw-gap: 0.85rem;
  --sw-scale: 0.88;
  --sw-dur: 920ms;
  --sw-ease: cubic-bezier(0.33, 0.08, 0.22, 1);
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--sw-gap);
  padding-block: 1.15rem;
  perspective: 1400px;
  transform-style: preserve-3d;
}

.stats-wallet-stage::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 0;
  width: min(16rem, 72%);
  height: 3.75rem;
  pointer-events: none;
  translate: -50% 55%;
  border-radius: 999px;
  background: radial-gradient(
    closest-side,
    color-mix(in oklab, var(--primary) 28%, transparent),
    transparent 78%
  );
  opacity: 0.42;
  filter: blur(6px);
  transition: opacity 0.55s var(--sw-ease);
}

.stats-wallet[data-phase="shuffle"] .stats-wallet-stage::after,
.stats-wallet[data-phase="spread"] .stats-wallet-stage::after {
  opacity: 0;
}

.stats-wallet-card {
  position: relative;
  z-index: 1;
  min-width: 0;
  min-height: 11.25rem;
  transform-origin: 50% 55%;
  transform-style: preserve-3d;
  backface-visibility: hidden;
  will-change: transform;
}

.stats-wallet-edge {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 2;
  width: 0.28rem;
  border-radius: 0.875rem 0 0 0.875rem;
  background: var(--primary);
  pointer-events: none;
}

.stats-wallet-card-face {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: inherit;
  overflow: hidden;
  padding: 1rem 1rem 1.05rem 1.2rem;
  border: 1px solid color-mix(in oklab, var(--border) 78%, var(--primary) 22%);
  border-radius: 0.875rem;
  background: var(--card);
  box-shadow:
    var(--shadow-card),
    0 18px 36px -28px color-mix(in oklab, var(--primary) 32%, transparent);
}

.stats-wallet-card-face::before {
  content: "";
  position: absolute;
  right: -1.4rem;
  bottom: -1.6rem;
  width: 6.5rem;
  height: 5.5rem;
  pointer-events: none;
  border-radius: 1.25rem;
  background: color-mix(in oklab, var(--primary-soft) 70%, transparent);
  transform: rotate(-18deg);
  opacity: 0.7;
}

.stats-wallet-card[data-hero="true"] .stats-wallet-card-face {
  background:
    linear-gradient(
      155deg,
      color-mix(in oklab, var(--primary-soft) 88%, white) 0%,
      var(--card) 58%
    );
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
}

.stats-wallet-card-top {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.stats-wallet-index {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--muted-foreground) 80%, var(--primary) 20%);
}

.stats-wallet-icon {
  display: flex;
  width: 2rem;
  height: 2rem;
  align-items: center;
  justify-content: center;
  border-radius: 0.55rem;
  background: color-mix(in oklab, var(--primary-soft) 92%, var(--primary) 8%);
  color: var(--primary);
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 18%, transparent);
}

.stats-wallet-value {
  position: relative;
  z-index: 1;
  margin-top: 0.85rem;
  font-family: var(--font-mono);
  font-size: clamp(1.65rem, 4.6vw, 2.15rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
  color: var(--primary-deep);
}

.stats-wallet-card[data-hero="true"] .stats-wallet-value {
  font-size: clamp(1.85rem, 5.2vw, 2.55rem);
}

.stats-wallet-label {
  position: relative;
  z-index: 1;
  margin-top: 0.45rem;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.25;
  color: var(--foreground);
}

.stats-wallet-desc {
  position: relative;
  z-index: 1;
  margin-top: 0.3rem;
  font-size: 0.75rem;
  line-height: 1.45;
  color: var(--muted-foreground);
}

/* Wallet fan — 2×2 (375 / tablet). % is the card itself, so 50% + half-gap
   moves each cell toward the stage centre. */
.stats-wallet-card:nth-child(1) {
  --sw-x: calc(50% + var(--sw-gap) / 2 - 6px);
  --sw-y: calc(50% + var(--sw-gap) / 2 + 8px);
  --sw-r: -12deg;
  --sw-peel-r: -20deg;
  --sw-mid-x: 26%;
  --sw-mid-y: -20%;
  --sw-mid-r: 16deg;
  z-index: 1;
}

.stats-wallet-card:nth-child(2) {
  --sw-x: calc(-50% - var(--sw-gap) / 2 + 4px);
  --sw-y: calc(50% + var(--sw-gap) / 2 - 4px);
  --sw-r: -4deg;
  --sw-peel-r: 10deg;
  --sw-mid-x: -30%;
  --sw-mid-y: -16%;
  --sw-mid-r: -14deg;
  z-index: 2;
}

.stats-wallet-card:nth-child(3) {
  --sw-x: calc(50% + var(--sw-gap) / 2 + 2px);
  --sw-y: calc(-50% - var(--sw-gap) / 2 + 6px);
  --sw-r: 6deg;
  --sw-peel-r: 14deg;
  --sw-mid-x: 20%;
  --sw-mid-y: 22%;
  --sw-mid-r: -12deg;
  z-index: 3;
}

.stats-wallet-card:nth-child(4) {
  --sw-x: calc(-50% - var(--sw-gap) / 2 - 4px);
  --sw-y: calc(-50% - var(--sw-gap) / 2 - 2px);
  --sw-r: 11deg;
  --sw-peel-r: 18deg;
  --sw-mid-x: -22%;
  --sw-mid-y: 14%;
  --sw-mid-r: 11deg;
  z-index: 4;
}

.stats-wallet[data-phase="wallet"] .stats-wallet-card {
  animation: none;
  transform: translate3d(var(--sw-x), var(--sw-y), 0) rotate(var(--sw-r)) rotateX(7deg)
    scale(var(--sw-scale));
}

.stats-wallet[data-phase="shuffle"] .stats-wallet-card {
  animation: stats-wallet-deal var(--sw-dur) var(--sw-ease) both;
  animation-delay: calc(var(--sw-i) * 75ms);
}

.stats-wallet[data-phase="shuffle"] .stats-wallet-card:nth-child(1) {
  z-index: 5;
}
.stats-wallet[data-phase="shuffle"] .stats-wallet-card:nth-child(2) {
  z-index: 4;
}
.stats-wallet[data-phase="shuffle"] .stats-wallet-card:nth-child(3) {
  z-index: 3;
}
.stats-wallet[data-phase="shuffle"] .stats-wallet-card:nth-child(4) {
  z-index: 2;
}

.stats-wallet[data-phase="spread"] .stats-wallet-card {
  transform: none;
  will-change: auto;
  z-index: 1;
}

@keyframes stats-wallet-deal {
  0% {
    transform: translate3d(var(--sw-x), var(--sw-y), 0) rotate(var(--sw-r)) rotateX(7deg)
      scale(var(--sw-scale));
  }
  24% {
    transform: translate3d(var(--sw-x), calc(var(--sw-y) - 36px), 18px) rotate(var(--sw-peel-r))
      rotateX(12deg) scale(1.05);
  }
  52% {
    transform: translate3d(var(--sw-mid-x), var(--sw-mid-y), 24px) rotate(var(--sw-mid-r))
      rotateX(4deg) scale(1.03);
  }
  78% {
    transform: translate3d(0, -6px, 0) rotate(-1.4deg) rotateX(0deg) scale(1.01);
  }
  100% {
    transform: translate3d(0, 0, 0) rotate(0deg) rotateX(0deg) scale(1);
  }
}

@media (min-width: 640px) {
  .stats-wallet-stage {
    --sw-gap: 1.1rem;
    --sw-scale: 0.92;
    padding-block: 1.35rem;
  }

  .stats-wallet-card {
    min-height: 12.25rem;
  }

  .stats-wallet-card-face {
    padding: 1.15rem 1.2rem 1.2rem 1.4rem;
  }

  .stats-wallet-desc {
    font-size: 0.8125rem;
  }
}

@media (min-width: 768px) {
  .stats-wallet-stage {
    --sw-gap: 1.2rem;
    --sw-scale: 0.94;
  }

  .stats-wallet-card {
    min-height: 13rem;
  }

  .stats-wallet-value {
    font-size: 2.15rem;
  }

  .stats-wallet-card[data-hero="true"] .stats-wallet-value {
    font-size: 2.55rem;
  }
}

/* Desktop / 1440: one row. Fan toward the horizontal centre. */
@media (min-width: 1024px) {
  .stats-wallet-stage {
    --sw-gap: 1.25rem;
    --sw-scale: 0.96;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    padding-block: 1.5rem;
  }

  .stats-wallet-card {
    min-height: 16.25rem;
  }

  .stats-wallet-card-face {
    padding: 1.25rem 1.25rem 1.35rem 1.5rem;
  }

  .stats-wallet-value {
    margin-top: 1.35rem;
    font-size: 2.35rem;
  }

  .stats-wallet-card[data-hero="true"] .stats-wallet-value {
    font-size: 2.85rem;
  }

  .stats-wallet-label {
    margin-top: 0.65rem;
    font-size: 0.9375rem;
  }

  .stats-wallet-desc {
    margin-top: 0.4rem;
    max-width: 16.5rem;
  }

  .stats-wallet-card:nth-child(1) {
    --sw-x: calc(1.5 * (100% + var(--sw-gap)) - 10px);
    --sw-y: 14px;
    --sw-r: -13deg;
    --sw-peel-r: -22deg;
    --sw-mid-x: 38%;
    --sw-mid-y: -28%;
    --sw-mid-r: 18deg;
  }

  .stats-wallet-card:nth-child(2) {
    --sw-x: calc(0.5 * (100% + var(--sw-gap)) + 4px);
    --sw-y: -8px;
    --sw-r: -5deg;
    --sw-peel-r: 8deg;
    --sw-mid-x: -18%;
    --sw-mid-y: -32%;
    --sw-mid-r: -16deg;
  }

  .stats-wallet-card:nth-child(3) {
    --sw-x: calc(-0.5 * (100% + var(--sw-gap)) - 2px);
    --sw-y: 10px;
    --sw-r: 5deg;
    --sw-peel-r: 14deg;
    --sw-mid-x: 16%;
    --sw-mid-y: 24%;
    --sw-mid-r: -10deg;
  }

  .stats-wallet-card:nth-child(4) {
    --sw-x: calc(-1.5 * (100% + var(--sw-gap)) + 8px);
    --sw-y: -6px;
    --sw-r: 12deg;
    --sw-peel-r: 20deg;
    --sw-mid-x: -36%;
    --sw-mid-y: 18%;
    --sw-mid-r: 12deg;
  }
}

@media (min-width: 1440px) {
  .stats-wallet-stage {
    --sw-gap: 1.5rem;
  }

  .stats-wallet-card {
    min-height: 17rem;
  }
}

@media (hover: hover) and (pointer: fine) {
  .stats-wallet[data-phase="spread"] .stats-wallet-card {
    transition: transform 0.38s var(--sw-ease);
  }

  .stats-wallet[data-phase="spread"] .stats-wallet-card:hover {
    transform: translateY(-7px);
    z-index: 3;
  }

  .stats-wallet[data-phase="spread"] .stats-wallet-card:hover .stats-wallet-card-face {
    box-shadow: var(--shadow-lift);
  }
}

@media (max-width: 479px) {
  .stats-wallet-stage {
    --sw-scale: 0.84;
    --sw-gap: 0.7rem;
    padding-block: 0.85rem;
  }

  .stats-wallet-card {
    min-height: 10.75rem;
  }

  .stats-wallet-card-face {
    padding: 0.85rem 0.8rem 0.9rem 1.05rem;
  }

  .stats-wallet-desc {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stats-wallet-card,
  .stats-wallet[data-phase="wallet"] .stats-wallet-card,
  .stats-wallet[data-phase="shuffle"] .stats-wallet-card,
  .stats-wallet[data-phase="spread"] .stats-wallet-card {
    animation: none !important;
    transform: none !important;
    will-change: auto;
  }

  .stats-wallet-stage::after {
    display: none;
  }
}

/* Testimonials card top-cap (thin diagonal bar only — not a full-card fill) */
.testimonials-card {
  position: relative;
  overflow: visible;
  border-radius: 1.25rem;
  border-color: color-mix(in oklab, #4be5ae 14%, white);
  /* background: color-mix(in oklab, #4be5ae 10%, white); */
  padding: 2.5rem 1.35rem 1.25rem;
}

.testimonials-card-cap {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 1.35rem;
  overflow: hidden;
  border-radius: 1.25rem 1.25rem 0 0;
  pointer-events: none;
}

.testimonials-card-cap-grey,
.testimonials-card-cap-teal {
  position: absolute;
  inset: 0;
}

.testimonials-card-cap-grey {
  background: #595c62;
  clip-path: polygon(0 0, 58% 0, 38% 100%, 0 100%);
}

.testimonials-card-cap-teal {
  background: #4be5ae;
  clip-path: polygon(59% 0, 100% 0, 100% 100%, 39% 100%);
}

.testimonials-card-avatar {
  display: flex;
  width: 2.75rem;
  height: 2.75rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  background: color-mix(in oklab, #4be5ae 18%, white);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 700;
  color: color-mix(in oklab, #4be5ae 38%, #16382c);
}

.testimonials-card-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.875rem;
  font-weight: 700;
  color: #595c62;
}

.testimonials-card-role {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.75rem;
  font-weight: 400;
  color: color-mix(in oklab, #595c62 62%, white);
}

.testimonials-card-stars {
  display: flex;
  gap: 0.125rem;
  margin-top: 0.75rem;
  color: #4be5ae;
}

.testimonials-card-quote {
  margin-top: 0.75rem;
  font-size: 13px;
  line-height: 1.625;
  color: #3d4044;
}

/* == Broker onboarding 2026-08-20 == */
/* Company-setup desk. Compact ConsoleShell: header / dense rail (icon +
   label) / 3-line ledger — sized to content, not stretched. Six-phase
   journey is one-open accordion (inactive = single row). Region copy in
   parts 3–5 uses stacked .bon-swap slots so a tab change cannot jump
   layout. Comparison table scrolls inside the card on small screens. */

.bon-section {
  --bon-gap: clamp(1rem, 2vw, 1.5rem);
  overflow-x: clip;
}

.bon-head {
  max-width: 54rem;
}

.bon-title {
  margin-top: 0.7rem;
  max-width: 22ch;
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 2.6vw, 2.35rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--foreground);
}

.bon-lead {
  margin-top: 0.7rem;
  max-width: 54ch;
  font-size: 0.9375rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

/* Part 1 — region pills (SeatsIntel™ / catalog pill pattern) -------- */

.bon-region-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.9rem;
}

.bon-region-tab {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, var(--border));
  background: var(--card);
  padding: 0.36rem 0.85rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  line-height: 1.2;
  color: var(--muted-foreground);
  cursor: pointer;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}

.bon-region-tab:hover {
  color: var(--foreground);
  border-color: color-mix(in oklab, var(--foreground) 18%, var(--border));
}

.bon-region-tab[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 45%, var(--border));
  background: color-mix(in oklab, var(--primary) 12%, var(--card));
  color: var(--primary);
}

.bon-region-tab:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.bon-swap {
  display: inline-grid;
  vertical-align: top;
}

.bon-swap > * {
  grid-area: 1 / 1;
  visibility: hidden;
}

.bon-swap > *[data-active="true"] {
  visibility: visible;
}

.bon-block-head {
  margin-bottom: 0.7rem;
}

.bon-block-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  color: var(--primary);
}

.bon-block-title {
  margin: 0.35rem 0 0;
  max-width: 28ch;
  font-size: clamp(1.15rem, 1.6vw, 1.4rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.bon-block-note {
  margin: 0.3rem 0 0;
  max-width: 62ch;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

/* Part 2 — regional comparison ------------------------------------- */

.bon-compare {
  margin-top: clamp(1.35rem, 2.6vw, 2rem);
}

.bon-compare-scroll {
  overflow-x: auto;
  overscroll-behavior-x: contain;
  max-width: 100%;
  padding-bottom: 0.15rem;
}

.bon-compare-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(11.25rem, 1fr));
  gap: 0.55rem;
  min-width: 46rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 900px) {
  .bon-compare-grid {
    min-width: 0;
  }
}

.bon-compare-col {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 0.85rem;
  background: var(--card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.bon-compare-col[data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--border));
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 22%, transparent);
}

.bon-compare-head {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 0.1rem;
  border: 0;
  border-bottom: 1px solid var(--border);
  background: color-mix(in oklab, var(--surface) 70%, var(--card));
  padding: 0.65rem 0.8rem 0.55rem;
  text-align: left;
  cursor: pointer;
}

.bon-compare-col[data-active="true"] .bon-compare-head {
  background: color-mix(in oklab, var(--primary) 8%, var(--card));
}

.bon-compare-head:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
}

.bon-compare-city {
  font-size: 0.9375rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  color: var(--foreground);
}

.bon-compare-desk {
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.bon-compare-col[data-active="true"] .bon-compare-desk {
  color: var(--primary);
}

.bon-compare-rows {
  display: grid;
  margin: 0;
  padding: 0.2rem 0;
}

.bon-compare-row {
  display: grid;
  gap: 0.1rem;
  padding: 0.4rem 0.8rem;
}

.bon-compare-row + .bon-compare-row {
  border-top: 1px dashed color-mix(in oklab, var(--border) 80%, transparent);
}

.bon-compare-row dt {
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.1em;
  color: var(--muted-foreground);
}

.bon-compare-row dd {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 550;
  line-height: 1.4;
  color: var(--foreground);
}

/* Part 3 — six-phase journey + compact desk ------------------------ */

.bon-region-panel {
  margin-top: clamp(1.35rem, 2.6vw, 2rem);
}

.bon-journey-split {
  display: grid;
  gap: var(--bon-gap);
  align-items: start;
}

@media (min-width: 1024px) {
  .bon-journey-split {
    grid-template-columns: minmax(0, 1.18fr) minmax(17.25rem, 0.92fr);
    gap: clamp(1.1rem, 1.8vw, 1.75rem);
  }
}

.bon-stage {
  position: relative;
  min-width: 0;
}

@media (min-width: 1024px) and (max-height: 1099px) {
  .bon-desk .lc-screen {
    max-height: calc(100svh - 8.5rem);
  }

  .bon-desk-inner {
    overflow-y: auto;
  }
}

@media (min-width: 1024px) and (min-height: 1100px) {
  .bon-stage {
    position: sticky;
    top: 5.25rem;
    max-height: calc(100svh - 5.75rem);
  }

  .bon-desk .lc-screen {
    max-height: calc(100svh - 7.25rem);
  }

  .bon-desk-inner {
    overflow-y: auto;
  }
}

.bon-stage-kicker {
  margin: 0 0 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.12em;
  color: var(--muted-foreground);
}

@media (min-width: 1024px) {
  .bon-stage-kicker {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
  }
}

.bon-phases {
  display: grid;
  gap: 0.32rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bon-phase {
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.bon-phase[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 40%, var(--border));
}

.bon-phase-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  width: 100%;
  border: 0;
  background: transparent;
  padding: 0.42rem 0.65rem;
  text-align: left;
  cursor: pointer;
}

.bon-phase-head:hover {
  background: color-mix(in oklab, var(--foreground) 3%, transparent);
}

.bon-phase-head:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
}

.bon-phase-head::after {
  content: "";
  flex-shrink: 0;
  width: 0.38rem;
  height: 0.38rem;
  margin-left: auto;
  border-right: 1.5px solid var(--muted-foreground);
  border-bottom: 1.5px solid var(--muted-foreground);
  transform: rotate(45deg);
  opacity: 0.5;
  transition: transform 220ms ease, opacity 220ms ease, border-color 220ms ease;
}

.bon-phase[data-current="true"] .bon-phase-head::after {
  transform: rotate(-135deg);
  border-color: var(--primary);
  opacity: 0.9;
}

.bon-phase-icon {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--primary) 25%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, var(--card));
  color: var(--primary);
}

.bon-phase[data-current="true"] .bon-phase-icon {
  border-color: var(--primary);
  background: color-mix(in oklab, var(--primary) 16%, var(--card));
}

.bon-phase-index {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.12em;
  color: var(--primary);
}

.bon-phase-head strong {
  min-width: 0;
  overflow: hidden;
  font-size: 0.875rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  color: var(--foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bon-phase:not([data-current="true"]) .bon-phase-head strong {
  color: color-mix(in oklab, var(--foreground) 78%, var(--muted-foreground));
}

.bon-phase-blurb {
  display: none;
  overflow: hidden;
  min-width: 0;
  max-width: 22ch;
  font-size: 0.6875rem;
  color: var(--muted-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bon-phase[data-current="true"] .bon-phase-blurb {
  display: inline;
}

@media (max-width: 639px) {
  .bon-phase-blurb {
    display: none !important;
  }
}

.bon-phase-body {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition:
    grid-template-rows 280ms ease,
    opacity 180ms ease;
}

.bon-phase[data-current="true"] .bon-phase-body {
  grid-template-rows: 1fr;
  opacity: 1;
}

.bon-phase-body-clip {
  min-height: 0;
  overflow: hidden;
}

.bon-phase-cols {
  display: grid;
  gap: 0.45rem;
  border-top: 1px solid var(--border);
  padding: 0.55rem 0.65rem 0.7rem;
}

@media (min-width: 720px) {
  .bon-phase-cols {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.bon-phase-col {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  background: color-mix(in oklab, var(--surface) 55%, var(--card));
  padding: 0.45rem 0.55rem 0.5rem;
}

.bon-phase-col[data-side="we"] {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, var(--card));
}

.bon-phase-label {
  margin: 0 0 0.28rem;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.12em;
  color: var(--muted-foreground);
}

.bon-phase-col[data-side="we"] .bon-phase-label {
  color: var(--primary);
}

.bon-phase-col ul {
  display: grid;
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bon-phase-col li {
  position: relative;
  padding-left: 0.7rem;
  font-size: 0.72rem;
  line-height: 1.35;
  color: var(--foreground);
}

.bon-phase-col li::before {
  content: "";
  position: absolute;
  top: 0.45rem;
  left: 0;
  width: 0.28rem;
  height: 0.28rem;
  border-radius: 999px;
  background: var(--primary);
}

.bon-phase-region {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--foreground);
}

/* Compact interactive demo — header / dense rail / ledger ----------- */

.bon-desk {
  min-width: 0;
}

.bon-desk .lc-frame,
.bon-desk .lc-bezel,
.bon-desk .lc-screen {
  min-width: 0;
}

.bon-desk .lc-bezel {
  padding: 0.45rem;
}

.bon-desk .lc-screen {
  height: auto;
  min-height: 0;
  max-height: none;
  overflow: hidden;
}

.bon-desk .lc-body {
  gap: 0;
  min-height: 0;
  overflow: hidden;
  padding: 0.55rem 0.6rem 0.6rem;
}

.bon-desk-inner {
  display: grid;
  grid-template-rows: auto auto auto;
  gap: 0.35rem;
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
}

.bon-desk-top {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  min-height: 1.35rem;
  padding-bottom: 0.4rem;
}

.bon-desk-top::before,
.bon-desk-top::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  height: 2px;
  border-radius: 999px;
}

.bon-desk-top::before {
  right: 0;
  background: color-mix(in oklab, var(--border) 85%, transparent);
}

.bon-desk-top::after {
  width: calc(var(--bon-progress, 0) * 100%);
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--primary) 45%, transparent),
    var(--primary)
  );
  transition: width 520ms cubic-bezier(0.4, 0, 0.2, 1);
}

.bon-kicker {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  min-width: 0;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.bon-kicker-count {
  overflow: hidden;
  border-left: 1px solid var(--border);
  padding-left: 0.5rem;
  color: var(--primary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bon-mode,
.bon-resume {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  min-height: 1.25rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.bon-resume {
  border: 1px solid color-mix(in oklab, var(--primary) 35%, var(--border));
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 12%, var(--card));
  padding: 0 0.6rem;
  letter-spacing: 0.06em;
  color: var(--primary);
  cursor: pointer;
}

.bon-resume:hover {
  background: color-mix(in oklab, var(--primary) 20%, var(--card));
}

.bon-rail {
  display: flex;
  flex-direction: column;
  gap: 0.06rem;
  flex: 0 0 auto;
  min-height: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bon-rail-item {
  position: relative;
  flex: 0 0 auto;
}

.bon-rail-item::before,
.bon-rail-item::after {
  content: "";
  position: absolute;
  left: 1.075rem;
  width: 2px;
  transform: translateX(-1px);
  border-radius: 999px;
  background: color-mix(in oklab, var(--border) 75%, transparent);
}

.bon-rail-item::before {
  top: -0.06rem;
  height: calc(50% - 0.48rem);
}

.bon-rail-item::after {
  top: calc(50% + 0.72rem);
  bottom: -0.06rem;
}

.bon-rail-item:first-child::before,
.bon-rail-item:last-child::after {
  display: none;
}

.bon-rail-item[data-state="done"]::before,
.bon-rail-item[data-state="done"]::after,
.bon-rail-item[data-state="current"]::before {
  background: color-mix(in oklab, var(--primary) 70%, transparent);
}

.bon-rail-item[data-state="current"]::after {
  background-color: transparent;
  background-image: repeating-linear-gradient(
    180deg,
    color-mix(in oklab, var(--primary) 70%, transparent) 0 3px,
    transparent 3px 8px
  );
  background-size: 100% 8px;
}

.bon-desk[data-live="true"] .bon-rail-item[data-state="current"]::after {
  animation: bon-rail-flow 0.85s linear infinite;
}

@keyframes bon-rail-flow {
  to {
    background-position: 0 8px;
  }
}

.bon-step {
  display: grid;
  grid-template-columns: 1.45rem minmax(0, 1fr);
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  min-height: 0;
  border: 1px solid transparent;
  border-radius: 0.55rem;
  background: transparent;
  padding: 0.1rem 0.3rem;
  text-align: left;
  cursor: pointer;
  transition:
    background 240ms ease,
    border-color 240ms ease;
}

.bon-step:hover {
  background: color-mix(in oklab, var(--foreground) 4%, transparent);
}

.bon-step:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.bon-step[data-state="current"] {
  border-color: color-mix(in oklab, var(--primary) 42%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, var(--card));
}

.bon-step[data-state="idle"] .bon-step-copy {
  opacity: 0.6;
}

.bon-step-mark {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 1.45rem;
  height: 1.45rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--muted-foreground);
  transition:
    color 240ms ease,
    border-color 240ms ease,
    background 240ms ease;
}

.bon-step[data-state="done"] .bon-step-mark {
  border-color: color-mix(in oklab, var(--primary) 40%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, var(--card));
  color: var(--primary);
}

.bon-step[data-state="current"] .bon-step-mark {
  border-color: var(--primary);
  background: color-mix(in oklab, var(--primary) 15%, var(--card));
  color: var(--primary);
}

.bon-step-tick {
  position: absolute;
  right: -0.15rem;
  bottom: -0.15rem;
  display: grid;
  place-items: center;
  width: 0.8rem;
  height: 0.8rem;
  border-radius: 999px;
  border: 1px solid var(--card);
  background: var(--primary);
  color: var(--primary-foreground);
}

.bon-step-ring {
  position: absolute;
  inset: -0.25rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 50%, transparent);
  opacity: 0;
}

.bon-desk[data-live="true"] .bon-step-ring {
  animation: bon-step-ring 1.9s ease-out infinite;
}

@keyframes bon-step-ring {
  0% {
    transform: scale(0.82);
    opacity: 0.85;
  }
  70% {
    transform: scale(1.2);
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}

.bon-step-copy {
  display: flex;
  min-width: 0;
  align-items: center;
}

.bon-step-label {
  display: -webkit-box;
  overflow: hidden;
  height: 1rem;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  font-size: 0.6875rem;
  font-weight: 650;
  line-height: 1rem;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.bon-step-index {
  margin-right: 0.3rem;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.bon-step[data-state="current"] .bon-step-index,
.bon-step[data-state="done"] .bon-step-index {
  color: var(--primary);
}

.bon-feed {
  display: grid;
  grid-template-rows: repeat(3, 1.1rem);
  gap: 0.1rem;
  margin: 0;
  overflow: hidden;
  padding: 0.28rem 0.45rem;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  background: color-mix(in oklab, var(--surface) 70%, var(--card));
  list-style: none;
}

.bon-feed-row {
  display: grid;
  grid-template-columns: 0.4rem minmax(0, 1fr);
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  height: 1.1rem;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  line-height: 1.1rem;
  color: var(--muted-foreground);
}

.bon-feed-row[data-state="idle"] {
  opacity: 0.4;
}

.bon-feed-row[data-state="done"] {
  color: color-mix(in oklab, var(--foreground) 72%, var(--muted-foreground));
}

.bon-feed-row[data-state="current"] {
  color: var(--primary);
}

.bon-feed-dot {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--muted-foreground) 40%, transparent);
}

.bon-feed-row[data-state="done"] .bon-feed-dot,
.bon-feed-row[data-state="current"] .bon-feed-dot {
  background: var(--primary);
}

.bon-desk[data-live="true"] .bon-feed-row[data-state="current"] .bon-feed-dot {
  animation: two-track-live-pulse 1.8s ease-out infinite;
}

.bon-feed-msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Part 4 — broker partner sub-accounts ----------------------------- */

.bon-partners {
  margin-top: clamp(1.35rem, 2.6vw, 2rem);
}

.bon-partner-gets {
  display: grid;
  gap: 0.55rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 720px) {
  .bon-partner-gets {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.bon-partner-get {
  display: grid;
  grid-template-columns: 1.15rem minmax(0, 1fr);
  gap: 0.45rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--card);
  padding: 0.7rem 0.75rem 0.75rem;
  box-shadow: var(--shadow-card);
}

.bon-partner-get-mark {
  display: grid;
  place-items: center;
  width: 1.2rem;
  height: 1.2rem;
  margin-top: 0.1rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--primary) 14%, var(--card));
  color: var(--primary);
}

.bon-partner-get strong {
  display: block;
  font-size: 0.875rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.bon-partner-get span span {
  display: block;
  margin-top: 0.2rem;
  font-size: 0.75rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

.bon-partner-notes {
  display: grid;
  gap: 0.5rem;
  margin: 0.7rem 0 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 720px) {
  .bon-partner-notes {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.bon-partner-notes li {
  border: 1px dashed color-mix(in oklab, var(--primary) 28%, var(--border));
  border-radius: 0.75rem;
  background: color-mix(in oklab, var(--primary) 4%, var(--card));
  padding: 0.6rem 0.75rem;
  font-size: 0.75rem;
  line-height: 1.45;
  color: var(--muted-foreground);
}

.bon-partner-notes strong {
  display: block;
  margin-bottom: 0.25rem;
  font-size: 0.6875rem;
  font-weight: 650;
  letter-spacing: 0.02em;
  color: var(--foreground);
}

/* Part 5 — region-aware checklist ---------------------------------- */

.bon-need {
  margin-top: clamp(1.35rem, 2.6vw, 2rem);
}

.bon-need-list {
  display: grid;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 720px) {
  .bon-need-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.bon-need-list li {
  display: grid;
  grid-template-columns: 1rem minmax(0, 1fr);
  align-items: start;
  gap: 0.45rem;
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  background: var(--card);
  padding: 0.5rem 0.65rem;
  font-size: 0.8125rem;
  line-height: 1.4;
  color: var(--foreground);
}

.bon-need-list li[data-region="true"] {
  border-color: color-mix(in oklab, var(--primary) 35%, var(--border));
  background: color-mix(in oklab, var(--primary) 6%, var(--card));
}

.bon-need-box {
  width: 1rem;
  height: 1rem;
  margin-top: 0.12rem;
  border: 1.5px solid color-mix(in oklab, var(--primary) 45%, var(--border));
  border-radius: 0.28rem;
  background: color-mix(in oklab, var(--primary) 8%, var(--card));
}

/* Part 6 — FAQ accordion ------------------------------------------- */

.bon-faq {
  margin-top: clamp(1.35rem, 2.6vw, 2rem);
}

.bon-faq-list {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--background);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.bon-faq-item {
  border-color: var(--border) !important;
}

.bon-faq-item:last-child {
  border-bottom: 0 !important;
}

.bon-faq-trigger {
  gap: 0.65rem !important;
  align-items: flex-start !important;
  min-height: 2.5rem;
  padding: 0.75rem 0.9rem !important;
  font-size: 0.9375rem !important;
  font-weight: 600 !important;
  line-height: 1.35 !important;
  text-decoration: none !important;
  color: var(--foreground) !important;
}

.bon-faq-trigger:hover,
.bon-faq-trigger:focus-visible {
  background: color-mix(in oklab, var(--primary) 6%, transparent);
  text-decoration: none !important;
  outline: none;
}

.bon-faq-trigger[data-state="open"] {
  background: var(--primary-soft);
}

.bon-faq-index {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.bon-faq-q {
  flex: 1;
  min-width: 0;
  text-align: left;
  overflow-wrap: anywhere;
}

.bon-faq-trigger svg {
  width: 1.125rem;
  height: 1.125rem;
  flex-shrink: 0;
  margin-top: 0.2rem;
  color: var(--primary);
}

.bon-faq-a {
  margin: 0;
  padding: 0 0.9rem 0.9rem 2.75rem;
  max-width: 62ch;
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--muted-foreground);
}

@media (prefers-reduced-motion: reduce) {
  .bon-step-ring,
  .bon-rail-item[data-state="current"]::after,
  .bon-feed-row[data-state="current"] .bon-feed-dot {
    animation: none;
  }

  .bon-step-ring {
    display: none;
  }

  .bon-region-tab,
  .bon-desk-top::after,
  .bon-step,
  .bon-step-mark,
  .bon-phase-body,
  .bon-phase-head::after {
    transition: none;
  }
}

/* == Homepage TravelTools laptop fit (tpa-section) 2026-08-20 ==
   MacBook CSS px at 100% zoom (not browser 80%): 1280×832, 1440×900,
   1470×956, 1512×982, 1680×1050, 1710×1112. Mini titles stay full
   (wrap, no ellipsis). Laptop 1024–1919 uses the same inner-zoom
   idea as .hero-fit-zoom (0.85), scoped to .tpa-fit-zoom only — never
   html. Do not inflate width/height by 1/0.85: that used box is wider
   than the viewport, and overflow:hidden on .tpa-section clips the
   right mini column (missing card border, “Quotatio” / “Share & c”).
   zoom: 0.85 with width: 100% (Hero pattern). Firefox without zoom
   keeps the reflow (column ratio + wrapping).
   375 / 768 / 900-stack / ≥1920 unchanged aside from title wrap. */

.tpa-fit-zoom {
  display: contents;
}

.tpa-minis .tpa-card-head {
  align-items: flex-start;
}

.tpa-minis .tpa-card-head h3 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  white-space: normal;
  text-overflow: unset;
  line-height: 1.2;
  font-size: clamp(0.78rem, 0.62rem + 0.7vw, 0.9rem);
}

.tpa-minis .tpa-row-label {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  white-space: normal;
  text-overflow: unset;
  line-height: 1.25;
}

@media (min-width: 900px) and (max-width: 1279px) {
  .tpa-boards {
    grid-template-columns: minmax(0, 1.06fr) minmax(0, 0.94fr);
  }
}

@media (min-width: 1280px) and (max-width: 1511px) {
  .tpa-boards {
    grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.88fr);
  }
}

@media (min-width: 1512px) and (max-width: 1919px) {
  .tpa-boards {
    grid-template-columns: minmax(0, 1.16fr) minmax(0, 0.84fr);
  }
}

@media (min-width: 900px) and (max-width: 1919px) {
  .tpa-minis .tpa-card {
    padding: 0.65rem 0.7rem 0.55rem;
  }

  .tpa-minis .tpa-card-note {
    height: 2.4rem;
    margin: 0.32rem 0 0.4rem;
    font-size: 0.7rem;
    line-height: 1.2;
  }

  .tpa-minis .tpa-card-metric {
    margin-top: 0.45rem;
    padding-top: 0.4rem;
  }

  .tpa-minis .tpa-card-metric span:first-child {
    font-size: clamp(1.05rem, 1.8vh, 1.35rem);
  }
}

@media (min-width: 1024px) and (max-width: 1919px) {
  .tpa-section {
    --tpa-fit-zoom: 0.85;
    --tpa-pad-y: clamp(1rem, 2.2vh, 1.55rem);
    padding-block: var(--tpa-pad-y);
  }

  .tpa-fit-zoom {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    align-self: stretch;
    box-sizing: border-box;
    width: 100%;
    max-width: 100%;
    min-width: 0;
    height: auto;
    max-height: none;
    min-height: 0;
    zoom: var(--tpa-fit-zoom);
    transform-origin: top left;
  }

  .tpa-fit-zoom > .tpa-shell {
    flex: 1 1 auto;
    width: 100%;
    min-width: 0;
    height: auto;
    max-height: none;
  }

  .tpa-boards,
  .tpa-live,
  .tpa-minis,
  .tpa-mini,
  .tpa-minis .tpa-card {
    min-width: 0;
    max-width: 100%;
  }
}

@media (min-width: 1024px) and (max-width: 1919px) and (max-height: 900px) {
  .tpa-section .tpa-head h2 {
    font-size: clamp(1.2rem, 0.95rem + 1.2vh, 1.65rem);
  }

  .tpa-lead {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
  }
}

@supports not (zoom: 0.85) {
  @media (min-width: 1024px) and (max-width: 1919px) {
    .tpa-section {
      padding-block: clamp(0.75rem, 1.8vh, 1.25rem);
    }

    .tpa-fit-zoom {
      display: contents;
      width: auto;
      max-width: none;
      height: auto;
      zoom: unset;
    }
  }
}

