  color: var(--foreground);
}

.sto-channel-lede {
  margin: 0;
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1.5;
  color: var(--muted-foreground);
}

.sto-buy-hop {
  position: relative;
  z-index: 0;
  display: grid;
  place-items: center;
  flex: 0 0 1.55rem;
  height: 1.55rem;
  margin: 0;
  overflow: hidden;
  pointer-events: none;
  color: var(--sto-line);
}

.sto-buy-svg {
  width: 0.75rem;
  height: 100%;
}

.sto-buy-hop .sto-hop-cap.is-end {
  top: auto;
  bottom: 0;
  left: 50%;
  right: auto;
  border-left-color: transparent;
  border-top-color: var(--sto-line);
  transform: translateX(-50%);
}

.sto-buy-hop .sto-hop-packet {
  position: absolute;
  left: 50%;
  top: 0;
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: var(--sto-line);
  transform: translateX(-50%);
  animation: sto-vpacket 1.8s linear infinite;
}

.sto-buy-hop .sto-hop-packet.is-follow {
  animation-delay: 0.9s;
}

.sto-buyers {
  display: grid;
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sto-buyers li {
  position: relative;
  display: grid;
  grid-template-columns: 1.15rem minmax(0, 1fr);
  align-items: center;
  gap: 0.35rem;
  min-height: 0;
  padding: 0.28rem 0.4rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 4px);
  background: var(--card);
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.2;
  overflow: visible;
}

.sto-buyers svg {
  width: 0.8rem;
  height: 0.8rem;
  color: var(--primary-deep);
}

.sto-process {
  position: relative;
  isolation: isolate;
  min-width: 0;
}

.sto-steps {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sto-flow {
  display: none;
}

.sto-step {
  position: relative;
  display: grid;
  gap: 0.22rem;
  min-width: 0;
  padding: 0.55rem 0.6rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: var(--shadow-card);
}

.sto-step[data-active="true"] {
  border-color: var(--primary);
  background: color-mix(in oklab, var(--primary) 10%, var(--card));
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--primary) 28%, transparent) inset,
    var(--shadow-card);
}

.sto-step-n {
  font-size: 0.625rem;
  font-weight: 700;
  color: var(--primary-deep);
}

.sto-step-icon {
  display: grid;
  width: 1.45rem;
  height: 1.45rem;
  place-items: center;
  border-radius: calc(var(--radius) - 6px);
  background: var(--muted);
  color: var(--primary-deep);
}

.sto-step-icon svg {
  width: 0.8rem;
  height: 0.8rem;
}

.sto-step h3 {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
}

.sto-step p {
  margin: 0;
  font-size: 0.6875rem;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.sto-step-arrow {
  display: none;
}

.sto-highlights {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.4rem;
  margin: 1rem 0 0.7rem;
  padding: 0.45rem;
  list-style: none;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--card);
}

.sto-highlights li {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  padding: 0.22rem 0.3rem;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.3;
}

.sto-highlights svg {
  flex-shrink: 0;
  width: 0.85rem;
  height: 0.85rem;
  color: var(--primary-deep);
}

.sto-close {
  margin: 0;
  text-align: center;
  font-size: 0.8125rem;
  font-style: italic;
  line-height: 1.45;
  color: var(--muted-foreground);
}

@keyframes sto-packet-fwd {
  from {
    left: 0;
  }
  to {
    left: calc(100% - 0.38rem);
  }
}

@keyframes sto-packet-rev {
  from {
    left: calc(100% - 0.38rem);
  }
  to {
    left: 0;
  }
}

@keyframes sto-vpacket {
  from {
    top: 0;
  }
  to {
    top: calc(100% - 0.38rem);
  }
}

@keyframes sto-vpacket-rev {
  from {
    top: calc(100% - 0.38rem);
  }
  to {
    top: 0;
  }
}

@keyframes sto-step-packet {
  from {
    left: 0;
  }
  to {
    left: calc(100% - 0.38rem);
  }
}

.sto-board[data-live="false"] .sto-hop-packet,
.sto-board[data-live="false"] .sto-vlink-packet,
.sto-board[data-live="false"] .sto-step-packet {
  animation: none;
  opacity: 1;
}

.sto-board[data-live="false"] .sto-hop-packet {
  left: 42%;
}

.sto-board[data-live="false"] .sto-vlink-packet {
  top: 0.7rem;
}

.sto-board[data-live="false"] .sto-step-packet {
  left: 40%;
}

.sto-board[data-live="false"] .sto-hop-packet.is-follow,
.sto-board[data-live="false"] .sto-vlink-packet.is-follow,
.sto-board[data-live="false"] .sto-step-packet.is-follow {
  display: none;
}

.sto-board[data-live="false"] .sto-channel[data-named="true"],
.sto-board[data-live="false"] .sto-channel-live i {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .sto-hop-packet,
  .sto-vlink-packet,
  .sto-step-packet,
  .sto-channel[data-named="true"],
  .sto-channel-live i {
    animation: none !important;
    opacity: 1;
  }

  .sto-hop-packet {
    left: 42%;
  }

  .sto-vlink-packet {
    top: 0.7rem;
  }

  .sto-step-packet {
    left: 40%;
  }

  .sto-hop-packet.is-follow,
  .sto-vlink-packet.is-follow,
  .sto-step-packet.is-follow {
    display: none;
  }
}

@media (min-width: 480px) {
  .sto-connect-list {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .sto-mods {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sto-highlights {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 640px) {
  .sto-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 1.15rem;
  }

  .sto-step-arrow {
    display: block;
    position: absolute;
    top: 50%;
    left: 100%;
    right: auto;
    width: 1.15rem;
    height: 2px;
    overflow: hidden;
    border: none;
    background: repeating-linear-gradient(
      90deg,
      var(--sto-line) 0 10px,
      transparent 10px 18px
    );
    transform: translateY(-50%);
  }

  .sto-step-arrow::after {
    content: "";
    position: absolute;
    top: 50%;
    right: 0;
    border: 4px solid transparent;
    border-left-color: var(--sto-line);
    transform: translateY(-50%);
  }

  .sto-step-packet {
    position: absolute;
    top: 50%;
    width: 0.38rem;
    height: 0.38rem;
    border-radius: 999px;
    background: var(--sto-line);
    transform: translateY(-50%);
    animation: sto-step-packet 2s linear infinite;
  }

  .sto-step-packet.is-follow {
    animation-delay: 1s;
  }

  .sto-step:nth-child(2n) .sto-step-arrow {
    display: none;
  }

  .sto-highlights {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 900px) {
  .sto-steps {
    grid-template-columns: repeat(3, minmax(0, 18rem));
    grid-auto-rows: 1fr;
    justify-content: center;
    justify-items: stretch;
    column-gap: 1.15rem;
    row-gap: 2.65rem;
  }

  .sto-step {
    z-index: 1;
    height: 100%;
    overflow: hidden;
  }

  .sto-step-arrow {
    display: none !important;
  }

  .sto-flow {
    display: block;
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: visible;
    pointer-events: none;
    color: var(--sto-line);
  }

  .sto-flow-svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
  }

  .sto-highlights {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 0.2rem;
    padding: 0.4rem 0.5rem;
  }

  .sto-highlights li {
    justify-content: center;
    text-align: left;
    font-size: 0.6875rem;
  }
}

@media (min-width: 1024px) {
  .sto-section {
    --sto-gutter: 3.5rem;
  }

  .sto-head {
    flex-direction: row;
    align-items: flex-end;
    justify-content: space-between;
    gap: 1.5rem;
  }

  .sto-tagline {
    text-align: right;
  }

  .sto-diagram {
    grid-template-columns: var(--sto-rail) minmax(0, 1fr) var(--sto-rail);
    column-gap: var(--sto-gutter);
    row-gap: 0;
    align-items: stretch;
  }

  .sto-vlink {
    display: none;
  }

  .sto-steps {
    grid-template-columns: repeat(6, minmax(0, 11rem));
    column-gap: 0.7rem;
    row-gap: 0;
  }

  .sto-step {
    padding: 0.45rem 0.5rem 0.5rem;
  }

  .sto-step h3 {
    font-size: 0.75rem;
  }

  .sto-step p {
    font-size: 0.625rem;
    line-height: 1.35;
  }

  .sto-hop {
    display: block;
    position: absolute;
    top: 50%;
    left: calc(100% + var(--sto-rail-pad) + 1px);
    z-index: 0;
    width: var(--sto-gutter);
    height: 0.85rem;
    overflow: hidden;
    pointer-events: none;
    color: var(--sto-line);
    transform: translateY(-50%);
  }

  .sto-hop-cap {
    position: absolute;
    top: 50%;
    width: 0;
    height: 0;
    border: 5px solid transparent;
  }

  .sto-hop-cap.is-end {
    right: 0;
    border-left-color: var(--sto-line);
    transform: translateY(-50%);
  }

  .sto-hop-cap.is-start {
    left: 0;
    border-right-color: var(--sto-line);
    transform: translateY(-50%);
  }

  .sto-hop .sto-hop-packet {
    position: absolute;
    top: 50%;
    width: 0.38rem;
    height: 0.38rem;
    border-radius: 999px;
    background: var(--sto-line);
    transform: translateY(-50%);
    animation: sto-packet-fwd 2.6s linear infinite;
  }

  .sto-hop .sto-hop-packet.is-follow {
    animation-delay: 1.3s;
  }

  .sto-hop .sto-hop-packet.is-rev {
    animation-name: sto-packet-rev;
    animation-delay: 0.65s;
  }

  .sto-chan-row .sto-hop,
  .sto-chan-cluster .sto-hop,
  .sto-channel .sto-hop {
    left: auto;
    right: calc(100% + var(--sto-rail-pad) + 1px);
  }

  .sto-mods {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .sto-connect-list li {
    justify-content: center;
  }
}

@media (min-width: 1280px) {
  .sto-section {
    --sto-gutter: 4.75rem;
  }

  .sto-mods {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }

  .sto-mod h3 {
    font-size: 0.7rem;
  }

  .sto-steps {
    grid-template-columns: repeat(6, minmax(0, 12rem));
    column-gap: 0.85rem;
  }
}

@media (min-width: 1440px) {
  .sto-section {
    --sto-gutter: 5.5rem;
  }
}

@media (min-width: 1920px) {
  .sto-section {
    --sto-gutter: 6rem;
  }
}

@media (max-width: 479px) {
  .sto-connect-list li {
    font-size: 0.625rem;
  }

  .sto-channel-n,
  .sto-sys-item strong {
    overflow-wrap: anywhere;
  }

  .sto-channel-n {
    white-space: normal;
  }
}

@media (max-width: 639px) {
  .sto-step-arrow {
    display: block;
    position: static;
    width: 1.5px;
    height: 0.7rem;
    margin: 0.35rem auto -0.15rem;
    border: none;
    background: repeating-linear-gradient(
      180deg,
      var(--sto-line) 0 2.5px,
      transparent 2.5px 6px
    );
  }

  .sto-step-arrow::after {
    content: "";
    position: static;
    display: block;
    width: 0;
    height: 0;
    margin: 0.45rem 0 0 -3px;
    border: 4px solid transparent;
    border-top-color: var(--sto-line);
    border-left-color: transparent;
  }

  .sto-step:last-child .sto-step-arrow {
    display: none;
  }

  .sto-step-packet {
    display: none;
  }
}

/* == TravelTools page scroll (tpa-section) 2026-08-20 ==
   Wheel over Live Seat Map / listings / map was swallowed by nested
   overflow:auto on .lc-body and .smt-table-wrap inside the 100svh
   overflow:hidden lock. Same class as HowItWorks: no nested overflow-y-auto;
   wheel anywhere in #travel continues document scroll. Table stays
   overflow-x only. tpa-fit-zoom remains width 100% / 0.85. */

.tpa-section .smt-console .lc-screen,
.tpa-section .smt-console .lc-body {
  overflow: visible;
  overscroll-behavior: auto;
}

.tpa-section .smt-table-wrap {
  overflow-x: auto;
  overflow-y: hidden;
}

@media (min-width: 900px) {
  .tpa-section {
    height: auto;
    max-height: none;
    overflow: visible;
  }

  .tpa-shell,
  .tpa-fit-zoom,
  .tpa-fit-zoom > .tpa-shell {
    height: auto;
    max-height: none;
    min-height: min-content;
  }

  .tpa-stage,
  .tpa-live,
  .tpa-minis,
  .tpa-minis .tpa-card,
  .tpa-section .smt-map-card,
  .tpa-section .smt-list-card {
    overflow: visible;
  }

  .tpa-minis .tpa-card-body {
    overflow: visible;
    overscroll-behavior: auto;
  }

  .tpa-section .smt-map-stage {
    overflow: clip;
  }
}

/* == TravelTools mini cards size-to-content (tpa-minis) 2026-08-20 ==
   2×2 sat in a 100svh column (grid 1fr rows + height:100% cards).
   .tpa-card-body / .tpa-rows used flex:1 so queued Quote / Margin / Share
   left a hollow well above the inner foot. Cards now size to content;
   lists keep a 4-row slot so auto-run does not jump. Notes wrap 2 lines.
   Metric value + label share one baseline. Page scroll / .tpa-fit-zoom
   width 100% unchanged.

   Desktop leftover column height (Live desk taller than the 2×2) is
   split equally above and below the cluster: .tpa-minis stretches in
   .tpa-boards, rows stay auto, align-content/place-content: center.
   Do not stretch card bodies (flex:1 recreates the wells). */

.tpa-minis {
  --tpa-row-h: 1.6rem;
  --tpa-row-gap: 0.28rem;
  --tpa-rows-h: calc(4 * var(--tpa-row-h) + 3 * var(--tpa-row-gap));
  align-items: start;
  align-content: start;
  grid-template-rows: repeat(2, auto);
}

.tpa-mini {
  height: auto;
  min-height: 0;
  align-self: start;
}

.tpa-minis .tpa-card {
  height: auto;
  min-height: 0;
}

.tpa-minis .tpa-card-note {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  white-space: normal;
  overflow: hidden;
  text-overflow: unset;
  height: calc(1.35em * 2 + 0.2rem);
  min-height: calc(1.35em * 2 + 0.2rem);
  max-height: calc(1.35em * 2 + 0.2rem);
  line-height: 1.35;
}

.tpa-minis .tpa-card-body {
  flex: 0 0 auto;
  min-height: 0;
  height: auto;
}

.tpa-minis .tpa-meta,
.tpa-minis .tpa-dial,
.tpa-minis .tpa-foot {
  flex: 0 0 auto;
}

.tpa-minis .tpa-rows {
  flex: 0 0 auto;
  min-height: var(--tpa-rows-h);
}

.tpa-minis .tpa-row {
  flex: 0 0 auto;
}

.tpa-minis .tpa-card-metric {
  flex: 0 0 auto;
  align-items: baseline;
  margin-top: 0.5rem;
}

.tpa-minis .tpa-card-metric span:first-child,
.tpa-minis .tpa-card-metric span:last-child {
  line-height: 1;
}

@media (min-width: 900px) {
  .tpa-boards {
    align-items: stretch;
  }

  .tpa-minis {
    align-self: stretch;
    height: 100%;
    min-height: 0;
    align-items: start;
    align-content: center;
    place-content: center;
    grid-template-rows: repeat(2, auto);
  }

  .tpa-mini,
  .tpa-minis .tpa-card {
    height: auto;
    min-height: 0;
    align-self: start;
  }

  .tpa-minis .tpa-card {
    --tpa-body-h: 0px;
  }

  .tpa-minis .tpa-card-body {
    flex: 0 0 auto;
    min-height: 0;
  }
}

@media (min-width: 900px) and (max-width: 1919px) {
  .tpa-minis .tpa-card-note {
    height: calc(1.35em * 2 + 0.2rem);
    min-height: calc(1.35em * 2 + 0.2rem);
    max-height: calc(1.35em * 2 + 0.2rem);
    line-height: 1.35;
  }

  .tpa-minis .tpa-card-metric span:first-child {
    font-size: clamp(1.05rem, 1.8vh, 1.35rem);
    line-height: 1;
  }
}

/* == TravelTools mini column fill + equal cards (tpa-*) 2026-08-20 ==
   Right column leftover (Live desk taller than the 2×2) is occupied by
   pipeline chrome above and a status strip below — not place-content
   centering. All four .tpa-mini share one height: reserved 2-line title
   + 2-line note + board (meta, dial, 4 rows, foot) + metric. Extra
   stretch goes into the four row cells, not a hollow well. Do not
   inflate .tpa-fit-zoom by 1/0.85. SellerTools / .sto-* untouched. */

.tpa-side {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  min-width: 0;
  min-height: 0;
}

.tpa-side-cap,
.tpa-side-stat {
  flex: 0 0 auto;
  border-radius: 0.85rem;
  border: 1px solid color-mix(in oklab, var(--primary) 16%, var(--border));
  background: color-mix(in oklab, var(--primary) 5%, white);
  padding: 0.48rem 0.55rem 0.5rem;
}

.tpa-side-cap-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem 0.6rem;
  min-height: 1.35rem;
}

.tpa-side-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}

.tpa-side-now {
  margin: 0;
  min-width: 0;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.3;
  color: var(--primary-deep);
}

.tpa-side-now span {
  margin-right: 0.28rem;
}

.tpa-side-run {
  margin: 0.28rem 0 0;
  min-height: 1.05rem;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  line-height: 1.05rem;
  color: var(--muted-foreground);
}

.tpa-side-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.28rem;
  margin: 0.38rem 0 0;
  padding: 0;
  list-style: none;
}

.tpa-side-steps li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 0.28rem;
  row-gap: 0.02rem;
  min-height: 2.35rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--border) 88%, white);
  background: var(--background);
  padding: 0.28rem 0.32rem;
}

.tpa-side-steps li[data-done="true"] {
  border-color: color-mix(in oklab, var(--primary) 22%, var(--border));
}

.tpa-side-steps li[data-current="true"] {
  border-color: color-mix(in oklab, var(--primary) 38%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, white);
}

.tpa-side-step-idx {
  grid-column: 1;
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.tpa-side-step-icon {
  grid-column: 2;
  justify-self: end;
  width: 0.7rem;
  height: 0.7rem;
  color: var(--primary);
  opacity: 0.45;
}

.tpa-side-steps li[data-done="true"] .tpa-side-step-icon,
.tpa-side-steps li[data-current="true"] .tpa-side-step-icon {
  opacity: 1;
}

.tpa-side-steps strong {
  grid-column: 1 / -1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1.15;
  color: var(--foreground);
}

.tpa-side-steps em {
  grid-column: 1 / -1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 0.55rem;
  font-style: normal;
  line-height: 1.2;
  color: var(--muted-foreground);
}

.tpa-side-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.28rem;
  margin: 0;
}

.tpa-side-stat-grid > div {
  min-width: 0;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--border) 88%, white);
  background: var(--background);
  padding: 0.28rem 0.35rem 0.32rem;
}

.tpa-side-stat-grid dt {
  margin: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted-foreground);
}

.tpa-side-stat-grid dd {
  margin: 0.1rem 0 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 0.82rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--primary);
}

.tpa-side-legend {
  margin: 0.38rem 0 0;
  min-height: 1.7rem;
  font-size: 0.68rem;
  line-height: 1.25;
  color: var(--muted-foreground);
}

.tpa-minis {
  --tpa-row-h: 1.85rem;
  --tpa-row-gap: 0.28rem;
  --tpa-rows-h: calc(4 * var(--tpa-row-h) + 3 * var(--tpa-row-gap));
  align-items: stretch;
  align-content: stretch;
  grid-template-rows: repeat(2, minmax(0, 1fr));
}

.tpa-mini {
  display: flex;
  min-height: 0;
  height: 100%;
  align-self: stretch;
}

.tpa-minis .tpa-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.tpa-minis .tpa-card-head {
  flex: 0 0 auto;
  min-height: calc(1.2em * 2 + 0.2rem);
}

.tpa-minis .tpa-card-head h3 {
  min-height: calc(1.2em * 2);
}

.tpa-minis .tpa-card-note {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  white-space: normal;
  text-overflow: unset;
  height: calc(1.35em * 2);
  min-height: calc(1.35em * 2);
  max-height: calc(1.35em * 2);
  line-height: 1.35;
}

.tpa-minis .tpa-card-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  height: auto;
}

.tpa-minis .tpa-meta,
.tpa-minis .tpa-dial,
.tpa-minis .tpa-foot {
  flex: 0 0 auto;
}

.tpa-minis .tpa-rows {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: var(--tpa-rows-h);
}

.tpa-minis .tpa-row {
