/* ── ToolkitShowcase static desks (SeatsSource / SeatsMarket / SeatsFunds) ──
   Prefix: .tks-* only. Do not use .sto-* or .tpa-*.
   Consoles fill .toolkit-screen; no auto-cycle, packets, or scan loops. */

.tks-desk {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.tks-desk .lc-frame,
.tks-desk .lc-bezel {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  max-width: 100%;
  max-height: 100%;
}

.tks-desk .lc-bezel {
  padding: 0.28rem;
  border-radius: 0.55rem;
}

.tks-desk .lc-screen {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  max-height: 100%;
  border-radius: 0.45rem;
}

.tks-desk .lc-scan,
.tks-desk .lc-scan * {
  animation: none;
  opacity: 0;
}

.tks-desk .lc-panel-dot,
.tks-desk .two-track-chrome-pulse,
.tks-desk .two-track-chrome-pulse::after {
  animation: none;
}

.tks-desk .two-track-chrome {
  gap: 0.4rem;
  padding: 0.32rem 0.55rem;
}

.tks-desk .two-track-chrome-path {
  font-size: 10px;
}

.tks-desk .lc-body {
  gap: 0;
  padding: 0.38rem 0.42rem 0.42rem;
  overflow: hidden;
}

.tks-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 0.38rem;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.tks-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.32rem;
  min-width: 0;
}

.tks-desk .lc-stat {
  min-width: 0;
  padding: 0.28rem 0.4rem;
}

.tks-desk .lc-stat-value {
  overflow: hidden;
  font-size: clamp(0.72rem, 1.35vw, 0.92rem);
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tks-context {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.tks-context-copy {
  min-width: 0;
}

.tks-kicker {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--muted-foreground);
}

.tks-title {
  margin: 0.08rem 0 0;
  font-size: clamp(0.72rem, 1.45vw, 0.88rem);
  font-weight: 650;
  line-height: 1.25;
  color: var(--foreground);
}

.tks-chip {
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, transparent);
  padding: 0.14rem 0.48rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.tks-work {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.38rem;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.tks-panel {
  min-width: 0;
  min-height: 0;
  height: 100%;
  padding: 0.4rem 0.45rem;
}

.tks-side {
  display: none;
}

.tks-desk .lc-panel-head {
  flex-shrink: 0;
  margin-bottom: 0.12rem;
}

.tks-desk .lc-panel-badge {
  max-width: 55%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tks-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  font-size: clamp(0.62rem, 1.15vw, 0.72rem);
}

.tks-table th {
  padding: 0.1rem 0.18rem 0.22rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-align: left;
  color: var(--muted-foreground);
}

.tks-table td {
  padding: 0.22rem 0.18rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  color: var(--foreground);
  vertical-align: middle;
}

.tks-event {
  overflow: hidden;
  font-weight: 650;
  line-height: 1.25;
  overflow-wrap: anywhere;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tks-num {
  text-align: right;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.tks-ask {
  font-weight: 700;
  color: var(--primary);
}

.tks-sync {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  min-width: 0;
}

.tks-tick {
  width: 0.72rem;
  height: 0.72rem;
  flex-shrink: 0;
  color: var(--primary);
}

.tks-tick-hold {
  display: block;
  width: 0.55rem;
  height: 0.55rem;
  flex-shrink: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 28%, transparent);
}

.tks-sync-label {
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tks-status {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  border-radius: 999px;
  padding: 0.06rem 0.38rem;
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.tks-status[data-tone="wait"] {
  color: var(--foreground);
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
}

.tks-status[data-tone="hold"] {
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--foreground) 6%, transparent);
}

.tks-map {
  display: block;
  width: 100%;
  height: auto;
  max-height: 5.2rem;
}

.tks-map-pitch {
  fill: color-mix(in oklab, var(--primary) 10%, var(--background));
  stroke: color-mix(in oklab, var(--primary) 28%, var(--border));
}

.tks-map-block {
  fill: color-mix(in oklab, var(--muted) 80%, white);
  stroke: var(--border);
}

.tks-map-hot {
  fill: color-mix(in oklab, var(--primary) 18%, white);
  stroke: color-mix(in oklab, var(--primary) 45%, var(--border));
}

.tks-map-hold {
  fill: color-mix(in oklab, var(--muted) 92%, white);
  stroke: color-mix(in oklab, var(--foreground) 16%, var(--border));
}

.tks-map text {
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  fill: var(--foreground);
}

.tks-holds,
.tks-mirror,
.tks-rails {
  display: grid;
  gap: 0.28rem;
  margin: 0.28rem 0 0;
  padding: 0;
  list-style: none;
  min-height: 0;
}

.tks-holds li,
.tks-mirror li,
.tks-rails li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.08rem 0.4rem;
  min-width: 0;
  padding: 0.28rem 0.35rem;
  border: 1px solid var(--border);
  border-radius: 0.45rem;
  background: color-mix(in oklab, var(--background) 80%, white);
}

.tks-holds li strong,
.tks-mirror li strong,
.tks-rails li strong {
  min-width: 0;
  overflow: hidden;
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tks-holds li span,
.tks-mirror li span {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  color: var(--primary);
}

.tks-holds li em,
.tks-mirror li em,
.tks-rails li em {
  grid-column: 1 / -1;
  font-family: var(--font-mono);
  font-size: 9px;
  font-style: normal;
  color: var(--muted-foreground);
}

@container tks (min-width: 26rem) and (min-height: 18.5rem) {
  .tks-work {
    grid-template-columns: minmax(0, 1.28fr) minmax(0, 0.82fr);
  }

  .tks-side {
    display: flex;
    flex-direction: column;
  }
}

@container tks (max-width: 21.5rem) {
  .tks-sync-label,
  .tks-col-section {
