.toolkit-light-flow {
  display: grid;
  gap: 1.25rem;
  min-width: 0;
}

.toolkit-light-steps {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.toolkit-light-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.85rem;
