}

.toolkit-light-step-index {
  display: inline-flex;
  min-width: 1.75rem;
  margin-top: 0.1rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.toolkit-light-step-label {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
