  }
}

.toolkit-light-dest-icon {
  width: 0.95rem;
  height: 0.95rem;
  flex-shrink: 0;
  color: var(--primary);
}

.toolkit-light-dest-label {
  min-width: 0;
  font-size: max(0.75rem, 0.8125rem);
  font-weight: 650;
  line-height: 1.25;
  color: var(--foreground);
  overflow-wrap: anywhere;
}

.toolkit-light-hero,
.toolkit-light-support {
  display: grid;
  gap: 0.55rem;
  min-width: 0;
}

.toolkit-light-desk-label {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
