}

.toolkit-light-support {
  margin-top: 2rem;
  padding-top: 1.75rem;
  border-top: 1px solid var(--border);
}

@media (min-width: 1024px) {
  .toolkit-light-support {
    grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
