}

@media (min-width: 768px) {
  .toolkit-light-foot {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 1.25rem;
  }
}

.toolkit-light-support-line {
  margin: 0;
  max-width: 28rem;
  font-size: max(0.75rem, 0.875rem);
  line-height: 1.5;
  color: var(--muted-foreground);
}

.toolkit-light-ctas {
  display: flex;
  flex-wrap: wrap;
