/* ============================================================
   Global Distribution mockup match (#platform-toolkit)
   Prefix: .toolkit-light* / .tks-* only.
   Do not touch .sto-* .tpa-* .mps-* .how-it-* .prd-* .int-*
   .feature-orbit-* .journey-num* .stats-wallet-* .mihp-*.
   Light surface + one static Ready desk + fan-out tree + logo
   strip. Content-height desk (no size-container / aspect-ratio
   lock) so all eight channel rows stay visible. Document scroll;
   overflow hidden both axes on .toolkit (never x-clip + y-visible).
   ============================================================ */

.toolkit.toolkit-light {
  --sb-track: color-mix(in oklab, var(--surface) 88%, var(--background));
}

.toolkit-light-col {
  display: grid;
  gap: 1.35rem;
  min-width: 0;
}

.toolkit.toolkit-light .toolkit-light-header {
  display: grid;
  gap: 0.85rem;
  max-width: none;
}

.toolkit.toolkit-light .toolkit-light-lead {
  max-width: 36rem;
  font-size: max(0.75rem, 0.9375rem);
}

.toolkit.toolkit-light .toolkit-light-stage {
  align-items: start;
  margin-top: 0;
}

@media (max-width: 1023px) {
  .toolkit.toolkit-light .toolkit-light-hero {
    order: 0;
  }
}

.toolkit.toolkit-light .toolkit-light-hero,
.toolkit.toolkit-light .toolkit-screen-hero {
  aspect-ratio: auto;
  height: auto;
  min-height: 0;
  max-height: none;
  overflow: hidden;
  container-type: normal;
  container-name: none;
  border-radius: 0.85rem;
}

.toolkit.toolkit-light .tks-desk,
.toolkit.toolkit-light .tks-desk .lc-frame,
.toolkit.toolkit-light .tks-desk .lc-bezel,
.toolkit.toolkit-light .tks-desk .lc-screen {
  height: auto;
  max-height: none;
  min-height: 0;
}

.toolkit.toolkit-light .tks-desk .lc-screen {
  overflow: hidden;
}

.toolkit.toolkit-light .tks-desk .lc-grid,
.toolkit.toolkit-light .tks-desk .lc-glare,
.toolkit.toolkit-light .tks-desk .lc-scan {
  display: none;
}

.toolkit.toolkit-light .tks-desk .lc-body {
  overflow: hidden;
}

.toolkit.toolkit-light .tks-body {
  height: auto;
  grid-template-rows: auto auto;
  gap: 0.55rem;
}

.toolkit.toolkit-light .tks-stats-hub {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) repeat(2, minmax(0, 0.7fr)) auto;
  align-items: stretch;
  gap: 0.4rem;
}

.toolkit.toolkit-light .tks-stat-hub {
  gap: 0.12rem;
}

.toolkit.toolkit-light .tks-stat-note {
  font-family: var(--font-sans);
  font-size: max(0.75rem, 0.6875rem);
  font-weight: 500;
  line-height: 1.3;
  color: var(--muted-foreground);
}

.toolkit.toolkit-light .tks-connect {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: center;
  min-height: 2.25rem;
  padding: 0.35rem 0.85rem;
  border-radius: 0.45rem;
  background: var(--primary);
  color: var(--primary-foreground);
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.toolkit.toolkit-light .tks-work-hub {
  height: auto;
  overflow: visible;
  grid-template-columns: minmax(0, 1fr);
}

.toolkit.toolkit-light .tks-side {
  display: flex;
  flex-direction: column;
}

.toolkit.toolkit-light .tks-panel-title {
  font-family: var(--font-sans);
  font-size: max(0.75rem, 0.8125rem);
  font-weight: 700;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--foreground);
}

.toolkit.toolkit-light .tks-table-hub th,
.toolkit.toolkit-light .tks-table-hub td {
  font-size: max(0.75rem, 0.6875rem);
}

.toolkit.toolkit-light .tks-col-sync {
  width: 2.4rem;
  text-align: center;
}

.toolkit.toolkit-light .tks-refresh {
  width: 0.85rem;
  height: 0.85rem;
  color: var(--muted-foreground);
}

.toolkit.toolkit-light .tks-settings-list {
  display: grid;
  gap: 0.45rem;
  margin: 0.15rem 0 0;
  padding: 0;
  list-style: none;
}

.toolkit.toolkit-light .tks-settings-list li {
  display: grid;
  gap: 0.28rem;
  min-width: 0;
}

.toolkit.toolkit-light .tks-settings-list li span {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--muted-foreground);
}

.toolkit.toolkit-light .tks-settings-list li strong {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  padding: 0.32rem 0.45rem;
  border: 1px solid var(--border);
  border-radius: 0.4rem;
  background: var(--background);
  font-size: max(0.75rem, 0.75rem);
  font-weight: 650;
  color: var(--foreground);
}

.toolkit.toolkit-light .tks-settings-chevron {
  width: 0.85rem;
  height: 0.85rem;
  flex-shrink: 0;
  color: var(--muted-foreground);
}

.toolkit.toolkit-light .tks-toggle {
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
  background: color-mix(in oklab, var(--primary) 8%, var(--background));
  color: var(--primary);
}

.toolkit.toolkit-light .tks-toggle i {
  position: relative;
  display: block;
  width: 1.7rem;
  height: 0.95rem;
  flex-shrink: 0;
  border-radius: 999px;
  background: var(--primary);
}

.toolkit.toolkit-light .tks-toggle i::after {
  content: "";
  position: absolute;
  top: 0.12rem;
  right: 0.12rem;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 999px;
  background: var(--primary-foreground);
}

.tks-tree {
  --tks-dest-gap: 0.7rem;
  display: grid;
  justify-items: center;
  margin: 0;
  padding: 1.15rem 1.1rem 0;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 1rem;
  background: var(--background);
  box-shadow: var(--shadow-card);
}

.tks-tree-node {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.55rem 0.95rem;
  border-radius: 0.55rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  line-height: 1.2;
  white-space: nowrap;
}

.tks-tree-inventory {
  border: 1.5px solid color-mix(in oklab, var(--primary) 55%, var(--border));
  background: var(--background);
  color: var(--foreground);
}

.tks-tree-hub {
  border: 1.5px solid var(--primary);
  background: var(--primary);
  color: var(--primary-foreground);
}

.tks-tree-icon {
  width: 0.95rem;
  height: 0.95rem;
  flex-shrink: 0;
  color: var(--primary);
}

.tks-tree-mark {
  width: 1.35rem;
  height: 0.85rem;
  object-fit: contain;
  filter: brightness(0) invert(1);
}

.tks-tree-join {
  display: flex;
  justify-content: center;
  height: 1.1rem;
}

.tks-tree-stem {
  display: block;
  width: 1px;
  height: 100%;
  background: color-mix(in oklab, var(--foreground) 22%, transparent);
}

.tks-tree-fan {
  position: relative;
  width: 100%;
  padding-top: 1.35rem;
}

.tks-tree-svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 1.35rem;
  overflow: visible;
  fill: none;
  stroke: color-mix(in oklab, var(--foreground) 22%, transparent);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.tks-tree-svg-4 {
  display: none;
}

.tks-tree-dest {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--tks-dest-gap);
  width: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

.tks-tree-dest-item {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 2.75rem;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 0.4rem;
  padding: 0.5rem 0.55rem;
  border: 1px solid color-mix(in oklab, var(--primary) 18%, var(--border));
  border-radius: 0.5rem;
  background: color-mix(in oklab, var(--primary) 8%, var(--background));
  text-align: left;
}

.tks-tree-dest-item::before {
  content: "";
  position: absolute;
  left: 50%;
  width: 1px;
  background: color-mix(in oklab, var(--foreground) 22%, transparent);
}

.tks-tree-dest-item:nth-child(n + 3)::before {
  top: calc(var(--tks-dest-gap) * -1);
  height: var(--tks-dest-gap);
}

.tks-tree-dest-icon {
  width: 0.95rem;
  height: 0.95rem;
  flex-shrink: 0;
  color: var(--primary);
}

.tks-tree-dest-label {
  min-width: 0;
  font-size: max(0.75rem, 0.6875rem);
  font-weight: 650;
  line-height: 1.2;
  color: var(--foreground);
  overflow-wrap: anywhere;
}

.tks-tree-foot {
  display: flex;
  width: calc(100% + 2.2rem);
  margin: 1.1rem -1.1rem 0;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.7rem 1rem;
  background: color-mix(in oklab, var(--primary) 10%, var(--background));
  font-size: max(0.75rem, 0.8125rem);
  line-height: 1.4;
  color: var(--foreground);
}

.tks-tree-foot-icon {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
  margin-top: 0.1rem;
  color: var(--primary);
}

.tks-logos {
  display: grid;
  gap: 1rem;
  margin-top: 2rem;
  min-width: 0;
}

.tks-logos-line {
  margin: 0;
  text-align: center;
  font-size: max(0.75rem, 0.875rem);
  line-height: 1.5;
  color: var(--muted-foreground);
}

.tks-logos-track {
  display: flex;
  gap: 0.7rem;
  min-width: 0;
  margin: 0;
  padding: 0.15rem 0 0.35rem;
  list-style: none;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.tks-logo-card {
  display: flex;
  flex: 0 0 auto;
  min-width: 8.75rem;
  min-height: 3.5rem;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.65rem 0.9rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--background);
  box-shadow: 0 1px 2px oklch(0.2 0.01 160 / 0.04);
  scroll-snap-align: start;
}

.tks-logo-name {
  font-size: 0.875rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1;
  color: var(--foreground);
}

.tks-logo-card[data-tone="viagogo"] .tks-logo-name {
  font-weight: 800;
  letter-spacing: -0.04em;
}

.tks-logo-card[data-tone="stubhub"] {
  background: oklch(0.33 0.13 305);
  border-color: oklch(0.33 0.13 305);
}

.tks-logo-card[data-tone="stubhub"] .tks-logo-name {
  color: white;
}

.tks-logo-card[data-tone="seatgeek"] .tks-logo-name {
  color: oklch(0.55 0.19 29);
  letter-spacing: 0.04em;
}

.tks-logo-card[data-tone="ticketmaster"] .tks-logo-name {
  color: oklch(0.48 0.16 250);
  font-weight: 800;
}

.tks-logo-card[data-tone="vivid"] .tks-logo-mark {
  width: 0.85rem;
  height: 0.85rem;
  border-radius: 0.2rem;
  background: linear-gradient(135deg, oklch(0.72 0.16 55), oklch(0.62 0.2 15));
}

.tks-logo-card[data-tone="more"] {
  gap: 0.45rem;
}

.tks-logo-globe {
  width: 1.05rem;
  height: 1.05rem;
  color: var(--primary);
}

.toolkit.toolkit-light .toolkit-light-foot {
  align-items: stretch;
  border-top: 0;
  padding-top: 1.35rem;
}

@media (min-width: 768px) {
  .toolkit.toolkit-light .toolkit-light-foot {
    flex-direction: column;
    align-items: center;
  }

  .toolkit.toolkit-light .toolkit-light-ctas {
    justify-content: center;
  }
}

@media (max-width: 639px) {
  .toolkit.toolkit-light .tks-stats-hub {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .toolkit.toolkit-light .tks-connect {
    grid-column: 1 / -1;
    min-height: 2.75rem;
  }

  .toolkit.toolkit-light .toolkit-light-ctas {
    width: 100%;
  }
}

@media (min-width: 640px) {
  .tks-tree-svg-2 {
    display: none;
  }

  .tks-tree-svg-4 {
    display: block;
  }

  .tks-tree-dest {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .tks-tree-dest-item:nth-child(n + 3)::before {
    content: none;
  }

  .tks-tree-dest-item:nth-child(n + 5)::before {
    content: "";
    top: calc(var(--tks-dest-gap) * -1);
    height: var(--tks-dest-gap);
  }

  .toolkit.toolkit-light .tks-work-hub {
    grid-template-columns: minmax(0, 1.35fr) minmax(12.5rem, 0.72fr);
  }

  .tks-logos-track {
    flex-wrap: wrap;
    justify-content: center;
    overflow: visible;
    scroll-snap-type: none;
  }
}

@media (min-width: 1024px) {
  .toolkit.toolkit-light .toolkit-light-stage {
    grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.18fr);
    gap: 2rem 2.25rem;
    margin-top: 0;
  }

  .toolkit.toolkit-light .tks-stat-note {
    font-size: 0.6875rem;
  }
}

/* ── Homepage MI + StickyScroll corner shells ───────────────────
   FeatureOrbit / JourneyNumbers pattern: paint lives on an inner
   overflow-hidden layer with border-radius: inherit. Section stays
   transparent so PageShell --background shows in the corners (no
   leftover square fill hugging the rounded card).
   .mihp-section previously set overflow-x: clip + overflow-y: visible,
   which undid section-curve clipping and is a Chromium STATUS_BREAKPOINT
   pair. StickyScroll cannot overflow:hidden on the section (sticky
   consoles) — shell clips paint only. No 100svh / nested overflow-y. */

.mihp-section {
  overflow: hidden;
  background: transparent;
}

.sss-section {
  overflow: visible;
  background: transparent;
}

.mihp-shell,
.sss-shell {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  border-radius: inherit;
}

.mihp-shell {
  background: var(--dark);
}

.sss-shell {
  background: var(--surface);
}

/* ============================================================
   Global Distribution follow-up (#platform-toolkit)
   Prefix: .toolkit-light* / .tks-* only.
   Do not touch .sto-* .tpa-* .mps-* .how-it-* .prd-* .int-*
   .feature-orbit-* .journey-num* .stats-wallet-* .mihp-* .sss-*.
   Logo strip unmounted. Hub node is the Nav lockup. Desktop
   columns stretch to equal height; stacked below lg. No 100svh,
   no size container, overflow hidden both axes on the desk.
   ============================================================ */

.tks-tree-lockup {
  display: block;
  width: auto;
  height: 1.85rem;
  max-width: min(14.75rem, 100%);
  object-fit: contain;
  object-position: center;
  filter: brightness(0) invert(1);
}

.tks-tree-hub {
  padding: 0.5rem 0.85rem;
}

@media (min-width: 1024px) {
  .toolkit.toolkit-light .toolkit-light-stage {
    align-items: stretch;
  }

  .toolkit.toolkit-light .toolkit-light-col {
    height: auto;
  }

  .toolkit.toolkit-light .toolkit-light-hero,
  .toolkit.toolkit-light .toolkit-screen-hero {
    display: flex;
    flex-direction: column;
    align-self: stretch;
    height: auto;
    min-height: 100%;
    overflow: hidden;
  }

  .toolkit.toolkit-light .tks-desk,
  .toolkit.toolkit-light .tks-desk .lc-frame,
  .toolkit.toolkit-light .tks-desk .lc-bezel,
  .toolkit.toolkit-light .tks-desk .lc-screen {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    width: 100%;
    height: 100%;
    min-height: 0;
    max-height: none;
  }

  .toolkit.toolkit-light .tks-desk .lc-body {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
  }

  .toolkit.toolkit-light .tks-body {
    display: grid;
    flex: 1 1 auto;
    grid-template-rows: auto minmax(0, 1fr);
    height: 100%;
    min-height: 0;
  }

  .toolkit.toolkit-light .tks-work-hub {
    height: 100%;
    min-height: 0;
    overflow: hidden;
    align-items: stretch;
  }

  .toolkit.toolkit-light .tks-panel {
    height: 100%;
  }

  .toolkit.toolkit-light .tks-table-hub {
    height: 100%;
  }

  .toolkit.toolkit-light .tks-table-hub tbody tr {
    height: 12.5%;
  }

  .toolkit.toolkit-light .tks-table-hub td {
    padding-block: 0.42rem;
  }

  .toolkit.toolkit-light .tks-settings {
    height: 100%;
  }

  .toolkit.toolkit-light .tks-settings-list {
    flex: 1 1 auto;
    align-content: space-between;
  }
}

/* ==========================================================================
   ProcessBento — 7-stage Discover → Settle rail (#partner-process)
   Restored after a styles.css collision deleted this block.
   Same spine as /platform (`workflowStages`). Desktop nowrap horizontal
   chips + dashed joins (bento-launch-flow language, static). Below 1024px:
   snap-scroll so 375px does not overflow the page. No obligatory motion.
   ========================================================================== */

.process-bento-rail {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  list-style: none;
  margin: 2rem 0 0;
  padding: 0;
  min-width: 0;
}

.process-bento-rail-item {
  display: flex;
  align-items: center;
  min-width: 0;
}

.process-bento-rail-item:not(:last-child) {
  flex: 1 1 auto;
}

.process-bento-rail-chip {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.4rem 0.7rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--card) 92%, transparent);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  white-space: nowrap;
  color: var(--foreground);
  box-shadow: 0 0 0 1px var(--border);
}

.process-bento-rail-join {
  display: flex;
  flex: 1 1 0.85rem;
  align-items: center;
  justify-content: center;
  min-width: 0.85rem;
  padding-inline: 0.15rem;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  line-height: 1;
  color: color-mix(in oklab, var(--primary) 55%, var(--muted-foreground));
}

.process-bento-rail-join::before {
  content: "";
  flex: 1 1 auto;
  min-width: 0.35rem;
  height: 0;
  margin-right: 0.15rem;
  border-top: 1.5px dashed color-mix(in oklab, var(--primary) 45%, var(--border));
}

.process-bento-support {
  margin-top: 1rem;
  max-width: 40rem;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.45;
  color: var(--foreground);
}

@media (min-width: 640px) {
  .process-bento-support {
    font-size: 1.125rem;
  }
}

@media (min-width: 1024px) and (max-width: 1199px) {
  .process-bento-rail-chip {
    padding-inline: 0.5rem;
    font-size: 0.625rem;
    letter-spacing: 0.06em;
  }
}

@media (max-width: 1023px) {
  .process-bento-rail {
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-padding-inline: 0.25rem;
    gap: 0;
    padding-bottom: 0.5rem;
    padding-top: 0.5rem;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-x: contain;
  }

  .process-bento-rail-item,
  .process-bento-rail-item:not(:last-child) {
    flex: 0 0 auto;
    scroll-snap-align: start;
  }

  .process-bento-rail-chip {
    min-height: 2.75rem;
    padding-inline: 0.85rem;
  }

  .process-bento-rail-join {
    flex: 0 0 1.25rem;
    min-width: 1.25rem;
    padding-inline: 0.2rem;
  }

  .process-bento-rail-join::before {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .process-bento-rail {
    scroll-behavior: auto;
  }
}

/* ── FeatureOrbit 7-product ecosystem (homepage #platform) ─────────
   Restored after a styles.css collision deleted this block.
   Prefix: .feature-orbit-* only. Do not touch .sto-* .tpa-* .mps-*
   .toolkit-* .int-* FeatureOrbitGrid. Seven nodes on the existing
   rings; mobile is a stacked title/body/CTA list. No 100svh / 340vh. */

.feature-orbit-node[data-accent="gold"],
.feature-orbit-card[data-accent="gold"],
.feature-orbit-detail[data-accent="gold"],
.feature-orbit-dot[data-accent="gold"],
.feature-orbit-mobile-card[data-accent="gold"] {
  --fo-accent: oklch(0.62 0.12 85);
}

.feature-orbit-node[data-accent="olive"],
.feature-orbit-card[data-accent="olive"],
.feature-orbit-detail[data-accent="olive"],
.feature-orbit-dot[data-accent="olive"],
.feature-orbit-mobile-card[data-accent="olive"] {
  --fo-accent: oklch(0.48 0.07 155);
}

.feature-orbit-node-btn {
  width: 7.35rem;
}

.feature-orbit-node-title {
  font-size: 0.75rem;
  line-height: 1.25;
}

.feature-orbit-node-tagline {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  font-size: 0.6875rem;
  line-height: 1.3;
}

.feature-orbit-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 44px;
  margin-top: 0.35rem;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--primary);
  text-decoration: none;
}

.feature-orbit-cta:hover {
  color: var(--primary-deep);
}

.feature-orbit-mobile-card {
  flex-direction: column;
  align-items: stretch;
  gap: 0.35rem;
  cursor: pointer;
}

.feature-orbit-mobile-head {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
}

.feature-orbit-mobile-body {
  margin: 0.15rem 0 0;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}

.feature-orbit-mobile-detail-slot {
  display: none;
}

@media (min-width: 1280px) {
  .feature-orbit-node-btn {
    width: 8rem;
  }
}

/* toolkit hub: official lockup on white, original colors, no filter */
.tks-tree-hub {
  background: var(--background);
  border: 1px solid var(--border);
  color: var(--foreground);
  padding: 0.45rem 0.7rem;
}

.tks-tree-lockup,
.tks-tree-mark {
  filter: none;
  height: 2.85rem;
  max-width: min(16.75rem, 100%);
}

/* == Homepage hero platform desks (hero-desk-*) ==
