  overflow: hidden;
}

.hero-tilt-card:has(.hero-desk) .hero-tilt-grid-bg,
.hero-tilt-card:has(.hero-desk) .hero-tilt-glare,
.hero-tilt-card:has(.hero-desk) .hero-tilt-scan {
