}

.hero-desk-shell,
.hero-desk-shell .lc-frame,
.hero-desk-shell .lc-bezel {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  max-width: 100%;
}

.hero-desk-shell .lc-bezel {
  padding: 0.42rem;
