@media (min-width: 640px) {
  .prd-cap-header h2 {
    font-size: 2.25rem;
  }

  .prd-cap-header p:last-child {
    font-size: 1rem;
  }

  .prd-cap-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .prd-cap-grid-wrap {
    margin-top: 3.5rem;
  }

  .prd-cap-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.85rem;
  }
}

