.lkh-room,
.fnh-room {
  position: relative;
  z-index: 1;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0.42rem;
  height: clamp(22rem, 52vh, 34rem);
  max-height: clamp(22rem, 52vh, 34rem);
  padding: 0.58rem 0.68rem 0.6rem;
  overflow: hidden;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in oklab, var(--background) 12%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 8%, transparent),
      transparent 42%
    ),
    color-mix(in oklab, black 50%, var(--dark));
  box-shadow:
    0 28px 64px color-mix(in oklab, black 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 10%, transparent);
  transform: rotateY(-8deg) rotateX(4deg);
  transform-origin: 48% 46%;
  transform-style: preserve-3d;
}

.srh-head,
.plh-head,
.lkh-head,
.fnh-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem;
  min-width: 0;
}

.srh-head-copy,
.plh-head-copy,
.lkh-head-copy,
.fnh-head-copy {
  min-width: 0;
}

.srh-kicker,
.plh-kicker,
.lkh-kicker,
.fnh-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
  color: var(--primary);
}

.srh-event,
.plh-event,
.lkh-event,
.fnh-event {
  margin: 0.16rem 0 0;
  font-family: var(--font-display);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--background);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.srh-event span,
.plh-event span,
.lkh-event span,
.fnh-event span {
  display: block;
  margin-top: 0.08rem;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.srh-head-meta,
.plh-head-meta,
.lkh-head-meta,
.fnh-head-meta {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.srh-horizon,
.plh-horizon,
.lkh-horizon,
.fnh-horizon {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 72%, transparent);
}

.srh-live,
.plh-live,
.lkh-live,
.fnh-live {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.2rem 0.48rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 35%, transparent);
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  font-family: var(--font-mono);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.srh-live-dot,
.plh-live-dot,
.lkh-live-dot,
.fnh-live-dot {
  width: 0.36rem;
  height: 0.36rem;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 0 8px color-mix(in oklab, var(--primary) 55%, transparent);
}

.srh-stage[data-live="true"] .srh-live-dot,
.plh-stage[data-live="true"] .plh-live-dot,
.lkh-stage[data-live="true"] .lkh-live-dot,
.fnh-stage[data-live="true"] .fnh-live-dot {
  animation: two-track-live-pulse 1.8s ease-in-out infinite;
}

.srh-body,
.plh-body,
.lkh-body,
.fnh-body {
  display: grid;
  grid-template-columns: 6.6rem minmax(0, 1fr);
  gap: 0.5rem;
  min-height: 0;
  overflow: hidden;
}

.srh-bus,
.plh-bus,
.lkh-bus,
.fnh-bus {
  position: absolute;
  top: 0.85rem;
  bottom: 0.85rem;
  left: 0.72rem;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    color-mix(in oklab, var(--primary) 45%, transparent) 18%,
    color-mix(in oklab, var(--primary) 45%, transparent) 82%,
    transparent
  );
  opacity: 0.7;
}

/* —— Source: catalog rail + inventory table —— */

.srh-catalog,
.plh-signals,
.lkh-queue,
.fnh-stages {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.22rem;
  min-height: 0;
  margin: 0;
  padding: 0.1rem 0 0.1rem 0.15rem;
  list-style: none;
}

.srh-catalog li,
.plh-signals li,
.lkh-queue li,
.fnh-stages li {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 0.9rem minmax(0, 1fr);
  gap: 0.28rem;
  align-items: center;
  min-width: 0;
  padding: 0.12rem 0.1rem;
  border-radius: 0.4rem;
  opacity: 0.55;
}

.lkh-queue li,
.plh-signals li {
  grid-template-columns: 0.9rem minmax(0, 1fr) auto;
}

.srh-catalog li[data-active="true"],
.plh-signals li[data-active="true"],
.lkh-queue li[data-active="true"],
.fnh-stages li[data-active="true"] {
  opacity: 1;
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.srh-catalog-dot,
.plh-signal-dot,
.lkh-queue-dot,
.fnh-stage-dot {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 28%, transparent);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--dark) 70%, transparent);
}

.srh-catalog li[data-active="true"] .srh-catalog-dot,
.plh-signals li[data-active="true"] .plh-signal-dot,
.lkh-queue li[data-active="true"] .lkh-queue-dot,
.fnh-stages li[data-active="true"] .fnh-stage-dot {
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 55%, transparent);
}

.srh-catalog-copy,
.plh-signal-copy,
.lkh-queue-copy,
.fnh-stage-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 0.02rem;
}

.srh-catalog-copy em,
.plh-signal-copy em,
.lkh-queue-copy em,
.fnh-stage-copy em {
  font-style: normal;
  font-size: 0.62rem;
  font-weight: 600;
  color: var(--background);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.srh-catalog-copy strong,
.plh-signal-copy strong,
.lkh-queue-copy strong,
.fnh-stage-copy strong {
  font-family: var(--font-mono);
  font-size: 0.54rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 58%, transparent);
}

.plh-signal-note,
.lkh-queue-state {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, var(--background) 48%, transparent);
}

.srh-stock,
.plh-field,
.lkh-pipe,
.fnh-field {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
  padding: 0.42rem 0.5rem;
  border-radius: 0.72rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  background: color-mix(in oklab, black 28%, transparent);
}

.srh-panel-label {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: color-mix(in oklab, var(--background) 62%, transparent);
}

.srh-panel-label span {
  font-weight: 500;
  opacity: 0.75;
}

.srh-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.68rem;
  color: color-mix(in oklab, var(--background) 82%, transparent);
}

.srh-table th {
  text-align: left;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: color-mix(in oklab, var(--background) 46%, transparent);
  padding: 0.18rem 0.28rem 0.28rem 0;
}

.srh-table td {
  padding: 0.28rem 0.28rem 0.28rem 0;
  border-top: 1px solid color-mix(in oklab, var(--background) 8%, transparent);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 8.5rem;
}

.srh-num {
  font-family: var(--font-mono);
  text-align: right;
}

.srh-ask {
  color: var(--primary);
  font-weight: 700;
}

.srh-status {
  display: inline-flex;
  padding: 0.08rem 0.32rem;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  letter-spacing: 0.04em;
  border: 1px solid color-mix(in oklab, var(--background) 14%, transparent);
}

.srh-status[data-state="listed"] {
  color: var(--primary);
  border-color: color-mix(in oklab, var(--primary) 35%, transparent);
}

.srh-status[data-state="syncing"] {
  color: color-mix(in oklab, var(--background) 78%, transparent);
}

.srh-status[data-state="hold"] {
  color: color-mix(in oklab, var(--background) 70%, var(--primary));
}

.srh-foot,
.plh-foot,
.lkh-foot,
.fnh-foot {
  min-width: 0;
}

.srh-feeds,
.plh-gates,
.lkh-connect,
.fnh-ledger {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.plh-gates {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.lkh-connect {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.fnh-ledger {
  grid-template-columns: 1fr;
  gap: 0.12rem;
}

.srh-feeds li,
.plh-gates li,
.lkh-connect li {
  display: flex;
  flex-direction: column;
  gap: 0.04rem;
  min-width: 0;
  padding: 0.28rem 0.38rem;
  border-radius: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  opacity: 0.62;
}

.srh-feeds li[data-active="true"],
.plh-gates li[data-active="true"],
.lkh-connect li[data-active="true"],
.fnh-ledger li[data-active="true"] {
  opacity: 1;
  border-color: color-mix(in oklab, var(--primary) 38%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.srh-feeds li span,
.plh-gates li span,
.lkh-connect li span {
  font-size: 0.64rem;
  font-weight: 600;
  color: var(--background);
}

.srh-feeds li em,
.plh-gates li em,
.lkh-connect li em {
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 0.52rem;
  color: color-mix(in oklab, var(--background) 52%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.plh-gates li[data-gate="accept"][data-active="true"] {
  border-color: color-mix(in oklab, var(--primary) 50%, transparent);
}

.plh-gates li[data-gate="hold"][data-active="true"] {
  border-color: color-mix(in oklab, var(--background) 28%, transparent);
}

.plh-gates li[data-gate="dismiss"][data-active="true"] {
  opacity: 0.9;
}

/* —— Pulse: market rec + broker gate —— */

.plh-math {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.4rem;
  margin: 0;
}

.plh-math div {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  padding: 0.28rem 0.35rem;
  border-radius: 0.45rem;
  background: color-mix(in oklab, var(--background) 5%, transparent);
}

.plh-math dt {
  font-family: var(--font-mono);
  font-size: 0.52rem;
  letter-spacing: 0.06em;
  color: color-mix(in oklab, var(--background) 52%, transparent);
}

.plh-math dd {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--background);
}

.plh-ask {
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  margin-top: auto;
}

.plh-ask span {
  font-family: var(--font-mono);
  font-size: 0.56rem;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.plh-ask strong {
  font-size: clamp(1.35rem, 2.4vw, 1.85rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--background);
}

.plh-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin: 0;
  font-size: 0.68rem;
  color: color-mix(in oklab, var(--background) 70%, transparent);
}

.plh-status em {
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--primary);
}

/* —— Link: POS queue + sale pipeline —— */

.lkh-pipe {
  margin: 0;
  padding: 0.38rem 0.45rem;
  list-style: none;
  gap: 0.18rem;
}

.lkh-pipe li {
  display: grid;
  grid-template-columns: 1.6rem minmax(0, 1fr);
  gap: 0.35rem;
  align-items: center;
  padding: 0.18rem 0.28rem;
  border-radius: 0.42rem;
  opacity: 0.5;
}

.lkh-pipe li[data-active="true"] {
  opacity: 1;
  background: color-mix(in oklab, var(--primary) 12%, transparent);
}

.lkh-pipe-index {
  font-size: 0.58rem;
  font-weight: 700;
  color: var(--primary);
}

.lkh-pipe-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.lkh-pipe-copy strong {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--background);
}

.lkh-pipe-copy em {
  font-style: normal;
  font-size: 0.58rem;
  color: color-mix(in oklab, var(--background) 52%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* —— Funds: rails + payout path —— */

.fnh-rails {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.32rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fnh-rails li {
  display: flex;
  flex-direction: column;
  gap: 0.08rem;
  padding: 0.38rem 0.42rem;
  border-radius: 0.55rem;
  border: 1px solid color-mix(in oklab, var(--background) 10%, transparent);
  opacity: 0.62;
}

.fnh-rails li[data-active="true"] {
  opacity: 1;
  border-color: color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 10%, transparent);
}

.fnh-rail-kicker {
  font-family: var(--font-mono);
  font-size: 0.5rem;
  letter-spacing: 0.1em;
  color: var(--primary);
}

.fnh-rails strong {
  font-size: 0.82rem;
  color: var(--background);
}

.fnh-rails em {
  font-style: normal;
  font-size: 0.58rem;
  color: color-mix(in oklab, var(--background) 55%, transparent);
}

.fnh-path {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.28rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fnh-path li {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.22rem;
  min-width: 0;
  opacity: 0.45;
}

.fnh-path li[data-active="true"] {
  opacity: 1;
}

.fnh-path-node {
  width: 0.48rem;
  height: 0.48rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 28%, transparent);
}

.fnh-path li[data-active="true"] .fnh-path-node {
  background: var(--primary);
  box-shadow: 0 0 10px color-mix(in oklab, var(--primary) 50%, transparent);
}

.fnh-path strong {
  display: block;
  font-size: 0.62rem;
  font-weight: 600;
  color: var(--background);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.fnh-path em {
  display: block;
  font-style: normal;
  font-family: var(--font-mono);
  font-size: 0.5rem;
  color: color-mix(in oklab, var(--background) 50%, transparent);
}

.fnh-ledger li {
  font-size: 0.62rem;
  line-height: 1.35;
  color: color-mix(in oklab, var(--background) 58%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  opacity: 0.55;
}

.fnh-ledger li[data-active="true"] {
  opacity: 1;
  color: color-mix(in oklab, var(--background) 82%, transparent);
}

@media (max-width: 1023px) {
  .srh-stage,
  .plh-stage,
  .lkh-stage,
  .fnh-stage {
    padding: 0.1rem 0.1rem 0.3rem 0;
  }

  .srh-room,
  .plh-room,
  .lkh-room,
  .fnh-room {
    height: clamp(18rem, 42vh, 26rem);
    max-height: clamp(18rem, 42vh, 26rem);
    transform: rotateY(-5deg) rotateX(2.5deg);
  }
}

@media (max-width: 639px) {
  .srh-room,
  .plh-room,
  .lkh-room,
  .fnh-room {
    transform: none;
    height: clamp(16rem, 38vh, 22rem);
    max-height: clamp(16rem, 38vh, 22rem);
    gap: 0.32rem;
    padding: 0.55rem 0.6rem 0.5rem;
  }

  .srh-body,
  .plh-body,
  .lkh-body,
  .fnh-body {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .srh-catalog,
  .plh-signals,
  .lkh-queue,
  .fnh-stages {
    flex-direction: row;
    padding: 0;
  }

  .srh-bus,
  .plh-bus,
  .lkh-bus,
  .fnh-bus,
  .srh-event span,
  .plh-event span,
  .lkh-event span,
  .fnh-event span,
  .srh-panel-label span,
  .plh-signal-note,
  .lkh-queue-state,
  .lkh-pipe-copy em,
  .fnh-stage-copy strong,
  .fnh-path em,
  .srh-feeds li em,
  .plh-gates li em,
  .lkh-connect li em {
    display: none;
  }

  .srh-catalog li,
  .plh-signals li,
  .lkh-queue li,
  .fnh-stages li {
    grid-template-columns: auto minmax(0, 1fr);
    min-width: 0;
    flex: 1 1 0;
  }

  .lkh-connect {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .fnh-ledger li:not([data-active="true"]) {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .srh-room,
  .plh-room,
  .lkh-room,
  .fnh-room {
    transform: none;
  }

  .srh-stage[data-live="true"] .srh-live-dot,
  .plh-stage[data-live="true"] .plh-live-dot,
  .lkh-stage[data-live="true"] .lkh-live-dot,
  .fnh-stage[data-live="true"] .fnh-live-dot {
    animation: none;
  }
}

/* ==========================================================================
   Product-hero desk fill (2026-08-22)
   Source / Pulse / Link / Funds rooms already clamp like .eih-room
   (22–34 / tablet 18–26 / phone 16–22). Inner panels were sparse:
   space-between on 3–4 chips, 3-row tables, huge rec number with
   margin-top: auto. Stretch header + body + footer; unique desks kept.
   ========================================================================== */

.srh-room,
.plh-room,
.lkh-room,
.fnh-room {
  gap: 0.32rem;
  padding: 0.48rem 0.55rem 0.45rem;
}

.srh-body,
.plh-body,
.lkh-body,
.fnh-body {
  grid-template-columns: 7.35rem minmax(0, 1fr);
  gap: 0.38rem;
  height: 100%;
  align-items: stretch;
}

.srh-catalog,
.plh-signals,
.lkh-queue,
.fnh-stages {
  display: grid;
  grid-auto-rows: 1fr;
  justify-content: stretch;
  align-content: stretch;
  gap: 0.1rem;
  height: 100%;
  padding: 0;
}

.srh-catalog li,
.plh-signals li,
.lkh-queue li,
.fnh-stages li {
  padding: 0.08rem 0.08rem;
  align-content: center;
}

.srh-stock,
.plh-field,
.lkh-pipe,
.fnh-field {
  height: 100%;
  gap: 0.26rem;
  padding: 0.32rem 0.38rem;
}

/* —— Source: layers + 5-row sheet filling the stock pane —— */

.srh-stock {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
}

.srh-layers {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.22rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.srh-layers li {
  display: flex;
  flex-direction: column;
  gap: 0.02rem;
  min-width: 0;
  padding: 0.22rem 0.28rem;
