/* ==========================================================================
   ProcessBento rail — live spine (#partner-process)
   Append-only. Base .process-bento-rail* / .process-bento-support stay above.
   Active node travels Discover → Settle (FeatureOrbit dwell). Hot join is
   the N→N+1 hop (brighter dashes + packet). Pause on hover, resume 450ms.
   ========================================================================== */

button.process-bento-rail-chip {
  appearance: none;
  margin: 0;
  border: 0;
  cursor: pointer;
  text-align: center;
  transition:
    color 0.28s ease,
    background-color 0.28s ease,
    box-shadow 0.28s ease;
}

.process-bento-rail-chip:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.process-bento-rail-chip[data-state="waiting"] {
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--card) 92%, transparent);
  box-shadow: 0 0 0 1px var(--border);
}

.process-bento-rail-chip[data-state="done"] {
  color: color-mix(in oklab, var(--foreground) 78%, var(--primary));
  background: color-mix(in oklab, var(--card) 88%, var(--primary));
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--primary) 42%, var(--border));
}

.process-bento-rail-chip[data-state="active"] {
  color: var(--primary-deep);
  font-weight: 700;
  background: color-mix(in oklab, var(--card) 82%, var(--primary));
  box-shadow:
    0 0 0 1.5px color-mix(in oklab, var(--primary) 72%, transparent),
    0 0 16px -2px color-mix(in oklab, var(--primary) 48%, transparent);
}

.process-bento-rail-join {
  position: relative;
  overflow: visible;
}

.process-bento-rail-join[data-done="true"] {
  color: color-mix(in oklab, var(--primary) 70%, var(--muted-foreground));
}

.process-bento-rail-join[data-hot="true"] {
  color: var(--primary);
}

.process-bento-rail-join[data-done="true"]::before {
  border-top-color: color-mix(in oklab, var(--primary) 68%, var(--border));
}

.process-bento-rail-join[data-hot="true"]::before {
  border-top: none;
  height: 1.5px;
  background-image: repeating-linear-gradient(
    90deg,
    var(--primary) 0 5px,
    transparent 5px 9px
  );
  background-size: 14px 1.5px;
  background-repeat: repeat-x;
  background-position: 0 50%;
  animation: process-bento-rail-dash 0.7s linear infinite;
}

.process-bento-rail:not([data-live="true"]) .process-bento-rail-join[data-hot="true"]::before {
  animation: none;
}

.process-bento-rail-packet {
  position: absolute;
  top: 50%;
  left: 0;
  z-index: 1;
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 999px;
  pointer-events: none;
  background: var(--primary);
  box-shadow:
    0 0 0 2px color-mix(in oklab, var(--dark) 35%, transparent),
    0 0 0 4px color-mix(in oklab, var(--primary) 16%, transparent);
  transform: translate(-50%, -50%);
  opacity: 0;
}

.process-bento-rail[data-live="true"] .process-bento-rail-join[data-hot="true"] .process-bento-rail-packet {
  animation: process-bento-rail-packet 1.6s linear infinite;
}

@keyframes process-bento-rail-dash {
  to {
    background-position: 14px 50%;
  }
}

@keyframes process-bento-rail-packet {
  0% {
    left: 0;
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  88% {
    opacity: 1;
  }
  100% {
    left: calc(100% - 0.2rem);
    opacity: 0;
  }
}

@media (max-width: 1023px) {
  .process-bento-rail-join::before {
    display: block;
    min-width: 0.45rem;
  }

  .process-bento-rail-join {
    flex-basis: 1.55rem;
    min-width: 1.55rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  button.process-bento-rail-chip {
    transition: none;
  }

  .process-bento-rail-join[data-hot="true"]::before,
  .process-bento-rail-packet {
    animation: none !important;
  }

  .process-bento-rail-packet {
    opacity: 0 !important;
  }
}

/* ==========================================================================
   /platform operating-stack sticky pane (2026-08-22)
   Prefix: .plt-flow-* only. The 2026-08-22 alignment patch set
   .plt-flow-grid { align-items: start } at ≥1024px, so the right column
   sized to the console and position:sticky had no travel — the desk
   scrolled off with card 01. Stretch the sticky column like HowItWorks.
   Append only. Do not touch .how-it-* .prd-* .int-* .tks-* .sss-*.
   ========================================================================== */

@media (min-width: 1024px) {
  .plt-flow-grid {
    align-items: stretch;
  }

  .plt-flow-sticky {
    align-self: stretch;
    height: auto;
    min-height: 100%;
  }

  .plt-flow-pane {
    position: sticky;
    top: 6rem;
    width: 100%;
    height: calc(100svh - 6rem);
  }

  .plt-flow-step {
    min-height: 46svh;
  }
}

/* ProcessBento rail: one packet hop = one chip advance (was 1.6s infinite
   vs 2.1s interval, so the dot completed a second trip before highlight). */
.process-bento-rail[data-live="true"] .process-bento-rail-join[data-hot="true"] .process-bento-rail-packet {
  animation: process-bento-rail-packet 2100ms linear 1 forwards;
}

.process-bento-rail[data-paused="true"] .process-bento-rail-join[data-hot="true"] .process-bento-rail-packet,
.process-bento-rail[data-paused="true"] .process-bento-rail-join[data-hot="true"]::before {
  animation-play-state: paused;
}

/* ==========================================================================
   /become-a-seller — dark apply desk + compact application (2026-08-22)
   Prefix: .slr-* (seller hero) and .saf-* (seller application form).
   Hero room matches .bdm-room: clamp(22rem, 52vh, 34rem). Not a live login.
   Form: desktop ~100svh with overflow-y auto safety. Append only.
   ========================================================================== */

