/* ==========================================================================
   WorkflowSteps leftover-row center (product / platform / shared How)
   `.ws-flow-grid` was CSS grid (`auto-fit` / 5 tracks). Grid cannot center
   a short last row — 7 cards paint 01–05 then 06–07 left under 01–02.
   Flex wrap + justify-content: center. Desktop cards ~20% so five fit a row.
   6+ steps lock that width so 06–07 stay card-sized (not stretched).
   1–5 steps still grow to fill. Homepage HowItWorks (`.how-it-*`) untouched.
   ========================================================================== */

.ws-flow-panel {
  --ws-flow-gap: clamp(1rem, 2.5vw, 1.35rem);
}

.ws-flow-panel .ws-flow-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: stretch;
  gap: var(--ws-flow-gap);
  grid-template-columns: none;
}

.ws-flow-panel .ws-flow-grid > .ws-flow-card-outer {
  box-sizing: border-box;
  flex: 1 1 100%;
  min-width: 0;
  max-width: 100%;
  grid-column: auto;
}

@media (min-width: 640px) {
  .ws-flow-panel .ws-flow-grid > .ws-flow-card-outer,
  .ws-flow-panel .ws-flow-grid > .ws-flow-card-outer.is-featured {
    flex: 1 1 calc((100% - var(--ws-flow-gap)) / 2);
    max-width: calc((100% - var(--ws-flow-gap)) / 2);
    grid-column: auto;
  }
}

@media (min-width: 1024px) {
  .ws-flow-panel .ws-flow-grid > .ws-flow-card-outer,
  .ws-flow-panel .ws-flow-grid > .ws-flow-card-outer.is-featured {
    flex: 1 1 calc((100% - 4 * var(--ws-flow-gap)) / 5);
    max-width: none;
    width: auto;
    grid-column: auto;
  }

  .ws-flow-panel .ws-flow-grid:has(> :nth-child(6)) > .ws-flow-card-outer,
  .ws-flow-panel .ws-flow-grid:has(> :nth-child(6)) > .ws-flow-card-outer.is-featured {
    flex: 0 0 calc((100% - 4 * var(--ws-flow-gap)) / 5);
    width: calc((100% - 4 * var(--ws-flow-gap)) / 5);
    max-width: calc((100% - 4 * var(--ws-flow-gap)) / 5);
  }
}

