  .tpa-section .smt-console,
  .tpa-section .smt-console .lc-frame,
  .tpa-section .smt-console .lc-bezel,
  .tpa-section .smt-console .lc-screen {
    min-height: 0;
    height: 100%;
    max-height: 100%;
  }

  .tpa-section .smt-console .lc-body {
    min-height: 0;
    overflow: visible;
    overscroll-behavior: auto;
  }

  .tpa-section .smt-desk {
    min-height: 0;
    height: 100%;
    max-height: 100%;
    overflow: visible;
    gap: 0.32rem;
    padding: 0.35rem 0.4rem 0.38rem;
  }

  .tpa-section .smt-split {
    min-height: 0;
    overflow: visible;
    gap: 0.32rem;
  }

  .tpa-section .smt-map-card,
  .tpa-section .smt-list-card {
    min-height: 0;
    overflow: hidden;
  }

  .tpa-section .smt-map-stage {
    flex: 1 1 auto;
    min-height: 4.5rem;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .tpa-section .smt-table th,
  .tpa-section .smt-table td {
